def now():
    return datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")

def norm_path(path):
    return os.path.abspath(os.path.expandvars(os.path.expanduser(path.strip().strip('"'))))

def is_inside(child, parent):
    try:
        child = os.path.normcase(os.path.abspath(child))
        parent = os.path.normcase(os.path.abspath(parent))
        return os.path.commonpath([child, parent]) == parent
    except Exception:
        return False

def read_file(path):
    if os.path.exists(path):
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            return f.read()
    return ""

def write_file(path, text):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)

def append_file(path, text):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "a", encoding="utf-8") as f:
        f.write(text)


def _guardian_redact_for_log_text(text):
    raw = str(text or "")
    if not raw:
        return ""
    redacted = redact_sensitive_text(raw, "[REDACTED]")
    return redacted[:4000]


def append_log(text):
    append_file(LOG_FILE, f"\n\n## {now()}\n{_guardian_redact_for_log_text(text)}\n")


# ----------------------------------------------------------------------
# Provider-gated brain/search/spell-check configuration
# No provider is required for Engel startup. No API keys are printed.
# ----------------------------------------------------------------------
_TRUE_VALUES = {"1", "true", "yes", "on", "enabled"}


def _env_flag(name, default=False):
    raw = os.environ.get(name)
    if raw is None:
        return bool(default)
    return str(raw).strip().lower() in _TRUE_VALUES


def _env_flag_auto(name, auto_condition):
    """Three-state gate:
    - env var not set                → auto_condition (auto-detect from
      credentials being present)
    - env var set to truthy value    → True  (explicit ON)
    - env var set to falsy value     → False (explicit OFF)
    Used to remove the double-gate "set ENABLED AND set the API key"
    friction. If the user has provisioned credentials, the feature should
    be considered enabled unless they've explicitly opted out.
    """
    raw = os.environ.get(name)
    if raw is None:
        return bool(auto_condition)
    return str(raw).strip().lower() in _TRUE_VALUES


def _has_env_secret(name):
    return bool(str(os.environ.get(name, "")).strip())


def _redact_provider_error(err):
    text = str(err)
    for key_name in ["OPENAI_API_KEY", "GEMINI_API_KEY", "ENGEL_LOCAL_LLM_API_KEY"]:
        value = str(os.environ.get(key_name, "")).strip()
        if value:
            text = text.replace(value, "[redacted]")
    return text


def _chatgpt_config_v2provider():
    provider = str(os.environ.get("ENGEL_ONLINE_LLM_PROVIDER", "")).strip().lower()
    key_set = _has_env_secret("OPENAI_API_KEY")
    # Auto-enable when both an OpenAI API key and ChatGPT provider are
    # configured. ENGEL_ONLINE_LLM_ENABLED still wins if set explicitly.
    enabled = _env_flag_auto("ENGEL_ONLINE_LLM_ENABLED", key_set and provider == "chatgpt")
    return {
        "provider": provider,
        "enabled": enabled,
        "configured": enabled and provider == "chatgpt" and key_set,
        "key_set": key_set,
        "model": str(os.environ.get("ENGEL_ONLINE_LLM_MODEL", "gpt-4.1-mini")).strip() or "gpt-4.1-mini",
        "url": str(os.environ.get("ENGEL_CHATGPT_API_URL", "https://api.openai.com/v1/chat/completions")).strip(),
    }


def _local_llm_config_v2provider():
    provider = str(os.environ.get("ENGEL_LOCAL_LLM_PROVIDER", "generic_local")).strip().lower() or "generic_local"
    endpoint = str(os.environ.get("ENGEL_LOCAL_LLM_ENDPOINT", "")).strip()
    model = str(os.environ.get("ENGEL_LOCAL_LLM_MODEL", "")).strip()
    # Auto-enable when both an endpoint and a model are configured. Explicit
    # ENGEL_LOCAL_LLM_ENABLED still wins.
    enabled = _env_flag_auto("ENGEL_LOCAL_LLM_ENABLED", bool(endpoint) and bool(model))
    return {
        "provider": provider,
        "enabled": enabled,
        "configured": enabled and bool(endpoint) and bool(model),
        "endpoint_set": bool(endpoint),
        "key_set": _has_env_secret("ENGEL_LOCAL_LLM_API_KEY"),
        "model_set": bool(model),
        "model": model,
        "endpoint": endpoint,
    }


def _gemini_search_config_v2provider():
    provider = str(os.environ.get("ENGEL_RESEARCH_SEARCH_PROVIDER", "")).strip().lower()
    key_set = _has_env_secret("GEMINI_API_KEY")
    model = str(os.environ.get("ENGEL_GEMINI_SEARCH_MODEL", "gemini-1.5-flash")).strip() or "gemini-1.5-flash"
    # Auto-enable when GEMINI_API_KEY is set + provider=gemini. Explicit
    # ENGEL_GEMINI_SEARCH_ENABLED still wins.
    enabled = _env_flag_auto("ENGEL_GEMINI_SEARCH_ENABLED", key_set and provider == "gemini")
    endpoint = str(os.environ.get("ENGEL_GEMINI_SEARCH_URL", "")).strip()
    if not endpoint:
        endpoint = "https://generativelanguage.googleapis.com/v1beta/models/" + model + ":generateContent"
    return {
        "provider": provider,
        "enabled": enabled,
        "configured": enabled and provider == "gemini" and key_set,
        "key_set": key_set,
        "model": model,
        "endpoint": endpoint,
    }


def _spell_check_config_v2provider():
    # Default mode is "safe_noop" (does nothing externally), so enabling by
    # default is safe. Explicit ENGEL_SPELL_CHECK_ENABLED=0 still turns it off.
    return {
        "enabled": _env_flag_auto("ENGEL_SPELL_CHECK_ENABLED", True),
        "mode": str(os.environ.get("ENGEL_SPELL_CHECK_MODE", "safe_noop")).strip().lower() or "safe_noop",
    }


def _provider_bool(value):
    return "yes" if value else "no"


def _brain_provider_no_provider_message_v2provider(reason=""):
    chatgpt = _chatgpt_config_v2provider()
    local = _local_llm_config_v2provider()

    # Detect already-available paths (these *are* brain providers, even
    # though they're not the configured ENGEL_ONLINE_LLM / ENGEL_LOCAL_LLM
    # slots). Helps the customer realise they may already have one.
    browser_ai_state = "unknown"
    try:
        import engel_browser_ai_bridge
        browser_ai_state = "connected" if engel_browser_ai_bridge._SESSION.get("ready") else "available_not_connected"
    except Exception:
        pass

    offline_qwen_state = "unknown"
    try:
        from pathlib import Path as _P
        gguf = _P(__file__).resolve().parent / "models" / "qwen2.5-0.5b-instruct" / "qwen2.5-0.5b-instruct-q4_k_m.gguf"
        if gguf.exists() and os.environ.get("ENGEL_OFFLINE_SEED_LLM_ENABLED") == "1":
            offline_qwen_state = "ready"
        elif gguf.exists():
            offline_qwen_state = "installed_not_enabled"
        else:
            offline_qwen_state = "not_installed"
    except Exception:
        pass

    lines = ["# Engel Brain Provider", ""]
    lines.append("No brain provider slot (ChatGPT / generic local) is configured.")
    lines.append("")
    lines.append("What you can use today:")

    if browser_ai_state == "connected":
        lines.append("  - Browser AI is CONNECTED. Type a message and it goes through the connected session.")
    elif browser_ai_state == "available_not_connected":
        lines.append("  - Browser AI bridge is available. Examples: `browser ai connect duck` (free, no signup), `browser ai connect chatgpt`, `browser ai connect claude`.")

    if offline_qwen_state == "ready":
        lines.append("  - Local offline LLM (Qwen 0.5B) is READY. Free-form chat will route through it.")
    elif offline_qwen_state == "installed_not_enabled":
        lines.append("  - Local offline LLM is installed but the gate is off. Type `local llm on` to enable it.")
    elif offline_qwen_state == "not_installed":
        lines.append("  - Local offline LLM is not installed. Skip unless you specifically want offline chat.")

    lines.append("")
    lines.append("To configure the provider slots directly:")
    if not chatgpt["configured"]:
        lines.append("  - ChatGPT:  set OPENAI_API_KEY and ENGEL_ONLINE_LLM_PROVIDER=chatgpt (auto-enables).")
    else:
        lines.append("  - ChatGPT:  configured.")
    if not local["configured"]:
        lines.append("  - Local:    set ENGEL_LOCAL_LLM_ENDPOINT and ENGEL_LOCAL_LLM_MODEL (auto-enables).")
    else:
        lines.append("  - Local:    configured.")

    if reason:
        lines += ["", "Detail:", str(reason)]
    lines += [
        "",
        "Safety:",
        "- No provider call was made.",
        "- No cloud fallback was used.",
        "- No keys, memory files, source files, logs, or private reports were sent.",
    ]
    return "\n".join(lines)


def _provider_system_prompt_v2provider(system_message="", extra_context="", include_local_context=False):
    base = str(system_message or "").strip()
    if not base:
        base = read_file(PROMPT_FILE)
    local_context = runtime_context(extra_context) if include_local_context else ""
    try:
        from engel_brain_provider_prompt_context import build_brain_provider_system_prompt

        return build_brain_provider_system_prompt(
            system_message=base,
            extra_context=local_context,
            include_local_context=include_local_context,
        )
    except Exception:
        if local_context:
            base = base + "\n\n" + local_context
        return base


def _chatgpt_generate_v2provider(prompt, system_message=""):
    cfg = _chatgpt_config_v2provider()
    if not cfg["configured"]:
        return {"ok": False, "text": _brain_provider_no_provider_message_v2provider("ChatGPT is not fully configured.")}
    headers = {
        "Authorization": "Bearer " + str(os.environ.get("OPENAI_API_KEY", "")).strip(),
        "Content-Type": "application/json",
    }
    payload = {
        "model": cfg["model"],
        "stream": False,
        "messages": [
            {"role": "system", "content": _provider_system_prompt_v2provider(system_message, include_local_context=False)},
            {"role": "user", "content": str(prompt)},
        ],
    }
    try:
        r = requests.post(cfg["url"], headers=headers, json=payload, timeout=180)
        r.raise_for_status()
        data = r.json()
        content = data.get("choices", [{}])[0].get("message", {}).get("content", "")
        return {"ok": True, "text": str(content).strip(), "provider": "chatgpt"}
    except Exception as e:
        return {"ok": False, "text": "Online LLM provider is not configured.\n\nDetail:\n" + _redact_provider_error(e)}


def _local_llm_generate_v2provider(prompt, system_message="", extra_context=""):
    cfg = _local_llm_config_v2provider()
    if not cfg["configured"]:
        return {"ok": False, "text": _brain_provider_no_provider_message_v2provider("Local/offline provider is not fully configured.")}
    endpoint = cfg["endpoint"].rstrip("/")
    url = endpoint if endpoint.endswith("/chat/completions") else endpoint + "/chat/completions"
    headers = {"Content-Type": "application/json"}
    local_key = str(os.environ.get("ENGEL_LOCAL_LLM_API_KEY", "")).strip()
    if local_key:
        headers["Authorization"] = "Bearer " + local_key
    payload = {
        "model": cfg["model"],
        "stream": False,
        "messages": [
            {"role": "system", "content": _provider_system_prompt_v2provider(system_message, extra_context, include_local_context=True)},
            {"role": "user", "content": str(prompt)},
        ],
    }
    try:
        r = requests.post(url, headers=headers, json=payload, timeout=180)
        r.raise_for_status()
        data = r.json()
        content = data.get("choices", [{}])[0].get("message", {}).get("content", "")
        return {"ok": True, "text": str(content).strip(), "provider": "local_offline"}
    except Exception as e:
        return {"ok": False, "text": _brain_provider_no_provider_message_v2provider(_redact_provider_error(e))}


def _select_brain_provider_v2provider():
    data = _brain_backend_read_v1() if "_brain_backend_read_v1" in globals() else {}
    explicit = str(os.environ.get("ENGEL_BRAIN_PROVIDER", "")).strip().lower()
    if not explicit:
        explicit = str(data.get("active_provider", "")).strip().lower()
    chatgpt = _chatgpt_config_v2provider()
    local = _local_llm_config_v2provider()
    if explicit in ["chatgpt", "online_chatgpt"]:
        return {"provider": "chatgpt", "configured": chatgpt["configured"], "explicit": True}
    if explicit in ["local", "local_offline", "generic_local"]:
        return {"provider": "local_offline", "configured": local["configured"], "explicit": True}
    if chatgpt["configured"]:
        return {"provider": "chatgpt", "configured": True, "explicit": False}
    if local["configured"]:
        return {"provider": "local_offline", "configured": True, "explicit": False}
    return {"provider": "", "configured": False, "explicit": bool(explicit)}


def _brain_text_result_v2provider(prompt, system_message="", extra_context=""):
    selected = _select_brain_provider_v2provider()
    if selected.get("provider") == "chatgpt" and selected.get("configured"):
        return _chatgpt_generate_v2provider(prompt, system_message)
    if selected.get("provider") == "local_offline" and selected.get("configured"):
        return _local_llm_generate_v2provider(prompt, system_message, extra_context)
    return {"ok": False, "text": _brain_provider_no_provider_message_v2provider()}


def ask_brain_provider(user_message, extra_context=""):
    result = _brain_text_result_v2provider(user_message, extra_context=extra_context)
    # If no provider is configured, return empty so the chat pipeline cleanly
    # falls through to browser-AI / offline-LLM / identity fallback instead of
    # surfacing the diagnostic message as if it were the brain's reply.
    if not result.get("ok"):
        return ""
    text = result.get("text", "")
    return spell_check_response(text)


def _gemini_research_candidates_v2provider(topic):
    cfg = _gemini_search_config_v2provider()
    if not cfg["configured"]:
        return {
            "ok": False,
            "urls": [],
            "detail": "Gemini research search is not configured. Overnight research enrichment will remain local/safe.",
        }
    prompt = "\n".join([
        "Find public, source-quality research URLs for this topic.",
        "Return only plain HTTPS URLs, one per line.",
        "Do not include login pages, social media, video pages, images, or shopping pages.",
        "Topic: " + str(topic),
    ])
    try:
        r = requests.post(
            cfg["endpoint"],
            params={"key": str(os.environ.get("GEMINI_API_KEY", "")).strip()},
            json={"contents": [{"parts": [{"text": prompt}]}]},
            timeout=60,
        )
        r.raise_for_status()
        data = r.json()
        text_parts = []
        for cand in data.get("candidates", []):
            for part in cand.get("content", {}).get("parts", []):
                if part.get("text"):
                    text_parts.append(str(part.get("text")))
        text = "\n".join(text_parts)
        import re
        urls = []
        seen = set()
        for url in re.findall(r"https://[^\s\]\)>\"]+", text):
            clean = url.strip().rstrip(".,;")
            if clean and _candidate_allowed(clean) and clean not in seen:
                seen.add(clean)
                urls.append(clean)
            if len(urls) >= 8:
                break
        return {"ok": True, "urls": urls, "detail": "Gemini research search returned " + str(len(urls)) + " candidate URLs."}
    except Exception as e:
        return {"ok": False, "urls": [], "detail": _redact_provider_error(e)}


def spell_check_response(text):
    try:
        cfg = _spell_check_config_v2provider()
        if not cfg["enabled"]:
            return text
        # Safe spell check plumbing is installed, but active correction is a no-op
        # until a segment-preserving checker is added. This keeps code, commands,
        # paths, JSON, logs, hashes, URLs, and approval wording unchanged.
        return text
    except Exception:
        return text


def spell_check_status():
    cfg = _spell_check_config_v2provider()
    return "\n".join([
        "# Engel Spell Check Status",
        "",
        "Enabled: " + _provider_bool(cfg["enabled"]),
        "Mode: " + cfg["mode"],
        "",
        "Behavior:",
        "- Config-gated and disabled by default.",
        "- Current correction mode is safe no-op/fail-open.",
        "- If the wrapper errors, Engel returns the original text.",
        "",
        "Bypass/safety contract:",
        "- Code blocks, inline code, commands, shell snippets, file paths, Windows paths, URLs, hashes, JSON, logs, stack traces, checkpoint IDs, approval-gate text, memory approval prompts, and source-edit approval prompts are not changed.",
    ])


