def _companion_thought_paths_v2mind_a():
    return {
        "json": os.path.join(MEMORY_DIR, "COMPANION_THOUGHT_INBOX_V2MIND_A.json"),
        "report": os.path.join(REPORTS_DIR, "mind", "COMPANION_THOUGHT_INBOX_V2MIND_A.md"),
        "promoted_topics": os.path.join(MEMORY_DIR, "COMPANION_THOUGHT_PROMOTED_RESEARCH_TOPICS_V2MIND_A.md"),
    }


def _companion_thought_source_command_v2mind_a(raw_text):
    raw = str(raw_text or "").strip()
    lower = raw.lower()
    if lower == "think about" or lower.startswith("think about "):
        return "think about"
    if lower == "engel, think about" or lower.startswith("engel, think about "):
        return "Engel, think about"
    if lower == "remember this idea:" or lower.startswith("remember this idea:"):
        return "remember this idea:"
    if lower == "research idea" or lower.startswith("research idea "):
        return "research idea"
    if lower == "research idea:" or lower.startswith("research idea:"):
        return "research idea"
    return ""


def _companion_thought_extract_idea_v2mind_a(raw_text, source_command=""):
    raw = str(raw_text or "").strip()
    lower = raw.lower()
    source = source_command or _companion_thought_source_command_v2mind_a(raw)

    prefixes = {
        "think about": ["think about"],
        "Engel, think about": ["engel, think about"],
        "remember this idea:": ["remember this idea:"],
        "research idea": ["research idea:", "research idea"],
    }

    for prefix in prefixes.get(source, []):
        if lower == prefix:
            return ""
        if lower.startswith(prefix + " "):
            return " ".join(raw[len(prefix):].strip().split())
        if prefix.endswith(":") and lower.startswith(prefix):
            return " ".join(raw[len(prefix):].strip().split())

    return ""


def _companion_thought_classification_v2mind_a(idea_text):
    text = str(idea_text or "").lower()
    labels = []

    def add(label):
        if label not in labels:
            labels.append(label)

    keyword_map = [
        ("Body", ["body", "desktop", "window", "screen", "voice", "visual", "physical", "launcher", "shortcut", "exe"]),
        ("Mind", ["mind", "brain", "thought", "think", "reason", "reflection", "companion", "identity", "conscious", "alive"]),
        ("Safety", ["safe", "safety", "guard", "guardrail", "approval", "approve", "permission", "risk", "gate"]),
        ("App", ["app", "ui", "gui", "launcher", "shortcut", "exe", "interface", "button", "route"]),
        ("Mobile", ["mobile", "phone", "iphone", "android", "bridge"]),
        ("Process", ["process", "pid", "runner", "loop", "cleanup", "orphan", "daemon"]),
        ("Research", ["research", "study", "compare", "source", "report", "topic", "investigate"]),
        ("Income", ["income", "money", "revenue", "business", "client", "sales", "profit"]),
        ("Memory", ["memory", "remember", "lesson", "history", "inbox", "archive", "queue", "chat memory", "conversation", "conversations"]),
        ("Swarm", ["swarm", "trail", "scout", "reinforce"]),
        ("Hive", ["hive", "colony", "nest", "brood", "ant", "ants", "supercolony", "pheromone"]),
        ("Offline", ["offline", "local", "standalone", "private", "no cloud", "internet", "no internet", "without internet"]),
    ]

    for label, words in keyword_map:
        if any(word in text for word in words):
            add(label)

    ant_hive_terms = ["ant", "ants", "hive", "colony", "swarm", "pheromone", "supercolony", "argentine ant", "argentine ants"]
    if any(term in text for term in ant_hive_terms):
        add("Mind")
        add("Swarm")
        add("Hive")
        add("Research")
        if any(term in text for term in ["offline", "local", "standalone", "private", "no cloud"]):
            add("Offline")

    ordered = ["Body", "Mind", "Safety", "App", "Mobile", "Process", "Research", "Income", "Memory", "Swarm", "Hive", "Offline"]
    labels = [label for label in ordered if label in labels]
    return labels if labels else ["Unknown"]


def _companion_thought_empty_inbox_v2mind_a():
    return {
        "schema_version": "V2MIND-A",
        "purpose": "Companion thought intake for explicit local/offline thought seeds.",
        "all_chat_memory": "deferred_to_V2MIND_B",
        "thoughts": [],
    }


def _companion_thought_load_inbox_v2mind_a():
    import json

    path = _companion_thought_paths_v2mind_a()["json"]
    if not os.path.exists(path):
        return _companion_thought_empty_inbox_v2mind_a(), ""

    text = read_file(path)
    try:
        loaded = json.loads(text) if text.strip() else _companion_thought_empty_inbox_v2mind_a()
    except Exception as e:
        return _companion_thought_empty_inbox_v2mind_a(), "Could not parse thought inbox JSON: " + str(e)

    if isinstance(loaded, list):
        loaded = {
            "schema_version": "V2MIND-A",
            "purpose": "Companion thought intake for explicit local/offline thought seeds.",
            "all_chat_memory": "deferred_to_V2MIND_B",
            "thoughts": loaded,
        }

    if not isinstance(loaded, dict):
        loaded = _companion_thought_empty_inbox_v2mind_a()
    if not isinstance(loaded.get("thoughts"), list):
        loaded["thoughts"] = []
    loaded.setdefault("schema_version", "V2MIND-A")
    loaded.setdefault("purpose", "Companion thought intake for explicit local/offline thought seeds.")
    loaded.setdefault("all_chat_memory", "deferred_to_V2MIND_B")
    return loaded, ""


def _companion_thought_suggested_topic_v2mind_a(thought):
    idea = str(thought.get("idea_text", "")).strip()
    if not idea:
        return "Review an empty Engel thought seed before promotion."
    return "Research how Engel should safely think about: " + idea


def _companion_thought_render_report_v2mind_a(inbox):
    thoughts = list(inbox.get("thoughts", []))
    unpromoted = [t for t in thoughts if not t.get("promoted")]
    promoted = [t for t in thoughts if t.get("promoted")]

    class_counts = {}
    for thought in thoughts:
        for label in thought.get("classification", []) or ["Unknown"]:
            class_counts[label] = class_counts.get(label, 0) + 1

    lines = [
        "# Companion Thought Inbox V2MIND-A",
        "",
        "Updated: " + now(),
        "",
        "Purpose:",
        "- Hold explicit thought seeds from Josh as local/offline Engel Mind material.",
        "- Keep new ideas safe as brood before any later promotion.",
        "- Support one Engel Mind with many local memory nests over time.",
        "",
        "Scope:",
        "- V2MIND-A captures explicit thought/idea inputs only.",
        "- All-chat memory is deferred to V2MIND-B.",
        "- Pheromone-style reinforcement/decay belongs to later V2SWARM-C.",
        "",
        "Counts:",
        "- Total thoughts: " + str(len(thoughts)),
        "- Unpromoted thoughts: " + str(len(unpromoted)),
        "- Promoted thoughts: " + str(len(promoted)),
        "",
        "## Classifications",
    ]

    if class_counts:
        for label in sorted(class_counts):
            lines.append("- " + label + ": " + str(class_counts[label]))
    else:
        lines.append("- none")

    lines += [
        "",
        "## Held Thoughts",
    ]

    if not thoughts:
        lines.append("- none")
    else:
        for thought in thoughts:
            lines += [
                "",
                "### " + str(thought.get("id", "unknown")),
                "- Timestamp: " + str(thought.get("timestamp", "")),
                "- Status: " + str(thought.get("status", "")),
                "- Promoted: " + str(bool(thought.get("promoted"))),
                "- Source command: " + str(thought.get("source_command", "")),
                "- Classification: " + ", ".join(thought.get("classification", []) or ["Unknown"]),
                "- Idea: " + str(thought.get("idea_text", "")),
                "- Suggested research-topic wording: " + _companion_thought_suggested_topic_v2mind_a(thought),
            ]
            if thought.get("intake_mode") or thought.get("v2mind_a2"):
                lines += [
                    "- Intake mode: " + str(thought.get("intake_mode", "")),
                    "- V2MIND-A2 natural language: " + str(bool(thought.get("v2mind_a2"))),
                ]

    lines += [
        "",
        "Safety:",
        "- Thought inbox is local.",
        "- No source edited.",
        "- No learning applied.",
        "- No research started.",
        "- No cloud fallback.",
        "- Authority order: Josh first, Guardian second, Engel/runtime below both.",
    ]
    return "\n".join(lines)


def _companion_thought_write_inbox_v2mind_a(inbox):
    import json

    paths = _companion_thought_paths_v2mind_a()
    write_file(paths["json"], json.dumps(inbox, indent=2))


def _companion_thought_refresh_report_v2mind_a(inbox):
    paths = _companion_thought_paths_v2mind_a()
    write_file(paths["report"], _companion_thought_render_report_v2mind_a(inbox))


def _companion_conversation_paths_v2mind_a2():
    return {
        "patterns_json": os.path.join(MEMORY_DIR, "COMPANION_CONVERSATION_PATTERNS_V2MIND_A2.json"),
        "patterns_report": os.path.join(REPORTS_DIR, "mind", "COMPANION_CONVERSATION_PATTERNS_V2MIND_A2.md"),
        "diagnose": os.path.join(REPORTS_DIR, "mind", "V2MIND_A2_COMPANION_LANGUAGE_EXPANSION_DIAGNOSE.md"),
    }


