def _companion_conversation_load_patterns_v2mind_a2():
    import json

    paths = _companion_conversation_paths_v2mind_a2()
    default = _companion_conversation_pattern_defaults_v2mind_a2()
    if not os.path.exists(paths["patterns_json"]):
        return default, "Pattern JSON missing; using built-in V2MIND-A2 defaults."
    try:
        text = read_file(paths["patterns_json"])
        data = json.loads(text) if text.strip() else default
        if not isinstance(data, dict):
            return default, "Pattern JSON did not contain an object; using built-in V2MIND-A2 defaults."
        return data, ""
    except Exception as exc:
        return default, "Pattern JSON read/parse warning: " + str(exc)


def _companion_thought_counts_v2mind_a(thoughts):
    class_counts = {}
    promoted = 0
    for thought in thoughts:
        if thought.get("promoted"):
            promoted += 1
        for label in thought.get("classification", []) or ["Unknown"]:
            class_counts[label] = class_counts.get(label, 0) + 1
    return len(thoughts), promoted, len(thoughts) - promoted, class_counts


def _companion_conversation_known_command_block_v2mind_a2(raw_text):
    text = str(raw_text or "").strip()
    lower = text.lower()
    if not lower:
        return True

    try:
        row = _safe_router_match_v2u(text)
        if row:
            return True
    except Exception:
        pass

    blocked_exact = {
        "ok", "okay", "yes", "no", "go", "continue", "done", "thanks", "thank you",
        "health", "health repair", "status", "help", "route regression matrix",
        "route regression status", "app setup status", "swarm status",
        "offline memory action gates review", "idea queue status", "idea queue review",
    }
    if lower in blocked_exact:
        return True

    blocked_prefixes = [
        "tool check ", "router check ", "permission check ", "backup ", "restore ",
        "app ", "swarm ", "offline memory ", "research ", "source ", "learning ",
        "patch ", "control ", "browser ", "open ", "notepad ", "mobile ", "batch ",
        "process ", "code ", "desktop ", "screenshot", "look", "approve ", "unapprove ",
        "scan ", "read ", "delete ", "install ", "launch ", "run ", "start ",
        "send ", "click ", "type ", "replace ", "rebuild ", "apply ",
    ]
    return any(lower.startswith(prefix) for prefix in blocked_prefixes)


def _companion_conversation_direct_risky_instruction_v2mind_a2(raw_text):
    lower = str(raw_text or "").strip().lower()
    risky_prefixes = [
        "edit ", "install ", "delete ", "send ", "launch ", "run ", "start ",
        "open ", "click ", "type ", "replace ", "rebuild ", "apply ", "write ",
        "create shortcut", "make startup", "add startup", "schedule ",
    ]
    return any(lower.startswith(prefix) for prefix in risky_prefixes)


def _companion_conversation_domain_signal_v2mind_a2(text):
    lower = str(text or "").lower()
    domain_terms = [
        "engel", "mind", "brain", "body", "memory", "remember", "thought", "idea",
        "companion", "offline", "local", "internet", "research", "safe", "safety",
        "guard", "guardian", "approval", "gate", "swarm", "hive", "colony", "nest",
        "nests", "ant", "ants", "argentine", "supercolony", "pheromone", "brood",
        "conversation", "chat", "lesson", "project", "alive",
    ]
    return any(term in lower for term in domain_terms)


def _companion_conversation_trim_idea_v2mind_a2(text):
    cleaned = " ".join(str(text or "").strip().split())
    return cleaned.strip(" \t\r\n:;,.!?\"'")


def _companion_conversation_strip_engel_prefix_v2mind_a2(text):
    raw = str(text or "").strip()
    lower = raw.lower()
    for prefix in ["engel, ", "engel "]:
        if lower.startswith(prefix):
            return raw[len(prefix):].strip()
    return raw


def _companion_conversation_vague_idea_v2mind_a2(idea):
    low = str(idea or "").strip().lower().strip(" .!?")
    if not low:
        return True
    vague = {
        "this", "that", "this idea", "this thought", "an idea", "the idea",
        "something", "something important", "it", "that idea", "that thought",
        "later", "for later",
    }
    return low in vague or len(low) < 8


def _companion_conversation_analyze_v2mind_a2(raw_text):
    raw = str(raw_text or "").strip()
    if not raw:
        return {"matched": False, "clarify": False, "reason": "empty", "idea_text": "", "source_command": ""}

    if _companion_conversation_known_command_block_v2mind_a2(raw):
        return {"matched": False, "clarify": False, "reason": "known_or_blocked_command", "idea_text": "", "source_command": ""}

    if _companion_conversation_direct_risky_instruction_v2mind_a2(raw):
        return {"matched": False, "clarify": False, "reason": "direct_risky_instruction", "idea_text": "", "source_command": ""}

    stripped = _companion_conversation_strip_engel_prefix_v2mind_a2(raw)
    lower = stripped.lower()
    candidates = []

    def add_candidate(source, idea):
        candidates.append((source, _companion_conversation_trim_idea_v2mind_a2(idea)))

    prefix_map = [
        ("Engel, I was thinking about", "i was thinking about "),
        ("I was thinking about", "i was thinking about "),
        ("I have been thinking about", "i have been thinking about "),
        ("let's think about", "let's think about "),
        ("lets think about", "lets think about "),
        ("can we think about", "can we think about "),
        ("I want to talk through", "i want to talk through "),
        ("I have an idea about", "i have an idea about "),
        ("I have an idea for", "i have an idea for "),
        ("what if", "what if "),
        ("could", "could "),
        ("here is something I want you to think about", "here is something i want you to think about"),
        ("I want you to remember this idea", "i want you to remember this idea"),
    ]
    for source, prefix in prefix_map:
        if lower.startswith(prefix):
            add_candidate(source, stripped[len(prefix):])
            break

    colon_prefixes = [
        ("hold this thought:", "hold this thought:"),
        ("hold onto this:", "hold onto this:"),
        ("remember this thought:", "remember this thought:"),
        ("this might be important:", "this might be important:"),
        ("this feels important:", "this feels important:"),
        ("save this as a thought:", "save this as a thought:"),
        ("keep this in your offline brain:", "keep this in your offline brain:"),
        ("this should be part of your Mind:", "this should be part of your mind:"),
    ]
    for source, prefix in colon_prefixes:
        if lower.startswith(prefix):
            add_candidate(source, stripped[len(prefix):])
            break

    if not candidates:
        clarify_phrases = {
            "hold this thought": "hold this thought",
            "hold onto this": "hold onto this",
            "remember this thought": "remember this thought",
            "this might be important": "this might be important",
            "this feels important": "this feels important",
            "save this as a thought": "save this as a thought",
            "keep this in your offline brain": "keep this in your offline brain",
            "this should be part of your mind": "this should be part of your Mind",
            "here is something i want you to think about": "here is something I want you to think about",
        }
        no_punct = lower.rstrip(" .!?")
        if no_punct in clarify_phrases:
            add_candidate(clarify_phrases[no_punct], "")

    body_mind_prefixes = [
        ("Engel, your Mind should", "your mind should "),
        ("your offline brain should", "your offline brain should "),
        ("your Body and Mind should", "your body and mind should "),
        ("your memory should", "your memory should "),
        ("your companion layer should", "your companion layer should "),
    ]
    for source, prefix in body_mind_prefixes:
        if lower.startswith(prefix):
            add_candidate(source, stripped)
            break

    if not candidates:
        hive_terms = [
            "hive mind", "swarm mind", "one colony", "many nests", "memory nests",
            "argentine ants", "argentine ant", "supercolony", "pheromone trails",
            "brood care", "caution pheromones",
        ]
        if any(term in lower for term in hive_terms) and _companion_conversation_domain_signal_v2mind_a2(stripped):
            add_candidate("natural hive/swarm design language", stripped)

    if not candidates:
        return {"matched": False, "clarify": False, "reason": "no_natural_intake_pattern", "idea_text": "", "source_command": ""}

    source, idea = candidates[0]
    if _companion_conversation_vague_idea_v2mind_a2(idea):
        return {"matched": False, "clarify": True, "reason": "needs_explicit_idea_text", "idea_text": "", "source_command": source}

    if not _companion_conversation_domain_signal_v2mind_a2(idea) and not _companion_conversation_domain_signal_v2mind_a2(raw):
        return {"matched": False, "clarify": True, "reason": "no_clear_mind_memory_project_signal", "idea_text": idea, "source_command": source}

    return {
        "matched": True,
        "clarify": False,
        "reason": "natural_companion_thought_intake",
        "idea_text": idea,
        "source_command": source,
    }


def companion_conversation_intake_match_v2mind_a2(raw_text):
    return _companion_conversation_analyze_v2mind_a2(raw_text)


def companion_conversation_extract_idea_v2mind_a2(raw_text):
    match = _companion_conversation_analyze_v2mind_a2(raw_text)
    return match.get("idea_text", "") if match.get("matched") else ""


def _companion_conversation_target_v2mind_a2(raw_text, idea):
    text = (str(raw_text or "") + " " + str(idea or "")).lower()
    if any(term in text for term in ["research", "study", "investigate", "source", "topic"]):
        return "OFFLINE_BRAIN_RESEARCH_SEED"
    return "OFFLINE_BRAIN_CONVERSATION_THOUGHT"


def _companion_conversation_clarification_v2mind_a2():
    return "\n".join([
        "# Thought Clarification",
        "",
        "I hear you. I'm not sure whether you want me to hold that as a thought seed.",
        "",
        "You can say:",
        "- hold this thought: ...",
        "- Engel, think about ...",
        "- remember this idea: ...",
        "",
        "Safety:",
        "- No thought captured.",
        "- No source edited.",
        "- No learning applied.",
        "- No research started.",
        "- No active recall enabled.",
        "- No cloud fallback.",
    ])


def companion_conversation_capture_v2mind_a2(raw_text, source_command=""):
    match = _companion_conversation_analyze_v2mind_a2(raw_text)
    if match.get("clarify"):
        return _companion_conversation_clarification_v2mind_a2()
    if not match.get("matched"):
        return ""

    data, error = _companion_thought_load_inbox_v2mind_a()
    if error:
        return "\n".join([
            "# Thought Not Held",
            "",
            "I hear you, but the local thought inbox needs review before I add to it.",
            "",
            "Reason:",
            "- " + error,
            "",
            "Safety:",
            "- Thought not captured.",
            "- No source edited.",
            "- No learning applied.",
            "- No research started.",
            "- No active recall enabled.",
            "- No cloud fallback.",
        ])

    idea = match.get("idea_text", "")
    source = source_command or match.get("source_command", "natural companion language")
    classification = _companion_thought_classification_v2mind_a(idea)
    timestamp = now()
    item = {
        "id": "V2MIND-A2-" + datetime.datetime.now().strftime("%Y%m%d_%H%M%S") + "-" + uuid.uuid4().hex[:8],
        "timestamp": timestamp,
        "raw_text": str(raw_text or "").strip(),
        "idea_text": idea,
        "source_command": source,
        "classification": classification,
        "status": "HELD",
        "target": _companion_conversation_target_v2mind_a2(raw_text, idea),
        "promoted": False,
        "safety_notes": [
            "Captured locally as natural companion-language thought intake.",
            "No source edited.",
            "No learning applied.",
            "No research started.",
            "No active recall enabled.",
            "No cloud fallback.",
        ],
        "intake_mode": "NATURAL_COMPANION_LANGUAGE",
        "v2mind_a2": True,
    }

    data.setdefault("thoughts", []).append(item)
    _companion_thought_write_inbox_v2mind_a(data)
    _companion_thought_refresh_report_v2mind_a(data)

    lines = [
        "# Thought Held",
        "",
        "I hear you.",
        "",
        "I'll hold this in my offline brain as a thought to keep working with:",
        "",
        "\"" + idea + "\"",
        "",
        "I'm holding it as part of:",
    ]
    lines += ["- " + label for label in classification]
    lines += [
        "",
        "What it means to me:",
        "- This is a companion thought seed, not an action.",
        "- I can later compare it with memory, research, swarm strategy, or approved lessons.",
        "- I will not act on it without Josh-first approval and Guardian safety gates.",
        "",
        "Safety:",
        "- Captured locally.",
        "- No source edited.",
        "- No learning applied.",
        "- No research started.",
        "- No active recall enabled.",
        "- No cloud fallback.",
    ]
    return "\n".join(lines)


def _companion_conversation_natural_capture_count_v2mind_a2():
    data, error = _companion_thought_load_inbox_v2mind_a()
    if error:
        return 0, error
    thoughts = data.get("thoughts", []) if isinstance(data, dict) else []
    count = 0
    for thought in thoughts:
        if thought.get("v2mind_a2") is True or thought.get("intake_mode") == "NATURAL_COMPANION_LANGUAGE":
            count += 1
    return count, ""


def companion_conversation_patterns_status_v2mind_a2():
    paths = _companion_conversation_paths_v2mind_a2()
    patterns, warning = _companion_conversation_load_patterns_v2mind_a2()
    natural_count, count_warning = _companion_conversation_natural_capture_count_v2mind_a2()
    groups = patterns.get("pattern_groups", {}) if isinstance(patterns, dict) else {}
    lines = [
        "# Companion Language Status V2MIND-A2",
        "",
        "Status: READ-ONLY / STATUS-ONLY",
        "",
        "Pattern files:",
        "- JSON exists: " + str(os.path.exists(paths["patterns_json"])) + " | " + paths["patterns_json"],
        "- Report exists: " + str(os.path.exists(paths["patterns_report"])) + " | " + paths["patterns_report"],
        "",
        "Pattern groups:",
    ]
    if groups:
        for name, examples in groups.items():
            lines.append("- " + str(name) + ": " + str(len(examples)))
    else:
        lines.append("- none")
    lines += [
        "",
        "Natural-language thought captures:",
        "- Count: " + str(natural_count),
    ]
    if warning:
        lines += ["", "Pattern warning:", "- " + warning]
    if count_warning:
        lines += ["", "Inbox warning:", "- " + count_warning]
    lines += [
        "",
        "Safety:",
        "- Read-only status.",
        "- Does not capture a thought.",
        "- Does not write LEARNING_LOG.md.",
        "- Does not write the research queue.",
        "- Does not start research.",
        "- Does not enable active recall.",
        "- Does not edit source or change behavior.",
    ]
    return "\n".join(lines)


def companion_conversation_patterns_review_v2mind_a2():
    paths = _companion_conversation_paths_v2mind_a2()
    report = read_file(paths["patterns_report"]) if os.path.exists(paths["patterns_report"]) else ""
    if report.strip():
        return report
    patterns, warning = _companion_conversation_load_patterns_v2mind_a2()
    groups = patterns.get("pattern_groups", {}) if isinstance(patterns, dict) else {}
    lines = [
        "# Companion Conversation Patterns V2MIND-A2",
        "",
        "Status: READ-ONLY / REPORT-ONLY",
        "",
        "Pattern report file is missing, so Engel is showing built-in pattern defaults.",
    ]
    if warning:
        lines += ["", "Warning:", "- " + warning]
    for name, examples in groups.items():
        lines += ["", "## " + str(name)]
        for example in examples:
            lines.append("- " + str(example))
    lines += [
        "",
        "Safety:",
        "- Review/report only.",
        "- Does not capture a thought.",
        "- Does not write LEARNING_LOG.md.",
        "- Does not write the research queue.",
        "- Does not start research.",
        "- Does not enable active recall.",
        "- Does not edit source or change behavior.",
    ]
    return "\n".join(lines)


def companion_thought_capture_v2mind_a(raw_text, source_command=""):
    data, error = _companion_thought_load_inbox_v2mind_a()
    if error:
        return "\n".join([
            "# Thought Not Held",
            "",
            "I hear you, but the local thought inbox needs review before I add to it.",
            "",
            "Reason:",
            "- " + error,
            "",
            "Safety:",
            "- Thought not captured.",
            "- No source edited.",
            "- No learning applied.",
            "- No research started.",
            "- No cloud fallback.",
        ])

    source = source_command or _companion_thought_source_command_v2mind_a(raw_text)
    idea = _companion_thought_extract_idea_v2mind_a(raw_text, source)
    if not idea:
        return "\n".join([
            "# Thought Not Held",
            "",
            "I hear you.",
            "",
            "Give me the idea after the command and I'll hold it in my offline brain.",
            "",
            "Examples:",
            "- think about Engel memory nests",
            "- remember this idea: Engel should compare approved lessons before changing behavior",
            "",
            "Safety:",
            "- Thought not captured.",
            "- No source edited.",
            "- No learning applied.",
            "- No research started.",
            "- No cloud fallback.",
        ])

    timestamp = now()
    item = {
        "id": "V2MIND-A-" + datetime.datetime.now().strftime("%Y%m%d_%H%M%S") + "-" + uuid.uuid4().hex[:8],
        "timestamp": timestamp,
        "raw_text": str(raw_text or "").strip(),
        "idea_text": idea,
        "source_command": source,
        "classification": _companion_thought_classification_v2mind_a(idea),
        "status": "HELD",
        "target": "OFFLINE_BRAIN_RESEARCH_SEED",
        "promoted": False,
        "safety_notes": [
            "Captured locally as an explicit thought seed.",
            "No source edited.",
            "No learning applied.",
            "No research started.",
            "No cloud fallback.",
        ],
    }

    data.setdefault("thoughts", []).append(item)
    _companion_thought_write_inbox_v2mind_a(data)
    _companion_thought_refresh_report_v2mind_a(data)

    lines = [
        "# Thought Held",
        "",
        "I hear you.",
        "",
        "I'll hold this in my offline brain:",
        "\"" + idea + "\"",
        "",
        "I will think about it as part of:",
    ]
    lines += ["- " + label for label in item["classification"]]
    lines += [
        "",
        "Why I am holding it:",
        "- This is a thought seed for Engel's local Mind.",
        "- It can later become research, a proposal, or an approved lesson.",
        "",
        "Safety:",
        "- Thought captured locally.",
        "- No source edited.",
        "- No learning applied.",
        "- No research started.",
        "- No cloud fallback.",
    ]
    return "\n".join(lines)


