def companion_thought_promote_v2mind_a(approval=""):
    if approval != "APPROVE":
        return "\n".join([
            "# Idea Queue Promotion Blocked",
            "",
            "Exact approval required:",
            "- idea queue promote APPROVE",
            "",
            "Safety:",
            "- No proposed-topic file written.",
            "- No JSON promotion flags changed.",
            "- No research queue edited.",
            "- No source edited.",
            "- No learning applied.",
            "- No research started.",
            "- No cloud fallback.",
        ])

    data, error = _companion_thought_load_inbox_v2mind_a()
    if error:
        return "\n".join([
            "# Idea Queue Promotion Blocked",
            "",
            "The local thought inbox needs review before promotion.",
            "",
            "Reason:",
            "- " + error,
            "",
            "Safety:",
            "- No proposed-topic file written.",
            "- No JSON promotion flags changed.",
            "- No research queue edited.",
            "- No source edited.",
            "- No learning applied.",
            "- No research started.",
            "- No cloud fallback.",
        ])

    thoughts = list(data.get("thoughts", []))
    unpromoted = [t for t in thoughts if not t.get("promoted")]
    if not unpromoted:
        return "\n".join([
            "# Idea Queue Promotion",
            "",
            "No unpromoted thought seeds found.",
            "",
            "Safety:",
            "- No proposed-topic file written.",
            "- No research queue edited.",
            "- No source edited.",
            "- No learning applied.",
            "- No research started.",
            "- No cloud fallback.",
        ])

    paths = _companion_thought_paths_v2mind_a()
    existing = read_file(paths["promoted_topics"])
    section_lines = [
        "## Promoted " + now(),
        "",
        "Purpose:",
        "- Proposed research topics promoted from V2MIND-A thought seeds.",
        "- Research is not started by this file.",
        "",
    ]
    for thought in unpromoted:
        section_lines += [
            "- Thought ID: " + str(thought.get("id", "unknown")),
            "  - Proposed topic: " + _companion_thought_suggested_topic_v2mind_a(thought),
            "  - Classification: " + ", ".join(thought.get("classification", []) or ["Unknown"]),
            "  - Source command: " + str(thought.get("source_command", "")),
            "  - Safety: proposed topic only; no research started.",
        ]

    section_lines += [
        "",
        "Safety:",
        "- Proposed-topic file only.",
        "- RESEARCH_GOALS_QUEUE_V1.md not edited.",
        "- LEARNING_LOG.md not edited.",
        "- No source edited.",
        "- No research started.",
        "- No cloud fallback.",
    ]

    header = ""
    if not existing.strip():
        header = "\n".join([
            "# Companion Thought Promoted Research Topics V2MIND-A",
            "",
            "This file holds proposed research topics promoted from explicit companion thought seeds.",
            "It is not a Research ON queue and does not start research.",
            "",
        ])
    new_text = (existing.rstrip() + "\n\n" if existing.strip() else header) + "\n".join(section_lines) + "\n"
    write_file(paths["promoted_topics"], new_text)

    promoted_at = now()
    promoted_ids = set([str(t.get("id", "")) for t in unpromoted])
    for thought in thoughts:
        if str(thought.get("id", "")) in promoted_ids:
            thought["promoted"] = True
            thought["status"] = "PROMOTED_TO_PROPOSED_RESEARCH_TOPIC"
            thought["promoted_timestamp"] = promoted_at
            thought["promoted_target"] = paths["promoted_topics"]
    data["thoughts"] = thoughts
    _companion_thought_write_inbox_v2mind_a(data)

    return "\n".join([
        "# Idea Queue Promotion Complete",
        "",
        "Promoted thought seeds:",
        str(len(unpromoted)),
        "",
        "Written to:",
        paths["promoted_topics"],
        "",
        "Safety:",
        "- Proposed-topic file written only after exact APPROVE.",
        "- JSON promotion flags updated after the proposed-topic write succeeded.",
        "- RESEARCH_GOALS_QUEUE_V1.md not edited.",
        "- LEARNING_LOG.md not edited.",
        "- No source edited.",
        "- No research started.",
        "- No cloud fallback.",
    ])


# ----------------------------------------------------------------------
# V2MIND-B Offline Conversation Memory Archive
# Archive-only. No distillation, recall, learning apply, research start, or cloud.
# ----------------------------------------------------------------------
def _offline_conversation_paths_v2mind_b():
    return {
        "archive": os.path.join(MEMORY_DIR, "OFFLINE_CONVERSATION_ARCHIVE_V2MIND_B.jsonl"),
        "index": os.path.join(MEMORY_DIR, "OFFLINE_CONVERSATION_INDEX_V2MIND_B.json"),
        "report": os.path.join(REPORTS_DIR, "mind", "OFFLINE_CONVERSATION_ARCHIVE_V2MIND_B.md"),
        "diagnose": os.path.join(REPORTS_DIR, "mind", "V2MIND_B_OFFLINE_CONVERSATION_ARCHIVE_DIAGNOSE.md"),
    }


def _offline_conversation_source_command_v2mind_b(raw_text):
    raw = str(raw_text or "").strip()
    lower = raw.lower()
    if lower == "offline memory archive note:" or lower.startswith("offline memory archive note:"):
        return "offline memory archive note:"
    if lower == "archive this memory:" or lower.startswith("archive this memory:"):
        return "archive this memory:"
    if lower == "remember this conversation:" or lower.startswith("remember this conversation:"):
        return "remember this conversation:"
    return ""


def _offline_conversation_extract_note_v2mind_b(raw_text, source_command=""):
    raw = str(raw_text or "").strip()
    source = source_command or _offline_conversation_source_command_v2mind_b(raw)
    prefixes = {
        "offline memory archive note:": ["offline memory archive note:"],
        "archive this memory:": ["archive this memory:"],
        "remember this conversation:": ["remember this conversation:"],
    }
    lower = raw.lower()
    for prefix in prefixes.get(source, []):
        if lower == prefix:
            return ""
        if lower.startswith(prefix):
            return " ".join(raw[len(prefix):].strip().split())
    return raw


def _offline_conversation_tags_v2mind_b(text):
    raw = str(text or "").lower()
    labels = []

    def add(label):
        if label not in labels:
            labels.append(label)

    keyword_map = [
        ("Body", ["body", "desktop", "window", "screen", "voice", "visual", "launcher", "shortcut", "exe", "alive"]),
        ("Mind", ["mind", "brain", "thought", "think", "reason", "reflection", "companion", "conscious", "identity"]),
        ("Memory", ["memory", "remember", "history", "archive", "log", "inbox", "lesson", "recall", "conversation"]),
        ("Offline", ["offline", "local", "standalone", "private", "no cloud", "without internet"]),
        ("Swarm", ["swarm", "trail", "scout", "reinforce", "pheromone"]),
        ("Hive", ["hive", "colony", "nest", "supercolony", "ant", "ants"]),
        ("Research", ["research", "study", "source", "brief", "topic", "investigate", "proposal"]),
        ("App", ["app", "ui", "gui", "route", "router", "tool", "command", "companion"]),
        ("Safety", ["safe", "safety", "guard", "guardian", "approval", "approve", "permission", "risk", "gate"]),
        ("Process", ["process", "pid", "runner", "loop", "cleanup", "batch", "scheduled task"]),
        ("Income", ["income", "money", "revenue", "business", "client", "sales", "profit"]),
        ("Drafting", ["draft", "drafting", "drawing", "cad", "plan", "roof", "construction", "estimate"]),
    ]
    for label, words in keyword_map:
        if any(word in raw for word in words):
            add(label)
    ordered = ["Body", "Mind", "Memory", "Offline", "Swarm", "Hive", "Research", "App", "Safety", "Process", "Income", "Drafting"]
    labels = [label for label in ordered if label in labels]
    return labels if labels else ["Unknown"]


def _offline_conversation_title_v2mind_b(text, fallback="Offline memory record"):
    clean = " ".join(str(text or "").strip().split())
    if not clean:
        return fallback
    if len(clean) > 90:
        return clean[:87].rstrip() + "..."
    return clean


def _offline_conversation_load_records_v2mind_b():
    import json

    path = _offline_conversation_paths_v2mind_b()["archive"]
    if not os.path.exists(path):
        return [], ""

    records = []
    warnings = []
    text = read_file(path)
    for line_number, line in enumerate(text.splitlines(), start=1):
        stripped = line.strip()
        if not stripped:
            continue
        try:
            row = json.loads(stripped)
            if isinstance(row, dict):
                records.append(row)
            else:
                warnings.append("Line " + str(line_number) + " is not a JSON object.")
        except Exception as e:
            warnings.append("Line " + str(line_number) + " could not be parsed: " + str(e))
    return records, "; ".join(warnings)


def _offline_conversation_stats_v2mind_b(records):
    tag_counts = {}
    last_timestamp = ""
    for record in records:
        timestamp = str(record.get("timestamp", ""))
        if timestamp and timestamp > last_timestamp:
            last_timestamp = timestamp
        for tag in record.get("tags", []) or ["Unknown"]:
            tag_counts[tag] = tag_counts.get(tag, 0) + 1
    return tag_counts, last_timestamp


def _offline_conversation_index_payload_v2mind_b(records, read_warning=""):
    paths = _offline_conversation_paths_v2mind_b()
    tag_counts, last_timestamp = _offline_conversation_stats_v2mind_b(records)
    return {
        "schema_version": "V2MIND-B",
        "purpose": "Offline conversation/work memory archive index.",
        "updated": now(),
        "archive_path": paths["archive"],
        "report_path": paths["report"],
        "record_count": len(records),
        "tag_counts": tag_counts,
        "last_archived_timestamp": last_timestamp,
        "read_warning": read_warning,
        "distillation_status": "DEFERRED_TO_V2MIND_C",
        "recall_status": "DEFERRED_TO_V2MIND_D",
        "approved_for_learning": False,
        "approved_for_research": False,
        "safety": [
            "Archive/index only.",
            "No LEARNING_LOG.md write.",
            "No RESEARCH_GOALS_QUEUE_V1.md write.",
            "No source apply.",
            "No research start.",
            "No cloud fallback.",
        ],
    }


def _offline_conversation_render_report_v2mind_b(records, read_warning=""):
    paths = _offline_conversation_paths_v2mind_b()
    tag_counts, last_timestamp = _offline_conversation_stats_v2mind_b(records)
    lines = [
        "# Offline Conversation Archive V2MIND-B",
        "",
        "Updated: " + now(),
        "",
        "Purpose:",
        "- Hold conversation and work-memory records locally in Engel's offline brain.",
        "- Keep this archive nest separate from thought seeds until later Mind phases.",
        "- Support one Engel Mind with many local memory nests over time.",
        "",
        "Scope:",
        "- V2MIND-B is archive-only.",
        "- Distillation/self-teaching is deferred to V2MIND-C.",
        "- Active recall into live Mind context is deferred to V2MIND-D.",
        "",
        "Paths:",
        "- Archive JSONL: " + paths["archive"],
        "- Index JSON: " + paths["index"],
        "- Report: " + paths["report"],
        "",
        "Counts:",
        "- Total records: " + str(len(records)),
        "- Last archived timestamp: " + (last_timestamp if last_timestamp else "none"),
        "",
        "## Tags",
    ]
    if tag_counts:
        for tag in sorted(tag_counts):
            lines.append("- " + tag + ": " + str(tag_counts[tag]))
    else:
        lines.append("- none")

    if read_warning:
        lines += ["", "Read warning:", "- " + read_warning]

    lines += ["", "## Recent Records"]
    recent = records[-10:]
    if not recent:
        lines.append("- none")
    else:
        for record in reversed(recent):
            lines += [
                "",
                "### " + str(record.get("id", "unknown")),
                "- Timestamp: " + str(record.get("timestamp", "")),
                "- Title: " + str(record.get("title", "")),
                "- Source type: " + str(record.get("source_type", "")),
                "- Source path: " + (str(record.get("source_path", "")) or "explicit user note"),
                "- Tags: " + ", ".join(record.get("tags", []) or ["Unknown"]),
                "- Safety classification: " + str(record.get("safety_classification", "")),
                "- Distillation status: " + str(record.get("distillation_status", "NOT_DISTILLED")),
                "- Recall status: " + str(record.get("recall_status", "NOT_ACTIVE")),
                "- Approved for learning: " + str(bool(record.get("approved_for_learning", False))),
                "- Approved for research: " + str(bool(record.get("approved_for_research", False))),
            ]

    lines += [
        "",
        "Safety:",
        "- Archive/report only.",
        "- Memory remains local in Engel's offline brain.",
        "- No learning applied.",
        "- No research started.",
        "- No source edited.",
        "- No cloud fallback.",
        "- Authority order: Josh first, Guardian second, Engel/runtime below both.",
    ]
    return "\n".join(lines)


def _offline_conversation_write_index_and_report_v2mind_b(records, read_warning=""):
    import json

    paths = _offline_conversation_paths_v2mind_b()
    write_file(paths["index"], json.dumps(_offline_conversation_index_payload_v2mind_b(records, read_warning), indent=2))
    write_file(paths["report"], _offline_conversation_render_report_v2mind_b(records, read_warning))


def _offline_conversation_append_record_v2mind_b(record):
    import json

    path = _offline_conversation_paths_v2mind_b()["archive"]
    append_file(path, json.dumps(record, ensure_ascii=True) + "\n")


def _offline_conversation_make_record_v2mind_b(raw_text_or_summary, source_type, source_path, archived_by_command, title="", notes=None):
    body = str(raw_text_or_summary or "").strip()
    return {
        "id": "V2MIND-B-" + datetime.datetime.now().strftime("%Y%m%d_%H%M%S") + "-" + uuid.uuid4().hex[:8],
        "timestamp": now(),
        "source_type": source_type,
        "source_path": source_path,
        "raw_text_or_summary": body,
        "title": title or _offline_conversation_title_v2mind_b(body),
        "tags": _offline_conversation_tags_v2mind_b(body),
        "safety_classification": "LOCAL_OFFLINE_ARCHIVE_ONLY",
        "archived_by_command": archived_by_command,
        "distillation_status": "NOT_DISTILLED",
        "recall_status": "NOT_ACTIVE",
        "approved_for_learning": False,
        "approved_for_research": False,
        "notes": notes or [
            "Archived locally only.",
            "No distillation in V2MIND-B.",
            "No active recall in V2MIND-B.",
            "No learning or research approval granted by this archive record.",
        ],
    }


def _offline_conversation_latest_local_source_v2mind_b():
    path = LOG_FILE
    if not os.path.exists(path):
        return None, "Preferred local work log not found: " + path
    text = read_file(path).strip()
    if not text:
        return None, "Preferred local work log is empty: " + path
    entries = []
    for chunk in text.split("\n## "):
        clean = chunk.strip()
        if not clean:
            continue
        if not clean.startswith("## "):
            clean = "## " + clean
        entries.append(clean)
    excerpt = "\n\n".join(entries[-8:]).strip() if entries else text[-12000:].strip()
    if len(excerpt) > 12000:
        excerpt = excerpt[-12000:].strip()
    return {
        "source_type": "local_engel_work_log",
        "source_path": path,
        "raw_text_or_summary": excerpt,
        "title": "Latest local Engel work log memory",
    }, ""


def offline_conversation_archive_status_v2mind_b():
    paths = _offline_conversation_paths_v2mind_b()
    records, read_warning = _offline_conversation_load_records_v2mind_b()
    tag_counts, last_timestamp = _offline_conversation_stats_v2mind_b(records)
    lines = [
        "# Offline Memory Status",
        "",
        "Status: " + ("READ_WARNING" if read_warning else "READY"),
        "",
        "I am holding this as local archive structure in my offline brain.",
        "",
        "Files:",
        "- Archive JSONL exists: " + str(os.path.exists(paths["archive"])),
        "- Index JSON exists: " + str(os.path.exists(paths["index"])),
        "- Markdown report exists: " + str(os.path.exists(paths["report"])),
        "",
        "Paths:",
        "- Archive JSONL: " + paths["archive"],
        "- Index JSON: " + paths["index"],
        "- Markdown report: " + paths["report"],
        "",
        "Counts:",
        "- Archived records: " + str(len(records)),
        "- Last archived timestamp: " + (last_timestamp if last_timestamp else "none"),
        "",
        "## Tag Counts",
    ]
    if tag_counts:
        for tag in sorted(tag_counts):
            lines.append("- " + tag + ": " + str(tag_counts[tag]))
    else:
        lines.append("- none")
    if read_warning:
        lines += ["", "Read warning:", "- " + read_warning]
    lines += [
        "",
        "Safety:",
        "- Read-only status.",
        "- No archive record created.",
        "- No distillation.",
        "- No active recall.",
        "- No LEARNING_LOG.md write.",
        "- No RESEARCH_GOALS_QUEUE_V1.md write.",
        "- No research started.",
        "- No cloud fallback.",
    ]
    return "\n".join(lines)


def offline_conversation_archive_review_v2mind_b():
    records, read_warning = _offline_conversation_load_records_v2mind_b()
    lines = [
        "# Offline Memory Review",
        "",
        "Status: " + ("READ_WARNING" if read_warning else "READY"),
        "",
        "I am reviewing only what is already archived in my local offline brain.",
        "",
        "Archived records: " + str(len(records)),
        "",
        "What is not done yet:",
        "- Distillation into lessons: NOT_DISTILLED / deferred to V2MIND-C.",
        "- Active recall into live Mind context: NOT_ACTIVE / deferred to V2MIND-D.",
        "- Learning/research approval: false by default.",
    ]
    if read_warning:
        lines += ["", "Read warning:", "- " + read_warning]
    lines += ["", "## Recent Archived Records"]
    recent = records[-8:]
    if not recent:
        lines.append("- none")
    else:
        for record in reversed(recent):
            lines += [
                "",
                "### " + str(record.get("id", "unknown")),
                "- Timestamp: " + str(record.get("timestamp", "")),
                "- Title: " + str(record.get("title", "")),
                "- Source type: " + str(record.get("source_type", "")),
                "- Tags: " + ", ".join(record.get("tags", []) or ["Unknown"]),
                "- Distillation status: " + str(record.get("distillation_status", "NOT_DISTILLED")),
                "- Recall status: " + str(record.get("recall_status", "NOT_ACTIVE")),
            ]
    lines += [
        "",
        "Safety:",
        "- Review/report only.",
        "- No archive record created.",
        "- No distillation.",
        "- No active recall.",
        "- No LEARNING_LOG.md write.",
        "- No RESEARCH_GOALS_QUEUE_V1.md write.",
        "- No research started.",
        "- No cloud fallback.",
    ]
    return "\n".join(lines)


