def _offline_memory_distillation_paths_v2mind_c():
    return {
        "proposals": os.path.join(MEMORY_DIR, "OFFLINE_MEMORY_DISTILLATION_PROPOSALS_V2MIND_C.json"),
        "index": os.path.join(MEMORY_DIR, "OFFLINE_MEMORY_DISTILLATION_INDEX_V2MIND_C.json"),
        "report": os.path.join(REPORTS_DIR, "mind", "OFFLINE_MEMORY_DISTILLATION_PROPOSALS_V2MIND_C.md"),
        "diagnose": os.path.join(REPORTS_DIR, "mind", "V2MIND_C_MEMORY_DISTILLATION_DIAGNOSE.md"),
    }


def _offline_memory_distillation_load_sources_v2mind_c():
    thought_path = _companion_thought_paths_v2mind_a()["json"]
    archive_path = _offline_conversation_paths_v2mind_b()["archive"]
    index_path = _offline_conversation_paths_v2mind_b()["index"]

    thought_exists = os.path.exists(thought_path)
    archive_exists = os.path.exists(archive_path)
    index_exists = os.path.exists(index_path)

    thought_data, thought_error = _companion_thought_load_inbox_v2mind_a()
    thoughts = list(thought_data.get("thoughts", []))
    records, archive_warning = _offline_conversation_load_records_v2mind_b()

    warnings = []
    if not thought_exists:
        warnings.append("V2MIND-A thought seed file missing: " + thought_path)
    if thought_error:
        warnings.append("V2MIND-A read warning: " + thought_error)
    if not archive_exists:
        warnings.append("V2MIND-B offline archive file missing: " + archive_path)
    if archive_warning:
        warnings.append("V2MIND-B archive read warning: " + archive_warning)

    return {
        "thought_path": thought_path,
        "archive_path": archive_path,
        "index_path": index_path,
        "thought_exists": thought_exists,
        "archive_exists": archive_exists,
        "index_exists": index_exists,
        "thoughts": thoughts,
        "records": records,
        "warnings": warnings,
    }


def _offline_memory_distillation_source_items_v2mind_c(sources):
    items = []
    for thought in sources.get("thoughts", []):
        text = str(thought.get("idea_text", "") or thought.get("raw_text", "")).strip()
        items.append({
            "id": str(thought.get("id", "unknown")),
            "type": "V2MIND-A_THOUGHT_SEED",
            "text": text,
            "tags": list(thought.get("classification", []) or []),
        })
    for record in sources.get("records", []):
        text = str(record.get("raw_text_or_summary", "") or record.get("title", "")).strip()
        items.append({
            "id": str(record.get("id", "unknown")),
            "type": "V2MIND-B_OFFLINE_ARCHIVE",
            "text": text,
            "tags": list(record.get("tags", []) or []),
        })
    return items


