def _offline_memory_distillation_matches_v2mind_c(items, spec):
    matches = []
    needles = [str(n).lower() for n in spec.get("needles", [])]
    for item in items:
        text = str(item.get("text", "")).lower()
        tags = " ".join(item.get("tags", []) or []).lower()
        haystack = text + " " + tags
        if any(needle in haystack for needle in needles):
            matches.append(item)
    return matches


def _offline_memory_distillation_confidence_v2mind_c(match_count):
    if match_count >= 3:
        return "HIGH"
    if match_count == 2:
        return "MEDIUM"
    return "LOW"


def _offline_memory_distillation_build_proposals_v2mind_c(sources):
    items = _offline_memory_distillation_source_items_v2mind_c(sources)
    proposals = []
    timestamp = now()
    for spec in _offline_memory_distillation_theme_specs_v2mind_c():
        matches = _offline_memory_distillation_matches_v2mind_c(items, spec)
        if not matches:
            continue
        source_ids = []
        source_types = []
        for item in matches:
            if item["id"] not in source_ids:
                source_ids.append(item["id"])
            if item["type"] not in source_types:
                source_types.append(item["type"])
        proposals.append({
            "id": "V2MIND-C-" + datetime.datetime.now().strftime("%Y%m%d_%H%M%S") + "-" + uuid.uuid4().hex[:8],
            "timestamp": timestamp,
            "source_ids": source_ids,
            "source_types": source_types,
            "theme": spec["theme"],
            "tags": spec["tags"],
            "candidate_lesson": spec["candidate_lesson"],
            "candidate_research_topic": spec["candidate_research_topic"],
            "candidate_swarm_or_hive_design_note": spec["candidate_swarm_or_hive_design_note"],
            "why_it_matters": spec["why_it_matters"],
            "safety_level": spec["safety_level"],
            "confidence": _offline_memory_distillation_confidence_v2mind_c(len(matches)),
            "status": "PROPOSED",
            "applied_to_learning": False,
            "added_to_research_queue": False,
            "active_recall_enabled": False,
            "requires_review": True,
            "requires_approve_to_apply": True,
            "notes": [
                "Proposal only.",
                "Not written to LEARNING_LOG.md.",
                "Not added to RESEARCH_GOALS_QUEUE_V1.md.",
                "Research was not started.",
                "Active recall was not enabled.",
                "Source and behavior were not changed.",
            ],
        })
    return proposals


def _offline_memory_distillation_theme_preview_v2mind_c(sources):
    items = _offline_memory_distillation_source_items_v2mind_c(sources)
    rows = []
    for spec in _offline_memory_distillation_theme_specs_v2mind_c():
        matches = _offline_memory_distillation_matches_v2mind_c(items, spec)
        if matches:
            rows.append({
                "theme": spec["theme"],
                "source_count": len(matches),
                "safety_level": spec["safety_level"],
                "confidence": _offline_memory_distillation_confidence_v2mind_c(len(matches)),
                "tags": spec["tags"],
            })
    return rows


def _offline_memory_distillation_index_payload_v2mind_c(proposals, sources):
    paths = _offline_memory_distillation_paths_v2mind_c()
    theme_counts = {}
    safety_counts = {}
    confidence_counts = {}
    for proposal in proposals:
        theme_counts[proposal["theme"]] = theme_counts.get(proposal["theme"], 0) + 1
        safety_counts[proposal["safety_level"]] = safety_counts.get(proposal["safety_level"], 0) + 1
        confidence_counts[proposal["confidence"]] = confidence_counts.get(proposal["confidence"], 0) + 1
    return {
        "schema_version": "V2MIND-C",
        "purpose": "Offline memory distillation proposal index.",
        "updated": now(),
        "proposal_path": paths["proposals"],
        "report_path": paths["report"],
        "proposal_count": len(proposals),
        "theme_counts": theme_counts,
        "safety_level_counts": safety_counts,
        "confidence_counts": confidence_counts,
        "source_counts": {
            "thought_seed_count": len(sources.get("thoughts", [])),
            "offline_archive_record_count": len(sources.get("records", [])),
        },
        "applied_to_learning": False,
        "added_to_research_queue": False,
        "active_recall_enabled": False,
        "safety": [
            "Proposal/index/report only.",
            "No LEARNING_LOG.md write.",
            "No RESEARCH_GOALS_QUEUE_V1.md write.",
            "No source apply.",
            "No learning apply.",
            "No active recall.",
            "No research start.",
            "No cloud fallback.",
        ],
    }


def _offline_memory_distillation_render_report_v2mind_c(proposals, sources):
    paths = _offline_memory_distillation_paths_v2mind_c()
    lines = [
        "# Offline Memory Distillation Proposals V2MIND-C",
        "",
        "Updated: " + now(),
        "",
        "Purpose:",
        "- Prepare proposal-only self-teaching candidates from local memory nests.",
        "- Keep V2MIND-C separate from learning, research queueing, and active recall.",
        "- Preserve one cooperative offline Mind colony under Josh-first approval and Guardian safety gates.",
        "",
        "Sources:",
        "- V2MIND-A thought seeds: " + str(len(sources.get("thoughts", []))),
        "- V2MIND-B offline archive records: " + str(len(sources.get("records", []))),
        "",
        "Paths:",
        "- Proposals JSON: " + paths["proposals"],
        "- Index JSON: " + paths["index"],
        "- Report: " + paths["report"],
        "",
        "Proposal count: " + str(len(proposals)),
        "",
        "## Proposals",
    ]
    if not proposals:
        lines.append("- none")
    else:
        for proposal in proposals:
            lines += [
                "",
                "### " + str(proposal.get("id", "unknown")),
                "- Theme: " + str(proposal.get("theme", "")),
                "- Tags: " + ", ".join(proposal.get("tags", []) or ["Unknown"]),
                "- Safety level: " + str(proposal.get("safety_level", "")),
                "- Confidence: " + str(proposal.get("confidence", "")),
                "- Status: " + str(proposal.get("status", "")),
                "- Source IDs: " + ", ".join(proposal.get("source_ids", []) or ["none"]),
                "- Candidate lesson: " + str(proposal.get("candidate_lesson", "")),
                "- Candidate research topic: " + str(proposal.get("candidate_research_topic", "")),
                "- Candidate swarm/hive design note: " + str(proposal.get("candidate_swarm_or_hive_design_note", "")),
                "- Why it matters: " + str(proposal.get("why_it_matters", "")),
                "- Applied to learning: " + str(bool(proposal.get("applied_to_learning", False))),
                "- Added to research queue: " + str(bool(proposal.get("added_to_research_queue", False))),
                "- Active recall enabled: " + str(bool(proposal.get("active_recall_enabled", False))),
                "- Requires review: " + str(bool(proposal.get("requires_review", True))),
                "- Requires APPROVE to apply: " + str(bool(proposal.get("requires_approve_to_apply", True))),
            ]

    lines += [
        "",
        "Safety:",
        "- Proposal/report only.",
        "- These are not applied lessons.",
        "- These are not active recall.",
        "- Research was not started.",
        "- LEARNING_LOG.md was not written.",
        "- RESEARCH_GOALS_QUEUE_V1.md was not written.",
        "- Source and behavior were not changed.",
        "- No cloud fallback.",
    ]
    return "\n".join(lines)


def _offline_memory_distillation_write_outputs_v2mind_c(proposals, sources):
    import json

    paths = _offline_memory_distillation_paths_v2mind_c()
    payload = {
        "schema_version": "V2MIND-C",
        "generated_at": now(),
        "proposal_count": len(proposals),
        "sources": {
            "thought_seed_file": sources.get("thought_path", ""),
            "offline_archive_file": sources.get("archive_path", ""),
            "thought_seed_count": len(sources.get("thoughts", [])),
            "offline_archive_record_count": len(sources.get("records", [])),
        },
        "proposals": proposals,
        "safety": {
            "proposal_only": True,
            "applied_to_learning": False,
            "added_to_research_queue": False,
            "active_recall_enabled": False,
            "research_started": False,
            "source_changed": False,
            "cloud_fallback": False,
        },
    }
    write_file(paths["proposals"], json.dumps(payload, indent=2))
    write_file(paths["index"], json.dumps(_offline_memory_distillation_index_payload_v2mind_c(proposals, sources), indent=2))
    write_file(paths["report"], _offline_memory_distillation_render_report_v2mind_c(proposals, sources))


