# V2MIND-D Distillation Proposal Routing Review
# Routing/review only. No learning, research queue, active recall, source apply, or cloud.
# ----------------------------------------------------------------------
def _offline_memory_proposal_routing_paths_v2mind_d():
    return {
        "routing": os.path.join(MEMORY_DIR, "OFFLINE_MEMORY_PROPOSAL_ROUTING_V2MIND_D.json"),
        "index": os.path.join(MEMORY_DIR, "OFFLINE_MEMORY_PROPOSAL_ROUTING_INDEX_V2MIND_D.json"),
        "report": os.path.join(REPORTS_DIR, "mind", "OFFLINE_MEMORY_PROPOSAL_ROUTING_V2MIND_D.md"),
        "diagnose": os.path.join(REPORTS_DIR, "mind", "V2MIND_D_DISTILLATION_ROUTING_DIAGNOSE.md"),
    }


def _offline_memory_proposal_routing_load_source_v2mind_d():
    import json

    distill_paths = _offline_memory_distillation_paths_v2mind_c()
    proposal_path = distill_paths["proposals"]
    index_path = distill_paths["index"]
    report_path = distill_paths["report"]
    warnings = []
    proposals = []
    data = {}

    if not os.path.exists(proposal_path):
        warnings.append("V2MIND-C proposal file missing: " + proposal_path)
    else:
        try:
            data = json.loads(read_file(proposal_path))
            if not isinstance(data, dict):
                warnings.append("V2MIND-C proposal file is not a JSON object.")
            else:
                proposals = data.get("proposals", [])
                if not isinstance(proposals, list):
                    warnings.append("V2MIND-C proposals field is not a list.")
                    proposals = []
        except Exception as e:
            warnings.append("V2MIND-C proposal file could not be parsed: " + str(e))

    return {
        "proposal_path": proposal_path,
        "index_path": index_path,
        "report_path": report_path,
        "proposal_exists": os.path.exists(proposal_path),
        "index_exists": os.path.exists(index_path),
        "report_exists": os.path.exists(report_path),
        "proposals": proposals,
        "warnings": warnings,
        "raw": data,
    }


def _offline_memory_proposal_routing_categories_v2mind_d(proposal):
    theme = str(proposal.get("theme", "")).lower()
    safety = str(proposal.get("safety_level", "")).upper()
    categories = []

    def add(category):
        if category not in categories:
            categories.append(category)

    if theme in ["offline brain", "memory nests"]:
        add("POSSIBLE_RECALL_LATER")
        add("POSSIBLE_SWARM_DESIGN_LATER")
    elif theme == "chat/work memory":
        add("POSSIBLE_RECALL_LATER")
        add("HOLD_FOR_LATER")
    elif theme == "approved lessons":
        add("POSSIBLE_LEARNING_LATER")
        add("CAUTION_ONLY")
    elif "argentine" in theme or "supercolony" in theme or "hive" in theme:
        add("POSSIBLE_SWARM_DESIGN_LATER")
        add("POSSIBLE_RESEARCH_LATER")
    elif theme == "safety guardrails":
        add("CAUTION_ONLY")
        add("POSSIBLE_LEARNING_LATER")
    elif theme == "engel body/mind":
        add("CAUTION_ONLY")
        add("HOLD_FOR_LATER")
    else:
        add("HOLD_FOR_LATER")

    if safety == "CAUTION" and "CAUTION_ONLY" not in categories and theme not in ["argentine ants / supercolony / hive mind"]:
        add("CAUTION_ONLY")

    return categories


def _offline_memory_proposal_routing_next_action_v2mind_d(proposal, categories):
    theme = str(proposal.get("theme", ""))
    if "CAUTION_ONLY" in categories and len(categories) == 1:
        return "Hold for Josh-first approval and Guardian safety review only; do not apply, queue, recall, or act."
    if theme == "Argentine ants / supercolony / hive mind":
        return "Keep as future swarm/hive design note and possible research candidate; do not make active behavior."
    if "POSSIBLE_RECALL_LATER" in categories:
        return "Hold for a later active-recall design review with explicit APPROVE; no recall is enabled now."
    if "POSSIBLE_LEARNING_LATER" in categories:
        return "Hold for a later lesson-adoption review with explicit APPROVE; no learning is applied now."
    if "POSSIBLE_RESEARCH_LATER" in categories:
        return "Hold as a possible future research topic; do not write the research queue now."
    if "POSSIBLE_SWARM_DESIGN_LATER" in categories:
        return "Hold as a future swarm/hive design note; no swarm behavior changes now."
    return "Hold for later review."


def _offline_memory_proposal_routing_reason_v2mind_d(proposal, categories):
    theme = str(proposal.get("theme", ""))
    safety = str(proposal.get("safety_level", ""))
    confidence = str(proposal.get("confidence", ""))
    return (
        "Theme '" + theme + "' with safety=" + safety + " and confidence=" + confidence +
        " maps to " + ", ".join(categories) +
        " for future review only. Josh-first approval and Guardian safety review remain required before any action."
    )


def _offline_memory_proposal_routing_build_v2mind_d(proposals):
    routed = []
    timestamp = now()
    for proposal in proposals:
        categories = _offline_memory_proposal_routing_categories_v2mind_d(proposal)
        routed.append({
            "id": "V2MIND-D-" + datetime.datetime.now().strftime("%Y%m%d_%H%M%S") + "-" + uuid.uuid4().hex[:8],
            "timestamp": timestamp,
            "source_proposal_id": str(proposal.get("id", "unknown")),
            "source_theme": str(proposal.get("theme", "")),
            "source_safety_level": str(proposal.get("safety_level", "")),
            "source_confidence": str(proposal.get("confidence", "")),
            "routing_categories": categories,
            "recommended_next_action": _offline_memory_proposal_routing_next_action_v2mind_d(proposal, categories),
            "reason": _offline_memory_proposal_routing_reason_v2mind_d(proposal, categories),
            "future_approval_required": True,
            "applied_to_learning": False,
            "added_to_research_queue": False,
            "active_recall_enabled": False,
            "source_changed": False,
            "status": "ROUTED_PROPOSAL_ONLY",
            "notes": [
                "Routing review only.",
                "Nothing approved by V2MIND-D.",
                "Nothing applied to LEARNING_LOG.md.",
                "Nothing added to RESEARCH_GOALS_QUEUE_V1.md.",
                "Research was not started.",
                "Active recall was not enabled.",
                "Source and behavior were not changed.",
            ],
        })
    return routed


def _offline_memory_proposal_routing_counts_v2mind_d(routed):
    category_counts = {}
    safety_counts = {}
    for item in routed:
        safety = item.get("source_safety_level", "Unknown")
        safety_counts[safety] = safety_counts.get(safety, 0) + 1
        for category in item.get("routing_categories", []) or ["HOLD_FOR_LATER"]:
            category_counts[category] = category_counts.get(category, 0) + 1
    return category_counts, safety_counts


def _offline_memory_proposal_routing_index_payload_v2mind_d(routed, source):
    paths = _offline_memory_proposal_routing_paths_v2mind_d()
    category_counts, safety_counts = _offline_memory_proposal_routing_counts_v2mind_d(routed)
    return {
        "schema_version": "V2MIND-D",
        "purpose": "Offline memory proposal routing index.",
        "updated": now(),
        "routing_path": paths["routing"],
        "report_path": paths["report"],
        "source_proposal_path": source.get("proposal_path", ""),
        "source_proposal_count": len(source.get("proposals", [])),
        "routed_count": len(routed),
        "category_counts": category_counts,
        "source_safety_level_counts": safety_counts,
        "future_approval_required": True,
        "nothing_approved": True,
        "applied_to_learning": False,
        "added_to_research_queue": False,
        "active_recall_enabled": False,
        "source_changed": False,
        "safety": [
            "Routing/index/report only.",
            "No LEARNING_LOG.md write.",
            "No RESEARCH_GOALS_QUEUE_V1.md write.",
            "No source apply.",
            "No learning apply.",
            "No active recall.",
            "No research start.",
            "No cloud fallback.",
        ],
    }


def _offline_memory_proposal_routing_render_report_v2mind_d(routed, source):
    paths = _offline_memory_proposal_routing_paths_v2mind_d()
    category_counts, safety_counts = _offline_memory_proposal_routing_counts_v2mind_d(routed)
    lines = [
        "# Offline Memory Proposal Routing V2MIND-D",
        "",
        "Updated: " + now(),
        "",
        "Purpose:",
        "- Sort V2MIND-C proposal seeds into possible future paths.",
        "- Keep routing review-only; do not approve or apply any path.",
        "- Preserve Engel's offline Mind colony under Josh-first approval and Guardian safety gates.",
        "",
        "Source:",
        "- V2MIND-C proposal file: " + source.get("proposal_path", ""),
        "- Source proposal count: " + str(len(source.get("proposals", []))),
        "",
        "Outputs:",
        "- Routing JSON: " + paths["routing"],
        "- Index JSON: " + paths["index"],
        "- Report: " + paths["report"],
        "",
        "Routed count: " + str(len(routed)),
        "",
        "## Category Counts",
    ]
    if category_counts:
        for category in sorted(category_counts):
            lines.append("- " + category + ": " + str(category_counts[category]))
    else:
        lines.append("- none")

    lines += ["", "## Source Safety Counts"]
    if safety_counts:
        for safety in sorted(safety_counts):
            lines.append("- " + safety + ": " + str(safety_counts[safety]))
    else:
        lines.append("- none")

    lines += ["", "## Routed Items"]
    if not routed:
        lines.append("- none")
    else:
        for item in routed:
            lines += [
                "",
                "### " + str(item.get("id", "unknown")),
                "- Source proposal ID: " + str(item.get("source_proposal_id", "")),
                "- Source theme: " + str(item.get("source_theme", "")),
                "- Source safety level: " + str(item.get("source_safety_level", "")),
                "- Source confidence: " + str(item.get("source_confidence", "")),
                "- Routing categories: " + ", ".join(item.get("routing_categories", []) or ["HOLD_FOR_LATER"]),
                "- Recommended next action: " + str(item.get("recommended_next_action", "")),
                "- Reason: " + str(item.get("reason", "")),
                "- Future approval required: " + str(bool(item.get("future_approval_required", True))),
                "- Applied to learning: " + str(bool(item.get("applied_to_learning", False))),
                "- Added to research queue: " + str(bool(item.get("added_to_research_queue", False))),
                "- Active recall enabled: " + str(bool(item.get("active_recall_enabled", False))),
                "- Source changed: " + str(bool(item.get("source_changed", False))),
                "- Status: " + str(item.get("status", "")),
            ]

    lines += [
        "",
        "Safety:",
        "- Routing/report only.",
        "- Nothing approved.",
        "- Nothing applied.",
        "- No active recall enabled.",
        "- Research was not started.",
        "- LEARNING_LOG.md was not written.",
        "- RESEARCH_GOALS_QUEUE_V1.md was not written.",
        "- Source and behavior were not changed.",
        "- No cloud fallback.",
    ]
    return "\n".join(lines)


def _offline_memory_proposal_routing_write_outputs_v2mind_d(routed, source):
    import json

    paths = _offline_memory_proposal_routing_paths_v2mind_d()
    payload = {
        "schema_version": "V2MIND-D",
        "generated_at": now(),
        "source_proposal_path": source.get("proposal_path", ""),
        "source_proposal_count": len(source.get("proposals", [])),
        "routed_count": len(routed),
        "routed_items": routed,
        "safety": {
            "routing_review_only": True,
            "nothing_approved": True,
            "applied_to_learning": False,
            "added_to_research_queue": False,
            "active_recall_enabled": False,
            "research_started": False,
            "source_changed": False,
            "cloud_fallback": False,
        },
    }
    write_file(paths["routing"], json.dumps(payload, indent=2))
    write_file(paths["index"], json.dumps(_offline_memory_proposal_routing_index_payload_v2mind_d(routed, source), indent=2))
    write_file(paths["report"], _offline_memory_proposal_routing_render_report_v2mind_d(routed, source))


def _offline_memory_proposal_routing_load_routing_v2mind_d():
    import json

    paths = _offline_memory_proposal_routing_paths_v2mind_d()
    if not os.path.exists(paths["routing"]):
        return None, ""
    try:
        data = json.loads(read_file(paths["routing"]))
        if not isinstance(data, dict):
            return None, "Routing file is not a JSON object."
        return data, ""
    except Exception as e:
        return None, "Routing file could not be parsed: " + str(e)


