# ----------------------------------------------------------------------
# V2MIND-E Routed Proposal Action Gates
# Gates/plans only. No gate execution, learning, research queue, recall, source apply, or cloud.
# ----------------------------------------------------------------------
def _offline_memory_action_gates_paths_v2mind_e():
    return {
        "gates": os.path.join(MEMORY_DIR, "OFFLINE_MEMORY_ACTION_GATES_V2MIND_E.json"),
        "index": os.path.join(MEMORY_DIR, "OFFLINE_MEMORY_ACTION_GATES_INDEX_V2MIND_E.json"),
        "report": os.path.join(REPORTS_DIR, "mind", "OFFLINE_MEMORY_ACTION_GATES_V2MIND_E.md"),
        "diagnose": os.path.join(REPORTS_DIR, "mind", "V2MIND_E_ROUTED_ACTION_GATES_DIAGNOSE.md"),
    }


def _offline_memory_action_gates_load_source_v2mind_e():
    import json

    routing_paths = _offline_memory_proposal_routing_paths_v2mind_d()
    routing_path = routing_paths["routing"]
    index_path = routing_paths["index"]
    report_path = routing_paths["report"]
    warnings = []
    routed_items = []
    data = {}

    if not os.path.exists(routing_path):
        warnings.append("V2MIND-D routing file missing: " + routing_path)
    else:
        try:
            data = json.loads(read_file(routing_path))
            if not isinstance(data, dict):
                warnings.append("V2MIND-D routing file is not a JSON object.")
            else:
                routed_items = data.get("routed_items", [])
                if not isinstance(routed_items, list):
                    warnings.append("V2MIND-D routed_items field is not a list.")
                    routed_items = []
        except Exception as e:
            warnings.append("V2MIND-D routing file could not be parsed: " + str(e))

    return {
        "routing_path": routing_path,
        "index_path": index_path,
        "report_path": report_path,
        "routing_exists": os.path.exists(routing_path),
        "index_exists": os.path.exists(index_path),
        "report_exists": os.path.exists(report_path),
        "routed_items": routed_items,
        "warnings": warnings,
        "raw": data,
    }


def _offline_memory_action_gates_gate_categories_v2mind_e(routing_categories):
    mapping = {
        "POSSIBLE_LEARNING_LATER": "LEARNING_PROPOSAL_GATE",
        "POSSIBLE_RESEARCH_LATER": "RESEARCH_TOPIC_GATE",
        "POSSIBLE_SWARM_DESIGN_LATER": "SWARM_DESIGN_GATE",
        "POSSIBLE_RECALL_LATER": "ACTIVE_RECALL_GATE",
        "HOLD_FOR_LATER": "HOLD_GATE",
        "CAUTION_ONLY": "CAUTION_GATE",
    }
    gates = []
    for category in routing_categories or []:
        gate = mapping.get(str(category), "HOLD_GATE")
        if gate not in gates:
            gates.append(gate)
    return gates if gates else ["HOLD_GATE"]


def _offline_memory_action_gates_future_command_v2mind_e(gate_categories):
    if "CAUTION_GATE" in gate_categories:
        return "FUTURE_ONLY: Josh-first approval and Guardian safety review caution gate before any other action."
    if "LEARNING_PROPOSAL_GATE" in gate_categories:
        return "FUTURE_ONLY: create a reviewed learning proposal; do not write LEARNING_LOG.md from V2MIND-E."
    if "RESEARCH_TOPIC_GATE" in gate_categories:
        return "FUTURE_ONLY: create a reviewed research-topic proposal; do not write RESEARCH_GOALS_QUEUE_V1.md from V2MIND-E."
    if "SWARM_DESIGN_GATE" in gate_categories:
        return "FUTURE_ONLY: create a swarm/hive design proposal; do not change swarm behavior from V2MIND-E."
    if "ACTIVE_RECALL_GATE" in gate_categories:
        return "FUTURE_ONLY: create an active-recall candidate review; do not enable recall from V2MIND-E."
    return "FUTURE_ONLY: hold for later Josh-first approval and Guardian safety review."


def _offline_memory_action_gates_build_v2mind_e(routed_items):
    gates = []
    timestamp = now()
    for routed in routed_items:
        routing_categories = list(routed.get("routing_categories", []) or [])
        gate_categories = _offline_memory_action_gates_gate_categories_v2mind_e(routing_categories)
        gates.append({
            "id": "V2MIND-E-" + datetime.datetime.now().strftime("%Y%m%d_%H%M%S") + "-" + uuid.uuid4().hex[:8],
            "timestamp": timestamp,
            "source_routing_id": str(routed.get("id", "unknown")),
            "source_theme": str(routed.get("source_theme", "")),
            "routing_categories": routing_categories,
            "gate_categories": gate_categories,
            "recommended_future_command": _offline_memory_action_gates_future_command_v2mind_e(gate_categories),
            "approval_required": True,
            "approved_now": False,
            "executed_now": False,
            "applied_to_learning": False,
            "added_to_research_queue": False,
            "active_recall_enabled": False,
            "source_changed": False,
            "safety_level": str(routed.get("source_safety_level", "")),
            "status": "GATE_CREATED_NOT_EXECUTED",
            "notes": [
                "Gate plan only.",
                "Gate is not approved.",
                "Gate is not executed.",
                "No LEARNING_LOG.md write.",
                "No RESEARCH_GOALS_QUEUE_V1.md write.",
                "Research was not started.",
                "Active recall was not enabled.",
                "Source and behavior were not changed.",
            ],
        })
    return gates


def _offline_memory_action_gates_counts_v2mind_e(gates):
    gate_counts = {}
    safety_counts = {}
    for gate in gates:
        safety = gate.get("safety_level", "Unknown") or "Unknown"
        safety_counts[safety] = safety_counts.get(safety, 0) + 1
        for category in gate.get("gate_categories", []) or ["HOLD_GATE"]:
            gate_counts[category] = gate_counts.get(category, 0) + 1
    return gate_counts, safety_counts


def _offline_memory_action_gates_index_payload_v2mind_e(gates, source):
    paths = _offline_memory_action_gates_paths_v2mind_e()
    gate_counts, safety_counts = _offline_memory_action_gates_counts_v2mind_e(gates)
    return {
        "schema_version": "V2MIND-E",
        "purpose": "Offline memory routed action gates index.",
        "updated": now(),
        "gates_path": paths["gates"],
        "report_path": paths["report"],
        "source_routing_path": source.get("routing_path", ""),
        "source_routed_count": len(source.get("routed_items", [])),
        "gate_count": len(gates),
        "gate_category_counts": gate_counts,
        "source_safety_level_counts": safety_counts,
        "approval_required": True,
        "approved_now": False,
        "executed_now": False,
        "applied_to_learning": False,
        "added_to_research_queue": False,
        "active_recall_enabled": False,
        "source_changed": False,
        "safety": [
            "Gate/index/report only.",
            "No gate execution.",
            "No LEARNING_LOG.md write.",
            "No RESEARCH_GOALS_QUEUE_V1.md write.",
            "No source apply.",
            "No learning apply.",
            "No active recall.",
            "No research start.",
            "No cloud fallback.",
        ],
    }


def _offline_memory_action_gates_render_report_v2mind_e(gates, source):
    paths = _offline_memory_action_gates_paths_v2mind_e()
    gate_counts, safety_counts = _offline_memory_action_gates_counts_v2mind_e(gates)
    lines = [
        "# Offline Memory Action Gates V2MIND-E",
        "",
        "Updated: " + now(),
        "",
        "Purpose:",
        "- Create safe future action gates from V2MIND-D routed proposal items.",
        "- Keep gates as plans only; gates are not actions.",
        "- Keep authority fixed at every future gate: Josh first, Guardian second, Engel/runtime below both.",
        "",
        "Source:",
        "- V2MIND-D routing file: " + source.get("routing_path", ""),
        "- Source routed count: " + str(len(source.get("routed_items", []))),
        "",
        "Outputs:",
        "- Gates JSON: " + paths["gates"],
        "- Index JSON: " + paths["index"],
        "- Report: " + paths["report"],
        "",
        "Gate count: " + str(len(gates)),
        "",
        "## Gate Category Counts",
    ]
    if gate_counts:
        for category in sorted(gate_counts):
            lines.append("- " + category + ": " + str(gate_counts[category]))
    else:
        lines.append("- none")

    lines += ["", "## Source Safety Counts"]
    if safety_counts:
        for safety in sorted(safety_counts):
            lines.append("- " + safety + ": " + str(safety_counts[safety]))
    else:
        lines.append("- none")

    lines += ["", "## Gates"]
    if not gates:
        lines.append("- none")
    else:
        for gate in gates:
            lines += [
                "",
                "### " + str(gate.get("id", "unknown")),
                "- Source routing ID: " + str(gate.get("source_routing_id", "")),
                "- Source theme: " + str(gate.get("source_theme", "")),
                "- Routing categories: " + ", ".join(gate.get("routing_categories", []) or ["HOLD_FOR_LATER"]),
                "- Gate categories: " + ", ".join(gate.get("gate_categories", []) or ["HOLD_GATE"]),
                "- Recommended future command: " + str(gate.get("recommended_future_command", "")),
                "- Approval required: " + str(bool(gate.get("approval_required", True))),
                "- Approved now: " + str(bool(gate.get("approved_now", False))),
                "- Executed now: " + str(bool(gate.get("executed_now", False))),
                "- Applied to learning: " + str(bool(gate.get("applied_to_learning", False))),
                "- Added to research queue: " + str(bool(gate.get("added_to_research_queue", False))),
                "- Active recall enabled: " + str(bool(gate.get("active_recall_enabled", False))),
                "- Source changed: " + str(bool(gate.get("source_changed", False))),
                "- Safety level: " + str(gate.get("safety_level", "")),
                "- Status: " + str(gate.get("status", "")),
            ]

    lines += [
        "",
        "Safety:",
        "- Gate/report only.",
        "- Gates are not approved.",
        "- Gates are not executed.",
        "- No active recall enabled.",
        "- Research was not started.",
        "- LEARNING_LOG.md was not written.",
        "- RESEARCH_GOALS_QUEUE_V1.md was not written.",
        "- Source and behavior were not changed.",
        "- No cloud fallback.",
    ]
    return "\n".join(lines)


def _offline_memory_action_gates_write_outputs_v2mind_e(gates, source):
    import json

    paths = _offline_memory_action_gates_paths_v2mind_e()
    payload = {
        "schema_version": "V2MIND-E",
        "generated_at": now(),
        "source_routing_path": source.get("routing_path", ""),
        "source_routed_count": len(source.get("routed_items", [])),
        "gate_count": len(gates),
        "gates": gates,
        "safety": {
            "gates_only": True,
            "approved_now": False,
            "executed_now": False,
            "applied_to_learning": False,
            "added_to_research_queue": False,
            "active_recall_enabled": False,
            "research_started": False,
            "source_changed": False,
            "cloud_fallback": False,
        },
    }
    write_file(paths["gates"], json.dumps(payload, indent=2))
    write_file(paths["index"], json.dumps(_offline_memory_action_gates_index_payload_v2mind_e(gates, source), indent=2))
    write_file(paths["report"], _offline_memory_action_gates_render_report_v2mind_e(gates, source))


def _offline_memory_action_gates_load_gates_v2mind_e():
    import json

    paths = _offline_memory_action_gates_paths_v2mind_e()
    if not os.path.exists(paths["gates"]):
        return None, ""
    try:
        data = json.loads(read_file(paths["gates"]))
        if not isinstance(data, dict):
            return None, "Gate file is not a JSON object."
        return data, ""
    except Exception as e:
        return None, "Gate file could not be parsed: " + str(e)


