# --- Consolidated Screenshot Helpers ---
def _screenshot_dir():
    """Return screenshot directory path."""
    return os.path.join(REPORTS_DIR, "screenshots")

def _latest_screenshot():
    """Return path to latest PNG screenshot or None."""
    d = _screenshot_dir()
    if not os.path.isdir(d):
        return None
    files = [os.path.join(d, f) for f in os.listdir(d) if f.lower().endswith(".png")]
    return max(files, key=os.path.getmtime) if files else None

def _ensure_screenshot_dir():
    """Ensure screenshot directory exists."""
    os.makedirs(_screenshot_dir(), exist_ok=True)
    return _screenshot_dir()

# --- End Consolidated Helpers ---


def desktop_screenshot():
    try:
        from PIL import ImageGrab
    except Exception as e:
        return (
            "Screenshot failed: Pillow/ImageGrab is not available.\n\n"
            f"Error: {e}"
        )

    screenshot_dir = _ensure_screenshot_dir()
    filename = "screenshot_" + now().replace(":", "-").replace(" ", "_") + ".png"
    path = os.path.join(screenshot_dir, filename)

    img = ImageGrab.grab()
    img.save(path)

    append_log(f"Desktop screenshot saved: {path}")
    return (
        "Desktop screenshot saved:\n"
        + path
        + "\n\nNo analysis was performed yet. Next step can be screenshot review."
    )


def desktop_screenshot_report():
    screenshot_dir = _screenshot_dir()

    if not os.path.isdir(screenshot_dir):
        return "Screenshot report failed: no screenshots folder exists yet."

    latest = _latest_screenshot()

    if not latest:
        return "Screenshot report failed: no screenshot PNG files found yet."

    try:
        from PIL import Image
        with Image.open(latest) as img:
            width, height = img.size
    except Exception as e:
        width, height = "unknown", "unknown"

    size_bytes = os.path.getsize(latest)
    modified = datetime.datetime.fromtimestamp(os.path.getmtime(latest)).strftime("%Y-%m-%d %H:%M:%S")

    report = (
        "# Latest Screenshot Report\n\n"
        f"File: {latest}\n"
        f"Size: {size_bytes} bytes\n"
        f"Dimensions: {width} x {height}\n"
        f"Captured/Modified: {modified}\n\n"
        "Status: Screenshot file exists and is ready for future visual review.\n"
        "Note: This report does not analyze image content yet."
    )

    report_file = os.path.join(REPORTS_DIR, "LAST_SCREENSHOT_REPORT.md")
    write_file(report_file, report)
    append_log(f"Screenshot report created: {report_file}")

    return report



