# ----------------------------------------------------------------------
# Permission Result System V2Q
# Common safety result shape: ALLOW / ASK / DENY.
# Base layer only. Does not weaken existing approval gates.
# ----------------------------------------------------------------------
def permission_result_v2q(decision, action, reason, required_approval="", blocked_actions=None, safety_notes=None):
    decision = str(decision or "").strip().upper()
    if decision not in ["ALLOW", "ASK", "DENY"]:
        decision = "ASK"

    return {
        "version": "V2Q",
        "decision": decision,
        "action": str(action or "").strip(),
        "reason": str(reason or "").strip(),
        "required_approval": str(required_approval or "").strip(),
        "blocked_actions": list(blocked_actions or []),
        "safety_notes": list(safety_notes or []),
    }

def permission_render_v2q(result):
    lines = [
        "# Permission Result V2Q",
        "",
        "Decision: " + result.get("decision", "ASK"),
        "Action: " + result.get("action", ""),
        "",
        "Reason:",
        result.get("reason", ""),
    ]

    approval = result.get("required_approval", "")
    if approval:
        lines += ["", "Required approval:", approval]

    blocked = result.get("blocked_actions", [])
    if blocked:
        lines += ["", "Blocked actions:"]
        for item in blocked:
            lines.append("- " + str(item))

    notes = result.get("safety_notes", [])
    if notes:
        lines += ["", "Safety notes:"]
        for item in notes:
            lines.append("- " + str(item))

    lines += [
        "",
        "Safety:",
        "- Common permission shape only.",
        "- Does not override existing approval gates.",
        "- No clicking.",
        "- No sending.",
        "- No deleting.",
        "- No cloud fallback.",
    ]

    return "\n".join(lines)

def permission_check_v2q(action):
    lower = str(action or "").lower()

    high_risk = ["send", "submit", "buy", "purchase", "delete", "remove", "password", "credential", "login", "payment", "settings", "security"]
    control_risk = ["click", "type", "press", "enter", "paste", "drag", "scroll", "mouse", "keyboard"]
    network_risk = ["browse", "fetch", "url", "web", "internet", "download"]
    write_risk = ["write", "edit", "patch", "modify", "overwrite", "install", "dependency"]

    if any(w in lower for w in high_risk):
        return permission_result_v2q(
            "DENY",
            action,
            "High-risk action requires a dedicated approval-gated command and must not run from a generic request.",
            "Dedicated APPROVE command required.",
            ["send", "submit", "buy/pay", "delete/remove", "login/credentials", "settings/security changes"],
            ["Use existing explicit approval gates only."]
        )

    if any(w in lower for w in control_risk):
        return permission_result_v2q(
            "ASK",
            action,
            "Desktop control action requires explicit user approval before acting.",
            "APPROVE required in the exact command.",
            ["unapproved click/type/paste/keypress"],
            ["Engel must stop after the approved action."]
        )

    if any(w in lower for w in write_risk):
        return permission_result_v2q(
            "ASK",
            action,
            "File/code write action requires backup-first, diagnose-first, targeted patch, compile-check, and test.",
            "APPROVE or patch command sequence required.",
            ["blind edit", "hot-lava edit", "dependency install"],
            ["No hot-lava blind edits."]
        )

    if any(w in lower for w in network_risk):
        return permission_result_v2q(
            "ASK",
            action,
            "Network/source action must preserve source-quality gates and public-source rules.",
            "Approval/source-quality gate may be required.",
            ["login/paywall/private-network fetch", "weak source brief"],
            ["No cloud fallback without approval."]
        )

    return permission_result_v2q(
        "ALLOW",
        action,
        "Low-risk status/read-only style action.",
        "",
        [],
        ["Read/status only actions may proceed if inside approved scope."]
    )

def permission_status_v2q():
    examples = [
        permission_check_v2q("read approved local file"),
        permission_check_v2q("patch Engel source file"),
        permission_check_v2q("control click 100 200"),
        permission_check_v2q("send email"),
    ]

    lines = [
        "# Permission Result System V2Q",
        "",
        "Status: INSTALLED",
        "",
        "Decisions:",
        "- ALLOW: low-risk/read/status action inside approved scope.",
        "- ASK: action may be possible but needs explicit approval or a safer plan.",
        "- DENY: action is blocked unless routed through a dedicated approval-gated workflow.",
        "",
        "Current rule:",
        "- V2Q is a common result shape.",
        "- It does not weaken existing gates.",
        "- Existing APPROVE checks remain active.",
        "- No autonomous actions.",
        "",
        "Examples:",
    ]

    for item in examples:
        lines += [
            "",
            "- Action: " + item["action"],
            "  Decision: " + item["decision"],
            "  Reason: " + item["reason"],
        ]

    lines += [
        "",
        "Recommended next step:",
        "- V2Q-B: migrate one risky tool at a time to call PermissionResult before acting.",
        "- Start with desktop control request / click plan / paste plan.",
        "",
        "Safety:",
        "- Status only.",
        "- No clicking.",
        "- No sending.",
        "- No deleting.",
        "- No cloud fallback.",
    ]

    return "\n".join(lines)


