def desktop_control_request(action):
    action = action.strip()

    if not action:
        return "Control request failed: describe the action you want Engel to evaluate."

    lower = action.lower()
    perm = permission_check_v2q("control request " + action)

    high_risk_words = [
        "send", "submit", "buy", "purchase", "delete", "remove",
        "password", "settings", "install", "uninstall", "pay",
        "message", "email", "discord"
    ]

    type_click_words = [
        "click", "type", "press", "enter", "move mouse", "drag",
        "scroll", "select", "copy", "paste"
    ]

    if any(w in lower for w in high_risk_words):
        risk = "APPROVAL REQUIRED"
        reason = "The request may involve sending, spending, deleting, account/security changes, messages, or another high-risk action."
    elif any(w in lower for w in type_click_words):
        risk = "APPROVAL REQUIRED"
        reason = "The request involves desktop control such as clicking, typing, pressing keys, dragging, or selecting."
    else:
        risk = "CAUTION / NEEDS REVIEW"
        reason = "The request may be safe, but Engel needs more context before any desktop action."

    return (
        "# Desktop Control Request Review\n\n"
        f"Requested action:\n{action}\n\n"
        f"Risk level:\n{risk}\n\n"
        f"Reason:\n{reason}\n\n"
        "Permission Result V2Q-B:\n"
        f"- Decision: {perm.get('decision', 'ASK')}\n"
        f"- Reason: {perm.get('reason', '')}\n"
        f"- Required approval: {perm.get('required_approval', '') or 'none'}\n\n"
        "What Engel can do now:\n"
        "- Take a screenshot\n"
        "- Use look focused or look task to observe the screen\n"
        "- Explain the safest next step\n"
        "- Prepare an approval request\n\n"
        "What Engel will not do yet:\n"
        "- Click\n"
        "- Type\n"
        "- Send messages\n"
        "- Submit forms\n"
        "- Spend money\n"
        "- Delete files\n"
        "- Change settings\n\n"
        "Recommended next safe step:\n"
        "Run screenshot, then look task, then ask for the exact supervised action if still needed."
    )



def desktop_control_approve_plan(action):
    action = action.strip()

    if not action:
        return "Approval plan failed: describe the action first."

    lower = action.lower()

    high_risk_words = [
        "send", "submit", "buy", "purchase", "delete", "remove",
        "password", "settings", "install", "uninstall", "pay",
        "message", "email", "discord"
    ]

    control_words = [
        "click", "type", "press", "enter", "move mouse", "drag",
        "scroll", "select", "copy", "paste"
    ]

    if any(w in lower for w in high_risk_words):
        risk = "HIGH / APPROVAL REQUIRED"
        gate = "Explicit approval required. Engel must not execute this automatically."
    elif any(w in lower for w in control_words):
        risk = "CONTROL / APPROVAL REQUIRED"
        gate = "Approval required before any mouse, keyboard, click, typing, drag, or scroll action."
    else:
        risk = "CAUTION / REVIEW FIRST"
        gate = "Engel should observe first, then request approval if control is needed."

    return (
        "# Desktop Control Approval Plan\n\n"
        f"Proposed action:\n{action}\n\n"
        f"Risk level:\n{risk}\n\n"
        "Exact action Engel would prepare:\n"
        "- Observe the current screen first using screenshot/look task.\n"
        "- Identify the target window or app.\n"
        "- Describe the intended action before doing anything.\n"
        "- Wait for clear approval.\n"
        "- Perform only the approved action.\n"
        "- Stop immediately after the action.\n"
        "- Report what happened.\n\n"
        "Stop condition:\n"
        "- If the screen does not match the plan, stop.\n"
        "- If the target is unclear, stop.\n"
        "- If a message, payment, delete, submit, or settings change appears, stop.\n"
        "- If Engel is unsure, stop and ask.\n\n"
        f"Approval gate:\n{gate}\n\n"
        "Current status:\n"
        "No desktop control was performed. This is only an approval plan."
    )



def _kernel_write_report(job_id, text):
    kernel_dir = os.path.join(REPORTS_DIR, "kernel")
    os.makedirs(kernel_dir, exist_ok=True)
    path = os.path.join(kernel_dir, f"kernel_job_{job_id}.md")
    write_file(path, text)
    return path

def _kernel_task_runner(job_id, task_name, func):
    KERNEL_JOBS[job_id]["status"] = "running"
    KERNEL_JOBS[job_id]["started"] = now()

    try:
        result = func()
        KERNEL_JOBS[job_id]["status"] = "complete"
        KERNEL_JOBS[job_id]["finished"] = now()
        KERNEL_JOBS[job_id]["result"] = result

        report = (
            "# Engel Kernel Job Result\n\n"
            f"Job ID: {job_id}\n"
            f"Task: {task_name}\n"
            f"Status: complete\n"
            f"Started: {KERNEL_JOBS[job_id].get('started')}\n"
            f"Finished: {KERNEL_JOBS[job_id].get('finished')}\n\n"
            "## Result\n\n"
            + str(result)
        )

        report_path = _kernel_write_report(job_id, report)
        KERNEL_JOBS[job_id]["report"] = report_path
        append_log(f"Kernel job complete: {job_id} task={task_name} report={report_path}")

    except Exception as e:
        err = traceback.format_exc()
        KERNEL_JOBS[job_id]["status"] = "failed"
        KERNEL_JOBS[job_id]["finished"] = now()
        KERNEL_JOBS[job_id]["error"] = str(e)

        report = (
            "# Engel Kernel Job Failed\n\n"
            f"Job ID: {job_id}\n"
            f"Task: {task_name}\n"
            f"Status: failed\n\n"
            "## Error\n\n"
            + err
        )

        report_path = _kernel_write_report(job_id, report)
        KERNEL_JOBS[job_id]["report"] = report_path
        append_log(f"Kernel job failed: {job_id} task={task_name} error={e}")

def kernel_task_map():
    return {
        "guardian": guardian_check,
        "screenshot": desktop_screenshot,
        "screenshot report": desktop_screenshot_report,
        "look": desktop_look_latest_screenshot,
        "look focused": desktop_look_focused,
        "look task": desktop_look_task,
        "morning": morning_report,
        "reflect": self_reflect,
        "reflect hard": self_reflect_hard,
    }

def kernel_run(task_name):
    global KERNEL_LATEST_JOB_ID

    task_name = task_name.strip().lower()
    tasks = kernel_task_map()

    if task_name not in tasks:
        allowed = [
            "guardian",
            "screenshot",
            "screenshot report",
            "look",
            "look focused",
            "look task",
            "morning",
            "reflect",
            "reflect hard",
        ]

        return (
            "# Kernel Run Blocked\n\n"
            f"Unknown or unsafe kernel task: {task_name}\n\n"
            "Allowed kernel tasks:\n"
            + "\n".join(["- " + item for item in allowed])
            + "\n\nArbitrary shell/PowerShell commands are not allowed in Kernel Worker v1."
        )

    job_id = str(uuid.uuid4())[:8]
    KERNEL_LATEST_JOB_ID = job_id

    KERNEL_JOBS[job_id] = {
        "id": job_id,
        "task": task_name,
        "status": "queued",
        "created": now(),
        "started": None,
        "finished": None,
        "result": None,
        "error": None,
        "report": None,
    }

    KERNEL_EXECUTOR.submit(_kernel_task_runner, job_id, task_name, tasks[task_name])
    append_log(f"Kernel job queued: {job_id} task={task_name}")

    return (
        "# Kernel Job Queued\n\n"
        f"Job ID: {job_id}\n"
        f"Task: {task_name}\n"
        "Status: queued/running\n\n"
        "Use:\n"
        "kernel status\n"
        "kernel result\n"
    )

def kernel_status():
    if not KERNEL_JOBS:
        allowed = [
            "kernel run guardian",
            "kernel run screenshot",
            "kernel run screenshot report",
            "kernel run look",
            "kernel run look focused",
            "kernel run look task",
            "kernel run morning",
            "kernel run reflect",
            "kernel run reflect hard",
        ]

        return (
            "# Engel Kernel Status\n\n"
            "No kernel jobs have been started yet.\n\n"
            "Allowed:\n"
            + "\n".join(["- " + item for item in allowed])
        )

    lines = [
        "# Engel Kernel Status",
        "",
        "Worker mode: SAFE background task queue",
        "Max workers: 2",
        "",
        "## Jobs"
    ]

    for job_id, job in list(KERNEL_JOBS.items())[-10:]:
        lines.append(
            f"- {job_id} | {job.get('task')} | {job.get('status')} | created {job.get('created')} | report {job.get('report') or 'not ready'}"
        )

    return "\n".join(lines)

def kernel_result(job_id=None):
    if not KERNEL_JOBS:
        return "Kernel result failed: no jobs exist yet."

    if not job_id or job_id.strip().lower() == "latest":
        job_id = KERNEL_LATEST_JOB_ID

    job_id = job_id.strip()

    if job_id not in KERNEL_JOBS:
        return f"Kernel result failed: unknown job ID {job_id}"

    job = KERNEL_JOBS[job_id]

    if job.get("status") in ["queued", "running"]:
        return (
            "# Kernel Job Still Running\n\n"
            f"Job ID: {job_id}\n"
            f"Task: {job.get('task')}\n"
            f"Status: {job.get('status')}\n"
        )

    report_path = job.get("report")
    report_text = read_file(report_path) if report_path else ""

    if not report_text:
        return (
            "# Kernel Result\n\n"
            f"Job ID: {job_id}\n"
            f"Status: {job.get('status')}\n"
            f"Result:\n{job.get('result') or job.get('error')}"
        )

    return report_text



def _tail_text(path, max_chars=8000):
    text = read_file(path)
    if len(text) > max_chars:
        return text[-max_chars:]
    return text

def self_reflect():
    logs = {
        "MAIN_AGENT_LOG": _tail_text(LOG_FILE),
        "PROJECT_HISTORY": _tail_text(os.path.join(MEMORY_DIR, "PROJECT_HISTORY.md")),
        "LEARNING_LOG": _tail_text(os.path.join(MEMORY_DIR, "LEARNING_LOG.md")),
        "COMMON_ERRORS": _tail_text(os.path.join(MEMORY_DIR, "COMMON_ERRORS.md")),
        "WORKFLOW_IMPROVEMENTS": _tail_text(os.path.join(MEMORY_DIR, "WORKFLOW_IMPROVEMENTS.md")),
        "NEXT_STEPS": _tail_text(os.path.join(MEMORY_DIR, "NEXT_STEPS.md")),
    }

    prompt = (
        "You are Engel reviewing your own recent work so you can improve. "
        "Be honest and practical. Do not invent actions. Only use the logs provided. "
        "Create a self-teaching report using this exact format:\n\n"
        "1. What worked:\n"
        "2. Mistakes or weak behavior:\n"
        "3. Lessons to remember:\n"
        "4. Workflow improvements:\n"
        "5. Next safest upgrade:\n"
        "6. Items needing user approval:\n\n"
        "Keep it concise and useful.\n\n"
        "RECENT LOGS:\n\n"
    )

    for name, text in logs.items():
        prompt += f"\n\n--- {name} ---\n{text if text.strip() else '[empty]'}\n"

    provider_result = _brain_text_result_v2provider(
        prompt,
        system_message="You are Engel's self-teaching review worker. You write practical improvement notes only.",
    )
    if not provider_result.get("ok"):
        return "Self-reflection failed: brain provider is not configured.\n\n" + provider_result.get("text", "")
    reflection = provider_result.get("text", "").strip()

    report = (
        "# Engel Self-Teaching Reflection\n\n"
        f"Time: {now()}\n"
        f"Brain provider: {_select_brain_provider_v2provider().get('provider') or 'none'}\n"
        f"Mode: {MODE}\n\n"
        + reflection
        + "\n\nSafety: Reflection only. No desktop control, file deletion, sending, or settings changes were performed."
    )

    report_file = os.path.join(REPORTS_DIR, "SELF_REFLECTION_REPORT.md")
    write_file(report_file, report)

    append_file(os.path.join(MEMORY_DIR, "LEARNING_LOG.md"), "\n\n## " + now() + "\nSelf-reflection completed.\n\n" + reflection + "\n")
    append_file(os.path.join(MEMORY_DIR, "WORKFLOW_IMPROVEMENTS.md"), "\n\n## " + now() + "\nSelf-reflection improvements:\n\n" + reflection + "\n")
    append_log(f"Self-reflection completed. Report: {report_file}")

    return report



def _hard_tail(path, max_chars=20000):
    text = read_file(path)
    return text[-max_chars:] if len(text) > max_chars else text

def _hard_collect_lines(text, keywords, max_lines=160):
    hits = []
    for line in text.splitlines():
        low = line.lower()
        if any(k in low for k in keywords):
            hits.append(line)
    return hits[-max_lines:]

def self_reflect_hard():
    sources = {
        "MAIN_AGENT_LOG": LOG_FILE,
        "PROJECT_HISTORY": os.path.join(MEMORY_DIR, "PROJECT_HISTORY.md"),
        "LEARNING_LOG": os.path.join(MEMORY_DIR, "LEARNING_LOG.md"),
        "COMMON_ERRORS": os.path.join(MEMORY_DIR, "COMMON_ERRORS.md"),
        "CODE_FIX_HISTORY": os.path.join(MEMORY_DIR, "CODE_FIX_HISTORY.md"),
        "WORKFLOW_IMPROVEMENTS": os.path.join(MEMORY_DIR, "WORKFLOW_IMPROVEMENTS.md"),
        "ROLLBACK_POINTS": os.path.join(MEMORY_DIR, "ROLLBACK_POINTS.md"),
    }

    combined_parts = []
    for name, src in sources.items():
        combined_parts.append("\n--- " + name + " ---\n" + _hard_tail(src, 20000))

    combined = "\n".join(combined_parts)
    low = combined.lower()

    keywords = [
        "syntaxerror",
        "unterminated string literal",
        "compile failed",
        "pycompileerror",
        "wont open",
        "won't open",
        "not work",
        "broken",
        "repair",
        "fixed",
        "kernel_run",
        "kernel_status",
        "reflect hard",
        "too generic",
        "generic",
        "pythonw",
        "hidden",
        "backup",
        "restore point",
        "no desktop control",
    ]

    evidence = _hard_collect_lines(combined, keywords)

    mistakes = []
    root_causes = []
    fixes = []
    lessons = []
    safety = []
    do_not_repeat = []

    if "unterminated string literal" in low or "syntaxerror" in low:
        mistakes.append("Patch inserted broken multi-line string literals into engel_app.py.")
        root_causes.append("Fragile text replacement was used on Python source containing newline-sensitive string literals.")
        fixes.append("Used py_compile to expose the exact failure and repaired the affected function/string block.")
        lessons.append("After every patch, run py_compile before launching hidden pythonw shortcuts.")

    if "wont open" in low or "won't open" in low or "pythonw" in low or "hidden" in low:
        mistakes.append("Hidden launch made failures harder to see.")
        root_causes.append("pythonw.exe hides console errors, so broken code looked like Engel simply would not open.")
        fixes.append("Used normal python.exe debug launch to reveal tracebacks.")
        lessons.append("When hidden launch fails, debug with .venv\\Scripts\\python.exe engel_companion.py.")

    if "kernel_run" in low or "kernel_status" in low:
        mistakes.append("Kernel status text patch broke the kernel function area.")
        fixes.append("Replacing the whole kernel_run/kernel_status function block worked better than chasing one bad line.")
        lessons.append("For core function repairs, replace complete functions instead of doing small blind string patches.")

    if "too generic" in low or "generic" in low:
        mistakes.append("reflect hard output was too generic and copied NEXT_STEPS-style advice.")
        root_causes.append("The local text model followed broad planning patterns instead of strict failure diagnosis.")
        fixes.append("Changed reflect hard to deterministic log-mining instead of relying only on the model.")
        lessons.append("Hard reflection should extract evidence from logs first, then summarize exact failures.")

    if "backup" in low or "restore point" in low:
        fixes.append("Created and recorded a stable backup/rollback point before more risky changes.")
        safety.append("Stable backup exists and should be preserved before further desktop-control upgrades.")

    if not mistakes:
        mistakes.append("No exact failure signals were found in the current log scan.")
        root_causes.append("Not proven in logs.")
        fixes.append("Not proven in logs.")
        lessons.append("Improve logging if failures are happening but not captured.")

    safety.append("No desktop control should be added until repair/rollback workflow stays stable.")
    do_not_repeat.extend([
        "Do not patch live source without py_compile afterward.",
        "Do not trust hidden launch when testing new code.",
        "Do not use fragile line replacement for complex Python function blocks.",
        "Do not accept generic reflection output as hard self-teaching.",
    ])

    report_lines = [
        "# Engel Hard Self-Teaching Reflection",
        "",
        "Time: " + now(),
        "Model: deterministic log scanner + " + MODEL,
        "Mode: " + MODE,
        "",
        "1. Exact mistakes found:",
    ]

    for item in mistakes:
        report_lines.append("- " + item)

    report_lines.append("")
    report_lines.append("2. Root causes:")
    for item in root_causes:
        report_lines.append("- " + item)

    report_lines.append("")
    report_lines.append("3. Fixes that worked:")
    for item in fixes:
        report_lines.append("- " + item)

    report_lines.append("")
    report_lines.append("4. Code/file lessons:")
    for item in lessons:
        report_lines.append("- " + item)

    report_lines.append("")
    report_lines.append("5. Safety lessons:")
    for item in safety:
        report_lines.append("- " + item)

    report_lines.append("")
    report_lines.append("6. Next safest technical upgrade:")
    report_lines.append("- Add a repair/health command that runs py_compile on engel_app.py and engel_companion.py before restart.")

    report_lines.append("")
    report_lines.append("7. Do-not-repeat list:")
    for item in do_not_repeat:
        report_lines.append("- " + item)

    report_lines.append("")
    report_lines.append("Evidence lines found:")
    if evidence:
        for line in evidence[-40:]:
            report_lines.append("- " + line[:240])
    else:
        report_lines.append("- No matching evidence lines found.")

    report_lines.append("")
    report_lines.append("Safety: Reflection only. No desktop control, file deletion, sending, or settings changes were performed.")

    report = "\n".join(report_lines)

    report_file = os.path.join(REPORTS_DIR, "SELF_REFLECTION_HARD_REPORT.md")
    write_file(report_file, report)

    append_file(os.path.join(MEMORY_DIR, "LEARNING_LOG.md"), "\n\n## " + now() + "\nHard deterministic self-reflection completed.\n\n" + report + "\n")
    append_file(os.path.join(MEMORY_DIR, "COMMON_ERRORS.md"), "\n\n## " + now() + "\nHard deterministic reflection error lessons:\n\n" + report + "\n")
    append_file(os.path.join(MEMORY_DIR, "CODE_FIX_HISTORY.md"), "\n\n## " + now() + "\nHard deterministic reflection code/file lessons:\n\n" + report + "\n")
    append_log("Hard deterministic self-reflection completed. Report: " + report_file)

    return report



def health_repair():
    import py_compile
    import traceback

    lines = []
    lines.append("# Engel Health Repair Report")
    lines.append("")
    lines.append("Time: " + now())
    lines.append("Workspace: " + ROOT)
    lines.append("Mode: " + MODE)
    lines.append("")
    lines.append("## Compile Checks")

    ok = True

    files_to_check = [
        os.path.join(ROOT, "engel_app.py"),
        os.path.join(ROOT, "engel_companion.py"),
    ]

    for file_path in files_to_check:
        try:
            py_compile.compile(file_path, doraise=True)
            lines.append("- OK: " + file_path)
        except Exception:
            ok = False
            lines.append("- FAILED: " + file_path)
            lines.append("```")
            lines.append(traceback.format_exc())
            lines.append("```")

    lines.append("")
    lines.append("## Guardian Check")
    try:
        guardian = guardian_check()
        lines.append(guardian)
        if "Guardian status: OK" not in guardian:
            ok = False
    except Exception:
        ok = False
        lines.append("Guardian check failed:")
        lines.append("```")
        lines.append(traceback.format_exc())
        lines.append("```")

    lines.append("")
    lines.append("## Desktop Control Check")
    try:
        if "desktop_control_status" in globals():
            lines.append(desktop_control_status())
        else:
            ok = False
            lines.append("desktop_control_status is missing.")
    except Exception:
        ok = False
        lines.append("Desktop control status failed:")
        lines.append("```")
        lines.append(traceback.format_exc())
        lines.append("```")

    lines.append("")
    lines.append("## Result")
    if ok:
        lines.append("Health repair status: OK")
        lines.append("Engel is safe to restart from the current files.")
    else:
        lines.append("Health repair status: NEEDS ATTENTION")
        lines.append("Do not patch further until the failed item is fixed.")

    lines.append("")
    lines.append("Safety: This command performed checks only. It did not edit source files.")

    report = "\n".join(lines)
    report_file = os.path.join(REPORTS_DIR, "HEALTH_REPAIR_REPORT.md")
    write_file(report_file, report)
    append_log("Health repair check completed. Report: " + report_file)

    return report



