# --- Consolidated Window Helpers ---
def _active_window_title():
    """Return title of currently active window."""
    try:
        import ctypes
        user32 = ctypes.windll.user32
        hwnd = user32.GetForegroundWindow()
        length = user32.GetWindowTextLengthW(hwnd)
        buff = ctypes.create_unicode_buffer(length + 1)
        user32.GetWindowTextW(hwnd, buff, length + 1)
        return buff.value if buff.value else "[unknown / no title]"
    except Exception as e:
        return "[could not read active window: " + str(e) + "]"

def _find_window_by_title_keyword(keyword):
    """Find windows matching keyword in title."""
    import ctypes
    keyword = keyword.lower()
    user32 = ctypes.windll.user32
    results = []
    EnumWindows = user32.EnumWindows
    EnumWindowsProc = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)
    def callback(hwnd, lParam):
        if user32.IsWindowVisible(hwnd):
            length = user32.GetWindowTextLengthW(hwnd)
            if length > 0:
                buff = ctypes.create_unicode_buffer(length + 1)
                user32.GetWindowTextW(hwnd, buff, length + 1)
                title = buff.value
                if keyword in title.lower():
                    results.append((hwnd, title))
        return True
    EnumWindows(EnumWindowsProc(callback), 0)
    return results

def _activate_window(hwnd):
    """Bring window to foreground."""
    import ctypes, time
    user32 = ctypes.windll.user32
    user32.ShowWindow(hwnd, 5)
    time.sleep(0.2)
    user32.SetForegroundWindow(hwnd)
    time.sleep(0.4)
# --- End Consolidated Helpers ---


