def desktop_control_paste_plan(target):
    target = str(target).strip().lower()
    if target != "latest":
        return (
            "# Paste Plan Failed\n\n"
            "Use:\n"
            "control paste-plan latest"
        )

    files = _draft_files()
    if not files:
        return "Paste plan failed: no local drafts found yet."

    latest = files[0]
    draft_text = _extract_draft_text(latest)
    if not draft_text:
        return "Paste plan failed: latest draft text is empty."

    active_title = _active_window_title()

    lower_title = active_title.lower()
    lower_text = draft_text.lower()

    high_risk_window_words = ["discord", "mail", "gmail", "outlook", "message", "chat", "browser"]
    high_risk_text_words = ["send", "submit", "buy", "purchase", "delete", "password", "pay"]

    risk = "CONTROL / APPROVAL REQUIRED"
    warnings = []

    if any(w in lower_title for w in high_risk_window_words):
        risk = "HIGH / APPROVAL REQUIRED"
        warnings.append("Active window may be a communication/browser app.")

    if any(w in lower_text for w in high_risk_text_words):
        risk = "HIGH / APPROVAL REQUIRED"
        warnings.append("Draft text contains higher-risk wording.")

    if not warnings:
        warnings.append("No special high-risk words detected, but pasting into apps still requires approval.")

    preview = draft_text
    if len(preview) > 600:
        preview = preview[:600] + "\n...[truncated]"

    perm = permission_check_v2q("control paste latest")

    lines = [
        "# Paste Approval Plan",
        "",
        "Source draft:",
        latest,
        "",
        "Active window:",
        active_title,
        "",
        "Risk level:",
        risk,
        "",
        "Permission Result V2Q-B:",
        "- Decision: " + perm.get("decision", "ASK"),
        "- Reason: " + perm.get("reason", ""),
        "- Required approval: " + (perm.get("required_approval", "") or "none"),
        "",
        "Warnings:",
    ]

    for w in warnings:
        lines.append("- " + w)

    lines += [
        "",
        "Draft preview:",
        preview,
        "",
        "What Engel would need before any future paste:",
        "- Screenshot/look task to confirm the target field.",
        "- Active window confirmed.",
        "- User review of final draft text.",
        "- Explicit approval command.",
        "- Paste only, then stop.",
        "",
        "What Engel will NOT do now:",
        "- No paste performed.",
        "- No typing performed.",
        "- No message sent.",
        "- No form submitted.",
        "- No click performed.",
        "- No files changed.",
        "",
        "Current status:",
        "Paste is still locked. This is only a plan.",
    ]

    return "\n".join(lines)



