def _safe_router_match_v2u(command):
    cmd = str(command or "").strip().lower()
    if not cmd:
        return None

    for row in _safe_router_registry_v2u():
        pat = row["pattern"].lower()
        if row["match"] == "exact" and cmd == pat:
            return row

    for row in _safe_router_registry_v2u():
        pat = row["pattern"].lower()
        if row["match"] == "prefix" and cmd.startswith(pat):
            return row

    return None

def router_check_v2u(command):
    cmd = str(command or "").strip()
    row = _safe_router_match_v2u(cmd)

    lines = [
        "# Safe Command Router Check V2U-A",
        "",
        "Command:",
        cmd if cmd else "[none]",
        "",
    ]

    if row:
        lines += [
            "Router match: YES",
            "Pattern: " + row["pattern"],
            "Match type: " + row["match"],
            "Family: " + row["family"],
            "Risk: " + row["risk"],
            "Notes: " + row["notes"],
        ]
        if row.get("labels"):
            lines.append("Labels: " + ", ".join(row.get("labels", [])))
    else:
        perm = permission_check_v2q(cmd)
        lines += [
            "Router match: NO",
            "",
            "Permission fallback:",
            "- Decision: " + perm.get("decision", "ASK"),
            "- Reason: " + perm.get("reason", ""),
            "",
            "Meaning:",
            "- This may fall through to chat/model if no route catches it.",
            "- V2U-B should tighten unknown-command behavior later.",
        ]

    lines += [
        "",
        "Safety:",
        "- Check/report only.",
        "- No command executed.",
        "- No clicking.",
        "- No sending.",
        "- No deleting.",
        "- Existing gates unchanged.",
    ]

    return "\n".join(lines)

