# ----------------------------------------------------------------------
# Process Truth + Duplicate Helper Guard V2PROCESS-A
# Report-only. No process killing, no PID-file deletion, no source apply.
# ----------------------------------------------------------------------
def _process_truth_rows_v2process_a():
    import subprocess
    rows = []
    try:
        cmd = [
            "powershell", "-NoProfile", "-Command",
            "Get-CimInstance Win32_Process -Filter \"Name = 'python.exe' OR Name = 'pythonw.exe' OR Name = 'cmd.exe'\" | "
            "Where-Object { $_.CommandLine -like '*EngelStandalone*' -or $_.CommandLine -like '*engel_*' } | "
            "ForEach-Object { [string]$_.ProcessId + '|' + [string]$_.ParentProcessId + '|' + [string]$_.Name + '|' + [string]$_.CommandLine }"
        ]
        out = subprocess.check_output(cmd, text=True, errors="replace", timeout=8)
        for line in out.splitlines():
            parts = line.split("|", 3)
            if len(parts) != 4:
                continue
            pid, ppid, name, command = parts
            if not str(pid).strip().isdigit():
                continue
            rows.append({
                "pid": int(str(pid).strip()),
                "ppid": int(str(ppid).strip()) if str(ppid).strip().isdigit() else None,
                "name": str(name).strip(),
                "command": str(command).strip(),
            })
    except Exception as e:
        return [], str(e)
    return sorted(rows, key=lambda r: (r.get("ppid") or 0, r.get("pid") or 0)), ""


def _process_truth_script_chains_v2process_a(rows, script_name):
    low_script = str(script_name).lower()
    script_rows = [r for r in rows if low_script in str(r.get("command", "")).lower()]
    by_pid = {r["pid"]: r for r in script_rows}
    child_map = {}
    for r in script_rows:
        child_map.setdefault(r.get("ppid"), []).append(r)
    roots = [r for r in script_rows if r.get("ppid") not in by_pid]
    roots = sorted(roots, key=lambda r: r["pid"])

    chains = []
    for root in roots:
        chain = [root]
        seen = {root["pid"]}
        cur = root
        while True:
            children = [c for c in child_map.get(cur["pid"], []) if c["pid"] not in seen]
            if not children:
                break
            children = sorted(children, key=lambda r: r["pid"])
            cur = children[0]
            chain.append(cur)
            seen.add(cur["pid"])
        chains.append(chain)
    return chains


def _process_truth_chain_text_v2process_a(chain):
    return " -> ".join(str(r.get("pid")) for r in chain)


def _process_truth_script_label_v2process_a(script_name, index):
    if script_name == "engel_mobile_bridge.py":
        return "ENGEL_MOBILE_BRIDGE_EXPECTED" if index == 0 else "ENGEL_MOBILE_BRIDGE_DUPLICATE"
    if script_name == "engel_alive_loop.py":
        return "ENGEL_ALIVE_LOOP_EXPECTED" if index == 0 else "ENGEL_ALIVE_LOOP_DUPLICATE"
    if script_name == "engel_companion.py":
        return "ENGEL_UI_MAIN"
    return "UNKNOWN_PYTHON_DO_NOT_TOUCH"


def _process_truth_report_v2process_a(title, duplicate_focus=False):
    rows, error = _process_truth_rows_v2process_a()
    lines = [
        "# " + title,
        "",
        "Time: " + now(),
        "Workspace: " + ROOT,
        "",
        "Safety:",
        "- Read-only/report-only.",
        "- No process killing.",
        "- No taskkill.",
        "- No Stop-Process.",
        "- No PID files deleted.",
        "- No source apply, learning apply, dependency install, or cloud fallback.",
        "",
    ]

    if error:
        lines += [
            "## Query Status",
            "Process query failed safely:",
            error,
            "",
            "No cleanup decision should be made from this failed query.",
        ]
        return "\n".join(lines)

    lines += ["## Engel-Owned Process Rows", ""]
    if not rows:
        lines.append("- None found by command-line filter.")
    for r in rows:
        command = str(r.get("command", ""))
        if len(command) > 220:
            command = command[:220] + "..."
        lines.append("- PID " + str(r.get("pid")) + " / PPID " + str(r.get("ppid")) + " / " + str(r.get("name")) + " / " + command)

    lines += ["", "## Parent-Child Chains", ""]
    for script_name in ["engel_companion.py", "engel_mobile_bridge.py", "engel_alive_loop.py"]:
        chains = _process_truth_script_chains_v2process_a(rows, script_name)
        lines.append("### " + script_name)
        if not chains:
            lines.append("- No chain found.")
            lines.append("")
            continue
        for index, chain in enumerate(chains):
            label = _process_truth_script_label_v2process_a(script_name, index)
            lines.append("- " + label + ": " + _process_truth_chain_text_v2process_a(chain))
        lines.append("")

    mobile_chains = _process_truth_script_chains_v2process_a(rows, "engel_mobile_bridge.py")
    alive_chains = _process_truth_script_chains_v2process_a(rows, "engel_alive_loop.py")

    lines += [
        "## Duplicate Summary",
        "- Mobile bridge chain count: " + str(len(mobile_chains)),
        "- Alive loop chain count: " + str(len(alive_chains)),
    ]
    if len(mobile_chains) > 1:
        lines.append("- Mobile bridge duplicate candidates for a later APPROVE-gated cleanup: " + "; ".join(_process_truth_chain_text_v2process_a(c) for c in mobile_chains[1:]))
    else:
        lines.append("- Mobile bridge duplicate candidates: none detected.")
    if len(alive_chains) > 1:
        lines.append("- Alive loop duplicate candidates for a later APPROVE-gated cleanup: " + "; ".join(_process_truth_chain_text_v2process_a(c) for c in alive_chains[1:]))
    else:
        lines.append("- Alive loop duplicate candidates: none detected.")

    lines += [
        "",
        "## Classifications",
        "- ENGEL_UI_MAIN: Engel companion/app command process chain when command line includes engel_companion.py.",
        "- ENGEL_MOBILE_BRIDGE_EXPECTED: first detected mobile bridge chain by root PID; keeper choice must be re-confirmed before cleanup.",
        "- ENGEL_MOBILE_BRIDGE_DUPLICATE: additional mobile bridge chains after the first detected chain.",
        "- ENGEL_ALIVE_LOOP_EXPECTED: first detected alive loop chain by root PID; keeper choice must be re-confirmed before cleanup.",
        "- ENGEL_ALIVE_LOOP_DUPLICATE: additional alive loop chains after the first detected chain.",
        "- ENGEL_PARENT_CHILD_CHAIN: any cmd/python/pythonw lineage shown with arrows.",
        "- UNKNOWN_PYTHON_DO_NOT_TOUCH: Python process without an Engel script match or without enough command-line proof.",
        "",
        "## Later Cleanup Gate",
        "These commands do not clean anything. A future cleanup command must require an exact APPROVE token, re-run process truth immediately before acting, and show the selected keeper/cleanup candidates first.",
    ]
    return "\n".join(lines)


def process_truth_status_v2process_a():
    return _process_truth_report_v2process_a("Engel Process Truth Status V2PROCESS-A")


def process_duplicate_report_v2process_a():
    return _process_truth_report_v2process_a("Engel Process Duplicate Report V2PROCESS-A", duplicate_focus=True)


