def _app_launcher_render_diagnosis_v2app_a(diagnosis):
    lines = [
        "# Branded Launcher Diagnosis V2APP-A",
        "",
        "Time: " + diagnosis.get("generated_at", now()),
        "Workspace: " + ROOT,
        "",
        "Status: PLAN/STAGING ONLY",
        "",
        "Summary:",
        "- The current visible Body entry found in launcher evidence is `engel_companion.py`.",
        "- `engel_app.py` remains Engel's core Mind/command module and CLI path.",
        "- `Start Engel App.vbs` starts helper scripts and the companion through `pythonw.exe`.",
        "- Existing process truth reports show Python process names are expected for the current script-based launch path.",
        "- No live launch behavior was changed by V2APP-A.",
        "",
        "## Current Launch Method",
        "",
        "- Hidden launcher: " + diagnosis["current_launch_method"].get("hidden_launcher", ""),
        "- Debug launcher: " + diagnosis["current_launch_method"].get("debug_launcher", ""),
        "- Desktop shortcut script: " + diagnosis["current_launch_method"].get("desktop_shortcut_script", ""),
        "- Visible Body entry: " + diagnosis["current_launch_method"].get("visible_body_entry", ""),
        "- Core Mind module: " + diagnosis["current_launch_method"].get("core_mind_module", ""),
        "- Helper scripts: " + ", ".join(diagnosis["current_launch_method"].get("helper_scripts", [])),
        "",
        "## Existing BAT/PS1/VBS Files Inspected",
        "",
    ]
    for row in diagnosis.get("all_bat_ps1_vbs_files", []):
        lines.append("- " + row.get("relative_path", "") + " | exists=" + str(row.get("exists")) + " | bytes=" + str(row.get("size_bytes")))

    lines += [
        "",
        "## Detected Launcher/Shortcut Files",
        "",
    ]
    for row in diagnosis.get("detected_launch_files", []):
        lines.append("- " + row.get("relative_path", "") + " | pythonw=" + str(row.get("contains", {}).get("pythonw")) + " | companion=" + str(row.get("contains", {}).get("engel_companion")) + " | shortcut=" + str(row.get("contains", {}).get("shortcut")))

    lines += [
        "",
        "## Python Entry Scripts Found",
        "",
    ]
    for row in diagnosis.get("python_entry_scripts", []):
        lines.append("- " + row.get("relative_path", "") + " | exists=" + str(row.get("exists")) + " | bytes=" + str(row.get("size_bytes")))

    lines += [
        "",
        "## Icon/Image Assets Found",
        "",
    ]
    for row in diagnosis.get("icon_candidates", []):
        lines.append("- " + row.get("relative_path", "") + " | exists=" + str(row.get("exists")) + " | bytes=" + str(row.get("size_bytes")))

    lines += [
        "",
        "Recommended icon path:",
        "- " + (diagnosis.get("recommended_icon_path") or "none found"),
        "",
        "Shortcut icon note:",
        "- " + diagnosis.get("shortcut_icon_note", ""),
        "",
        "## Process Truth Reports Found",
        "",
    ]
    for row in diagnosis.get("process_truth_reports", []):
        lines.append("- " + row.get("relative_path", "") + " | exists=" + str(row.get("exists")) + " | bytes=" + str(row.get("size_bytes")))

    lines += [
        "",
        "Safety:",
        "- Diagnosis only.",
        "- No EXE built.",
        "- No dependency installed.",
        "- No launcher file changed.",
        "- No startup behavior changed.",
        "- No process killed.",
        "- No research, swarm source apply, desktop action, or cloud fallback started.",
    ]
    return "\n".join(lines)


