def app_launcher_plan_v2app_a(command_name="app launcher plan"):
    import json

    diagnosis = _app_launcher_collect_diagnosis_v2app_a()
    spec = _app_launcher_spec_payload_v2app_a(diagnosis)
    paths = _app_launcher_paths_v2app_a()

    files_written = {
        "plan_md": paths["plan_md"],
        "plan_json": paths["plan_json"],
        "diagnosis_md": paths["diagnosis_md"],
        "memory_spec": paths["memory_spec"],
        "staging_readme": paths["staging_readme"],
        "staging_spec": paths["staging_spec"],
    }

    diagnosis_report = _app_launcher_render_diagnosis_v2app_a(diagnosis)
    plan_report = _app_launcher_render_plan_v2app_a(diagnosis, spec, files_written, command_name)
    json_payload = _app_launcher_json_payload_v2app_a(diagnosis, spec, files_written)
    staging_readme = _app_launcher_render_staging_readme_v2app_a(spec)

    write_file(paths["diagnosis_md"], diagnosis_report)
    write_file(paths["plan_md"], plan_report)
    write_file(paths["plan_json"], json.dumps(json_payload, indent=2))
    write_file(paths["memory_spec"], json.dumps(spec, indent=2))
    write_file(paths["staging_readme"], staging_readme)
    write_file(paths["staging_spec"], json.dumps(spec, indent=2))

    append_log("V2APP-A branded launcher plan generated by command: " + str(command_name))
    return plan_report


def branded_launcher_plan_v2app_a():
    return app_launcher_plan_v2app_a("branded launcher plan")


def exe_plan_v2app_a():
    return app_launcher_plan_v2app_a("exe plan")


def _app_launcher_text_targets_live_exe_v2app_am(launcher_text, live_exe_path):
    lower = str(launcher_text or "").lower()
    live_lower = str(live_exe_path or "").lower()
    if live_lower and live_lower in lower:
        return True
    return (
        "wscript.scriptfullname" in lower
        and "buildpath" in lower
        and "live\\app\\engel.exe" in lower
    )


def _app_post_y2_stable_checkpoint_v2app_ab():
    import json

    live_exe_path = os.path.join(ROOT, "live", "app", "Engel.exe")
    launcher_path = os.path.join(ROOT, "Start Engel App.vbs")
    live_prompt_path = os.path.join(ROOT, "prompts", "ENGEL_SYSTEM.md")
    expected_live_sha = "5D53431C2014FCDE05036EC5CDC97BDA0E4A76AFDE61B8585EF9702ACF289C25"
    expected_launcher_sha = "A22E4F5E7690441F60B92DCA6F402FBEEB5A0B8E753BD2231A92A02289969186"
    expected_prompt_sha = "19660C2E7121257B739AF431F156637F76FEDC9D15CEE64004F7EFDE77DBAB3D"
    previous_launcher_sha = "C36308E77220E24FBCF3FD9A24B6209F72CD19AB95B51662737D5F3952068320"
    aa_state_path = os.path.join(MEMORY_DIR, "V2APP_AA_POST_LAUNCHER_STABLE_CHECKPOINT.json")
    aa_marker_path = os.path.join(MEMORY_DIR, "ENGEL_STABLE_CHECKPOINT_V2APPAA.md")
    ai_state_path = os.path.join(MEMORY_DIR, "V2APP_AI_POST_PROMOTION_LAUNCH_SMOKE_RELEASE_CHECKPOINT.json")
    ai_marker_path = os.path.join(MEMORY_DIR, "ENGEL_STABLE_RELEASE_CHECKPOINT_V2APPAI.md")
    z_state_path = os.path.join(MEMORY_DIR, "V2APP_Z_MANUAL_SHORTCUT_LAUNCH_SMOKE_REVIEW.json")
    d3_state_path = os.path.join(MEMORY_DIR, "ENGEL_MAIN_IDENTITY_STATE_V2IDENTITYD3.json")
    y2_report_path = os.path.join(REPORTS_DIR, "app", "V2APP_Y2_LAUNCHER_SWITCH_RESULT.md")

    def record(path):
        if "_app_staged_launch_report_record_v2app_n" in globals():
            return _app_staged_launch_report_record_v2app_n(path, include_hash=True)
        data = _app_launcher_file_record_v2app_a(path)
        data["sha256"] = ""
        return data

    def read_json(path):
        if not os.path.exists(path):
            return {}
        try:
            return json.loads(read_file(path))
        except Exception:
            return {}

    live_exe_record = record(live_exe_path)
    launcher_record = record(launcher_path)
    prompt_record = record(live_prompt_path)
    launcher_text = read_file(launcher_path) if os.path.exists(launcher_path) else ""
    launcher_targets_live_exe = _app_launcher_text_targets_live_exe_v2app_am(launcher_text, live_exe_path)
    launcher_has_old_script_flow = any(token in launcher_text.lower() for token in [
        "pythonw.exe",
        "engel_alive_loop.py",
        "engel_mobile_bridge.py",
        "engel_companion.py",
    ])
    aa_state = read_json(aa_state_path)
    ai_state = read_json(ai_state_path)
    z_state = read_json(z_state_path)
    d3_state = read_json(d3_state_path)
    y2_text = read_file(y2_report_path) if os.path.exists(y2_report_path) else ""
    aa_verified = bool(os.path.exists(aa_marker_path) and aa_state.get("checkpoint_result") == "STABLE_CHECKPOINT_RECORDED")
    aa_live_hash_match = live_exe_record.get("sha256") == expected_live_sha
    ai_result = str(ai_state.get("final_result", ""))
    ai_expected_live_sha = str(ai_state.get("post_smoke_live_exe_sha256") or "B36E3C9D5F83F7BECC77EDBCAF84E327C04AB45A7BC1D77A6D68767CB64A62FE")
    ai_expected_launcher_sha = str(ai_state.get("post_smoke_launcher_sha256") or expected_launcher_sha)
    ai_expected_prompt_sha = str(ai_state.get("post_smoke_live_prompt_sha256") or expected_prompt_sha)
    ai_marker_exists = os.path.exists(ai_marker_path)
    ai_verified = bool(
        ai_marker_exists
        and ai_result in ("RELEASE_CHECKPOINT_RECORDED", "SAFE_WITH_FOLLOWUP")
        and live_exe_record.get("sha256") == ai_expected_live_sha
        and launcher_record.get("sha256") == ai_expected_launcher_sha
        and prompt_record.get("sha256") == ai_expected_prompt_sha
    )
    current_checkpoint = "V2APP-AI" if ai_marker_exists else "V2APP-AA"
    current_result = ai_result if ai_marker_exists else str(aa_state.get("checkpoint_result", ""))
    current_expected_live_sha = ai_expected_live_sha if ai_marker_exists else expected_live_sha
    current_live_hash_match = live_exe_record.get("sha256") == current_expected_live_sha
    current_release_verified = ai_verified if ai_marker_exists else bool(
        aa_verified
        and aa_live_hash_match
        and launcher_record.get("sha256") == expected_launcher_sha
        and prompt_record.get("sha256") == expected_prompt_sha
    )

    return {
        "live_exe_path": live_exe_path,
        "expected_live_exe_sha256": current_expected_live_sha,
        "historical_aa_live_exe_sha256": expected_live_sha,
        "live_exe_record": live_exe_record,
        "live_exe_hash_match": current_live_hash_match,
        "launcher_path": launcher_path,
        "expected_launcher_sha256": expected_launcher_sha,
        "launcher_record": launcher_record,
        "launcher_hash_match": launcher_record.get("sha256") == expected_launcher_sha,
        "previous_launcher_sha256": previous_launcher_sha,
        "launcher_targets_live_exe": launcher_targets_live_exe,
        "launcher_has_old_script_flow": launcher_has_old_script_flow,
        "live_prompt_path": live_prompt_path,
        "expected_live_prompt_sha256": expected_prompt_sha,
        "live_prompt_record": prompt_record,
        "live_prompt_hash_match": prompt_record.get("sha256") == expected_prompt_sha,
        "aa_state_path": aa_state_path,
        "aa_marker_path": aa_marker_path,
        "aa_result": str(aa_state.get("checkpoint_result", "")),
        "aa_verified": aa_verified,
        "aa_live_exe_hash_match": aa_live_hash_match,
        "aa_historical_superseded": ai_marker_exists,
        "ai_state_path": ai_state_path,
        "ai_marker_path": ai_marker_path,
        "ai_result": ai_result,
        "ai_verified": ai_verified,
        "current_stable_checkpoint": current_checkpoint,
        "current_release_state": current_result,
        "current_expected_live_exe_sha256": current_expected_live_sha,
        "current_live_exe_hash_match": current_live_hash_match,
        "current_release_checkpoint_verified": current_release_verified,
        "z_state_path": z_state_path,
        "z_result": str(z_state.get("final_result", "")),
        "manual_launch_confirmed": bool(aa_state.get("manual_launch_confirmed_by_josh") or str(z_state.get("launch_succeeded", "")).upper() == "YES"),
        "d3_state_path": d3_state_path,
        "d3_result": str(d3_state.get("final_result", "")),
        "d3_verified": d3_state.get("final_result") == "STABLE_IDENTITY_VERIFIED",
        "y2_report_path": y2_report_path,
        "y2_result": "LAUNCHER_SWITCHED_TO_LIVE_CONTRACT_EXE" if "LAUNCHER_SWITCHED_TO_LIVE_CONTRACT_EXE" in y2_text else "",
        "y2_verified": "LAUNCHER_SWITCHED_TO_LIVE_CONTRACT_EXE" in y2_text,
        "stable_checkpoint_verified": current_release_verified,
    }


