def _app_launcher_shortcut_script_v2app_b(spec):
    launcher = spec.get("approved_launcher_target", os.path.join(ROOT, "Start Engel App.vbs"))
    icon = spec.get("icon_path", os.path.join(ROOT, "assets", "branding", "final", "engel_icon_final.ico"))
    return "\n".join([
        "# V2APP-B STAGED ONLY - DO NOT RUN WITHOUT EXPLICIT APPROVE.",
        "# This script is generated as a reviewed proposal. It was not executed by V2APP-B.",
        "# Running it would create a desktop shortcut, so it must wait for a later explicit APPROVE gate.",
        "# It intentionally does not delete, overwrite, or replace any existing shortcut.",
        "",
        "param(",
        "    [string]$Approval = \"\"",
        ")",
        "",
        "$ErrorActionPreference = \"Stop\"",
        "",
        "if ($Approval -ne \"APPROVE\") {",
        "    throw \"Blocked: V2APP-B staged shortcut script requires explicit APPROVE before it can run.\"",
        "}",
        "",
        "$LauncherPath = \"" + launcher + "\"",
        "$IconPath = \"" + icon + "\"",
        "$ShortcutName = \"Engel\"",
        "$Desktop = [Environment]::GetFolderPath(\"Desktop\")",
        "$ShortcutPath = Join-Path $Desktop ($ShortcutName + \".lnk\")",
        "",
        "if (-not (Test-Path -LiteralPath $LauncherPath)) {",
        "    throw \"Approved launcher target not found: $LauncherPath\"",
        "}",
        "",
        "if (-not (Test-Path -LiteralPath $IconPath)) {",
        "    throw \"Engel icon not found: $IconPath\"",
        "}",
        "",
        "if (Test-Path -LiteralPath $ShortcutPath) {",
        "    throw \"Refusing to replace existing shortcut: $ShortcutPath. A later approved command must explicitly choose replacement.\"",
        "}",
        "",
        "$Wsh = New-Object -ComObject WScript.Shell",
        "$Shortcut = $Wsh.CreateShortcut($ShortcutPath)",
        "$Shortcut.TargetPath = \"wscript.exe\"",
        "$Shortcut.Arguments = '\"' + $LauncherPath + '\"'",
        "$Shortcut.WorkingDirectory = \"" + ROOT + "\"",
        "$Shortcut.Description = \"Start Engel\"",
        "$Shortcut.IconLocation = $IconPath",
        "$Shortcut.Save()",
        "",
        "Write-Host \"Created staged-approved desktop shortcut:\"",
        "Write-Host $ShortcutPath",
        "",
    ])


