def app_launcher_assets_plan_v2app_b(command_name="app launcher assets plan"):
    import json

    diagnosis = _app_launcher_diagnosis_v2app_b()
    spec = _app_launcher_spec_payload_v2app_b(diagnosis)
    paths = _app_launcher_paths_v2app_b()
    files_written = {
        "shortcut_script": paths["shortcut_script"],
        "exe_spec_proposal": paths["exe_spec_proposal"],
        "icon_plan": paths["icon_plan"],
        "plan_md": paths["plan_md"],
        "plan_json": paths["plan_json"],
        "memory_spec": paths["memory_spec"],
    }
    report = _app_launcher_assets_report_v2app_b(diagnosis, spec, files_written, command_name)
    payload = _app_launcher_json_payload_v2app_b(diagnosis, spec, files_written, command_name)

    write_file(paths["shortcut_script"], _app_launcher_shortcut_script_v2app_b(spec))
    write_file(paths["exe_spec_proposal"], _app_launcher_exe_spec_proposal_v2app_b(spec))
    write_file(paths["icon_plan"], _app_launcher_icon_plan_v2app_b(spec))
    write_file(paths["plan_md"], report)
    write_file(paths["plan_json"], json.dumps(payload, indent=2))
    write_file(paths["memory_spec"], json.dumps(spec, indent=2))

    append_log("V2APP-B branded launcher assets staged by command: " + str(command_name))
    return report


