def _app_exe_packaging_relative_v2app_d(path):
    try:
        return os.path.relpath(path, ROOT)
    except Exception:
        return str(path)


def _app_exe_packaging_dir_listing_v2app_d(path, max_items=60):
    rows = []
    try:
        if not os.path.isdir(path):
            return rows
        for name in sorted(os.listdir(path))[:max_items]:
            full = os.path.join(path, name)
            rows.append({
                "name": name,
                "relative_path": _app_exe_packaging_relative_v2app_d(full),
                "is_dir": os.path.isdir(full),
                "size_bytes": os.path.getsize(full) if os.path.isfile(full) else 0,
                "modified": datetime.datetime.fromtimestamp(os.path.getmtime(full)).strftime("%Y-%m-%d %H:%M:%S"),
            })
    except Exception:
        return rows
    return rows


def _app_exe_packaging_venv_layout_v2app_d():
    venv = os.path.join(ROOT, ".venv")
    scripts = os.path.join(venv, "Scripts")
    return {
        "venv": _app_launcher_file_record_v2app_a(venv),
        "top_level": _app_exe_packaging_dir_listing_v2app_d(venv, 20),
        "scripts_key_files": [
            _app_launcher_file_record_v2app_a(os.path.join(scripts, name))
            for name in [
                "python.exe",
                "pythonw.exe",
                "pip.exe",
                "pyinstaller.exe",
                "pyi-makespec.exe",
                "nuitka.exe",
                "cxfreeze.exe",
            ]
        ],
    }


def _app_exe_packaging_glob_existing_v2app_d(pattern):
    try:
        import glob
        return [p for p in sorted(glob.glob(pattern)) if os.path.exists(p)]
    except Exception:
        return []


def _app_exe_packaging_dependency_indicators_v2app_d():
    site = os.path.join(ROOT, ".venv", "Lib", "site-packages")
    scripts = os.path.join(ROOT, ".venv", "Scripts")
    candidates = [
        os.path.join(scripts, "pyinstaller.exe"),
        os.path.join(scripts, "pyi-makespec.exe"),
        os.path.join(scripts, "nuitka.exe"),
        os.path.join(scripts, "cxfreeze.exe"),
        os.path.join(scripts, "cxfreeze-quickstart.exe"),
        os.path.join(site, "PyInstaller"),
        os.path.join(site, "nuitka"),
        os.path.join(site, "cx_Freeze"),
    ]
    candidates += _app_exe_packaging_glob_existing_v2app_d(os.path.join(site, "pyinstaller-*.dist-info"))
    candidates += _app_exe_packaging_glob_existing_v2app_d(os.path.join(site, "PyInstaller-*.dist-info"))
    candidates += _app_exe_packaging_glob_existing_v2app_d(os.path.join(site, "nuitka-*.dist-info"))
    candidates += _app_exe_packaging_glob_existing_v2app_d(os.path.join(site, "Nuitka-*.dist-info"))
    candidates += _app_exe_packaging_glob_existing_v2app_d(os.path.join(site, "cx_Freeze-*.dist-info"))
    seen = []
    for path in candidates:
        if os.path.exists(path) and path not in seen:
            seen.append(path)
    return seen


def _app_exe_packaging_exe_candidates_v2app_d():
    explicit = [
        os.path.join(ROOT, "Engel.exe"),
        os.path.join(ROOT, "dist", "Engel.exe"),
        os.path.join(ROOT, "dist", "Engel", "Engel.exe"),
        os.path.join(ROOT, "build", "Engel.exe"),
        os.path.join(ROOT, "staging", "app", "Engel.exe"),
        os.path.join(ROOT, "staging", "app", "dist", "Engel.exe"),
        os.path.join(ROOT, "staging", "app", "dist", "Engel", "Engel.exe"),
        os.path.join(ROOT, "staging", "app", "build_output", "Engel.exe"),
        os.path.join(ROOT, "staging", "app", "build_output", "dist", "Engel.exe"),
        os.path.join(ROOT, "staging", "app", "build_output", "dist", "Engel", "Engel.exe"),
    ]
    candidates = [p for p in explicit if os.path.exists(p)]
    build_output = os.path.join(ROOT, "staging", "app", "build_output")
    try:
        if os.path.isdir(build_output):
            for root, dirs, files in os.walk(build_output):
                dirs[:] = [d for d in dirs if d not in ["__pycache__"]]
                for filename in files:
                    if filename.lower() == "engel.exe":
                        full = os.path.join(root, filename)
                        if full not in candidates:
                            candidates.append(full)
    except Exception:
        pass
    return candidates


