def app_exe_build_plan_v2app_d():
    import json

    diagnosis = _app_exe_packaging_diagnosis_v2app_d("app exe build plan")
    spec = _app_exe_packaging_spec_payload_v2app_d(diagnosis)
    paths = _app_exe_packaging_paths_v2app_d()
    files_written = {
        "plan_md": paths["plan_md"],
        "plan_json": paths["plan_json"],
        "checklist_md": paths["checklist_md"],
        "memory_spec": paths["memory_spec"],
        "staging_proposal": paths["staging_proposal"],
        "pyinstaller_spec_draft": paths["pyinstaller_spec_draft"],
    }

    plan = _app_exe_packaging_render_plan_v2app_d(diagnosis, spec, files_written)
    checklist = _app_exe_packaging_render_checklist_v2app_d(spec)
    staging_proposal = _app_exe_packaging_render_staging_proposal_v2app_d(spec)
    spec_draft = _app_exe_packaging_render_pyinstaller_spec_draft_v2app_d(spec)
    payload = _app_exe_packaging_json_payload_v2app_d(diagnosis, spec, files_written)

    write_file(paths["plan_md"], plan)
    write_file(paths["plan_json"], json.dumps(payload, indent=2))
    write_file(paths["checklist_md"], checklist)
    write_file(paths["memory_spec"], json.dumps(spec, indent=2))
    write_file(paths["staging_proposal"], staging_proposal)
    write_file(paths["pyinstaller_spec_draft"], spec_draft)

    append_log("V2APP-D EXE packaging/build plan generated; no EXE built and no dependency installed.")
    return plan


