def _app_exe_staged_quote_arg_v2app_e(arg):
    text = str(arg)
    if text == "":
        return '""'
    if any(ch.isspace() for ch in text) or '"' in text:
        return '"' + text.replace('"', '\\"') + '"'
    return text


def _app_exe_staged_build_command_v2app_e():
    expected = _app_exe_staged_expected_v2app_e()
    command = [
        expected["pyinstaller_exe"],
        "--noconfirm",
        "--clean",
        "--windowed",
        "--onefile",
        "--name",
        "Engel",
        "--icon",
        expected["icon_path"],
        "--distpath",
        expected["build_output"],
        "--workpath",
        expected["build_work"],
        "--specpath",
        expected["spec_path"],
        expected["entry_point"],
    ]
    return command, " ".join(_app_exe_staged_quote_arg_v2app_e(part) for part in command)


def _app_exe_staged_inside_staging_v2app_e(path):
    staging = os.path.abspath(os.path.join(ROOT, "staging", "app"))
    target = os.path.abspath(path)
    return target == staging or target.startswith(staging + os.sep)


def _app_exe_staged_dependency_status_v2app_e():
    expected = _app_exe_staged_expected_v2app_e()
    pyinstaller = _app_launcher_file_record_v2app_a(expected["pyinstaller_exe"])
    pyi_makespec = _app_launcher_file_record_v2app_a(expected["pyi_makespec_exe"])
    nuitka = _app_launcher_file_record_v2app_a(expected["nuitka_exe"])
    cxfreeze = _app_launcher_file_record_v2app_a(expected["cxfreeze_exe"])
    cxfreeze_quickstart = _app_launcher_file_record_v2app_a(expected["cxfreeze_quickstart_exe"])
    tools = [
        {"name": "PyInstaller", "role": "preferred_v2appe_build_tool", "record": pyinstaller, "usable_for_v2appe_build": bool(pyinstaller.get("exists"))},
        {"name": "pyi-makespec", "role": "pyinstaller_companion_script", "record": pyi_makespec, "usable_for_v2appe_build": False},
        {"name": "Nuitka", "role": "status_only_alternative", "record": nuitka, "usable_for_v2appe_build": False},
        {"name": "cx_Freeze", "role": "status_only_alternative", "record": cxfreeze, "usable_for_v2appe_build": False},
        {"name": "cx_Freeze quickstart", "role": "status_only_alternative_companion_script", "record": cxfreeze_quickstart, "usable_for_v2appe_build": False},
    ]
    available = [tool["name"] for tool in tools if tool["record"].get("exists")]
    partial = []
    if pyi_makespec.get("exists") and not pyinstaller.get("exists"):
        partial.append("pyi-makespec.exe exists but pyinstaller.exe is missing")
    if cxfreeze_quickstart.get("exists") and not cxfreeze.get("exists"):
        partial.append("cxfreeze-quickstart.exe exists but cxfreeze.exe is missing")

    pyinstaller_available = bool(pyinstaller.get("exists"))
    status = "PYINSTALLER_AVAILABLE" if pyinstaller_available and not partial else "MISSING"
    if partial:
        status = "PARTIAL_OR_AMBIGUOUS"

    return {
        "version": "V2APP-E",
        "generated_at": now(),
        "scripts_dir": os.path.join(ROOT, ".venv", "Scripts"),
        "checked_scope": "project .venv Scripts only",
        "tools": tools,
        "available_tools": available,
        "partial_or_ambiguous": partial,
        "pyinstaller_available": pyinstaller_available,
        "supported_tool_available": bool(available),
        "v2appe_build_tool": "PyInstaller",
        "v2appe_can_build": pyinstaller_available and not partial,
        "status": status,
        "message": "PyInstaller is available for the staged V2APP-E build." if pyinstaller_available and not partial else "Staged build cannot run yet.",
    }


def _app_exe_staged_exe_candidates_v2app_e():
    expected = _app_exe_staged_expected_v2app_e()
    build_output = expected["build_output"]
    explicit = [
        os.path.join(build_output, "Engel.exe"),
        os.path.join(build_output, "Engel", "Engel.exe"),
        os.path.join(ROOT, "staging", "app", "Engel.exe"),
    ]
    candidates = [p for p in explicit if os.path.exists(p)]
    try:
        if os.path.isdir(build_output):
            for root, dirs, files in os.walk(build_output):
                dirs[:] = [d for d in dirs if d not in ["__pycache__"]]
                for filename in files:
                    if filename.lower() == "engel.exe":
                        full = os.path.join(root, filename)
                        if full not in candidates:
                            candidates.append(full)
    except Exception:
        pass
    return candidates


