def _app_exe_staged_render_result_v2app_e(command_display, run_result, exes):
    stdout = str(getattr(run_result, "stdout", "") or "")
    stderr = str(getattr(run_result, "stderr", "") or "")
    if len(stdout) > 8000:
        stdout = stdout[-8000:]
    if len(stderr) > 8000:
        stderr = stderr[-8000:]
    success = getattr(run_result, "returncode", 1) == 0
    return "\n".join([
        "# Engel EXE Staged Build Result V2APP-H",
        "",
        "Command: app exe build staged APPROVE",
        "Status: " + ("BUILD_SUCCEEDED" if success else "BUILD_FAILED"),
        "Return code: " + str(getattr(run_result, "returncode", "")),
        "",
        "Executed command:",
        "```text",
        command_display,
        "```",
        "",
        "Staged Engel.exe candidates:",
        "- " + (", ".join(exes) if exes else "none"),
        "",
        "stdout tail:",
        "```text",
        stdout,
        "```",
        "",
        "stderr tail:",
        "```text",
        stderr,
        "```",
        "",
        "Safety confirmations:",
        "- Dependency install performed: NO",
        "- Live launcher changed: NO",
        "- Desktop shortcut changed: NO",
        "- Startup entries added: NO",
        "- Scheduled tasks added: NO",
        "- Research loop started: NO",
        "- Swarm/research source apply happened: NO",
        "- Cloud fallback happened: NO",
    ])


def app_exe_build_staged_v2app_e(approval_text=""):
    import json
    import subprocess

    paths = _app_exe_staged_paths_v2app_e()
    paths_h = _app_exe_staged_paths_v2app_h()
    approval = str(approval_text or "").strip()
    command, command_display = _app_exe_staged_build_command_v2app_e()
    deps = _app_exe_staged_dependency_status_v2app_e()

    if approval != "APPROVE":
        _app_exe_staged_write_state_v2app_e("app exe build staged", "REFUSED_APPROVAL_NOT_EXACT", {
            "future_build_command_display": command_display,
            "refusal": "Exact APPROVE token required. No build was run.",
        })
        _app_exe_staged_write_state_v2app_h("app exe build staged", "REFUSED_APPROVAL_NOT_EXACT", {
            "future_build_command_display": command_display,
            "refusal": "Exact APPROVE token required. No build was run.",
        })
        return "\n".join([
            "# Engel EXE Staged Build V2APP-H",
            "",
            "Approval required: exact `app exe build staged APPROVE`.",
            "",
            "No build was run.",
            "No dependency was installed.",
            "No launcher or shortcut was changed.",
        ])

    if not deps.get("v2appe_can_build"):
        dependency_report = _app_exe_staged_render_dependency_report_v2app_e(deps)
        write_file(paths["dependency_md"], dependency_report)
        _app_exe_staged_write_state_v2app_e("app exe build staged APPROVE", "REFUSED_DEPENDENCY_MISSING", {
            "future_build_command_display": command_display,
            "refusal": "Packaging dependency missing. No build was run. Separate dependency approval required.",
        })
        _app_exe_staged_write_state_v2app_h("app exe build staged APPROVE", "REFUSED_DEPENDENCY_MISSING", {
            "future_build_command_display": command_display,
            "refusal": "Packaging dependency missing. No build was run. Separate dependency approval required.",
        })
        append_log("V2APP-H staged build refused: packaging dependency missing. No build was run.")
        return "\n".join([
            "# Engel EXE Staged Build V2APP-H",
            "",
            "Packaging dependency missing. No build was run. Separate dependency approval required.",
            "",
            "Required staged build tool:",
            "- PyInstaller already available in project `.venv\\Scripts`.",
            "",
            "Detected tool indicators:",
            "- " + (", ".join(deps.get("available_tools", [])) if deps.get("available_tools") else "none"),
            "",
            "No dependency was installed.",
            "No launcher or shortcut was changed.",
        ])

    expected = _app_exe_staged_expected_v2app_e()
    guarded_paths = [
        expected["build_output"],
        expected["build_work"],
        expected["spec_path"],
        expected["staged_exe"],
    ]
    if not all(_app_exe_staged_inside_staging_v2app_e(path) for path in guarded_paths):
        _app_exe_staged_write_state_v2app_e("app exe build staged APPROVE", "REFUSED_OUTPUT_OUTSIDE_STAGING", {
            "future_build_command_display": command_display,
            "refusal": "Build output/work path was outside staging. No build was run.",
        })
        _app_exe_staged_write_state_v2app_h("app exe build staged APPROVE", "REFUSED_OUTPUT_OUTSIDE_STAGING", {
            "future_build_command_display": command_display,
            "refusal": "Build output/work path was outside staging. No build was run.",
        })
        return "\n".join([
            "# Engel EXE Staged Build V2APP-H",
            "",
            "Build output/work path was outside staging. No build was run.",
            "",
            "No dependency was installed.",
            "No launcher or shortcut was changed.",
        ])

    os.makedirs(expected["build_output"], exist_ok=True)
    os.makedirs(expected["build_work"], exist_ok=True)
    os.makedirs(expected["spec_path"], exist_ok=True)

    pyinstaller_path = os.path.abspath(expected["pyinstaller_exe"])
    command_path = os.path.abspath(command[0]) if command else ""
    if command_path != pyinstaller_path or not os.path.exists(pyinstaller_path):
        _app_exe_staged_write_state_v2app_h("app exe build staged APPROVE", "REFUSED_PROJECT_VENV_PYINSTALLER_INVALID", {
            "future_build_command_display": command_display,
            "refusal": "Project .venv PyInstaller target is missing or command target is not exact. No build was run.",
        })
        return "\n".join([
            "# Engel EXE Staged Build V2APP-H",
            "",
            "Project .venv PyInstaller target is missing or command target is not exact. No build was run.",
            "",
            "No dependency was installed.",
            "No launcher or shortcut was changed.",
        ])

    append_log("V2APP-H staged build command before execution: " + command_display)
    run_result = subprocess.run(command, cwd=ROOT, capture_output=True, text=True)
    exes = _app_exe_staged_exe_candidates_v2app_e()
    result = _app_exe_staged_render_result_v2app_e(command_display, run_result, exes)
    write_file(paths_h["result_md"], result)
    state = _app_exe_staged_state_payload_v2app_e("app exe build staged APPROVE", "BUILD_RAN", {
        "result_report_written": True,
        "result_report_path": paths_h["result_md"],
        "build_return_code": run_result.returncode,
        "build_command": command,
        "build_command_display": command_display,
    })
    state["version"] = "V2APP-H"
    if isinstance(state.get("expected"), dict):
        state["expected"]["version"] = "V2APP-H"
    write_file(paths_h["state_json"], json.dumps(state, indent=2))
    append_log("V2APP-H staged build finished with return code " + str(run_result.returncode) + ": " + paths_h["result_md"])
    return result


