def app_exe_smoke_test_staged_v2app_i(approval_text=""):
    import json
    import subprocess
    import time

    paths = _app_exe_smoke_test_paths_v2app_i()
    approval = str(approval_text or "").strip()

    if approval != "APPROVE":
        _app_exe_smoke_test_write_state_v2app_i("app exe smoke test staged", "REFUSED_APPROVAL_NOT_EXACT", {
            "refusal": "Exact APPROVE token required. No smoke test was run.",
        })
        return "\n".join([
            "# Engel EXE Smoke Test V2APP-I",
            "",
            "Approval required: exact `app exe smoke test staged APPROVE`.",
            "",
            "No Engel.exe launch was attempted.",
            "No launcher or shortcut was changed.",
        ])

    payload = _app_exe_smoke_test_status_payload_v2app_i("app exe smoke test staged APPROVE", "SMOKE_TEST_APPROVED")
    expected = payload.get("expected", {})
    staged_exe = expected.get("staged_exe", "")

    if not payload.get("required_staged_exe_exact") or not payload.get("staged_exe_inside_staging"):
        payload.update({
            "state_status": "REFUSED_TARGET_OUTSIDE_APPROVED_STAGING_PATH",
            "process_start_attempted": False,
            "process_started": False,
            "refusal": "Smoke-test target was not the exact staged Engel.exe path. No smoke test was run.",
            "result_report_written": True,
            "result_report_path": paths["result_md"],
        })
        result = _app_exe_smoke_test_render_result_v2app_i(payload)
        write_file(paths["result_md"], result)
        write_file(paths["state_json"], json.dumps(payload, indent=2))
        append_log("V2APP-I staged EXE smoke test refused: target outside approved staging path.")
        return result

    if not os.path.exists(staged_exe) or not os.path.isfile(staged_exe):
        payload.update({
            "state_status": "REFUSED_STAGED_EXE_MISSING",
            "process_start_attempted": False,
            "process_started": False,
            "refusal": "Staged Engel.exe is missing. No smoke test was run.",
            "result_report_written": True,
            "result_report_path": paths["result_md"],
        })
        result = _app_exe_smoke_test_render_result_v2app_i(payload)
        write_file(paths["result_md"], result)
        write_file(paths["state_json"], json.dumps(payload, indent=2))
        append_log("V2APP-I staged EXE smoke test refused: staged Engel.exe missing.")
        return result

    proc = None
    started_pid = None
    process_start_attempted = True
    process_started = False
    alive_after_wait = False
    stop_attempted = False
    stop_method = "none"
    stopped_only_started = False
    final_return_code = None
    error = ""

    try:
        append_log("V2APP-I staged EXE smoke test launching exact staged target: " + staged_exe)
        creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        proc = subprocess.Popen(
            [staged_exe],
            cwd=os.path.dirname(staged_exe),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            creationflags=creationflags,
        )
        started_pid = proc.pid
        process_started = True
        time.sleep(4)
        final_return_code = proc.poll()
        alive_after_wait = final_return_code is None
        if alive_after_wait:
            stop_attempted = True
            stop_method = "terminate"
            proc.terminate()
            try:
                final_return_code = proc.wait(timeout=8)
            except subprocess.TimeoutExpired:
                stop_method = "kill_after_terminate_timeout"
                proc.kill()
                final_return_code = proc.wait(timeout=8)
            stopped_only_started = True
    except Exception as e:
        error = str(e)
        try:
            if proc is not None and proc.poll() is None:
                stop_attempted = True
                stop_method = "terminate_after_error"
                proc.terminate()
                final_return_code = proc.wait(timeout=8)
                stopped_only_started = True
        except Exception as stop_error:
            error = error + " | stop_error: " + str(stop_error)

    state_status = "SMOKE_TEST_SUCCEEDED" if process_started and alive_after_wait and stopped_only_started and not error else "SMOKE_TEST_FAILED_OR_INCONCLUSIVE"
    payload.update({
        "state_status": state_status,
        "process_start_attempted": process_start_attempted,
        "process_started": process_started,
        "started_pid": started_pid,
        "alive_after_launch_wait": alive_after_wait,
        "stop_attempted": stop_attempted,
        "stop_target_pid": started_pid if stop_attempted else "",
        "stop_method": stop_method,
        "stopped_only_started_process": stopped_only_started,
        "final_return_code": final_return_code,
        "error": error,
        "result_report_written": True,
        "result_report_path": paths["result_md"],
    })
    result = _app_exe_smoke_test_render_result_v2app_i(payload)
    write_file(paths["result_md"], result)
    write_file(paths["state_json"], json.dumps(payload, indent=2))
    append_log("V2APP-I staged EXE smoke test finished with status " + state_status + ": " + paths["result_md"])
    return result


