def _app_exe_functional_test_process_truth_snapshot_v2app_k(label):
    snapshot = {
        "label": label,
        "available": False,
        "conclusive": False,
        "status": "UNAVAILABLE",
        "mobile_bridge_chain_count": None,
        "alive_loop_chain_count": None,
        "duplicate_helper_chains_detected": None,
        "summary_lines": [],
        "error": "",
    }
    try:
        report = process_truth_status_v2process_a()
        snapshot["available"] = True
        if "Process query failed safely:" in report:
            snapshot["status"] = "QUERY_FAILED_SAFE"
            snapshot["summary_lines"] = ["Process truth query failed safely."]
            return snapshot

        summary_lines = []
        for line in report.splitlines():
            stripped = line.strip()
            if stripped.startswith("- Mobile bridge chain count:"):
                try:
                    snapshot["mobile_bridge_chain_count"] = int(stripped.split(":", 1)[1].strip())
                except Exception:
                    pass
                summary_lines.append(stripped)
            elif stripped.startswith("- Alive loop chain count:"):
                try:
                    snapshot["alive_loop_chain_count"] = int(stripped.split(":", 1)[1].strip())
                except Exception:
                    pass
                summary_lines.append(stripped)
            elif "duplicate candidates" in stripped:
                summary_lines.append(stripped)

        snapshot["summary_lines"] = summary_lines
        snapshot["conclusive"] = snapshot["mobile_bridge_chain_count"] is not None and snapshot["alive_loop_chain_count"] is not None
        snapshot["status"] = "CONCLUSIVE" if snapshot["conclusive"] else "INCONCLUSIVE"
        if snapshot["conclusive"]:
            snapshot["duplicate_helper_chains_detected"] = bool(
                snapshot["mobile_bridge_chain_count"] > 1 or snapshot["alive_loop_chain_count"] > 1
            )
        return snapshot
    except Exception as e:
        snapshot["error"] = str(e)
        snapshot["status"] = "ERROR"
        return snapshot


