def app_exe_functional_test_staged_v2app_k(approval_text=""):
    import json
    import subprocess
    import time

    paths = _app_exe_functional_test_paths_v2app_k()
    approval = str(approval_text or "").strip()

    if approval != "APPROVE":
        _app_exe_functional_test_write_state_v2app_k("app exe functional test staged", "REFUSED_APPROVAL_NOT_EXACT", {
            "refusal": "Exact APPROVE token required. No functional test was run.",
        })
        return "\n".join([
            "# Engel EXE Functional Test V2APP-K",
            "",
            "Approval required: exact `app exe functional test staged APPROVE`.",
            "",
            "No Engel.exe launch was attempted.",
            "No launcher or shortcut was changed.",
            "No functional test result report was written.",
        ])

    payload = _app_exe_functional_test_status_payload_v2app_k("app exe functional test staged APPROVE", "FUNCTIONAL_TEST_APPROVED")
    expected = payload.get("expected", {})
    staged_exe = expected.get("staged_exe", "")

    def finish_with_result(state_status, classification, reason, extra=None):
        payload.update({
            "state_status": state_status,
            "classification": classification,
            "classification_reason": reason,
            "result_report_written": True,
            "result_report_path": paths["result_md"],
        })
        if extra:
            payload.update(extra)
        result = _app_exe_functional_test_render_result_v2app_k(payload)
        write_file(paths["result_md"], result)
        write_file(paths["state_json"], json.dumps(payload, indent=2))
        append_log("V2APP-K staged EXE functional test finished with status " + state_status + ": " + paths["result_md"])
        return result

    if not payload.get("required_staged_exe_exact") or not payload.get("staged_exe_inside_staging"):
        return finish_with_result("REFUSED_TARGET_OUTSIDE_APPROVED_STAGING_PATH", "FAIL", "Functional-test target was not the exact staged Engel.exe path. No test was run.", {
            "process_start_attempted": False,
            "process_started": False,
        })

    if not os.path.exists(staged_exe) or not os.path.isfile(staged_exe):
        return finish_with_result("REFUSED_STAGED_EXE_MISSING", "FAIL", "Staged Engel.exe is missing. No test was run.", {
            "process_start_attempted": False,
            "process_started": False,
        })

    if not payload.get("smoke_review", {}).get("smoke_review_passed"):
        return finish_with_result("REFUSED_SMOKE_REVIEW_NOT_PASS", "FAIL", "Smoke review did not have PASS classification. No functional test was run.", {
            "process_start_attempted": False,
            "process_started": False,
        })

    process_truth_before = _app_exe_functional_test_process_truth_snapshot_v2app_k("before_launch")
    proc = None
    started_pid = None
    process_start_attempted = True
    process_started = False
    alive_after_wait = False
    stop_attempted = False
    stop_method = "none"
    stopped_only_started = False
    final_return_code = None
    error = ""
    process_truth_during = {
        "label": "during_launch",
        "available": False,
        "conclusive": False,
        "status": "NOT_RUN",
    }

    try:
        append_log("V2APP-K staged EXE functional test launching exact staged target: " + staged_exe)
        creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        proc = subprocess.Popen(
            [staged_exe],
            cwd=os.path.dirname(staged_exe),
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            creationflags=creationflags,
        )
        started_pid = proc.pid
        process_started = True
        time.sleep(8)
        final_return_code = proc.poll()
        alive_after_wait = final_return_code is None
        if alive_after_wait:
            process_truth_during = _app_exe_functional_test_process_truth_snapshot_v2app_k("during_launch")
            stop_attempted = True
            stop_method = "terminate"
            proc.terminate()
            try:
                final_return_code = proc.wait(timeout=10)
            except subprocess.TimeoutExpired:
                stop_method = "kill_started_after_terminate_timeout"
                proc.kill()
                final_return_code = proc.wait(timeout=10)
            stopped_only_started = True
    except Exception as e:
        error = str(e)
        try:
            if proc is not None and proc.poll() is None:
                stop_attempted = True
                stop_method = "terminate_after_error"
                proc.terminate()
                final_return_code = proc.wait(timeout=10)
                stopped_only_started = True
        except Exception as stop_error:
            error = error + " | stop_error: " + str(stop_error)

    before_mobile = process_truth_before.get("mobile_bridge_chain_count")
    before_alive = process_truth_before.get("alive_loop_chain_count")
    during_mobile = process_truth_during.get("mobile_bridge_chain_count")
    during_alive = process_truth_during.get("alive_loop_chain_count")
    truth_conclusive = bool(process_truth_before.get("conclusive") and process_truth_during.get("conclusive"))
    unexpected_duplicates = "UNKNOWN"
    if truth_conclusive:
        unexpected_duplicates = bool(during_mobile > before_mobile or during_alive > before_alive)

    classification = "FAIL"
    state_status = "FUNCTIONAL_TEST_FAILED"
    reason = "Staged EXE failed to start, exited immediately, or was not closed by the test."
    if process_started and alive_after_wait and stopped_only_started and not error:
        if truth_conclusive and unexpected_duplicates is False and stop_method == "terminate":
            classification = "PASS"
            state_status = "FUNCTIONAL_TEST_SUCCEEDED"
            reason = "Staged EXE started, remained alive during wait, helper-chain check was conclusive, and only the started process was closed."
        else:
            classification = "CAUTION"
            state_status = "FUNCTIONAL_TEST_INCONCLUSIVE"
            reason = "Staged EXE started and only the started process was closed, but helper-chain/process truth check or close method was inconclusive."

    return finish_with_result(state_status, classification, reason, {
        "process_start_attempted": process_start_attempted,
        "process_started": process_started,
        "started_pid": started_pid,
        "alive_after_launch_wait": alive_after_wait,
        "stop_attempted": stop_attempted,
        "stop_target_pid": started_pid if stop_attempted else "",
        "stop_method": stop_method,
        "stopped_only_started_process": stopped_only_started,
        "final_return_code": final_return_code,
        "error": error,
        "process_truth_before": process_truth_before,
        "process_truth_during": process_truth_during,
        "unexpected_duplicate_helper_chains_detected": unexpected_duplicates,
    })


