def _app_setup_paths_v2app_m():
    return {
        "diagnose_md": os.path.join(REPORTS_DIR, "app", "V2APP_M_APP_SETUP_DIAGNOSE.md"),
        "plan_md": os.path.join(REPORTS_DIR, "app", "ENGEL_APP_SETUP_PLAN_V2APPM.md"),
        "status_md": os.path.join(REPORTS_DIR, "app", "ENGEL_APP_SETUP_STATUS_V2APPM.md"),
        "checklist_md": os.path.join(REPORTS_DIR, "app", "ENGEL_APP_SETUP_CHECKLIST_V2APPM.md"),
        "state_json": os.path.join(MEMORY_DIR, "ENGEL_APP_SETUP_STATE_V2APPM.json"),
    }


def _app_setup_known_readiness_paths_v2app_m():
    return {
        "v2app_l_readiness_status": os.path.join(REPORTS_DIR, "app", "ENGEL_EXE_STAGED_READINESS_STATUS_V2APPL.md"),
        "v2app_l_next_phase_plan": os.path.join(REPORTS_DIR, "app", "ENGEL_EXE_NEXT_PHASE_PLAN_V2APPL.md"),
        "v2app_l_functional_test_review": os.path.join(REPORTS_DIR, "app", "ENGEL_EXE_FUNCTIONAL_TEST_REVIEW_V2APPL.md"),
        "v2app_c_shortcut_status": os.path.join(REPORTS_DIR, "app", "BRANDED_SHORTCUT_CREATE_STATUS_V2APPC.md"),
    }


def _app_setup_line_value_v2app_m(text, prefix):
    for line in str(text or "").splitlines():
        stripped = line.strip()
        if stripped.startswith(prefix):
            return stripped[len(prefix):].strip()
    return ""


def _app_setup_shortcut_summary_v2app_m():
    expected_command = r'C:\Windows\System32\wscript.exe "' + os.path.join(ROOT, "Start Engel App.vbs") + '"'
    try:
        diagnosis = _app_shortcut_diagnosis_v2app_c("app setup status")
        existing = diagnosis.get("existing_shortcut", {})
        policy = diagnosis.get("shortcut_policy", {})
        return {
            "safe_read_attempted": True,
            "safe_readable": bool(existing.get("readable")),
            "shortcut_exists": bool(existing.get("exists")),
            "shortcut_path": existing.get("path", ""),
            "target_path": existing.get("target_path", ""),
            "arguments": existing.get("arguments", ""),
            "working_directory": existing.get("working_directory", ""),
            "equivalent_to_approved_launcher": policy.get("equivalent_to_approved_launcher"),
            "launcher_form": policy.get("launcher_form", "unknown"),
            "action_needed": policy.get("action_needed", "unknown"),
            "expected_safe_equivalent_command": expected_command,
            "error": "",
        }
    except Exception as exc:
        return {
            "safe_read_attempted": True,
            "safe_readable": False,
            "shortcut_exists": None,
            "shortcut_path": os.path.join(os.path.expanduser("~"), "Desktop", "Engel.lnk"),
            "target_path": "",
            "arguments": "",
            "working_directory": "",
            "equivalent_to_approved_launcher": None,
            "launcher_form": "unknown",
            "action_needed": "manual review if shortcut status cannot be read",
            "expected_safe_equivalent_command": expected_command,
            "error": str(exc),
        }


def _app_setup_payload_v2app_m(command_name, state_status):
    paths = _app_setup_paths_v2app_m()
    known_paths = _app_setup_known_readiness_paths_v2app_m()
    staged_exe = os.path.join(ROOT, "staging", "app", "build_output", "Engel.exe")
    live_launcher = os.path.join(ROOT, "Start Engel App.vbs")
    readiness_text = read_file(known_paths["v2app_l_readiness_status"]) if os.path.exists(known_paths["v2app_l_readiness_status"]) else ""
    functional_review_text = read_file(known_paths["v2app_l_functional_test_review"]) if os.path.exists(known_paths["v2app_l_functional_test_review"]) else ""

    setup_outputs = {}
    for key, path in paths.items():
        setup_outputs[key] = _app_launcher_file_record_v2app_a(path)

    known_readiness_files = {}
    for key, path in known_paths.items():
        known_readiness_files[key] = _app_launcher_file_record_v2app_a(path)

    return {
        "version": "V2APP-M",
        "command": command_name,
        "state_status": state_status,
        "generated_at": now(),
        "workspace": ROOT,
        "staged_exe": _app_launcher_file_record_v2app_a(staged_exe),
        "live_launcher": _app_launcher_file_record_v2app_a(live_launcher),
        "desktop_shortcut": _app_setup_shortcut_summary_v2app_m(),
        "known_readiness_files": known_readiness_files,
        "setup_outputs": setup_outputs,
        "readiness": {
            "v2app_l_readiness": _app_setup_line_value_v2app_m(readiness_text, "- Readiness:"),
            "v2app_l_review_classification": _app_setup_line_value_v2app_m(readiness_text, "- V2APP-L review classification:"),
            "v2app_k_classification": _app_setup_line_value_v2app_m(readiness_text, "- V2APP-K classification:"),
            "functional_review_result": "PASS" if "Result: **PASS**" in functional_review_text else ("CAUTION" if "Result: **CAUTION**" in functional_review_text else "UNKNOWN"),
        },
        "safety": {
            "status_or_report_only": True,
            "live_launcher_replaced": False,
            "desktop_shortcut_edited": False,
            "startup_entry_added": False,
            "scheduled_task_added": False,
            "exe_rebuilt": False,
            "dependency_installed": False,
            "exe_launched": False,
            "source_apply": False,
            "learning_apply": False,
            "research_started": False,
            "swarm_execution": False,
            "cloud_fallback": False,
            "desktop_control": False,
            "process_cleanup_changed": False,
        },
    }


def _app_setup_write_state_v2app_m(payload):
    import json
    paths = _app_setup_paths_v2app_m()
    write_file(paths["state_json"], json.dumps(payload, indent=2))


def _app_setup_bool_text_v2app_m(value):
    if value is True:
        return "true"
    if value is False:
        return "false"
    return "unknown"


def _app_setup_found_text_v2app_m(record):
    return "FOUND" if record.get("exists") else "MISSING"


