def _app_staged_launch_sha256_v2app_n(path):
    import hashlib
    import os
    if not os.path.isfile(path):
        return ""
    try:
        h = hashlib.sha256()
        with open(path, "rb") as f:
            for chunk in iter(lambda: f.read(1024 * 1024), b""):
                h.update(chunk)
        return h.hexdigest().upper()
    except Exception:
        return ""


def _app_staged_launch_report_record_v2app_n(path, include_hash=False):
    record = _app_launcher_file_record_v2app_a(path)
    record["sha256"] = _app_staged_launch_sha256_v2app_n(path) if include_hash and record.get("exists") else ""
    return record


