def _app_staged_source_freshness_v2app_o(staged_record):
    import os
    source_paths = {
        "engel_app.py": os.path.join(ROOT, "engel_app.py"),
        "engel_companion.py": os.path.join(ROOT, "engel_companion.py"),
        "engel_swarm_mind.py": os.path.join(ROOT, "engel_swarm_mind.py"),
    }
    staged_mtime = os.path.getmtime(staged_record.get("path", "")) if staged_record.get("exists") else 0
    records = {}
    source_newer = False
    for key, path in source_paths.items():
        rec = _app_launcher_file_record_v2app_a(path)
        rec["newer_than_staged_exe"] = bool(rec.get("exists") and staged_mtime and os.path.getmtime(path) > staged_mtime)
        if rec["newer_than_staged_exe"]:
            source_newer = True
        records[key] = rec
    return {
        "source_files": records,
        "source_appears_newer_than_staged_exe": source_newer,
    }


