def app_exe_rebuild_staged_v2app_p(approval=""):
    import subprocess

    approval_text = str(approval or "").strip()
    paths = _app_exe_rebuild_staged_paths_v2app_p()
    if approval_text != "APPROVE":
        return "\n".join([
            "# Engel EXE Rebuild Staged V2APP-P",
            "",
            "Approval required: exact `app exe rebuild staged APPROVE`.",
            "",
            "Use: app exe rebuild staged APPROVE",
            "",
            "No rebuild was run.",
            "No EXE was launched.",
            "No dependency was installed.",
            "No launcher or shortcut was changed.",
        ])

    pre_payload = _app_exe_rebuild_staged_payload_v2app_p("app exe rebuild staged APPROVE", "PREFLIGHT")
    expected = pre_payload.get("expected", {})
    deps = pre_payload.get("dependency_status", {})
    command = pre_payload.get("build_command", [])
    command_display = pre_payload.get("build_command_display", "")

    if not pre_payload.get("project_python", {}).get("exists") or not deps.get("v2appe_can_build"):
        blocked = _app_exe_rebuild_staged_payload_v2app_p("app exe rebuild staged APPROVE", "REFUSED_DEPENDENCY_MISSING", {
            "refusal": "Project .venv Python or PyInstaller is not available. No rebuild was run.",
        })
        _app_exe_rebuild_staged_write_state_v2app_p(blocked)
        return "\n".join([
            "# Engel EXE Rebuild Staged V2APP-P",
            "",
            "Project `.venv` Python or PyInstaller is not available.",
            "No rebuild was run.",
            "No dependency was installed.",
            "No launcher or shortcut was changed.",
        ])

    missing_sources = []
    for path in [os.path.join(ROOT, "engel_app.py"), os.path.join(ROOT, "engel_companion.py")]:
        if not os.path.exists(path):
            missing_sources.append(path)
    if missing_sources:
        blocked = _app_exe_rebuild_staged_payload_v2app_p("app exe rebuild staged APPROVE", "REFUSED_SOURCE_MISSING", {
            "missing_sources": missing_sources,
            "refusal": "Required source files are missing. No rebuild was run.",
        })
        _app_exe_rebuild_staged_write_state_v2app_p(blocked)
        return "\n".join([
            "# Engel EXE Rebuild Staged V2APP-P",
            "",
            "Required source files are missing. No rebuild was run.",
            "",
            "Missing:",
            "- " + "\n- ".join(missing_sources),
        ])

    if not pre_payload.get("output_and_work_paths_inside_staging_app"):
        blocked = _app_exe_rebuild_staged_payload_v2app_p("app exe rebuild staged APPROVE", "REFUSED_OUTPUT_OUTSIDE_STAGING", {
            "refusal": "Output/work paths are not clearly under staging/app. No rebuild was run.",
        })
        _app_exe_rebuild_staged_write_state_v2app_p(blocked)
        return "\n".join([
            "# Engel EXE Rebuild Staged V2APP-P",
            "",
            "Output/work paths are not clearly under `E:\\EngelStandalone\\staging\\app`.",
            "No rebuild was run.",
        ])

    pre_record = _app_staged_launch_report_record_v2app_n(expected["staged_exe"], include_hash=True)
    os.makedirs(expected["build_output"], exist_ok=True)
    os.makedirs(expected["build_work"], exist_ok=True)
    os.makedirs(expected["spec_path"], exist_ok=True)
    append_log("V2APP-P staged rebuild command before execution: " + command_display)
    run_result = subprocess.run(command, cwd=ROOT, capture_output=True, text=True)
    post_record = _app_staged_launch_report_record_v2app_n(expected["staged_exe"], include_hash=True)
    result_status = "REBUILD_SUCCEEDED" if run_result.returncode == 0 and post_record.get("exists") else "REBUILD_FAILED"
    stdout_tail = str(run_result.stdout or "")
    stderr_tail = str(run_result.stderr or "")
    if len(stdout_tail) > 8000:
        stdout_tail = stdout_tail[-8000:]
    if len(stderr_tail) > 8000:
        stderr_tail = stderr_tail[-8000:]

    payload = _app_exe_rebuild_staged_payload_v2app_p("app exe rebuild staged APPROVE", result_status, {
        "pre_build_staged_exe": pre_record,
        "post_build_staged_exe": post_record,
        "build_return_code": run_result.returncode,
        "build_command": command,
        "build_command_display": command_display,
        "build_stdout_tail": stdout_tail,
        "build_stderr_tail": stderr_tail,
        "result_report_written": True,
        "result_report_path": paths["result_md"],
    })
    report = _app_exe_rebuild_staged_result_report_v2app_p(payload, "V2APP-P ran the staged rebuild command only; no launch, test, or promotion followed.")
    write_file(paths["result_md"], report)
    _app_exe_rebuild_staged_write_state_v2app_p(payload)
    append_log("V2APP-P approved staged rebuild finished with return code " + str(run_result.returncode) + "; no EXE launch or live promotion.")
    return report


