def _app_staged_rebuild_current_payload_v2app_u(command_name):
    p_payload = _app_exe_rebuild_staged_payload_v2app_p(command_name, "V2APP_U_STATUS_REFRESHED")
    p_state = _app_staged_rebuild_current_latest_v2app_p_state_v2app_u()
    state_data = p_state.get("data", {})
    staged = p_payload.get("staged_exe", {})
    source_newer = bool(p_payload.get("source_freshness", {}).get("source_appears_newer_than_staged_exe"))
    rebuild_recommended = bool(p_payload.get("rebuild_recommended"))
    contract_payload = _app_live_destination_contract_payload_v2app_t(command_name)
    health = _app_staged_rebuild_current_health_status_v2app_u()
    route = _app_staged_rebuild_current_route_status_v2app_u()
    live_path = contract_payload.get("intended_future_live_exe_path", os.path.join(ROOT, "live", "app", "Engel.exe"))
    live_exists = os.path.exists(live_path)
    launcher = _app_launcher_file_record_v2app_a(os.path.join(ROOT, "Start Engel App.vbs"))
    previous_sha = ""
    previous_basis = ""
    if state_data.get("pre_build_staged_exe", {}).get("sha256"):
        previous_sha = state_data.get("pre_build_staged_exe", {}).get("sha256")
        previous_basis = "latest V2APP-P pre-build staged EXE metadata"
    elif state_data.get("staged_exe", {}).get("sha256"):
        previous_sha = state_data.get("staged_exe", {}).get("sha256")
        previous_basis = "latest V2APP-P staged EXE metadata"
    else:
        previous_sha = "not available"
        previous_basis = "not available"

    blocking = []
    if not os.path.exists(_app_live_destination_contract_paths_v2app_t()["contract_md"]):
        blocking.append("V2APP-T destination contract marker is missing.")
    if not os.path.exists(_app_live_destination_contract_paths_v2app_t()["report_md"]):
        blocking.append("V2APP-T destination contract report is missing.")
    if not staged.get("exists"):
        blocking.append("Staged Engel.exe is missing.")
    if source_newer:
        blocking.append("Current source files are newer than the staged EXE.")
    if rebuild_recommended:
        blocking.append("V2APP-P logic still recommends staged rebuild.")
    if health.get("status") != "OK":
        blocking.append("Health/status check is not OK: " + health.get("detail", ""))
    if route.get("status") != "REPORT_FOUND":
        blocking.append("Route regression status is not REPORT_FOUND: " + route.get("detail", ""))
    if live_exists:
        blocking.append("A live EXE exists at the V2APP-T contract path; V2APP-U expected staged-only state.")

    final_result = "STAGED_REBUILD_CURRENT_SOURCE_OK" if not blocking else "BLOCKED"
    if state_data.get("state_status") == "REBUILD_FAILED":
        final_result = "FAILED"

    return {
        "version": "V2APP-U",
        "command": command_name,
        "generated_at": now(),
        "workspace": ROOT,
        "rebuild_scope": "staged only",
        "existing_rebuild_mechanism": "V2APP-P app exe rebuild staged APPROVE",
        "v2app_p_state": p_state,
        "previous_staged_sha256": previous_sha,
        "previous_staged_sha256_basis": previous_basis,
        "new_staged_sha256": staged.get("sha256") or "not available",
        "staged_exe": staged,
        "source_newer_than_staged_exe_after_rebuild": source_newer,
        "rebuild_recommended_after_rebuild": rebuild_recommended,
        "health_status": health,
        "route_regression_status": route,
        "v2app_t_contract_path": live_path,
        "v2app_t_contract_marker_exists": os.path.exists(_app_live_destination_contract_paths_v2app_t()["contract_md"]),
        "v2app_t_contract_report_exists": os.path.exists(_app_live_destination_contract_paths_v2app_t()["report_md"]),
        "live_exe_exists_at_contract_path": live_exists,
        "current_live_exe_hash_status": contract_payload.get("current_live_exe_hash_status", ""),
        "runtime_model": contract_payload.get("runtime_model", "SCRIPT_BASED"),
        "launcher": launcher,
        "live_promotion_happened": False,
        "launcher_changed": "no",
        "shortcut_changed": "no",
        "startup_changed": "no",
        "final_result": final_result,
        "blocking_reasons": blocking,
        "next_step": "V2APP-Q style route retest/review of the rebuilt staged EXE, then a separate explicit live-promotion task if Josh wants it.",
        "safety": {
            "promoted": False,
            "copied_to_live": False,
            "created_live_exe": False,
            "overwrote_live_exe": False,
            "deleted_live_exe": False,
            "launched_exe": False,
            "launcher_modified": False,
            "shortcut_modified": False,
            "startup_changed": False,
            "launcher_switched": False,
            "dependency_installed": False,
        },
    }


