def _identity_refresh_v2identity_a(command_name):
    paths = _identity_paths_v2identity_a()
    initial = _identity_payload_v2identity_a(command_name)
    write_file(paths["staged_md"], _identity_staged_instruction_text_v2identity_a())
    write_file(paths["diagnose_md"], _identity_diagnose_report_v2identity_a(initial))
    write_file(paths["plan_md"], _identity_update_plan_report_v2identity_a(initial))
    payload = _identity_payload_v2identity_a(command_name)
    payload["diagnosis_report_exists"] = os.path.exists(paths["diagnose_md"])
    payload["staged_identity_file_exists"] = os.path.exists(paths["staged_md"])
    payload["update_plan_exists"] = os.path.exists(paths["plan_md"])
    payload["status_report_exists"] = True
    payload["state_json_exists"] = True
    write_file(paths["status_md"], _identity_status_report_v2identity_a(payload))
    write_file(paths["state_json"], _identity_state_json_v2identity_a(payload))
    return _identity_payload_v2identity_a(command_name)


def identity_instruction_status_v2identity_a():
    payload = _identity_refresh_v2identity_a("identity instruction status")
    payload["diagnosis_report_exists"] = os.path.exists(payload["diagnosis_report"])
    payload["staged_identity_file_exists"] = os.path.exists(payload["staged_identity_file"])
    payload["update_plan_exists"] = os.path.exists(payload["update_plan"])
    payload["status_report_exists"] = os.path.exists(payload["status_report"])
    payload["state_json_exists"] = os.path.exists(payload["state_json"])
    return _identity_status_report_v2identity_a(payload)


