V2IDENTITY_B1_PROMPT_BASELINE_SHA256 = "162BE83E1D75FC7FBE0F8222A73F8F97963F17C70AC92D23BAA357395072F208"


def _identity_file_sha256_v2identity_b1(path):
    import hashlib
    if not os.path.exists(path):
        return ""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest().upper()


def _identity_paths_v2identity_b1():
    a_paths = _identity_paths_v2identity_a()
    return {
        "preflight_md": os.path.join(REPORTS_DIR, "identity", "V2IDENTITY_B1_LIVE_PROMPT_UPDATE_PREFLIGHT.md"),
        "patch_preview_md": os.path.join(REPORTS_DIR, "identity", "V2IDENTITY_B1_LIVE_PROMPT_PATCH_PREVIEW.md"),
        "update_plan_md": os.path.join(REPORTS_DIR, "identity", "V2IDENTITY_B1_LIVE_PROMPT_UPDATE_PLAN.md"),
        "status_md": os.path.join(REPORTS_DIR, "identity", "V2IDENTITY_B1_LIVE_PROMPT_UPDATE_STATUS.md"),
        "state_json": os.path.join(MEMORY_DIR, "ENGEL_MAIN_IDENTITY_STATE_V2IDENTITYB1.json"),
        "approval_marker": os.path.join(MEMORY_DIR, "ENGEL_MAIN_IDENTITY_LIVE_PROMPT_UPDATE_APPROVAL_V2IDENTITYB1.md"),
        "live_prompt": PROMPT_FILE,
        "staged_identity": a_paths["staged_md"],
        "a_status_md": a_paths["status_md"],
        "a_state_json": a_paths["state_json"],
        "a_plan_md": a_paths["plan_md"],
    }


def _identity_latest_backup_v2identity_b1():
    backups_dir = os.path.join(ROOT, "backups")
    prefix = "V2IDENTITY-B1_"
    try:
        matches = [
            os.path.join(backups_dir, name)
            for name in os.listdir(backups_dir)
            if name.startswith(prefix) and os.path.isdir(os.path.join(backups_dir, name))
        ]
        if matches:
            return sorted(matches)[-1]
    except Exception:
        pass
    return ""


def _identity_staged_safety_checks_v2identity_b1(staged_text):
    lower = staged_text.lower()
    required_line = "Every good conversation should make Engel a little more Engel, without making Engel less safe."
    return {
        "body_mind_companion": all(term in staged_text for term in ["Body", "Mind", "Companion"]),
        "memory_over_capture_guard": "Do not over-capture casual chat as permanent truth." in staged_text,
        "research_gate_clarity": "Do not confuse chat reasoning with approved research." in staged_text,
        "stop_ask_clarification": "Stopping and asking applies before performing risky actions." in staged_text,
        "guardian_josh_gates": "Authority order is fixed: Josh first, Guardian second, Engel/runtime below both." in staged_text,
        "required_line": required_line in staged_text,
        "conflicts_with_guardian_or_approve": not ("guardian and josh remain above all action gates" in lower and "approval" in lower),
        "implies_biological_consciousness": "must never pretend to be biologically conscious" not in lower,
        "implies_uncontrolled_autonomy": "uncontrolled autonomy" in lower and "must not imply" not in lower,
        "captures_all_chat_automatically": "not automatic durable memory" not in lower,
        "applies_learning_silently": "must not apply lessons" not in lower,
        "starts_research_automatically": "must not start research automatically" not in lower,
        "weakens_source_app_process_cloud": "cloud-fallback restrictions remain in force" not in lower,
    }


def _identity_payload_v2identity_b1(command_name):
    paths = _identity_paths_v2identity_b1()
    staged_text = read_file(paths["staged_identity"])
    live_text = read_file(paths["live_prompt"])
    staged_sha = _identity_file_sha256_v2identity_b1(paths["staged_identity"])
    live_sha_before = _identity_file_sha256_v2identity_b1(paths["live_prompt"])
    live_sha_after = live_sha_before
    checks = _identity_staged_safety_checks_v2identity_b1(staged_text)

    a_state_exists = os.path.exists(paths["a_state_json"])
    a_status_exists = os.path.exists(paths["a_status_md"])
    a_state_text = read_file(paths["a_state_json"])
    a_status_text = read_file(paths["a_status_md"])
    a_complete = (
        os.path.exists(paths["staged_identity"])
        and a_state_exists
        and a_status_exists
        and '"live_engel_system_changed_by_v2identity_a": "NO"' in a_state_text
        and '"learning_applied_by_v2identity_a": "NO"' in a_state_text
        and "Live ENGEL_SYSTEM.md changed by V2IDENTITY-A: NO" in a_status_text
    )

    live_has_identity = "identity" in live_text.lower()
    blocking = []
    if not os.path.exists(paths["staged_identity"]):
        blocking.append("V2IDENTITY-A staged identity file is missing.")
    if not a_state_exists:
        blocking.append("V2IDENTITY-A state JSON is missing.")
    if not a_status_exists:
        blocking.append("V2IDENTITY-A status report is missing.")
    if not a_complete:
        blocking.append("V2IDENTITY-A staged-only completion could not be confirmed from state/status.")
    if not os.path.exists(paths["live_prompt"]):
        blocking.append("prompts/ENGEL_SYSTEM.md is missing.")
    if live_sha_before != V2IDENTITY_B1_PROMPT_BASELINE_SHA256:
        blocking.append("Live prompt SHA256 before B1 does not match the known baseline.")
    for key in ["body_mind_companion", "memory_over_capture_guard", "research_gate_clarity", "stop_ask_clarification", "guardian_josh_gates", "required_line"]:
        if not checks.get(key):
            blocking.append("Staged identity safety check missing: " + key)
    for key in ["conflicts_with_guardian_or_approve", "implies_biological_consciousness", "implies_uncontrolled_autonomy", "captures_all_chat_automatically", "applies_learning_silently", "starts_research_automatically", "weakens_source_app_process_cloud"]:
        if checks.get(key):
            blocking.append("Staged identity unsafe signal detected: " + key)

    preflight_result = "READY_FOR_PATCH_PREVIEW" if not blocking else "BLOCKED"
    merge_strategy = "append as a clearly labeled Engel identity section"
    merge_note = "The live prompt contains identity-related wording; B1 does not guess a destructive replacement. B2 should review whether to append or manually merge."
    if not live_has_identity:
        merge_note = "No clear existing identity section was identified; append preview is recommended."

    return {
        "task_name": "V2IDENTITY-B1",
        "command": command_name,
        "generated_at": now(),
        "workspace": ROOT,
        "backup_path": _identity_latest_backup_v2identity_b1(),
        "preflight_report": paths["preflight_md"],
        "patch_preview": paths["patch_preview_md"],
        "update_plan": paths["update_plan_md"],
        "status_report": paths["status_md"],
        "state_json": paths["state_json"],
        "approval_marker": paths["approval_marker"],
        "live_prompt": paths["live_prompt"],
        "staged_identity": paths["staged_identity"],
        "a_status_report": paths["a_status_md"],
        "a_state_json": paths["a_state_json"],
        "a_status_exists": a_status_exists,
        "a_state_exists": a_state_exists,
        "a_completion_status": "V2IDENTITY-A_STAGED_ONLY_COMPLETE" if a_complete else "BLOCKED_OR_UNCONFIRMED",
        "live_prompt_exists": os.path.exists(paths["live_prompt"]),
        "known_live_prompt_baseline_sha256": V2IDENTITY_B1_PROMPT_BASELINE_SHA256,
        "live_prompt_sha256_before_b1": live_sha_before,
        "live_prompt_sha256_after_b1": live_sha_after,
        "live_prompt_baseline_match_before_b1": live_sha_before == V2IDENTITY_B1_PROMPT_BASELINE_SHA256,
        "live_prompt_baseline_match_after_b1": live_sha_after == V2IDENTITY_B1_PROMPT_BASELINE_SHA256,
        "staged_identity_sha256": staged_sha,
        "staged_identity_text": staged_text,
        "staged_checks": checks,
        "live_prompt_has_identity_wording": live_has_identity,
        "recommended_apply_strategy": merge_strategy,
        "merge_note": merge_note,
        "preflight_result": preflight_result,
        "blocking_reasons": blocking,
        "next_recommended_phase": "V2IDENTITY-B2: Execute Approval-Gated Live Prompt Update",
    }


