def _identity_refresh_v2identity_b1(command_name):
    paths = _identity_paths_v2identity_b1()
    payload = _identity_payload_v2identity_b1(command_name)
    write_file(paths["preflight_md"], _identity_preflight_report_v2identity_b1(payload))
    write_file(paths["patch_preview_md"], _identity_patch_preview_report_v2identity_b1(payload))
    write_file(paths["update_plan_md"], _identity_update_plan_report_v2identity_b1(payload))
    if payload.get("preflight_result") == "READY_FOR_PATCH_PREVIEW":
        write_file(paths["approval_marker"], _identity_approval_marker_v2identity_b1(payload))
    payload = _identity_payload_v2identity_b1(command_name)
    write_file(paths["status_md"], _identity_status_report_v2identity_b1(payload))
    write_file(paths["state_json"], _identity_state_json_v2identity_b1(payload))
    return _identity_payload_v2identity_b1(command_name)


