def app_exe_dependency_install_v2app_f(approval_text=""):
    import json
    import subprocess

    paths = _app_exe_dependency_paths_v2app_g()
    approval = str(approval_text or "").strip()
    expected = _app_exe_dependency_expected_v2app_f()
    command = list(expected.get("future_install_command", []))

    if approval != "APPROVE":
        payload = _app_exe_dependency_payload_v2app_g("app exe dependency install", "REFUSED_APPROVAL_NOT_EXACT", {
            "approval_token_exact": False,
            "refusal": "Exact APPROVE token required. No install was run.",
        })
        write_file(paths["state_json"], json.dumps(payload, indent=2))
        return "\n".join([
            "# Engel EXE Dependency Install V2APP-G",
            "",
            "Approval required: exact `app exe dependency install APPROVE`.",
            "",
            "No install was run.",
            "No EXE was built.",
            "No launcher or shortcut was changed.",
        ])

    expected_python = os.path.abspath(os.path.join(ROOT, ".venv", "Scripts", "python.exe"))
    command_python = os.path.abspath(command[0]) if command else ""
    exact_command_shape = (
        len(command) == 5
        and command_python == expected_python
        and command[1:] == ["-m", "pip", "install", "pyinstaller"]
    )
    if not os.path.exists(expected_python) or not exact_command_shape:
        payload = _app_exe_dependency_payload_v2app_g("app exe dependency install APPROVE", "REFUSED_PROJECT_VENV_TARGET_INVALID", {
            "approval_token_exact": True,
            "refusal": "Project .venv python target is missing or command target is not exact. No install was run.",
        })
        write_file(paths["state_json"], json.dumps(payload, indent=2))
        return "\n".join([
            "# Engel EXE Dependency Install V2APP-G",
            "",
            "Project .venv python target is missing or command target is not exact. No install was run.",
            "",
            "Expected command:",
            "```text",
            expected.get("future_install_command_display", ""),
            "```",
            "",
            "No dependency was installed.",
            "No EXE was built.",
            "No launcher or shortcut was changed.",
        ])

    append_log("V2APP-G dependency install command before execution: " + expected.get("future_install_command_display", ""))
    run_result = subprocess.run(command, cwd=ROOT, capture_output=True, text=True)
    deps_after = _app_exe_staged_dependency_status_v2app_e()
    payload = _app_exe_dependency_payload_v2app_g("app exe dependency install APPROVE", "INSTALL_RAN", {
        "approval_token_exact": True,
        "install_attempted": True,
        "install_return_code": run_result.returncode,
        "current_dependency_status": deps_after,
        "safety": {
            "exact_approve_required": True,
            "install_attempted": True,
            "dependencies_installed": bool(deps_after.get("pyinstaller_available")),
            "requirements_modified": False,
            "exe_build_attempted": False,
            "engel_exe_built": False,
            "live_launcher_changed": False,
            "desktop_shortcut_changed": False,
            "startup_entries_added": False,
            "scheduled_tasks_added": False,
            "research_loop_started": False,
            "swarm_execution": False,
            "source_apply_from_swarm_or_research": False,
            "cloud_fallback": False,
        },
        "result_report_path": paths["result_md"],
        "status_report_path": paths["status_md"],
    })
    result = _app_exe_dependency_render_install_result_v2app_g(payload, run_result)
    status_report = _app_exe_dependency_render_status_v2app_g(payload)
    write_file(paths["result_md"], result)
    write_file(paths["status_md"], status_report)
    write_file(paths["state_json"], json.dumps(payload, indent=2))
    append_log("V2APP-G dependency install command finished with return code " + str(run_result.returncode) + ": " + paths["result_md"])
    return result

# ----------------------------------------------------------------------
# V2APP-C Approval-Gated Live Engel Desktop Shortcut Creation
# Creates/refreshes only Engel.lnk, and only after exact APPROVE.
# ----------------------------------------------------------------------
def _app_shortcut_paths_v2app_c():
    return {
        "plan_md": os.path.join(REPORTS_DIR, "app", "BRANDED_SHORTCUT_CREATE_PLAN_V2APPC.md"),
        "status_md": os.path.join(REPORTS_DIR, "app", "BRANDED_SHORTCUT_CREATE_STATUS_V2APPC.md"),
        "memory_state": os.path.join(MEMORY_DIR, "BRANDED_SHORTCUT_STATE_V2APPC.json"),
        "result_md": os.path.join(REPORTS_DIR, "app", "BRANDED_SHORTCUT_CREATE_RESULT_V2APPC.md"),
        "equivalence_repair_md": os.path.join(REPORTS_DIR, "app", "BRANDED_SHORTCUT_EQUIVALENCE_REPAIR_V2APPC_R1.md"),
    }


def _app_shortcut_expected_v2app_c():
    desktop = _app_shortcut_desktop_path_v2app_c()
    return {
        "shortcut_name": "Engel",
        "shortcut_filename": "Engel.lnk",
        "desktop_path": desktop,
        "destination": os.path.join(desktop, "Engel.lnk"),
        "target": os.path.join(ROOT, "Start Engel App.vbs"),
        "working_directory": ROOT,
        "icon_path": os.path.join(ROOT, "assets", "branding", "final", "engel_icon_final.ico"),
    }


def _app_shortcut_ps_quote_v2app_c(value):
    return "'" + str(value or "").replace("'", "''") + "'"


def _app_shortcut_run_powershell_json_v2app_c(script, timeout=10):
    import json
    import subprocess

    try:
        completed = subprocess.run(
            ["powershell.exe", "-NoProfile", "-Command", script],
            capture_output=True,
            text=True,
            timeout=timeout,
        )
    except Exception as exc:
        return {"ok": False, "error": str(exc), "data": {}}

    if completed.returncode != 0:
        return {
            "ok": False,
            "error": (completed.stderr or completed.stdout or "").strip(),
            "data": {},
        }

    text = (completed.stdout or "").strip()
    if not text:
        return {"ok": True, "error": "", "data": {}}

    try:
        return {"ok": True, "error": "", "data": json.loads(text)}
    except Exception as exc:
        return {"ok": False, "error": "PowerShell JSON parse failed: " + str(exc), "data": {"raw": text}}


def _app_shortcut_desktop_path_v2app_c():
    script = "[pscustomobject]@{Desktop=[Environment]::GetFolderPath('Desktop')} | ConvertTo-Json -Compress"
    result = _app_shortcut_run_powershell_json_v2app_c(script, timeout=5)
    desktop = result.get("data", {}).get("Desktop") if result.get("ok") else ""
    if desktop:
        return desktop
    return os.path.join(os.path.expanduser("~"), "Desktop")


def _app_shortcut_normalize_path_v2app_c(path):
    value = str(path or "").strip().strip('"')
    if not value:
        return ""
    return os.path.normcase(os.path.abspath(value))


def _app_shortcut_normalize_icon_v2app_c(icon):
    value = str(icon or "").strip().strip('"')
    if value.lower().endswith(",0"):
        value = value[:-2]
    return _app_shortcut_normalize_path_v2app_c(value) if value else ""


def _app_shortcut_bool_text_v2app_c(value):
    if value is True:
        return "true"
    if value is False:
        return "false"
    return "unknown"


def _app_shortcut_yes_no_v2app_c(value):
    return "yes" if value else "no"


def _app_shortcut_strip_outer_quotes_v2app_c(value):
    text = str(value or "").strip()
    if len(text) >= 2 and text[0] == text[-1] and text[0] in ["'", '"']:
        return text[1:-1].strip()
    return text


def _app_shortcut_has_url_scheme_v2app_c(value):
    text = _app_shortcut_strip_outer_quotes_v2app_c(value).strip().lower()
    if not text:
        return False
    blocked_prefixes = (
        "http:",
        "https:",
        "file:",
        "ftp:",
        "mailto:",
        "shell:",
        "explorer:",
        "powershell:",
        "cmd:",
        "ms-appx:",
        "ms-appinstaller:",
    )
    return "://" in text or text.startswith(blocked_prefixes)


def _app_shortcut_has_path_traversal_v2app_c(value):
    text = _app_shortcut_strip_outer_quotes_v2app_c(value).replace("/", "\\")
    parts = [part.strip() for part in text.split("\\") if part.strip()]
    return any(part in [".", ".."] for part in parts)


def _app_shortcut_stable_absolute_path_v2app_c(value):
    text = _app_shortcut_strip_outer_quotes_v2app_c(value)
    if not text or "\r" in text or "\n" in text:
        return ""
    if _app_shortcut_has_url_scheme_v2app_c(text):
        return ""
    if _app_shortcut_has_path_traversal_v2app_c(text):
        return ""
    if not os.path.isabs(text):
        return ""
    return text


def _app_shortcut_normalize_strict_path_v2app_c(value):
    text = _app_shortcut_stable_absolute_path_v2app_c(value)
    if not text:
        return ""
    return _app_shortcut_normalize_path_v2app_c(text)


def _app_shortcut_extract_single_argument_path_v2app_c(arguments):
    raw = str(arguments or "").strip()
    if not raw:
        return "", "arguments are empty"
    if "\r" in raw or "\n" in raw:
        return "", "arguments contain a newline"

    quote = raw[0] if raw[0] in ["'", '"'] else ""
    if quote:
        if len(raw) < 2 or raw[-1] != quote:
            return "", "arguments are not exactly one quoted path"
        value = raw[1:-1].strip()
    else:
        value = raw

    if not value:
        return "", "arguments do not contain a path"
    if "'" in value or '"' in value:
        return "", "arguments contain nested quotes"
    if _app_shortcut_has_url_scheme_v2app_c(value):
        return "", "arguments contain a URL or URI"
    if _app_shortcut_has_path_traversal_v2app_c(value):
        return "", "arguments contain relative or parent-path traversal"
    if not os.path.isabs(value):
        return "", "arguments do not contain an absolute path"
    return value, ""


def _app_shortcut_wsh_host_targets_v2app_c():
    roots = []
    seen_roots = set()
    for root in [os.environ.get("SystemRoot", ""), r"C:\Windows"]:
        root = str(root or "").strip()
        root_key = _app_shortcut_normalize_path_v2app_c(root) if root else ""
        if root and root_key not in seen_roots:
            roots.append(root)
            seen_roots.add(root_key)

    targets = []
    for root in roots:
        for folder in ["System32", "SysWOW64"]:
            for exe in ["wscript.exe", "cscript.exe"]:
                targets.append(os.path.join(root, folder, exe))
    return targets


def _app_shortcut_launcher_equivalence_v2app_c(existing, expected):
    if not existing.get("exists"):
        return {
            "equivalent": False,
            "form": "missing",
            "reason": "No Engel.lnk exists at the expected desktop destination.",
            "approved_launcher_argument": "",
            "accepted_wsh_targets": _app_shortcut_wsh_host_targets_v2app_c(),
        }
    if not existing.get("readable"):
        return {
            "equivalent": False,
            "form": "unreadable",
            "reason": "Existing Engel.lnk could not be read safely: " + existing.get("error", "unknown error"),
            "approved_launcher_argument": "",
            "accepted_wsh_targets": _app_shortcut_wsh_host_targets_v2app_c(),
        }

    expected_target = expected.get("target", "")
    expected_norm = _app_shortcut_normalize_strict_path_v2app_c(expected_target)
    target = existing.get("target_path", "")
    target_norm = _app_shortcut_normalize_strict_path_v2app_c(target)
    arguments = str(existing.get("arguments", "") or "")

    if not target_norm:
        return {
            "equivalent": False,
            "form": "invalid_target",
            "reason": "Detected target is not a stable absolute local path.",
            "approved_launcher_argument": "",
            "accepted_wsh_targets": _app_shortcut_wsh_host_targets_v2app_c(),
        }

    if target_norm == expected_norm:
        if not arguments.strip():
            return {
                "equivalent": True,
                "form": "direct_vbs",
                "reason": "Direct VBS target matches the approved launcher and has no arguments.",
                "approved_launcher_argument": "",
                "accepted_wsh_targets": _app_shortcut_wsh_host_targets_v2app_c(),
            }
        return {
            "equivalent": False,
            "form": "direct_vbs_with_unapproved_arguments",
            "reason": "Direct VBS target has unexpected arguments.",
            "approved_launcher_argument": "",
            "accepted_wsh_targets": _app_shortcut_wsh_host_targets_v2app_c(),
        }

    accepted_hosts = _app_shortcut_wsh_host_targets_v2app_c()
    accepted_norms = {
        _app_shortcut_normalize_strict_path_v2app_c(path): path
        for path in accepted_hosts
    }
    accepted_norms = {key: value for key, value in accepted_norms.items() if key}
    if target_norm in accepted_norms:
        argument_path, argument_error = _app_shortcut_extract_single_argument_path_v2app_c(arguments)
        argument_norm = _app_shortcut_normalize_strict_path_v2app_c(argument_path)
        if argument_error:
            return {
                "equivalent": False,
                "form": "windows_script_host_invalid_arguments",
                "reason": "Windows Script Host target arguments rejected: " + argument_error + ".",
                "approved_launcher_argument": argument_path,
                "accepted_wsh_targets": accepted_hosts,
            }
        if argument_norm == expected_norm:
            host_name = os.path.basename(_app_shortcut_strip_outer_quotes_v2app_c(target))
            return {
                "equivalent": True,
                "form": "windows_script_host_" + host_name.lower(),
                "reason": "Windows Script Host target is accepted because its single argument is exactly the approved Start Engel App.vbs path.",
                "approved_launcher_argument": argument_path,
                "accepted_wsh_targets": accepted_hosts,
            }
        return {
            "equivalent": False,
            "form": "windows_script_host_other_script",
            "reason": "Windows Script Host target arguments do not point exactly to the approved Start Engel App.vbs path.",
            "approved_launcher_argument": argument_path,
            "accepted_wsh_targets": accepted_hosts,
        }

    return {
        "equivalent": False,
        "form": "unapproved_target",
        "reason": "Detected target is not the approved VBS launcher or an approved Windows Script Host executable.",
        "approved_launcher_argument": "",
        "accepted_wsh_targets": accepted_hosts,
    }


def _app_shortcut_field_matches_v2app_c(existing, expected):
    if not existing.get("exists") or not existing.get("readable"):
        return {
            "working_directory": "unknown",
            "icon": "unknown",
        }
    work_ok = (
        _app_shortcut_normalize_strict_path_v2app_c(existing.get("working_directory", ""))
        == _app_shortcut_normalize_strict_path_v2app_c(expected.get("working_directory", ""))
    )
    icon_ok = (
        _app_shortcut_normalize_icon_v2app_c(existing.get("icon_location", ""))
        == _app_shortcut_normalize_icon_v2app_c(expected.get("icon_path", ""))
    )
    return {
        "working_directory": bool(work_ok),
        "icon": bool(icon_ok),
    }


def _app_shortcut_policy_v2app_c(existing, expected):
    equivalence = _app_shortcut_launcher_equivalence_v2app_c(existing, expected)
    fields = _app_shortcut_field_matches_v2app_c(existing, expected)
    equivalent = bool(equivalence.get("equivalent"))
    work_match = fields["working_directory"]
    icon_match = fields["icon"]

    if not existing.get("exists"):
        action_needed = "approval repair needed"
    elif not existing.get("readable"):
        action_needed = "blocked/manual review"
    elif not equivalent:
        action_needed = "blocked/manual review"
    elif work_match is True and icon_match is True:
        action_needed = "none"
    else:
        action_needed = "approval repair needed"

    return {
        "equivalent_to_approved_launcher": equivalent,
        "launcher_form": equivalence.get("form", "unknown"),
        "launcher_equivalence_reason": equivalence.get("reason", ""),
        "approved_launcher_argument": equivalence.get("approved_launcher_argument", ""),
        "accepted_wsh_targets": equivalence.get("accepted_wsh_targets", []),
        "working_directory_matches_expected": work_match,
        "icon_matches_expected": icon_match,
        "action_needed": action_needed,
    }


def _app_shortcut_inspect_existing_v2app_c():
    expected = _app_shortcut_expected_v2app_c()
    shortcut_path = expected["destination"]
    if not os.path.exists(shortcut_path):
        return {
            "exists": False,
            "readable": True,
            "path": shortcut_path,
            "desktop_path": expected["desktop_path"],
            "target_path": "",
            "arguments": "",
            "working_directory": "",
            "icon_location": "",
            "description": "",
            "error": "",
        }

    script = "\n".join([
        "$ErrorActionPreference = 'Stop'",
        "$ShortcutPath = " + _app_shortcut_ps_quote_v2app_c(shortcut_path),
        "$Wsh = New-Object -ComObject WScript.Shell",
        "$Shortcut = $Wsh.CreateShortcut($ShortcutPath)",
        "[pscustomobject]@{",
        "  Exists = $true;",
        "  Path = $ShortcutPath;",
        "  TargetPath = $Shortcut.TargetPath;",
        "  Arguments = $Shortcut.Arguments;",
        "  WorkingDirectory = $Shortcut.WorkingDirectory;",
        "  IconLocation = $Shortcut.IconLocation;",
        "  Description = $Shortcut.Description",
        "} | ConvertTo-Json -Compress",
    ])
    result = _app_shortcut_run_powershell_json_v2app_c(script, timeout=10)
    if not result.get("ok"):
        return {
            "exists": True,
            "readable": False,
            "path": shortcut_path,
            "desktop_path": expected["desktop_path"],
            "target_path": "",
            "arguments": "",
            "working_directory": "",
            "icon_location": "",
            "description": "",
            "error": result.get("error", ""),
        }

    data = result.get("data", {})
    return {
        "exists": bool(data.get("Exists", True)),
        "readable": True,
        "path": data.get("Path", shortcut_path),
        "desktop_path": expected["desktop_path"],
        "target_path": data.get("TargetPath", ""),
        "arguments": data.get("Arguments", ""),
        "working_directory": data.get("WorkingDirectory", ""),
        "icon_location": data.get("IconLocation", ""),
        "description": data.get("Description", ""),
        "error": "",
    }


def _app_shortcut_existing_matches_v2app_c(existing, expected):
    policy = _app_shortcut_policy_v2app_c(existing, expected)
    return bool(
        policy.get("equivalent_to_approved_launcher")
        and policy.get("working_directory_matches_expected") is True
        and policy.get("icon_matches_expected") is True
    )


def _app_shortcut_mismatch_notes_v2app_c(existing, expected):
    if not existing.get("exists"):
        return []
    if not existing.get("readable"):
        return ["Existing Engel.lnk could not be read safely: " + existing.get("error", "unknown error")]

    notes = []
    policy = _app_shortcut_policy_v2app_c(existing, expected)
    if not policy.get("equivalent_to_approved_launcher"):
        notes.append("Launcher equivalence failed: " + policy.get("launcher_equivalence_reason", "unknown reason"))
    if policy.get("working_directory_matches_expected") is False:
        notes.append("Working directory mismatch: detected `" + str(existing.get("working_directory", "")) + "`; expected `" + expected.get("working_directory", "") + "`.")
    if policy.get("icon_matches_expected") is False:
        notes.append("Icon mismatch: detected `" + str(existing.get("icon_location", "")) + "`; expected `" + expected.get("icon_path", "") + "`.")
    return notes


def _app_shortcut_detect_engel_exes_v2app_c():
    candidates = []
    for path in [
        os.path.join(ROOT, "Engel.exe"),
        os.path.join(ROOT, "dist", "Engel.exe"),
        os.path.join(ROOT, "dist", "Engel", "Engel.exe"),
        os.path.join(ROOT, "staging", "app", "Engel.exe"),
        os.path.join(ROOT, "staging", "app", "dist", "Engel.exe"),
    ]:
        if os.path.exists(path):
            candidates.append(path)
    return candidates


def _app_shortcut_dependency_indicators_v2app_c():
    indicators = []
    for path in [
        os.path.join(ROOT, ".venv", "Scripts", "pyinstaller.exe"),
        os.path.join(ROOT, ".venv", "Scripts", "nuitka.exe"),
        os.path.join(ROOT, ".venv", "Lib", "site-packages", "PyInstaller"),
        os.path.join(ROOT, ".venv", "Lib", "site-packages", "nuitka"),
    ]:
        if os.path.exists(path):
            indicators.append(path)
    return indicators


def _app_shortcut_diagnosis_v2app_c(command_name):
    expected = _app_shortcut_expected_v2app_c()
    existing = _app_shortcut_inspect_existing_v2app_c()
    policy = _app_shortcut_policy_v2app_c(existing, expected)
    return {
        "version": "V2APP-C",
        "repair": "V2APP-C Repair 1 Shortcut Equivalence Recognition",
        "command": command_name,
        "generated_at": now(),
        "workspace": ROOT,
        "expected_shortcut": expected,
        "existing_shortcut": existing,
        "shortcut_policy": policy,
        "equivalent_to_approved_launcher": policy.get("equivalent_to_approved_launcher"),
        "icon_matches_expected": policy.get("icon_matches_expected"),
        "working_directory_matches_expected": policy.get("working_directory_matches_expected"),
        "action_needed": policy.get("action_needed"),
        "existing_matches_expected": _app_shortcut_existing_matches_v2app_c(existing, expected),
        "mismatch_notes": _app_shortcut_mismatch_notes_v2app_c(existing, expected),
        "launcher": _app_launcher_file_record_v2app_a(expected["target"]),
        "icon": _app_launcher_file_record_v2app_a(expected["icon_path"]),
        "v2appa_report": _app_launcher_file_record_v2app_a(os.path.join(REPORTS_DIR, "app", "BRANDED_LAUNCHER_PLAN_V2APPA.md")),
        "v2appb_report": _app_launcher_file_record_v2app_a(os.path.join(REPORTS_DIR, "app", "BRANDED_LAUNCHER_ASSETS_PLAN_V2APPB.md")),
        "v2appb_staged_script": _app_launcher_file_record_v2app_a(os.path.join(ROOT, "staging", "app", "Create_Engel_Desktop_Shortcut_V2APPB.ps1")),
        "engel_exe_candidates": _app_shortcut_detect_engel_exes_v2app_c(),
        "packaging_dependency_indicators": _app_shortcut_dependency_indicators_v2app_c(),
        "live_launcher_changed": False,
        "startup_behavior_changed": False,
        "exe_built": False,
        "dependencies_installed_by_v2app_c": False,
        "startup_entries_added": False,
        "scheduled_tasks_added": False,
        "research_loop_started": False,
        "swarm_or_research_source_apply": False,
    }


def _app_shortcut_write_state_v2app_c(diagnosis, status, action=""):
    import json

    paths = _app_shortcut_paths_v2app_c()
    payload = {
        "version": "V2APP-C",
        "generated_at": now(),
        "status": status,
        "action": action,
        "diagnosis": diagnosis,
        "safety": {
            "live_launcher_changed": False,
            "startup_behavior_changed": False,
            "exe_built": False,
            "dependencies_installed": False,
            "startup_entries_added": False,
            "scheduled_tasks_added": False,
            "research_loop_started": False,
            "source_apply_from_swarm_or_research": False,
            "cloud_fallback": False,
        },
        "next_steps": {
            "V2APP-D": "Create Engel EXE packaging/build plan only; no EXE build, dependency install, or launcher replacement without separate approval.",
            "V2STATE-E": "Refresh stale session snapshot truth after V2APP-C.",
        },
    }
    write_file(paths["memory_state"], json.dumps(payload, indent=2))
    return paths["memory_state"]


def _app_shortcut_render_plan_v2app_c(diagnosis):
    expected = diagnosis["expected_shortcut"]
    existing = diagnosis.get("existing_shortcut", {})
    policy = diagnosis.get("shortcut_policy", {})
    lines = [
        "# Branded Shortcut Create Plan V2APP-C",
        "",
        "Command: app shortcut create plan",
        "Status: READ-ONLY / REPORT-ONLY",
        "Repair: V2APP-C Repair 1 Shortcut Equivalence Recognition",
        "Workspace: " + ROOT,
        "",
        "Shortcut that would be created:",
        "- Shortcut name: " + expected["shortcut_name"],
        "- Destination: " + expected["destination"],
        "- Target: " + expected["target"],
        "- Working directory: " + expected["working_directory"],
        "- Icon: " + expected["icon_path"],
        "",
        "Current shortcut inspection:",
        "- Shortcut exists: " + _app_shortcut_yes_no_v2app_c(existing.get("exists")),
        "- Readable: " + _app_shortcut_bool_text_v2app_c(existing.get("readable")),
        "- Detected target: " + str(existing.get("target_path", "")),
        "- Detected arguments: " + str(existing.get("arguments", "")),
        "- Detected working directory: " + str(existing.get("working_directory", "")),
        "- Detected icon: " + str(existing.get("icon_location", "")),
        "- Equivalent to approved launcher: " + _app_shortcut_bool_text_v2app_c(policy.get("equivalent_to_approved_launcher")),
        "- Launcher form: " + str(policy.get("launcher_form", "unknown")),
        "- Launcher equivalence reason: " + str(policy.get("launcher_equivalence_reason", "")),
        "- Icon matches expected: " + _app_shortcut_bool_text_v2app_c(policy.get("icon_matches_expected")),
        "- Working directory matches expected: " + _app_shortcut_bool_text_v2app_c(policy.get("working_directory_matches_expected")),
        "- Action needed: " + str(policy.get("action_needed", "blocked/manual review")),
        "",
        "Existing-shortcut rule:",
    ]
    mismatch_notes = diagnosis.get("mismatch_notes", [])
    if existing.get("exists") and existing.get("readable") and policy.get("equivalent_to_approved_launcher"):
        if str(policy.get("launcher_form", "")).startswith("windows_script_host"):
            lines.append("- Existing `Engel.lnk` uses Windows Script Host form.")
            lines.append("- This is acceptable only because its single argument points exactly to `" + expected["target"] + "`.")
            lines.append("- Arbitrary WSH arguments, URLs, relative paths, parent traversal, and other `.vbs` files are not accepted.")
        else:
            lines.append("- Existing `Engel.lnk` uses the direct approved VBS launcher target.")
        if policy.get("action_needed") == "none":
            lines.append("- No live change is needed; exact `app shortcut create APPROVE` should report a no-op.")
        else:
            lines.append("- Target is equivalent, but icon/workdir repair still requires exact `app shortcut create APPROVE`.")
    elif mismatch_notes:
        lines.append("- Existing `Engel.lnk` is not equivalent to the approved launcher and would not be silently replaced.")
        for note in mismatch_notes:
            lines.append("- " + note)
    elif existing.get("exists"):
        lines.append("- Existing `Engel.lnk` is present but requires manual review before any replacement.")
    else:
        lines.append("- No existing `Engel.lnk` detected at the user desktop destination; creation still requires exact `APPROVE`.")

    lines += [
        "",
        "Safety notes:",
        "- This command does not create a shortcut.",
        "- This command does not modify the desktop.",
        "- This command does not run the staged V2APP-B script.",
        "- This command does not change `Start Engel App.vbs` or live launch behavior.",
        "- Exact live creation command remains `app shortcut create APPROVE`.",
        "- A repair/refreshed shortcut still requires exact `APPROVE`.",
        "- A non-equivalent existing shortcut requires manual review or a future separate explicit repair command.",
        "",
        "No-change confirmations:",
        "- Live launcher changed: NO",
        "- Startup behavior changed: NO",
        "- EXE built: NO",
        "- Dependencies installed: NO",
        "- Startup entries added: NO",
        "- Scheduled tasks added: NO",
        "- Research loop started: NO",
        "- Swarm/research source apply happened: NO",
        "- Desktop/cloud action happened: NO",
    ]
    return "\n".join(lines)


