def _app_shortcut_create_with_powershell_v2app_c(expected):
    allowed_hosts = "@(" + ",".join([
        _app_shortcut_ps_quote_v2app_c(path)
        for path in _app_shortcut_wsh_host_targets_v2app_c()
    ]) + ")"
    script = "\n".join([
        "$ErrorActionPreference = 'Stop'",
        "$ShortcutPath = " + _app_shortcut_ps_quote_v2app_c(expected["destination"]),
        "$TargetPath = " + _app_shortcut_ps_quote_v2app_c(expected["target"]),
        "$WorkingDirectory = " + _app_shortcut_ps_quote_v2app_c(expected["working_directory"]),
        "$IconPath = " + _app_shortcut_ps_quote_v2app_c(expected["icon_path"]),
        "$AllowedHosts = " + allowed_hosts,
        "function Strip-OuterQuotes([string]$Value) {",
        "  if ($null -eq $Value) { return '' }",
        "  $v = $Value.Trim()",
        "  if ($v.Length -ge 2) {",
        "    $first = [int][char]$v[0]",
        "    $last = [int][char]$v[$v.Length - 1]",
        "    if (($first -eq 34 -and $last -eq 34) -or ($first -eq 39 -and $last -eq 39)) { return $v.Substring(1, $v.Length - 2).Trim() }",
        "  }",
        "  return $v",
        "}",
        "function Has-UrlScheme([string]$Value) {",
        "  $v = (Strip-OuterQuotes $Value).ToLowerInvariant()",
        "  if ([string]::IsNullOrWhiteSpace($v)) { return $false }",
        "  if ($v.Contains('://')) { return $true }",
        "  foreach ($prefix in @('http:', 'https:', 'file:', 'ftp:', 'mailto:', 'shell:', 'explorer:', 'powershell:', 'cmd:', 'ms-appx:', 'ms-appinstaller:')) {",
        "    if ($v.StartsWith($prefix)) { return $true }",
        "  }",
        "  return $false",
        "}",
        "function Has-PathTraversal([string]$Value) {",
        "  $v = (Strip-OuterQuotes $Value).Replace('/', '\\')",
        "  foreach ($part in $v.Split('\\')) {",
        "    $p = $part.Trim()",
        "    if ($p -eq '.' -or $p -eq '..') { return $true }",
        "  }",
        "  return $false",
        "}",
        "function Get-StableAbsolutePath([string]$Value) {",
        "  $v = Strip-OuterQuotes $Value",
        "  if ([string]::IsNullOrWhiteSpace($v)) { return '' }",
        "  if ($v.Contains(\"`r\") -or $v.Contains(\"`n\")) { return '' }",
        "  if (Has-UrlScheme $v) { return '' }",
        "  if (Has-PathTraversal $v) { return '' }",
        "  if (-not [System.IO.Path]::IsPathRooted($v)) { return '' }",
        "  return $v",
        "}",
        "function Normalize-ShortcutPath([string]$Value) {",
        "  $v = Get-StableAbsolutePath $Value",
        "  if ([string]::IsNullOrWhiteSpace($v)) { return '' }",
        "  try { return [System.IO.Path]::GetFullPath($v).TrimEnd([char]92).ToLowerInvariant() } catch { return '' }",
        "}",
        "function Get-SingleArgumentPath([string]$Value) {",
        "  if ($null -eq $Value) { return '' }",
        "  $raw = $Value.Trim()",
        "  if ([string]::IsNullOrWhiteSpace($raw)) { return '' }",
        "  if ($raw.Contains(\"`r\") -or $raw.Contains(\"`n\")) { return '' }",
        "  $path = $raw",
        "  $first = [int][char]$raw[0]",
        "  if ($first -eq 34 -or $first -eq 39) {",
        "    if ($raw.Length -lt 2) { return '' }",
        "    $last = [int][char]$raw[$raw.Length - 1]",
        "    if ($last -ne $first) { return '' }",
        "    $path = $raw.Substring(1, $raw.Length - 2).Trim()",
        "  }",
        "  if ([string]::IsNullOrWhiteSpace($path)) { return '' }",
        "  if ($path.Contains('\"') -or $path.Contains(\"'\")) { return '' }",
        "  return Get-StableAbsolutePath $path",
        "}",
        "function Test-ApprovedLauncher([string]$Target, [string]$Arguments) {",
        "  $targetNorm = Normalize-ShortcutPath $Target",
        "  $expectedNorm = Normalize-ShortcutPath $TargetPath",
        "  if ([string]::IsNullOrWhiteSpace($targetNorm) -or [string]::IsNullOrWhiteSpace($expectedNorm)) { return $false }",
        "  if ($targetNorm -eq $expectedNorm -and [string]::IsNullOrWhiteSpace($Arguments)) { return $true }",
        "  foreach ($hostPath in $AllowedHosts) {",
        "    if ($targetNorm -eq (Normalize-ShortcutPath $hostPath)) {",
        "      $argPath = Get-SingleArgumentPath $Arguments",
        "      if (-not [string]::IsNullOrWhiteSpace($argPath) -and (Normalize-ShortcutPath $argPath) -eq $expectedNorm) { return $true }",
        "    }",
        "  }",
        "  return $false",
        "}",
        "function Normalize-Icon([string]$Value) {",
        "  if ([string]::IsNullOrWhiteSpace($Value)) { return '' }",
        "  $v = $Value.Trim().Trim('\"')",
        "  if ($v.ToLower().EndsWith(',0')) { $v = $v.Substring(0, $v.Length - 2) }",
        "  $normalized = Normalize-ShortcutPath $v",
        "  if ([string]::IsNullOrWhiteSpace($normalized)) { return $v.ToLowerInvariant() }",
        "  return $normalized",
        "}",
        "if (-not (Test-Path -LiteralPath $TargetPath)) { throw 'Approved launcher target not found: ' + $TargetPath }",
        "if (-not (Test-Path -LiteralPath $IconPath)) { throw 'Engel icon not found: ' + $IconPath }",
        "$Wsh = New-Object -ComObject WScript.Shell",
        "$Action = 'CREATED'",
        "if (Test-Path -LiteralPath $ShortcutPath) {",
        "  $Existing = $Wsh.CreateShortcut($ShortcutPath)",
        "  $LauncherOk = Test-ApprovedLauncher $Existing.TargetPath $Existing.Arguments",
        "  if (-not $LauncherOk) {",
        "    throw ('Refusing to replace mismatched Engel.lnk. target=' + $Existing.TargetPath + '; arguments=' + $Existing.Arguments + '; workdir=' + $Existing.WorkingDirectory + '; icon=' + $Existing.IconLocation)",
        "  }",
        "  $Action = 'REFRESHED'",
        "}",
        "$Shortcut = $Wsh.CreateShortcut($ShortcutPath)",
        "$Shortcut.TargetPath = $TargetPath",
        "$Shortcut.Arguments = ''",
        "$Shortcut.WorkingDirectory = $WorkingDirectory",
        "$Shortcut.Description = 'Start Engel'",
        "$Shortcut.IconLocation = $IconPath",
        "$Shortcut.Save()",
        "[pscustomobject]@{Action=$Action; ShortcutPath=$ShortcutPath; TargetPath=$TargetPath; WorkingDirectory=$WorkingDirectory; IconLocation=$IconPath} | ConvertTo-Json -Compress",
    ])
    return _app_shortcut_run_powershell_json_v2app_c(script, timeout=20)


def _app_shortcut_render_result_v2app_c(diagnosis, action, blocked_reason=""):
    expected = diagnosis["expected_shortcut"]
    existing = diagnosis.get("existing_shortcut", {})
    policy = diagnosis.get("shortcut_policy", {})
    lines = [
        "# Branded Shortcut Create Result V2APP-C",
        "",
        "Command: app shortcut create APPROVE",
        "Status: " + action,
        "Repair: V2APP-C Repair 1 Shortcut Equivalence Recognition",
        "Workspace: " + ROOT,
        "",
        "Requested shortcut:",
        "- Shortcut name: " + expected["shortcut_name"],
        "- Destination: " + expected["destination"],
        "- Target: " + expected["target"],
        "- Working directory: " + expected["working_directory"],
        "- Icon: " + expected["icon_path"],
        "",
        "Existing shortcut policy:",
        "- Shortcut exists: " + _app_shortcut_yes_no_v2app_c(existing.get("exists")),
        "- Detected target: " + str(existing.get("target_path", "")),
        "- Detected arguments: " + str(existing.get("arguments", "")),
        "- Equivalent to approved launcher: " + _app_shortcut_bool_text_v2app_c(policy.get("equivalent_to_approved_launcher")),
        "- Launcher form: " + str(policy.get("launcher_form", "unknown")),
        "- Icon matches expected: " + _app_shortcut_bool_text_v2app_c(policy.get("icon_matches_expected")),
        "- Working directory matches expected: " + _app_shortcut_bool_text_v2app_c(policy.get("working_directory_matches_expected")),
        "- Action needed: " + str(policy.get("action_needed", "blocked/manual review")),
        "",
    ]
    if blocked_reason:
        lines += [
            "Blocked reason:",
            "- " + blocked_reason,
            "",
        ]
    lines += [
        "Result:",
        "- Created/refreshed live shortcut: " + ("YES" if action in ["CREATED", "REFRESHED"] else "NO"),
        "- Action: " + action,
        "",
        "No-change confirmations:",
        "- Live launcher changed: NO",
        "- Startup behavior changed: NO",
        "- EXE built: NO",
        "- Dependencies installed: NO",
        "- Startup entries added: NO",
        "- Scheduled tasks added: NO",
        "- Research loop started: NO",
        "- Swarm/research source apply happened: NO",
        "- Cloud fallback used: NO",
        "- Desktop action outside approved shortcut creation: NO",
    ]
    return "\n".join(lines)


def app_shortcut_create_v2app_c(approval=""):
    paths = _app_shortcut_paths_v2app_c()
    if approval != "APPROVE":
        diagnosis = _app_shortcut_diagnosis_v2app_c("app shortcut create")
        report = _app_shortcut_render_result_v2app_c(
            diagnosis,
            "BLOCKED_APPROVAL_REQUIRED",
            "Exact command required: app shortcut create APPROVE",
        )
        _app_shortcut_write_state_v2app_c(diagnosis, "BLOCKED_APPROVAL_REQUIRED")
        return report

    diagnosis = _app_shortcut_diagnosis_v2app_c("app shortcut create APPROVE")
    expected = diagnosis["expected_shortcut"]
    existing = diagnosis.get("existing_shortcut", {})
    policy = diagnosis.get("shortcut_policy", {})

    if not diagnosis.get("launcher", {}).get("exists"):
        report = _app_shortcut_render_result_v2app_c(diagnosis, "BLOCKED_MISSING_LAUNCHER", "Launcher target missing: " + expected["target"])
        write_file(paths["result_md"], report)
        _app_shortcut_write_state_v2app_c(diagnosis, "BLOCKED_MISSING_LAUNCHER")
        append_log("V2APP-C shortcut create blocked: missing launcher.")
        return report

    if not diagnosis.get("icon", {}).get("exists"):
        report = _app_shortcut_render_result_v2app_c(diagnosis, "BLOCKED_MISSING_ICON", "Icon missing: " + expected["icon_path"])
        write_file(paths["result_md"], report)
        _app_shortcut_write_state_v2app_c(diagnosis, "BLOCKED_MISSING_ICON")
        append_log("V2APP-C shortcut create blocked: missing icon.")
        return report

    if existing.get("exists") and existing.get("readable") and policy.get("action_needed") == "none":
        report = _app_shortcut_render_result_v2app_c(
            diagnosis,
            "NO_LIVE_CHANGE_NEEDED",
            "Existing Engel.lnk is already equivalent to the approved launcher and icon/workdir are acceptable.",
        )
        write_file(paths["result_md"], report)
        _app_shortcut_write_state_v2app_c(diagnosis, "NO_LIVE_CHANGE_NEEDED")
        append_log("V2APP-C shortcut create APPROVE no-op: existing Engel.lnk already equivalent and acceptable.")
        return report

    if existing.get("exists") and not policy.get("equivalent_to_approved_launcher"):
        notes = diagnosis.get("mismatch_notes", []) or ["Existing Engel.lnk is not equivalent to the approved launcher."]
        report = _app_shortcut_render_result_v2app_c(diagnosis, "BLOCKED_MANUAL_REVIEW", " ".join(notes))
        write_file(paths["result_md"], report)
        _app_shortcut_write_state_v2app_c(diagnosis, "BLOCKED_MANUAL_REVIEW")
        append_log("V2APP-C shortcut create blocked: existing Engel.lnk not equivalent to approved launcher.")
        return report

    result = _app_shortcut_create_with_powershell_v2app_c(expected)
    if not result.get("ok"):
        report = _app_shortcut_render_result_v2app_c(diagnosis, "BLOCKED_CREATE_FAILED", result.get("error", "Unknown shortcut creation failure."))
        write_file(paths["result_md"], report)
        _app_shortcut_write_state_v2app_c(diagnosis, "BLOCKED_CREATE_FAILED")
        append_log("V2APP-C shortcut create failed: " + result.get("error", "unknown"))
        return report

    action = result.get("data", {}).get("Action", "REFRESHED" if existing.get("exists") else "CREATED")
    after = _app_shortcut_diagnosis_v2app_c("app shortcut create APPROVE result")
    report = _app_shortcut_render_result_v2app_c(after, action)
    write_file(paths["result_md"], report)
    _app_shortcut_write_state_v2app_c(after, action)
    append_log("V2APP-C shortcut create completed with action: " + str(action))
    return report


