def _route_verification_bool_v1(value):
    if value is True:
        return "true"
    if value is False:
        return "false"
    if value is None:
        return "missing"
    return str(value)

def verification_set_status_v1():
    import json
    import os

    path = _route_verification_set_path_v1()
    lines = [
        "# Verification Set Status",
        "",
        "Status: READ_ONLY / STATUS_ONLY / DISPLAY_ONLY",
        "",
        "Source:",
        path,
        "",
        "Safety:",
        "- does not run verifiers",
        "- does not execute route-regression matrix entries",
        "- does not generate reports",
        "- does not start research",
        "- does not call providers",
        "- does not mutate files",
    ]

    if not os.path.exists(path):
        lines += [
            "",
            "Manifest:",
            "- missing",
            "- No replacement file was created.",
            "- No repair was attempted.",
        ]
        return "\n".join(lines)

    try:
        data = json.loads(read_file(path))
    except Exception as exc:
        lines += [
            "",
            "Manifest:",
            "- invalid JSON: " + str(exc),
            "- No replacement file was created.",
            "- No repair was attempted.",
        ]
        return "\n".join(lines)

    verifiers = data.get("standard_verifiers", [])
    matrix_entries = data.get("route_regression_matrix_entries", [])
    safety = data.get("safety_contract", {})

    lines += [
        "",
        "Manifest:",
        "- version: " + str(data.get("version", "missing")),
        "- mode: " + str(data.get("mode", "missing")),
        "- runtime_feature_enabled: " + _route_verification_bool_v1(data.get("runtime_feature_enabled")),
        "- runs_automatically: " + _route_verification_bool_v1(data.get("runs_automatically")),
        "",
        "Standard verifier set:",
    ]
    if isinstance(verifiers, list) and verifiers:
        for verifier in verifiers:
            lines.append("- " + str(verifier))
    else:
        lines.append("- none listed")

    lines += [
        "",
        "Route-regression matrix behavior:",
        "- Display only; matrix entries are not executed by this command.",
    ]
    if isinstance(matrix_entries, list) and matrix_entries:
        for entry in matrix_entries:
            if not isinstance(entry, dict):
                continue
            command = str(entry.get("command", "missing"))
            behavior = str(entry.get("expected_behavior", "missing"))
            execute = _route_verification_bool_v1(entry.get("should_execute_in_test"))
            lines += [
                "- command: " + command,
                "  expected_behavior: " + behavior,
                "  should_execute_in_test: " + execute,
            ]
    else:
        lines.append("- none listed")

    lines += [
        "",
        "Report-generating route safety:",
        "- report-generating routes are documented, not auto-executed, when should_execute_in_test: false",
        "",
        "Safety contract:",
        "- no runtime autonomy: " + _route_verification_bool_v1(safety.get("runtime_autonomy_enabled") is False),
        "- runtime_autonomy_enabled: " + _route_verification_bool_v1(safety.get("runtime_autonomy_enabled")),
        "- no Level 2 runtime autonomy: " + _route_verification_bool_v1(safety.get("runtime_level_2_enabled") is False),
        "- runtime_level_2_enabled: " + _route_verification_bool_v1(safety.get("runtime_level_2_enabled")),
        "- no loops: " + _route_verification_bool_v1(safety.get("loops_enabled") is False),
        "- loops_enabled: " + _route_verification_bool_v1(safety.get("loops_enabled")),
        "- no background workers: " + _route_verification_bool_v1(safety.get("background_workers") is False),
        "- background_workers: " + _route_verification_bool_v1(safety.get("background_workers")),
        "- no live research: " + _route_verification_bool_v1(safety.get("live_research") is False),
        "- live_research: " + _route_verification_bool_v1(safety.get("live_research")),
        "- no provider calls: " + _route_verification_bool_v1(safety.get("provider_calls") is False),
        "- provider_calls: " + _route_verification_bool_v1(safety.get("provider_calls")),
        "- trusted memory writes blocked: " + _route_verification_bool_v1(safety.get("trusted_memory_writes") is False),
        "- trusted_memory_writes: " + _route_verification_bool_v1(safety.get("trusted_memory_writes")),
        "- source edits blocked: " + _route_verification_bool_v1(safety.get("source_edits") is False),
        "- source_edits: " + _route_verification_bool_v1(safety.get("source_edits")),
        "- learning apply blocked: " + _route_verification_bool_v1(safety.get("learning_apply") is False),
        "- learning_apply: " + _route_verification_bool_v1(safety.get("learning_apply")),
        "- queue mutation blocked: " + _route_verification_bool_v1(safety.get("queue_mutation") is False),
        "- queue_mutation: " + _route_verification_bool_v1(safety.get("queue_mutation")),
        "- digest/history writes blocked: " + _route_verification_bool_v1(safety.get("digest_history_writes") is False),
        "- digest_history_writes: " + _route_verification_bool_v1(safety.get("digest_history_writes")),
        "- ALIVE_STATE writes blocked: " + _route_verification_bool_v1(safety.get("alive_state_writes") is False),
        "- alive_state_writes: " + _route_verification_bool_v1(safety.get("alive_state_writes")),
    ]
    return "\n".join(lines)

