def _route_regression_classify_v2test_a(command):
    router = None
    tool = None
    try:
        router = _safe_router_match_v2u(command)
    except Exception:
        router = None
    try:
        tool = _tool_registry_match_v2s(command)
    except Exception:
        tool = None
    return router, tool

def _route_regression_render_v2test_a(cases, generated=True):
    import datetime
    import os

    backup = "E:\\EngelStandalone_BACKUP_STABLE_20260430_232244"
    try:
        parent = os.path.dirname(ROOT.rstrip("\\/"))
        backups = []
        for name in os.listdir(parent):
            if name.startswith("EngelStandalone_BACKUP_STABLE_"):
                backups.append(name)
        if backups:
            backup = os.path.join(parent, sorted(backups)[-1])
    except Exception:
        pass

    lines = [
        "# V2TEST-A Route Regression Test Matrix",
        "",
        "Time: " + now(),
        "",
        "Stable backup:",
        "- " + backup,
        "",
        "Generated by route_regression_matrix_v2test_a: " + str(bool(generated)),
        "",
        "Purpose:",
        "- Define a report-only regression matrix for known Engel routes before deeper route cleanup/refactor.",
        "- Classify route/tool expectations without executing target commands.",
        "- Preserve Research ON/OFF, batch preview, source/learning apply, patch approval gates, and fallback behavior.",
        "",
        "Safety:",
        "- V2TEST-A does not execute matrix commands.",
        "- V2TEST-A does not start research.",
        "- V2TEST-A does not click, send, delete, login, pay, change settings, install dependencies, or apply patches.",
        "- All `should_execute_in_test` values are `false`.",
    ]

    families = []
    for case in cases:
        if case["family"] not in families:
            families.append(case["family"])

    for family in families:
        lines += [
            "",
            "## " + family,
            "",
            "| command | expected router match if applicable | expected tool match if applicable | expected risk | expected behavior type | should_execute_in_test | notes/safety |",
            "|---|---|---|---|---|---|---|",
        ]
        for case in [c for c in cases if c["family"] == family]:
            router, tool = _route_regression_classify_v2test_a(case["command"])
            router_text = "yes: " + router.get("pattern", "") if router else "review: no registry match"
            tool_text = "yes: " + tool.get("pattern", "") if tool else "review: no registry match"
            lines.append(
                "| " + case["command"] +
                " | " + router_text +
                " | " + tool_text +
                " | " + case["risk"] +
                " | " + case["behavior"] +
                " | false" +
                " | " + case["notes"] + " |"
            )

    lines += [
        "",
        "## V2TEST-A Commands",
        "",
        "- `route regression matrix`: CAUTION / write / test / report / explicit command",
        "- `route regression status`: LOW / read_only / test / system_status",
        "",
        "## Intentionally Not Tested By Execution",
        "",
        "- Research ON/OFF and durable loop start/stop.",
        "- Patch apply.",
        "- Learning apply.",
        "- Source apply.",
        "- Desktop click/paste/type.",
        "- Login/account/payment/system setting routes.",
        "- Unknown command fallback behavior.",
        "",
        "Safety footer:",
        "- Report/classification only.",
        "- No matrix command executed.",
        "- No route dispatcher refactor.",
        "- Existing approval gates unchanged.",
    ]
    return "\n".join(lines)

def route_regression_matrix_v2test_a():
    import json
    import os

    paths = _route_regression_paths_v2test_a()
    cases = _route_regression_cases_v2test_a()
    report = _route_regression_render_v2test_a(cases, True)

    os.makedirs(os.path.dirname(paths["report"]), exist_ok=True)
    os.makedirs(os.path.dirname(paths["json"]), exist_ok=True)
    write_file(paths["report"], report)

    rows = []
    for case in cases:
        router, tool = _route_regression_classify_v2test_a(case["command"])
        rows.append({
            "family": case["family"],
            "command": case["command"],
            "expected_risk": case["risk"],
            "expected_behavior_type": case["behavior"],
            "should_execute_in_test": False,
            "router_match": router.get("pattern") if router else None,
            "tool_match": tool.get("pattern") if tool else None,
            "notes": case["notes"],
        })

    payload = {
        "name": "V2TEST_A_ROUTE_REGRESSION_MATRIX",
        "generated_at": now(),
        "report_path": paths["report"],
        "should_execute_in_test": False,
        "case_count": len(rows),
        "cases": rows,
        "safety": {
            "executes_target_commands": False,
            "starts_research": False,
            "changes_approval_gates": False,
            "changes_batch_preview": False,
            "changes_route_dispatchers": False,
        },
    }
    write_file(paths["json"], json.dumps(payload, indent=2))
    append_log("V2TEST-A route regression matrix generated: " + paths["report"])
    return report

def route_regression_status_v2test_a():
    import json
    import os
    paths = _route_regression_paths_v2test_a()
    exists = os.path.exists(paths["report"])
    json_exists = os.path.exists(paths["json"])
    lines = [
        "# V2TEST-A Route Regression Status",
        "",
        "Status: " + ("REPORT_FOUND" if exists else "REPORT_MISSING"),
        "",
        "Report path:",
        paths["report"],
        "",
        "Summary JSON path:",
        paths["json"],
        "",
        "Summary JSON exists: " + str(json_exists),
        "",
        "Commands:",
        "- route regression matrix",
        "- route regression status",
        "",
        "Safety:",
        "- Status/read only.",
        "- Does not execute matrix commands.",
        "- Does not execute verifier scripts.",
        "- Does not start research.",
        "- Does not change route behavior.",
        "",
        "Standard verification set before future colony/autonomy work:",
    ]
    for verifier in _route_verification_set_v1():
        lines.append("- python .\\" + verifier["script"] + " [" + verifier["scope"] + "]")
    try:
        manifest = json.loads(read_file(_route_verification_set_path_v1()))
        entries = manifest.get("route_regression_matrix_entries", [])
    except Exception as exc:
        entries = []
        lines += [
            "",
            "Verification manifest warning:",
            "- Could not read documentation-only manifest: " + str(exc),
        ]
    lines += [
        "",
        "Documentation-only route matrix entries from verification manifest:",
        "- These entries are listed for safety ritual visibility only.",
        "- This status route does not execute them and does not generate reports.",
    ]
    if isinstance(entries, list) and entries:
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            lines += [
                "- command: " + str(entry.get("command", "")),
                "  expected_behavior: " + str(entry.get("expected_behavior", "")),
                "  should_execute_in_test: " + _route_verification_bool_v1(entry.get("should_execute_in_test")),
            ]
    else:
        lines.append("- none listed")
    lines += [
        "",
        "Verification-set safety:",
        "- Hive verifier covers worker-ant/hive routes.",
        "- Colony verifier covers colony routes.",
        "- Swarm verifier covers swarm-trails preview/report-only routes.",
        "- Colony autonomy verifier covers the autonomy ladder and Level 1 sensing preview/report-only routes.",
        "- Mycelium verifier covers the read-only mycelium status/contract routes and absent runtime/report/candidate paths.",
        "- These verifiers preserve no-write, no-provider, no-background, no-learning-apply, no-queue-mutation, no-trusted-memory-write, no-source-edit, no-digest/history, and no-ALIVE_STATE guarantees.",
        "- This status route lists the verifier set only; it does not run the scripts.",
    ]
    if exists:
        text = read_file(paths["report"]).strip()
        excerpt = text[:4000] + ("\n...[truncated]" if len(text) > 4000 else "")
        lines += ["", "## Matrix Excerpt", "", excerpt]
    return "\n".join(lines)


