def unknown_command_check_v2ue(text):
    cmd = str(text or "").strip()
    router = _safe_router_match_v2u(cmd) if "_safe_router_match_v2u" in globals() else None
    perm = permission_check_v2q(cmd)

    risky_words = [
        "delete", "remove", "erase", "send", "submit", "post", "email",
        "buy", "purchase", "pay", "login", "password", "token", "api key",
        "install", "download", "run script", "click", "type", "paste",
        "press enter", "edit", "patch", "overwrite"
    ]

    low = cmd.lower()
    risky_hits = [w for w in risky_words if w in low]

    conversational_starters = [
        "what", "why", "how", "explain", "help", "plan", "think", "tell me",
        "summarize", "review", "idea", "next step"
    ]
    conversational = any(low.startswith(w) for w in conversational_starters)

    if router:
        classification = "KNOWN_ROUTE"
        recommendation = "Use the existing known command route."
    elif risky_hits:
        classification = "UNKNOWN_RISKY_ACTION"
        recommendation = "Do not fall through to chat as action. Ask for a known approval-gated command or run router/tool/permission check first."
    elif conversational:
        classification = "UNKNOWN_CONVERSATIONAL"
        recommendation = "Safe candidate for normal local chat fallback."
    else:
        classification = "UNKNOWN_UNCLEAR"
        recommendation = "Ask for clarification or suggest known commands before action."

    lines = [
        "# Unknown Command Check V2U-E",
        "",
        "Input:",
        cmd if cmd else "[none]",
        "",
        "Classification:",
        classification,
        "",
        "Router match:",
        "YES" if router else "NO",
    ]

    if router:
        lines += [
            "Matched pattern: " + router.get("pattern", ""),
            "Family: " + router.get("family", ""),
            "Risk: " + router.get("risk", ""),
        ]

    lines += [
        "",
        "Permission result:",
        "- Decision: " + perm.get("decision", "ASK"),
        "- Reason: " + perm.get("reason", ""),
        "",
        "Risky word hits:",
    ]

    if risky_hits:
        for w in risky_hits:
            lines.append("- " + w)
    else:
        lines.append("- none")

    lines += [
        "",
        "Recommendation:",
        recommendation,
        "",
        "Safety:",
        "- Check/report only.",
        "- No command executed.",
        "- No router behavior changed.",
        "- No clicking/sending/deleting/cloud fallback.",
    ]

    return "\n".join(lines)



# ----------------------------------------------------------------------
# Closest-Command Suggestions V2U-F
# Suggests likely known commands for unknown/misspelled inputs.
# Report/check only. Does not execute suggested commands.
# ----------------------------------------------------------------------
def _command_suggestion_candidates_v2uf():
    candidates = []

    try:
        for row in _safe_router_registry_v2u():
            p = str(row.get("pattern", "")).strip()
            if p:
                candidates.append(p)
    except Exception:
        pass

    try:
        for row in _tool_registry_v2s():
            p = str(row.get("pattern", "")).strip()
            if p:
                candidates.append(p)
    except Exception:
        pass

    extra = [
        "health",
        "router status",
        "router check research status",
        "tool registry status",
        "tool check research status",
        "permission status",
        "permission check control click 100 100",
        "research status",
        "research on",
        "research off",
        "research thinking status",
        "research thinking screen",
        "overnight topic rotation status",
        "overnight proposal harvest status",
        "overnight proposal harvest review",
        "patch diff status",
        "approved projects hygiene",
        "unknown command safety plan",
        "unknown command check delete all files",
        "external code ideas proposal",
        "backup stable APPROVE",
    ]

    candidates.extend(extra)

    cleaned = []
    seen = set()
    for c in candidates:
        c = str(c).strip()
        if not c:
            continue
        key = c.lower()
        if key not in seen:
            cleaned.append(c)
            seen.add(key)
    return cleaned

def closest_command_suggestions_v2uf(text, limit=8):
    import difflib

    raw = str(text or "").strip()
    low = raw.lower()

    candidates = _command_suggestion_candidates_v2uf()
    scored = []

    for c in candidates:
        cl = c.lower()

        score = difflib.SequenceMatcher(None, low, cl).ratio()

        if low and cl.startswith(low[: min(len(low), 8)]):
            score += 0.15

        raw_words = set(low.split())
        cand_words = set(cl.replace("<", " ").replace(">", " ").split())
        overlap = len(raw_words & cand_words)
        if overlap:
            score += min(0.20, overlap * 0.06)

        if score >= 0.34:
            scored.append((score, c))

    scored.sort(key=lambda x: (-x[0], x[1]))

    out = []
    seen = set()
    for score, c in scored:
        key = c.lower()
        if key in seen:
            continue
        out.append({"command": c, "score": round(score, 3)})
        seen.add(key)
        if len(out) >= int(limit or 8):
            break

    return out

def command_suggest_v2uf(text):
    raw = str(text or "").strip()
    router = _safe_router_match_v2u(raw) if "_safe_router_match_v2u" in globals() else None
    suggestions = closest_command_suggestions_v2uf(raw, 8)

    lines = [
        "# Closest Command Suggestions V2U-F",
        "",
        "Input:",
        raw if raw else "[none]",
        "",
        "Known route:",
        "YES" if router else "NO",
    ]

    if router:
        lines += [
            "Matched pattern: " + router.get("pattern", ""),
            "Family: " + router.get("family", ""),
            "Risk: " + router.get("risk", ""),
        ]

    lines += [
        "",
        "Suggestions:",
    ]

    if suggestions:
        for item in suggestions:
            lines.append("- " + item["command"] + "  (score " + str(item["score"]) + ")")
    else:
        lines.append("- none")

    lines += [
        "",
        "Safety:",
        "- Suggestion/report only.",
        "- No suggested command executed.",
        "- No router behavior changed.",
        "- No clicking.",
        "- No sending.",
        "- No deleting.",
        "- No cloud fallback.",
    ]

    return "\n".join(lines)

# Wrap V2U-E unknown command check so unknown reports include suggestions.
_unknown_command_check_base_v2uf = unknown_command_check_v2ue

def unknown_command_check_v2ue(text):
    base = _unknown_command_check_base_v2uf(text)
    try:
        router = _safe_router_match_v2u(str(text or "").strip()) if "_safe_router_match_v2u" in globals() else None
        if router:
            return base

        suggestions = closest_command_suggestions_v2uf(text, 5)
        lines = ["", "## Closest Command Suggestions V2U-F"]

        if suggestions:
            for item in suggestions:
                lines.append("- " + item["command"] + "  (score " + str(item["score"]) + ")")
        else:
            lines.append("- none")

        lines += [
            "",
            "Suggestion safety:",
            "- Suggestions are not executed.",
            "- Use router check or tool check before running a suggested command.",
        ]

        return base + "\n" + "\n".join(lines)
    except Exception:
        return base



