# ----------------------------------------------------------------------
# Dry-Run Unknown-Command Guard Evaluator V2U-H
# Evaluates what guard mode WOULD do. Report-only. No blocking yet.
# ----------------------------------------------------------------------
def unknown_command_guard_dry_run_v2uh(text):
    import os

    cmd = str(text or "").strip()
    router = _safe_router_match_v2u(cmd) if "_safe_router_match_v2u" in globals() else None
    perm = permission_check_v2q(cmd)
    suggestions = closest_command_suggestions_v2uf(cmd, 5) if "closest_command_suggestions_v2uf" in globals() else []

    risky_words = [
        "delete", "remove", "erase", "send", "submit", "post", "email",
        "buy", "purchase", "pay", "login", "password", "token", "api key",
        "install", "download", "run script", "click", "type", "paste",
        "press enter", "edit", "patch", "overwrite"
    ]

    conversational_starters = [
        "what", "why", "how", "explain", "help", "plan", "think", "tell me",
        "summarize", "review", "idea", "next step"
    ]

    low = cmd.lower()
    risky_hits = [w for w in risky_words if w in low]
    conversational = any(low.startswith(w) for w in conversational_starters)

    if router:
        guard_decision = "ALLOW_KNOWN_ROUTE"
        guard_reason = "Known command route exists. Guard would allow the existing route system to handle it."
    elif risky_hits or perm.get("decision") == "DENY":
        guard_decision = "WOULD_BLOCK_RISKY_UNKNOWN"
        guard_reason = "Unknown action-like/risky command should not fall through to chat."
    elif conversational:
        guard_decision = "WOULD_ALLOW_CHAT"
        guard_reason = "Unknown text appears conversational and safe for normal local chat fallback."
    elif suggestions:
        guard_decision = "WOULD_SUGGEST_COMMAND"
        guard_reason = "Unknown command is unclear, but likely command suggestions are available."
    else:
        guard_decision = "WOULD_ASK_CLARIFY"
        guard_reason = "Unknown command is unclear and no strong safe command match was found."

    lines = [
        "# Unknown-Command Guard Dry Run V2U-H",
        "",
        "Input:",
        cmd if cmd else "[none]",
        "",
        "Guard mode currently:",
        "OFF / DRY-RUN ONLY",
        "",
        "Dry-run decision:",
        guard_decision,
        "",
        "Reason:",
        guard_reason,
        "",
        "Router match:",
        "YES" if router else "NO",
    ]

    if router:
        lines += [
            "Matched pattern: " + router.get("pattern", ""),
            "Family: " + router.get("family", ""),
            "Risk: " + router.get("risk", ""),
        ]

    lines += [
        "",
        "Permission result:",
        "- Decision: " + perm.get("decision", "ASK"),
        "- Reason: " + perm.get("reason", ""),
        "",
        "Risky word hits:",
    ]

    if risky_hits:
        for w in risky_hits:
            lines.append("- " + w)
    else:
        lines.append("- none")

    lines += ["", "Closest suggestions:"]
    if suggestions:
        for item in suggestions:
            lines.append("- " + item["command"] + "  (score " + str(item["score"]) + ")")
    else:
        lines.append("- none")

    lines += [
        "",
        "What would happen later if guard mode were active:",
    ]

    if guard_decision == "ALLOW_KNOWN_ROUTE":
        lines += [
            "- Engel would continue to the existing known route.",
            "- Existing permission/APPROVE gates would still apply.",
        ]
    elif guard_decision == "WOULD_BLOCK_RISKY_UNKNOWN":
        lines += [
            "- Engel would block chat fallback.",
            "- Engel would show the risk reason and suggest router/tool/permission checks.",
            "- Engel would not click, type, paste, send, delete, install, patch, or login.",
        ]
    elif guard_decision == "WOULD_ALLOW_CHAT":
        lines += [
            "- Engel would allow normal local chat fallback.",
            "- No command/action route would run.",
        ]
    elif guard_decision == "WOULD_SUGGEST_COMMAND":
        lines += [
            "- Engel would not run anything.",
            "- Engel would show closest command suggestions.",
        ]
    else:
        lines += [
            "- Engel would ask for clarification.",
            "- Engel would not run an action.",
        ]

    lines += [
        "",
        "Safety:",
        "- Dry-run/report only.",
        "- No fallback behavior changed.",
        "- No command executed.",
        "- No clicking.",
        "- No sending.",
        "- No deleting.",
        "- No cloud fallback.",
    ]

    report = "\n".join(lines)
    out_dir = os.path.join(REPORTS_DIR, "router")
    os.makedirs(out_dir, exist_ok=True)
    write_file(os.path.join(out_dir, "UNKNOWN_COMMAND_GUARD_DRY_RUN_V2UH.md"), report)
    return report



