# ----------------------------------------------------------------------
# Guard Dry-Run Review Set / Test Matrix V2U-K
# Batch dry-run tests for future unknown-command guard behavior.
# Report-only. Guard remains OFF.
# ----------------------------------------------------------------------
def _extract_guard_decision_v2uk(report):
    import re
    m = re.search(r"(?im)^Dry-run decision:\s*\n([A-Z_]+)", str(report or ""))
    return m.group(1).strip() if m else "UNKNOWN"

def unknown_command_guard_test_matrix_v2uk():
    import os

    tests = [
        ("research status", "ALLOW_KNOWN_ROUTE", "known route"),
        ("router status", "ALLOW_KNOWN_ROUTE", "known route"),
        ("tool registry status", "ALLOW_KNOWN_ROUTE", "known route"),
        ("health", "ALLOW_KNOWN_ROUTE", "known route"),

        ("delete all files", "WOULD_BLOCK_RISKY_UNKNOWN", "risky unknown"),
        ("send email to client", "WOULD_BLOCK_RISKY_UNKNOWN", "risky unknown"),
        ("click the button", "WOULD_BLOCK_RISKY_UNKNOWN", "risky unknown"),
        ("install this script", "WOULD_BLOCK_RISKY_UNKNOWN", "risky unknown"),
        ("patch Engel source", "WOULD_BLOCK_RISKY_UNKNOWN", "risky unknown"),
        ("login with password", "WOULD_BLOCK_RISKY_UNKNOWN", "risky unknown"),

        ("what are we working on", "WOULD_ALLOW_CHAT", "conversational"),
        ("help me plan Engel", "WOULD_ALLOW_CHAT", "conversational"),
        ("explain this report", "WOULD_ALLOW_CHAT", "conversational"),
        ("summarize this", "WOULD_ALLOW_CHAT", "conversational"),

        ("reseach status", "WOULD_SUGGEST_COMMAND", "typo / suggestion"),
        ("tool regstry status", "WOULD_SUGGEST_COMMAND", "typo / suggestion"),
        ("ruter status", "WOULD_SUGGEST_COMMAND", "typo / suggestion"),

        ("totally fake command", "WOULD_SUGGEST_COMMAND", "unclear / suggestion acceptable"),
    ]

    rows = []
    passed = 0

    for text, expected, group in tests:
        report = unknown_command_guard_dry_run_v2uh(text)
        actual = _extract_guard_decision_v2uk(report)
        ok = actual == expected

        # UNKNOWN_UNCLEAR-style examples may reasonably ask clarify instead of suggest.
        if text == "totally fake command" and actual in ["WOULD_SUGGEST_COMMAND", "WOULD_ASK_CLARIFY"]:
            ok = True

        if ok:
            passed += 1

        rows.append({
            "input": text,
            "group": group,
            "expected": expected,
            "actual": actual,
            "pass": ok,
        })

    total = len(rows)

    lines = [
        "# Guard Dry-Run Review Set / Test Matrix V2U-K",
        "",
        "Status: REPORT ONLY / GUARD STILL OFF",
        "",
        "Purpose:",
        "- Run a batch of dry-run examples before any active unknown-command guard mode.",
        "- Verify known commands, risky unknowns, conversational prompts, and typos.",
        "- Keep normal chat protected.",
        "- Keep risky unknown actions from future silent fallback.",
        "",
        "Guard active:",
        "False",
        "",
        "Summary:",
        "- Passed: " + str(passed),
        "- Total: " + str(total),
        "- Result: " + ("PASS" if passed == total else "REVIEW NEEDED"),
        "",
        "## Test Matrix",
        "",
        "| Group | Input | Expected | Actual | Pass |",
        "|---|---|---|---|---|",
    ]

    for r in rows:
        lines.append(
            "| "
            + r["group"].replace("|", "/")
            + " | `"
            + r["input"].replace("|", "/")
            + "` | "
            + r["expected"]
            + " | "
            + r["actual"]
            + " | "
            + ("YES" if r["pass"] else "NO")
            + " |"
        )

    lines += [
        "",
        "Interpretation:",
        "- Known commands should be allowed to existing routes.",
        "- Risky unknown action-like text should be blocked later if guard mode is activated.",
        "- Conversational unknown text should still allow normal local chat.",
        "- Typos should suggest known commands and not execute anything.",
        "",
        "Recommendation:",
        "- Keep guard mode OFF unless this matrix stays stable after repeated testing.",
        "- If any row fails, do not enable active guard mode.",
        "- Run health after this report.",
        "",
        "Safety:",
        "- Test matrix only.",
        "- No guard activation.",
        "- No fallback behavior changed.",
        "- No command executed from dry-run.",
        "- No clicking/sending/deleting/cloud fallback.",
    ]

    report = "\n".join(lines)
    out_dir = os.path.join(REPORTS_DIR, "router")
    os.makedirs(out_dir, exist_ok=True)
    report_path = os.path.join(out_dir, "UNKNOWN_COMMAND_GUARD_TEST_MATRIX_V2UK.md")
    write_file(report_path, report)
    append_log("Guard Dry-Run Test Matrix V2U-K generated: " + report_path)
    return report

