def _tail_text_v2v(path, max_chars=4000):
    import os
    if not os.path.exists(path):
        return ""
    try:
        text = read_file(path)
    except Exception:
        return ""
    if len(text) > max_chars:
        return text[-max_chars:]
    return text

def _state_truth_paths_v2state_e():
    return {
        "report": os.path.join(REPORTS_DIR, "state", "STATE_TRUTH_REFRESH_V2STATEE.md"),
        "memory_json": os.path.join(MEMORY_DIR, "STATE_TRUTH_REFRESH_V2STATEE.json"),
    }

def _state_latest_backup_with_prefix_v2state_e(prefix):
    try:
        parent = os.path.dirname(ROOT.rstrip("\\/"))
        matches = []
        for name in os.listdir(parent):
            if name.startswith(prefix):
                matches.append(os.path.join(parent, name))
        if matches:
            return sorted(matches)[-1]
    except Exception:
        pass
    return ""

def _state_latest_stable_backup_v2state_e():
    latest = _state_latest_backup_with_prefix_v2state_e("EngelStandalone_BACKUP_STABLE_")
