def _bridge_tail_v2bridgea(path, max_chars=3500):
    import os
    if not os.path.exists(path):
        return "[missing]"
    try:
        text = read_file(path)
    except Exception as e:
        return "[read failed: " + str(e) + "]"
    if len(text) > max_chars:
        return text[-max_chars:]
    return text

