# V2BRIDGE-A Repair 1 - Safe Bridge Command Wrapper
# Prevents UI route crashes from bridge command exceptions.
# ----------------------------------------------------------------------
def chatgpt_bridge_safe_v2bridgea(command):
    try:
        c = str(command or "").strip().lower()

        if c == "status":
            return chatgpt_bridge_status_v2bridgea()
        if c == "score":
            return chatgpt_bridge_score_board_v2bridgea()
        if c == "packet":
            return chatgpt_bridge_packet_v2bridgea()
        if c == "outbox":
            return chatgpt_bridge_outbox_latest_v2bridgea()

        return "# ChatGPT Bridge Error V2BRIDGE-A Repair 1\n\nUnknown bridge command:\n" + str(command)

    except Exception as e:
        return "\n".join([
            "# ChatGPT Bridge Safe Error V2BRIDGE-A Repair 1",
            "",
            "Bridge command failed safely instead of crashing Engel.",
            "",
            "Command:",
            str(command),
            "",
            "Error:",
            str(e),
            "",
            "Safety:",
            "- No API call.",
            "- No browser control.",
            "- No login.",
            "- No sending.",
            "- No deleting.",
            "- No cloud fallback.",
        ])


