# ----------------------------------------------------------------------
# V2NIGHT-A Morning Research Review / Duplicate Proposal Guard
# Report-only. No learning apply. No LEARNING_LOG edits. No deletion.
# ----------------------------------------------------------------------
def _morning_review_report_path_v2night_a():
    import os
    folder = os.path.join(REPORTS_DIR, "morning")
    os.makedirs(folder, exist_ok=True)
    return os.path.join(folder, "MORNING_RESEARCH_REVIEW_V2NIGHT_A.md")

def _morning_tail_text_v2night_a(path, limit=8000):
    import os
    try:
        if not os.path.exists(path):
            return "[missing] " + str(path)
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            data = f.read()
        return data[-limit:] if len(data) > limit else data
    except Exception as e:
        return "[read failed] " + str(path) + " | " + str(e)

def _morning_norm_v2night_a(text):
    import re
    return re.sub(r"[^a-z0-9]+", " ", str(text or "").lower()).strip()

def _morning_extract_proposals_v2night_a(review_text):
    import re
    blocks = re.split(r"\n### Proposal\s+", "\n" + str(review_text or ""))
    out = []
    for block in blocks[1:]:
        lines = block.splitlines()
        pid = lines[0].strip() if lines else "UNKNOWN"
        ptype = ""
        old_status = ""
        proposed = ""

        m_type = re.search(r"- Type:\s*(.+)", block)
        if m_type:
            ptype = m_type.group(1).strip()

        m_status = re.search(r"- Status:\s*(.+)", block)
        if m_status:
            old_status = m_status.group(1).strip()

        m_prop = re.search(r"- Proposed (lesson|action):\s*(.+)", block)
        if m_prop:
            proposed = m_prop.group(2).strip()

        if proposed:
            out.append({
                "id": pid,
                "type": ptype,
                "old_status": old_status,
                "proposed": proposed,
                "norm": _morning_norm_v2night_a(proposed),
            })
    return out

def morning_research_review_v2night_a():
    import difflib

    report_path = _morning_review_report_path_v2night_a()
    learning_text = _morning_tail_text_v2night_a(LEARNING_LOG, 200000)
    learning_norm = _morning_norm_v2night_a(learning_text)

    try:
        proposal_review = learning_proposals_review()
    except Exception as e:
        proposal_review = "learning proposals review failed: " + str(e)

    proposals = _morning_extract_proposals_v2night_a(proposal_review)

    rows = []
    already = 0
    candidates = 0
    review_needed = 0

    chunks = [c.strip() for c in learning_norm.split("  ") if len(c.strip()) > 30]

    for p in proposals:
        status = "REVIEW_NEEDED"
        reason = "No exact match found in LEARNING_LOG.md."

        if p["norm"] and p["norm"] in learning_norm:
            status = "ALREADY_APPLIED"
            reason = "Proposed lesson/action text already appears in LEARNING_LOG.md."
            already += 1
        elif p["norm"]:
            best = 0.0
            for c in chunks[-250:]:
                best = max(best, difflib.SequenceMatcher(None, p["norm"], c).ratio())
            if best >= 0.88:
                status = "DUPLICATE_CANDIDATE"
                reason = "Very similar wording appears in LEARNING_LOG.md. Review before applying."
                candidates += 1
            else:
                review_needed += 1
        else:
            review_needed += 1

        rows.append((p["id"], p["type"], p["old_status"], status, reason, p["proposed"]))

    try:
        research_summary = research_status()
    except Exception as e:
        research_summary = "research status failed: " + str(e)

    try:
        rotation_summary = overnight_topic_rotation_status()
    except Exception as e:
        rotation_summary = "overnight topic rotation status failed: " + str(e)

    try:
        bridge_summary = chatgpt_bridge_safe_v2bridgea("outbox")
    except Exception as e:
        bridge_summary = "bridge outbox latest failed: " + str(e)

    lines = [
        "# Morning Research Review V2NIGHT-A",
        "",
        "Time: " + now(),
        "",
        "Report path:",
        report_path,
        "",
        "Mode: REPORT ONLY",
        "",
        "## Summary",
        "- Proposals found: " + str(len(proposals)),
        "- ALREADY_APPLIED: " + str(already),
        "- DUPLICATE_CANDIDATE: " + str(candidates),
        "- REVIEW_NEEDED: " + str(review_needed),
        "",
        "## Duplicate Proposal Guard",
        "",
        "| Proposal | Type | Original Status | Morning Status | Reason | Proposed Text |",
        "|---|---|---|---|---|---|",
    ]

    if rows:
        for pid, ptype, old_status, status, reason, proposed in rows:
            safe_text = str(proposed).replace("|", "/")
            if len(safe_text) > 180:
                safe_text = safe_text[:177] + "..."
            lines.append("| " + pid + " | " + ptype + " | " + old_status + " | " + status + " | " + reason + " | " + safe_text + " |")
    else:
        lines.append("| none | none | none | none | No proposals parsed from learning proposals review. | none |")

    lines += [
        "",
        "## Research Status Snapshot",
        "```text",
        research_summary[-6000:],
        "```",
        "",
        "## Topic Rotation Snapshot",
        "```text",
        rotation_summary[-6000:],
        "```",
        "",
        "## Bridge Outbox Snapshot",
        "```text",
        bridge_summary[-6000:],
        "```",
        "",
        "## Safety",
        "- Report/check only.",
        "- LEARNING_LOG.md read only.",
        "- No learning applied.",
        "- No source files edited by this command.",
        "- No deletion or cleanup applied.",
        "- No browsing/search/API/cloud.",
        "- No clicking/sending/login.",
        "- Duplicates are marked only in this report.",
    ]

    text = "\n".join(lines)
    with open(report_path, "w", encoding="utf-8") as f:
        f.write(text)

    append_log("Morning Research Review V2NIGHT-A report created: " + report_path)

    return "\n".join([
        "# Morning Research Review V2NIGHT-A",
        "",
        "Report created:",
        report_path,
        "",
        "Summary:",
        "- Proposals found: " + str(len(proposals)),
        "- ALREADY_APPLIED: " + str(already),
        "- DUPLICATE_CANDIDATE: " + str(candidates),
        "- REVIEW_NEEDED: " + str(review_needed),
        "",
        "Safety:",
        "- Report only.",
        "- LEARNING_LOG.md not edited.",
        "- No learning applied.",
        "- No deletion/cleanup.",
        "- No browsing/API/cloud.",
    ])

