def _source_dir():
    path = os.path.join(REPORTS_DIR, "research", "sources")
    os.makedirs(path, exist_ok=True)
    return path

def _safe_source_filename(url):
    import urllib.parse

    parsed = urllib.parse.urlparse(url)
    base = (parsed.netloc + "_" + parsed.path).strip("_")
    safe = "".join(c if c.isalnum() or c in ["-", "_"] else "_" for c in base)
    safe = "_".join(safe.split("_"))
    if not safe:
        safe = "source"
    return safe[:90]

def _clean_html_to_text(html_text):
    import re
    import html as html_lib

    text = re.sub(r"(?is)<script.*?>.*?</script>", " ", html_text)
    text = re.sub(r"(?is)<style.*?>.*?</style>", " ", text)
    text = re.sub(r"(?is)<noscript.*?>.*?</noscript>", " ", text)
    text = re.sub(r"(?is)<header.*?>.*?</header>", " ", text)
    text = re.sub(r"(?is)<footer.*?>.*?</footer>", " ", text)
    text = re.sub(r"(?is)<nav.*?>.*?</nav>", " ", text)
    text = re.sub(r"(?is)<[^>]+>", " ", text)
    text = html_lib.unescape(text)
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r"\n\s*\n+", "\n\n", text)
    text = "\n".join(line.strip() for line in text.splitlines() if line.strip())
    return text.strip()

def _extract_title(html_text):
    import re
    import html as html_lib

    m = re.search(r"(?is)<title[^>]*>(.*?)</title>", html_text)
    if not m:
        return "[no title found]"

    title = re.sub(r"\s+", " ", m.group(1)).strip()
    return html_lib.unescape(title) if title else "[no title found]"

def source_fetch(url):
    import ipaddress
    import urllib.parse

    url = str(url).strip()

    if not url:
        return "Source fetch failed: no URL provided."

    parsed = urllib.parse.urlparse(url)
    host = str(parsed.hostname or "").strip().lower()

    if parsed.scheme not in ["http", "https"]:
        return "\n".join([
            "# Source Fetch Blocked",
            "",
            "Only http:// and https:// URLs are allowed.",
            "",
            "Blocked URL:",
            url,
        ])
    if not host:
        return "# Source Fetch Blocked\n\nURL host is missing."
    blocked_hosts = {
        "localhost",
        "127.0.0.1",
        "::1",
        "0.0.0.0",
        "metadata.google.internal",
        "169.254.169.254",
    }
    if host in blocked_hosts or host.endswith(".local"):
        return "# Source Fetch Blocked\n\nHost is blocked by Guardian network safety policy."
    try:
        ip = ipaddress.ip_address(host)
        if ip.is_loopback or ip.is_private or ip.is_link_local or ip.is_reserved or ip.is_multicast or ip.is_unspecified:
            return "# Source Fetch Blocked\n\nPrivate/internal IP targets are blocked by Guardian network safety policy."
    except ValueError:
        pass

    try:
        headers = {
            "User-Agent": "EngelStandaloneSourceReader/1.0"
        }

        r = requests.get(url, headers=headers, timeout=20)
        r.raise_for_status()

        content_type = r.headers.get("content-type", "")
        raw = r.text

        title = _extract_title(raw)
        clean_text = _clean_html_to_text(raw)

        if len(clean_text) > 30000:
            clean_text = clean_text[:30000] + "\n\n[TRUNCATED TO 30000 CHARACTERS]"

        stamp = now().replace(":", "-").replace(" ", "_")
        filename = "source_" + _safe_source_filename(url) + "_" + stamp + ".md"
        path = os.path.join(_source_dir(), filename)

        report = "\n".join([
            "# Saved Web Source",
            "",
            "Time: " + now(),
            "URL: " + url,
            "Title: " + title,
            "Content-Type: " + content_type,
            "",
            "## Extracted Text",
            "",
            clean_text if clean_text else "[no readable text extracted]",
            "",
            "## Safety",
            "- Fetched URL text only.",
            "- No clicking.",
            "- No login.",
            "- No form submission.",
            "- No code execution.",
        ])

        write_file(path, report)
        append_file(
            os.path.join(MEMORY_DIR, "RESEARCH_NOTES.md"),
            "\n\n## "
            + now()
            + "\nSource fetched:\n"
            + _guardian_redact_for_log_text(url)
            + "\nSaved:\n"
            + path
            + "\n",
        )
        append_log("Source fetched and saved: " + path)

        return "\n".join([
            "# Source Fetched",
            "",
            "URL:",
            url,
            "",
            "Title:",
            title,
            "",
            "Saved to:",
            path,
            "",
            "Safety: Source text fetched only. No clicking, login, submission, or code execution.",
        ])

    except Exception as e:
        return "Source fetch failed:\n" + str(e)

def _source_files():
    folder = _source_dir()
    files = [
        os.path.join(folder, f)
        for f in os.listdir(folder)
        if f.lower().endswith(".md")
    ]
    return sorted(files, key=os.path.getmtime, reverse=True)

