def _source_quality_label_from_text(text):
    extracted = text
    if "## Extracted Text" in extracted:
        extracted = extracted.split("## Extracted Text", 1)[1]
    if "## Safety" in extracted:
        extracted = extracted.split("## Safety", 1)[0]
    extracted = extracted.strip()

    extracted_low = extracted.lower()

    hard_block_signals = [
        "something went wrong",
        "access denied",
        "captcha",
        "cloudflare",
        "enable javascript",
        "403 forbidden",
        "401 unauthorized",
        "unauthorized access",
        "service unavailable",
        "blocked by",
        "please enable cookies",
        "security check",
        "checking if the site connection is secure",
    ]

    positive_source_signals = [
        "nist",
        "owasp",
        "framework",
        "risk management",
        "artificial intelligence",
        "security",
        "privacy",
        "large language model",
        "generative ai",
        "responsible ai",
        "trustworthy",
        "guidance",
        "standard",
        "project",
        "documentation",
    ]

    if not extracted or extracted == "[no readable text extracted]":
        return "BLOCKED / ERROR PAGE"

    has_hard_block = any(signal in extracted_low for signal in hard_block_signals)
    positive_hits = sum(1 for signal in positive_source_signals if signal in extracted_low)

    if has_hard_block and len(extracted) < 1500:
        return "BLOCKED / ERROR PAGE"

    if len(extracted) >= 1500 and positive_hits >= 2:
        return "GOOD SOURCE"

    if has_hard_block:
        return "BLOCKED / ERROR PAGE"

    if len(extracted) < 500:
        return "WEAK SOURCE"

    return "GOOD SOURCE"


