def source_quality_latest():
    files = _source_files()

    if not files:
        return "Source quality failed: no saved sources found. Use source fetch [url] first."

    latest = files[0]
    text = read_file(latest)

    extracted = text
    if "## Extracted Text" in extracted:
        extracted = extracted.split("## Extracted Text", 1)[1]
    if "## Safety" in extracted:
        extracted = extracted.split("## Safety", 1)[0]
    extracted = extracted.strip()

    extracted_low = extracted.lower()
    quality = _source_quality_label_from_text(text)

    hard_block_signals = [
        "something went wrong",
        "access denied",
        "captcha",
        "cloudflare",
        "enable javascript",
        "403 forbidden",
        "401 unauthorized",
        "unauthorized access",
        "service unavailable",
        "blocked by",
        "please enable cookies",
        "security check",
        "checking if the site connection is secure",
    ]

    positive_source_signals = [
        "nist",
        "owasp",
        "framework",
        "risk management",
        "artificial intelligence",
        "security",
        "privacy",
        "large language model",
        "generative ai",
        "responsible ai",
        "trustworthy",
        "guidance",
        "standard",
        "project",
        "documentation",
    ]

    hard_hits = [s for s in hard_block_signals if s in extracted_low]
    positive_hits = [s for s in positive_source_signals if s in extracted_low]

    reasons = []
    next_steps = []

    if quality == "GOOD SOURCE":
        reasons.append("Readable source text was extracted.")
        reasons.append("Positive source signals found: " + str(len(positive_hits)))
        if hard_hits:
            reasons.append("Hard-block words were detected, but positive-content override passed because readable content is long and source-like.")
        next_steps.append("Run research brief latest.")
        next_steps.append("Fetch at least one more source to verify important claims.")
    elif quality == "WEAK SOURCE":
        reasons.append("The extracted source text is short and may not contain enough useful information.")
        next_steps.append("Use this only as a clue, not a reliable source.")
        next_steps.append("Fetch another source with more complete text.")
    else:
        reasons.append("The saved source appears to contain a hard error, access block, CAPTCHA, JavaScript requirement, or no readable text.")
        if hard_hits:
            reasons.append("Hard block signals found: " + ", ".join(hard_hits[:6]))
        next_steps.append("Do not treat this as useful research content.")
        next_steps.append("Fetch another public source, official documentation, article, or PDF.")

    preview = extracted[:800] if extracted else "[empty]"
    if len(extracted) > 800:
        preview += "\n...[truncated]"

    lines = [
        "# Source Quality Review",
        "",
        "Source file:",
        latest,
        "",
        "Quality:",
        quality,
        "",
        "Diagnostics:",
        "- Extracted text length: " + str(len(extracted)),
        "- Positive signal count: " + str(len(positive_hits)),
        "- Hard block signal count: " + str(len(hard_hits)),
        "",
        "Reasons:",
    ]

    for reason in reasons:
        lines.append("- " + reason)

    lines += [
        "",
        "Preview:",
        preview,
        "",
        "Recommended next steps:",
    ]

    for step in next_steps:
        lines.append("- " + step)

    lines += [
        "",
        "Safety:",
        "- Quality review only.",
        "- No browsing.",
        "- No clicking.",
        "- No form submission.",
        "- No sending.",
    ]

    report = "\n".join(lines)
    report_file = os.path.join(REPORTS_DIR, "research", "SOURCE_QUALITY_LATEST.md")
    write_file(report_file, report)
    append_log("Source quality V3 review completed: " + report_file)

    return report


