def _read_overnight_queue():
    queue_file = os.path.join(REPORTS_DIR, "overnight", "OVERNIGHT_QUEUE.md")

    if not os.path.exists(queue_file):
        return [], []

    text = read_file(queue_file)

    topics = []
    sources = []
    section = None

    for raw in text.splitlines():
        line = raw.strip()
        low = line.lower()

        if not line:
            continue

        if low in ["topics queued:", "## topics", "## topics queued", "topics:"]:
            section = "topics"
            continue

        if low in ["sources queued:", "## sources", "## sources queued", "sources:"]:
            section = "sources"
            continue

        if low.startswith("## ") and "topic" not in low and "source" not in low:
            section = None
            continue

        if line.startswith("- "):
            item = line[2:].strip()
            if not item or item.lower() == "none":
                continue

            if section == "topics":
                topics.append(item)
            elif section == "sources":
                sources.append(item)

    # Dedupe while preserving order
    def dedupe(items):
        out = []
        seen = set()
        for item in items:
            key = item.lower()
            if key not in seen:
                seen.add(key)
                out.append(item)
        return out

    return dedupe(topics), dedupe(sources)


