def _normalize_candidate_url(href):
    import html as html_lib
    import urllib.parse

    if not href:
        return None

    href = html_lib.unescape(str(href).strip())

    if href.startswith("//"):
        href = "https:" + href

    parsed = urllib.parse.urlparse(href)

    # DuckDuckGo redirect links often store the real URL in uddg=
    if "uddg=" in href:
        qs = urllib.parse.parse_qs(parsed.query)
        if "uddg" in qs and qs["uddg"]:
            return qs["uddg"][0]

    # Some DDG links look like /l/?uddg=...
    if href.startswith("/"):
        fake = urllib.parse.urlparse("https://duckduckgo.com" + href)
        qs = urllib.parse.parse_qs(fake.query)
        if "uddg" in qs and qs["uddg"]:
            return qs["uddg"][0]
        return None

    if href.startswith("http://") or href.startswith("https://"):
        return href

    return None

def _candidate_allowed(url):
    import urllib.parse

    try:
        parsed = urllib.parse.urlparse(url)
        domain = parsed.netloc.lower()
    except Exception:
        return False

    if not domain:
        return False

    blocked_domains = [
        "duckduckgo.com",
        "www.duckduckgo.com",
        "lite.duckduckgo.com",
        "html.duckduckgo.com",
        "google.com",
        "www.google.com",
        "bing.com",
        "www.bing.com",
        "x.com",
        "twitter.com",
        "facebook.com",
        "instagram.com",
        "youtube.com",
        "www.youtube.com",
        "accounts.google.com",
    ]

    for d in blocked_domains:
        if domain == d or domain.endswith("." + d):
            return False

    bad_extensions = [".jpg", ".jpeg", ".png", ".gif", ".webp", ".svg", ".css", ".js", ".ico"]
    path_low = parsed.path.lower()
    if any(path_low.endswith(ext) for ext in bad_extensions):
        return False

    return True

def _extract_duckduckgo_urls(html_text):
    import re

    urls = []
    seen = set()

    # Broad href extraction works across DuckDuckGo html/lite variants.
    hrefs = re.findall(r"href=[\"\']([^\"\']+)[\"\']", html_text, flags=re.I)

    for href in hrefs:
        candidate = _normalize_candidate_url(href)

        if not candidate:
            continue

        if not _candidate_allowed(candidate):
            continue

        if candidate not in seen:
            seen.add(candidate)
            urls.append(candidate)

        if len(urls) >= 12:
            break

    return urls



