# ----------------------------------------------------------------------
# External Code Ideas Proposal V2P
# Reads V2O quarantine report and creates proposal-only improvement list.
# No code execution. No dependency install. No source copying.
# ----------------------------------------------------------------------
def external_code_ideas_proposal_v2p():
    import os
    import re

    latest = os.path.join(REPORTS_DIR, "external_code", "EXTERNAL_CODE_INTAKE_LATEST.md")
    out_dir = os.path.join(REPORTS_DIR, "external_code")
    out = os.path.join(out_dir, "EXTERNAL_CODE_IDEAS_PROPOSAL.md")

    if not os.path.exists(latest):
        return "# External Code Ideas Proposal V2P\n\nNo intake report found yet.\n\nRun:\nexternal code intake <path-to-zip>"

    text = read_file(latest)

    useful = []
    in_useful = False
    for line in text.splitlines():
        stripped = line.strip()
        if stripped.lower().startswith("useful idea hints"):
            in_useful = True
            continue
        if stripped.lower().startswith("risk pattern matches"):
            in_useful = False
        if in_useful and stripped.startswith("- "):
            useful.append(stripped[2:].strip())

    risk_counts = {}
    for line in text.splitlines():
        m = re.match(r"^-\s*([a-zA-Z0-9_]+)\s*\|", line.strip())
        if m:
            k = m.group(1)
            risk_counts[k] = risk_counts.get(k, 0) + 1

    safe_now = [
        "Permission result system: allow / ask / deny.",
        "Tool registry labels: read_only / write / destructive / network / approval_required.",
        "Read-before-write guard for all file edits.",
        "Diff-before-apply reports for proposed source edits.",
        "Workspace-root path guard for tool/file operations.",
    ]

    careful = [
        "SKILL.md-style local skill folders, but only with allowed-tools metadata and no auto-execution.",
        "Context compaction for long Engel chats, but preserve safety gates and recent user intent.",
        "Session history summaries, stored locally, with privacy-safe limits.",
        "Web fetch guard ideas, but only inside Engel source-quality gate and public-source rules.",
    ]

    reject = [
        "Do not copy bash/shell execution tools directly.",
        "Do not copy cron/scheduler automation directly.",
        "Do not copy external provider/cloud API integrations directly.",
        "Do not store API keys or use base64 as security.",
        "Do not copy remote/SSH/runtime concepts into Engel.",
        "Do not merge quarantined source code directly.",
    ]

    lines = [
        "# External Code Ideas Proposal V2P",
        "",
        "Time: " + now(),
        "",
        "Source intake report:",
        latest,
        "",
        "Purpose:",
        "- Convert external code intake results into proposal-only Engel improvements.",
        "- No code copied.",
        "- No code executed.",
        "- No dependency install.",
        "- No cloud fallback.",
        "",
        "## Intake Summary",
        "- Useful idea hints detected: " + str(len(useful)),
        "- Risk categories detected: " + str(len(risk_counts)),
        "",
        "Risk category counts:",
    ]

    if risk_counts:
        for k in sorted(risk_counts):
            lines.append("- " + k + ": " + str(risk_counts[k]))
    else:
        lines.append("- none")

    lines += ["", "## Safe to Implement Soon"]
    for item in safe_now:
        lines.append("- " + item)

    lines += ["", "## Needs Careful Design / Approval"]
    for item in careful:
        lines.append("- " + item)

    lines += ["", "## Reject / Do Not Copy"]
    for item in reject:
        lines.append("- " + item)

    lines += ["", "## Useful Hints From Intake Report"]
    if useful:
        for item in useful[:40]:
            lines.append("- " + item)
    else:
        lines.append("- none")

    lines += [
        "",
        "## Recommended Next Patch",
        "V2Q Permission Result System",
        "",
        "Goal:",
        "- Add a common PermissionResult shape for Engel tools:",
        "  - ALLOW",
        "  - ASK",
        "  - DENY",
        "- Every risky tool should return one of these before acting.",
        "- Keep all existing approval gates.",
        "- No autonomous actions.",
        "",
        "Safety:",
        "- Proposal/report only.",
        "- No code copied from quarantine.",
        "- No execution.",
        "- No dependency install.",
        "- No source-quality gate changes.",
    ]

    report = "\n".join(lines)
    write_file(out, report)

    try:
        append_file(
            os.path.join(MEMORY_DIR, "PROJECT_HISTORY.md"),
            "\n\n## " + now() + " - External code ideas proposal generated\n"
            + "Report: " + out + "\n"
            + "Recommended next patch: V2Q Permission Result System.\n"
        )
    except Exception:
        pass

    append_log("External Code Ideas Proposal V2P created: " + out)
    return report


def external_code_intake_v2o(zip_path):
    import os
    import re
    import zipfile
    import hashlib

    raw = str(zip_path or "").strip().strip('"')
    if not raw:
        return "# External Code Intake Guard V2O\n\nUsage:\nexternal code intake <path-to-zip>"

    if raw.startswith("\\\\"):
        return "# External Code Intake Blocked\n\nUNC/network paths are blocked for external code intake."

    src = norm_path(raw if os.path.isabs(raw) else os.path.join(ROOT, raw))

    if not os.path.exists(src):
        return "# External Code Intake Failed\n\nZip file not found:\n" + src

    if not src.lower().endswith(".zip"):
        return "# External Code Intake Blocked\n\nOnly .zip files are accepted."

    quarantine_root = norm_path(os.path.join(ROOT, "workspace", "quarantine", "external_code"))
    reports_dir = norm_path(os.path.join(REPORTS_DIR, "external_code"))
    os.makedirs(quarantine_root, exist_ok=True)
    os.makedirs(reports_dir, exist_ok=True)

    safe_name = re.sub(r"[^A-Za-z0-9._-]+", "_", os.path.basename(src))[:80]
    dest = norm_path(os.path.join(quarantine_root, now().replace(":", "-").replace(" ", "_") + "_" + safe_name))

    if not is_inside(dest, quarantine_root):
        return "# External Code Intake Blocked\n\nQuarantine path failed safety check."

    os.makedirs(dest, exist_ok=True)

    patterns = [
        ("shell_exec", r"\b(subprocess\.|os\.system|Popen\(|shell=True|bash|powershell|cmd\.exe|taskkill)"),
        ("network", r"\b(requests\.|httpx\.|urllib\.|aiohttp|socket\.|websocket|curl|wget)"),
        ("secrets", r"(API_KEY|OPENAI|ANTHROPIC|password|secret|token|base64|dotenv|\.env)"),
        ("file_write_delete", r"\b(write_text|unlink\(|remove\(|rmtree|shutil\.move|chmod|chown)"),
        ("eval_exec", r"\b(eval\(|exec\(|compile\()"),
        ("remote_scheduler", r"\b(ssh|paramiko|scp|sftp|docker|cron|schedule|apscheduler)")
    ]

    text_exts = {".py", ".md", ".txt", ".json", ".toml", ".yml", ".yaml", ".js", ".ts", ".html", ".css", ".ps1", ".bat", ".sh"}

    max_files = 2500
    max_total = 150 * 1024 * 1024
    max_scan_file = 2 * 1024 * 1024

    extracted = 0
    skipped = []
    matches = []
    useful = []

    try:
        with zipfile.ZipFile(src) as z:
            infos = z.infolist()
            total_size = sum(int(i.file_size or 0) for i in infos)

            if len(infos) > max_files:
                return "# External Code Intake Blocked\n\nZip has too many files: " + str(len(infos))

            if total_size > max_total:
                return "# External Code Intake Blocked\n\nZip uncompressed size too large: " + str(total_size) + " bytes"

            for info in infos:
                name = info.filename.replace("\\", "/")

                if not name or name.endswith("/"):
                    continue

                if name.startswith("/") or ".." in name.split("/"):
                    skipped.append(name + " :: blocked path traversal")
                    continue

                target = norm_path(os.path.join(dest, name))
                if not is_inside(target, dest):
                    skipped.append(name + " :: blocked outside quarantine")
                    continue

                os.makedirs(os.path.dirname(target), exist_ok=True)

                data = z.read(info)
                with open(target, "wb") as f:
                    f.write(data)

                extracted += 1

                ext = os.path.splitext(name)[1].lower()
                if ext not in text_exts or len(data) > max_scan_file:
                    continue

                text = data.decode("utf-8", errors="replace")
                low_name = name.lower()

                if "skill.md" in low_name:
                    useful.append("SKILL.md style skill definition found: " + name)
                if "permission" in low_name or "guard" in low_name:
                    useful.append("Permission/guard related file found: " + name)
                if "diff" in low_name:
                    useful.append("Diff/edit review related file found: " + name)
                if "session" in low_name or "context" in low_name:
                    useful.append("Session/context idea found: " + name)

                lines = text.splitlines()
                for label, pat in patterns:
                    for i, line in enumerate(lines, start=1):
                        if re.search(pat, line, flags=re.I):
                            matches.append((label, name, i, line.strip()[:220]))
                            if len(matches) >= 200:
                                break
                    if len(matches) >= 200:
                        break

    except zipfile.BadZipFile:
        return "# External Code Intake Failed\n\nBad zip file:\n" + src
    except Exception as e:
        return "# External Code Intake Failed\n\nDetail:\n" + str(e)

    digest = ""
    try:
        h = hashlib.sha256()
        with open(src, "rb") as f:
            for chunk in iter(lambda: f.read(1024 * 1024), b""):
                h.update(chunk)
        digest = h.hexdigest()
    except Exception:
        digest = "unavailable"

    report_path = os.path.join(reports_dir, "external_code_intake_" + now().replace(":", "-").replace(" ", "_") + ".md")
    latest_path = os.path.join(reports_dir, "EXTERNAL_CODE_INTAKE_LATEST.md")

    lines = [
        "# External Code Intake Guard V2O",
        "",
        "Time: " + now(),
        "",
        "Source zip:",
        src,
        "",
        "SHA256:",
        digest,
        "",
        "Quarantine folder:",
        dest,
        "",
        "Result:",
        "- Extracted files: " + str(extracted),
        "- Skipped unsafe entries: " + str(len(skipped)),
        "- Risk pattern matches: " + str(len(matches)),
        "- Useful idea hints: " + str(len(useful)),
        "",
        "Decision:",
        "- Safe to borrow ideas: REVIEW REQUIRED",
        "- Safe to run directly: NO",
        "- Safe to merge directly: NO",
        "",
        "Useful idea hints:",
    ]

    if useful:
        for item in useful[:40]:
            lines.append("- " + item)
    else:
        lines.append("- none detected")

    lines += ["", "Risk pattern matches:"]
    if matches:
        for label, name, lineno, snippet in matches[:80]:
            lines.append("- " + label + " | " + name + ":" + str(lineno) + " | " + snippet)
    else:
        lines.append("- none detected")

    lines += ["", "Skipped entries:"]
    if skipped:
        for item in skipped[:40]:
            lines.append("- " + item)
    else:
        lines.append("- none")

    lines += [
        "",
        "Safety:",
        "- Quarantine-only.",
        "- No code executed.",
        "- No dependencies installed.",
        "- No files copied into Engel source.",
        "- No browsing.",
        "- No clicking/login/sending/deleting.",
        "- Approval required before any idea is patched into Engel.",
    ]

    report = "\n".join(lines)
    write_file(report_path, report)
    write_file(latest_path, report)

    try:
        append_file(
            os.path.join(MEMORY_DIR, "PROJECT_HISTORY.md"),
            "\n\n## " + now() + " - External code intake completed\n"
            + "Zip: " + src + "\n"
            + "Report: " + report_path + "\n"
            + "Quarantine: " + dest + "\n"
            + "Rule: external code is quarantine-only until approved.\n"
        )
    except Exception:
        pass

    append_log("External Code Intake Guard V2O completed: " + report_path)

    return report


