# ----------------------------------------------------------------------
# Research Thinking Controls V1C-SAFE
# Optional controls only. No auto-open on Research ON.
# ----------------------------------------------------------------------
def _thinking_controls_root():
    return globals().get("ROOT", ROOT)

def _thinking_controls_memory_dir():
    import os
    return globals().get("MEMORY_DIR", os.path.join(_thinking_controls_root(), "memory"))

def _thinking_pid_file():
    import os
    return os.path.join(_thinking_controls_memory_dir(), "engel_research_thinking_screen.pid")

def _thinking_pid_alive(pid):
    try:
        import ctypes
        if not pid:
            return False
        PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
        STILL_ACTIVE = 259
        handle = ctypes.windll.kernel32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, False, int(pid))
        if not handle:
            return False
        exit_code = ctypes.c_ulong()
        ok = ctypes.windll.kernel32.GetExitCodeProcess(handle, ctypes.byref(exit_code))
        ctypes.windll.kernel32.CloseHandle(handle)
        return bool(ok) and exit_code.value == STILL_ACTIVE
    except Exception:
        return False

def _thinking_read_pid():
    try:
        import os
        path = _thinking_pid_file()
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8", errors="replace") as f:
                txt = f.read().strip()
            if txt.isdigit():
                return int(txt)
    except Exception:
        pass
    return None

def _thinking_write_pid(pid):
    try:
        import os
        path = _thinking_pid_file()
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            f.write(str(pid))
    except Exception:
        pass

def _thinking_clear_pid():
    try:
        import os
        path = _thinking_pid_file()
        if os.path.exists(path):
            os.remove(path)
    except Exception:
        pass

def research_thinking_screen_safe():
    import os
    import sys
    import subprocess

    pid = _thinking_read_pid()
    if _thinking_pid_alive(pid):
        return "\n".join([
            "# Research Thinking Screen",
            "",
            "Already open.",
            "",
            "Tracked PID: " + str(pid),
            "",
            "Commands:",
            "- research thinking status",
            "- research thinking off",
        ])

    root = _thinking_controls_root()
    script = os.path.join(root, "engel_research_thinking_screen.py")
    if not os.path.exists(script):
        return "# Research Thinking Screen\n\nMissing script:\n" + script

    pyw = os.path.join(root, ".venv", "Scripts", "pythonw.exe")
    py = os.path.join(root, ".venv", "Scripts", "python.exe")
    exe = pyw if os.path.exists(pyw) else py if os.path.exists(py) else sys.executable

    flags = 0
    try:
        flags = subprocess.CREATE_NO_WINDOW
    except Exception:
        flags = 0

    proc = subprocess.Popen([exe, script], cwd=root, creationflags=flags)
    _thinking_write_pid(proc.pid)

    return "\n".join([
        "# Research Thinking Screen",
        "",
        "Opened Engel Research Thinking screen.",
        "",
        "Tracked PID: " + str(proc.pid),
        "",
        "Safety:",
        "- Optional local screen only.",
        "- No browsing.",
        "- No clicking.",
        "- No sending.",
        "- No API use.",
    ])

def research_thinking_status():
    import os

    pid = _thinking_read_pid()
    alive = _thinking_pid_alive(pid)

    root = _thinking_controls_root()
    live_file = os.path.join(root, "reports", "research", "RESEARCH_LIVE_STATUS.md")
    live = ""
    try:
        if os.path.exists(live_file):
            with open(live_file, "r", encoding="utf-8", errors="replace") as f:
                live = f.read().strip()
    except Exception:
        live = ""

    return "\n".join([
        "# Research Thinking Screen Status",
        "",
        "PID file:",
        _thinking_pid_file(),
        "",
        "Tracked PID:",
        str(pid or "none"),
        "",
        "Screen running:",
        str(alive),
        "",
        "## Live Status",
        live if live else "No live status file yet.",
        "",
        "Safety:",
        "- Status only.",
        "- No browsing.",
        "- No sending.",
        "- No API use.",
    ])

def research_thinking_off():
    import os
    import signal
    import time

    pid = _thinking_read_pid()
    if not pid or not _thinking_pid_alive(pid):
        _thinking_clear_pid()
        return "# Research Thinking Screen OFF\n\nNo tracked thinking screen was active."

    stopped = False
    try:
        os.kill(pid, signal.SIGTERM)
        stopped = True
    except Exception:
        try:
            os.kill(pid, 9)
            stopped = True
        except Exception:
            stopped = False

    time.sleep(0.3)
    _thinking_clear_pid()

    return "\n".join([
        "# Research Thinking Screen OFF",
        "",
        "Stopped tracked thinking screen: " + str(stopped),
        "PID: " + str(pid),
    ])


