# --- Remote Worker LAN Background Auto-Run ---

def _lan_server_thread_target(host, port):
    """Background daemon thread: starts HTTPServer, stores instance for shutdown."""
    global _LAN_SERVER_INSTANCE
    try:
        import engel_remote_worker_lan_pairing as _lan
        from http.server import HTTPServer
        _lan.ensure_scaffold()
        server = HTTPServer((host, port), _lan.PairingRequestHandler)
        with _LAN_SERVER_LOCK:
            _LAN_SERVER_INSTANCE = server
        _lan.start_udp_broadcaster(port)
        server.serve_forever()
        server.server_close()
    except Exception:
        pass
    finally:
        with _LAN_SERVER_LOCK:
            _LAN_SERVER_INSTANCE = None


def remote_worker_lan_autorun_start(approval_text=""):
    global _LAN_SERVER_THREAD, _LAN_SERVER_INSTANCE
    approval = str(approval_text or "").strip()
    if approval != "APPROVE":
        return "\n".join([
            "# Remote Worker LAN Auto-Run — Start",
            "",
            "This action requires explicit approval.",
            "Command: remote worker lan autorun start APPROVE",
            "",
            "What this does (all in background, no manual terminal needed):",
            "  1. Starts the LAN pairing HTTP server in a daemon thread (port 8765, LAN-accessible)",
            "  2. Generates a pairing token for your Android device",
            "  3. Enables auto-worker so the Android device receives assignments when it polls",
            "",
            "Safety boundaries:",
            "  - Server runs LAN-only; no internet route",
            "  - phone_does_not_control_engel: true",
            "  - auto_apply: false  |  trusted_memory_write: false",
            "  - All worker results remain untrusted until Engel verification + human approval",
            "  - Server stops when Engel app stops (daemon thread)",
            "",
            "To stop: remote worker lan autorun stop",
        ])
    try:
        import engel_remote_worker_lan_pairing as _lan
        import json
        # Check if already running
        with _LAN_SERVER_LOCK:
            if _LAN_SERVER_THREAD is not None and _LAN_SERVER_THREAD.is_alive():
                return "\n".join([
                    "# Remote Worker LAN Auto-Run",
                    "",
                    "Status: ALREADY_RUNNING",
                    "",
                    "Server is already running in the background.",
                    "Use: remote worker lan autorun status  — to check details",
                    "Use: remote worker lan autorun stop    — to stop it",
                ])
        host = "0.0.0.0"
        port = _lan.DEFAULT_PORT
        # Step 1: start background server thread
        import engel_remote_worker_lan_pairing as _lan_reg
        _lan_reg.register_chat_callback(local_communication_response_for_unrouted_text_v2comm_sanity)
        t = _threading.Thread(
            target=_lan_server_thread_target,
            args=(host, port),
            daemon=True,
            name="engel-lan-server",
        )
        with _LAN_SERVER_LOCK:
            _LAN_SERVER_THREAD = t
        t.start()
        # Step 2: generate pairing token
        token_json = _lan.render_token()
        token_data = json.loads(token_json)
        pairing_code = token_data.get("pairing_code", "—")
        expires_at = token_data.get("expires_at_utc", "—")
        # Step 3: enable auto-worker
        _lan.LINK_MANAGER_ROOT.mkdir(parents=True, exist_ok=True)
        state: dict = {}
        if _lan.LINK_MANAGER_STATE_PATH.exists():
            try:
                loaded = json.loads(_lan.LINK_MANAGER_STATE_PATH.read_text(encoding="utf-8"))
                if isinstance(loaded, dict):
                    state.update(loaded)
            except Exception:
                pass
        state["auto_worker_enabled"] = True
        state["auto_worker_paused"] = False
        state["phone_does_not_control_engel"] = True
        state["auto_apply"] = False
        state["trusted_memory_write"] = False
        _lan.LINK_MANAGER_STATE_PATH.write_text(json.dumps(state, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        return "\n".join([
            "# Remote Worker LAN Auto-Run — Started",
            "",
            "Status: RUNNING",
            "",
            f"  Server address : 0.0.0.0:{port}  (LAN-accessible on your local network)",
            f"  Pairing code   : {pairing_code}",
            f"  Token expires  : {expires_at}",
            "  Auto-worker    : ENABLED",
            "",
            "Next steps:",
            "  1. Enter the pairing code in your Android Engel Remote Worker app",
            "  2. Android will begin polling for assignments automatically",
            "  3. All results return as untrusted — Engel verifies, you approve",
            "",
            "  remote worker lan autorun status — check server thread",
            "  remote worker lan autorun stop   — stop background server",
        ])
    except Exception as exc:
        return "# Remote Worker LAN Auto-Run — Start\n\nError: " + str(exc)


def remote_worker_lan_autorun_stop():
    global _LAN_SERVER_THREAD, _LAN_SERVER_INSTANCE
    try:
        with _LAN_SERVER_LOCK:
            server = _LAN_SERVER_INSTANCE
            thread = _LAN_SERVER_THREAD
        if server is None and (thread is None or not thread.is_alive()):
            return "\n".join([
                "# Remote Worker LAN Auto-Run — Stop",
                "",
                "Status: NOT_RUNNING",
                "",
                "No background LAN server is currently running.",
            ])
        if server is not None:
            server.shutdown()
        return "\n".join([
            "# Remote Worker LAN Auto-Run — Stopped",
            "",
            "Status: STOPPED",
            "",
            "The background LAN server has been shut down.",
            "Android device will no longer receive new assignments.",
            "",
            "Auto-worker flag remains as-is in link manager state.",
            "Use: remote worker link manager disable auto worker — to also disable polling.",
        ])
    except Exception as exc:
        return "# Remote Worker LAN Auto-Run — Stop\n\nError: " + str(exc)


def remote_worker_lan_autorun_status():
    global _LAN_SERVER_THREAD, _LAN_SERVER_INSTANCE
    try:
        import engel_remote_worker_lan_pairing as _lan
        import json
        with _LAN_SERVER_LOCK:
            thread = _LAN_SERVER_THREAD
            server = _LAN_SERVER_INSTANCE
        running = thread is not None and thread.is_alive()
        lm_state = _lan.link_manager_state()
        auto_worker = lm_state.get("auto_worker_enabled", False)
        lines = [
            "# Remote Worker LAN Auto-Run — Status",
            "",
            f"  Server thread  : {'RUNNING' if running else 'STOPPED'}",
            f"  Server bound   : {'0.0.0.0:' + str(_lan.DEFAULT_PORT) if running else 'n/a'}",
            f"  Auto-worker    : {'ENABLED' if auto_worker else 'DISABLED'}",
            "",
        ]
        if running:
            lines += [
                "Commands:",
                "  remote worker lan autorun stop   — stop background server",
                "  remote worker lan pairing token  — generate a fresh pairing code",
            ]
        else:
            lines += [
                "Commands:",
                "  remote worker lan autorun start APPROVE — start server + token + auto-worker",
            ]
        return "\n".join(lines)
    except Exception as exc:
        return "# Remote Worker LAN Auto-Run — Status\n\nError: " + str(exc)


