def research_office_off():
    import os
    import signal
    import time

    pid = _research_office_read_pid()
    if not pid or not _thinking_pid_alive(pid):
        _research_office_clear_pid()
        return "# Engel Colony Hive OFF\n\nNo tracked Colony Hive screen was active."

    stopped = False
    try:
        os.kill(pid, signal.SIGTERM)
        stopped = True
    except Exception:
        try:
            os.kill(pid, 9)
            stopped = True
        except Exception:
            stopped = False

    time.sleep(0.3)
    _research_office_clear_pid()

    return "\n".join([
        "# Engel Colony Hive OFF",
        "",
        "Stopped tracked Colony Hive screen: " + str(stopped),
        "PID: " + str(pid),
        "",
        "Safety:",
        "- Closed only the tracked local Colony Hive screen.",
        "- No research/provider/network/worker/loop behavior changed.",
    ])


def colony_hive_off():
    return research_office_off()


def _super_swarm_hive_3d_pid_file():
    import os
    return os.path.join(_thinking_controls_memory_dir(), "engel_super_swarm_hive_3d.pid")


def _super_swarm_hive_3d_read_pid():
    try:
        import os
        path = _super_swarm_hive_3d_pid_file()
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8", errors="replace") as f:
                txt = f.read().strip()
            if txt.isdigit():
                return int(txt)
    except Exception:
        pass
    return None


def _super_swarm_hive_3d_write_pid(pid):
    try:
        import os
        path = _super_swarm_hive_3d_pid_file()
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            f.write(str(pid))
    except Exception:
        pass


def _super_swarm_hive_3d_clear_pid():
    try:
        import os
        path = _super_swarm_hive_3d_pid_file()
        if os.path.exists(path):
            os.remove(path)
    except Exception:
        pass


