def _super_swarm_hive_3d_exe():
    import os
    return os.path.join(_thinking_controls_root(), "live", "app", "EngelSuperSwarmHive3D.exe")


def _super_swarm_hive_3d_launch_command():
    import os
    import sys

    root = _thinking_controls_root()
    visual_exe = _super_swarm_hive_3d_exe()
    script = _super_swarm_hive_3d_script()
    if os.path.exists(visual_exe):
        return [visual_exe], "packaged visual executable"

    if not os.path.exists(script):
        return None, "missing visual script"

    pyw = os.path.join(root, ".venv", "Scripts", "pythonw.exe")
    py = os.path.join(root, ".venv", "Scripts", "python.exe")
    if os.path.exists(pyw):
        return [pyw, script], "project pythonw source launcher"
    if os.path.exists(py):
        return [py, script], "project python source launcher"
    if not getattr(sys, "frozen", False):
        return [sys.executable, script], "current Python source launcher"
    return None, "packaged visual executable unavailable"


