def _latest_named_file(folder, prefix):
    if not os.path.isdir(folder):
        return None

    files = []
    for name in os.listdir(folder):
        full = os.path.join(folder, name)
        if os.path.isfile(full) and name.startswith(prefix) and name.lower().endswith(".md"):
            files.append(full)

    if not files:
        return None

    return sorted(files, key=os.path.getmtime, reverse=True)[0]

def _latest_learning_entry_text():
    learning_path = os.path.join(MEMORY_DIR, "LEARNING_LOG.md")

    if not os.path.exists(learning_path):
        return "[LEARNING_LOG.md not found]"

    text = read_file(learning_path).strip()

    if not text:
        return "[LEARNING_LOG.md is empty]"

    marker = "\n## "
    idx = text.rfind(marker)

    if idx != -1:
        latest = text[idx + 1:].strip()
    elif text.startswith("## "):
        latest = text.strip()
    else:
        latest = text[-5000:].strip()

    return latest[-8000:]

def research_learning_plan():
    research_root = os.path.join(REPORTS_DIR, "research")

    latest_summary = _latest_named_file(research_root, "research_summary_latest_")
    latest_memory_extract = _latest_named_file(research_root, "research_memory_extract_")
