def _offline_brain_now_v1():
    try:
        return now()
    except Exception:
        import datetime
        return datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")

def _offline_brain_status_path_v1():
    import os
    root = globals().get("ROOT", ROOT)
    reports = globals().get("REPORTS_DIR", os.path.join(root, "reports"))
    return os.path.join(reports, "BRAIN_STATUS.md")

def _offline_brain_is_connection_error_v1(err):
    txt = str(err).lower()
    checks = [
        "connection refused",
        "failed to establish a new connection",
        "max retries exceeded",
        "newconnectionerror",
        "winerror 10061",
        "connection",
    ]
    return any(c in txt for c in checks)

def _offline_brain_write_status_v1(status, detail=""):
    text = "\n".join([
        "# Engel Brain Status",
        "",
        "Time: " + _offline_brain_now_v1(),
        "Brain: " + status,
        "Selected provider: " + (_select_brain_provider_v2provider().get("provider") or "none"),
        "Local model: " + str(globals().get("MODEL", "unknown")),
        "",
        "Detail:",
        str(detail or ""),
        "",
        "Safety:",
        "- Status only.",
        "- No process launching.",
        "- No cloud fallback.",
        "- No sending.",
        "- No deleting.",
    ])
    try:
        write_file(_offline_brain_status_path_v1(), text)
    except Exception:
        pass
    return text

