def _code_workbench_staged_dir_v2code_a():
    p = os.path.join(WORKSPACE_DIR, "staged")
    os.makedirs(p, exist_ok=True)
    return p

def _code_workbench_reports_dir_v2code_a():
    p = os.path.join(REPORTS_DIR, "code_workbench")
    os.makedirs(p, exist_ok=True)
    return p

def _code_workbench_latest_path_v2code_a():
    return os.path.join(_code_workbench_reports_dir_v2code_a(), "V2CODE_A_LATEST.md")

def _code_workbench_write_report_v2code_a(name, report):
    stamp = now().replace(":", "-").replace(" ", "_")
    out = os.path.join(_code_workbench_reports_dir_v2code_a(), name + "_" + stamp + ".md")
    write_file(out, report)
    write_file(_code_workbench_latest_path_v2code_a(), report)
    append_log("Code Workbench report created: " + out)
    return out

def _code_workbench_resolve_v2code_a(path_text):
    raw = str(path_text or "").strip().strip('"')
    if not raw:
        return ""
    if os.path.isabs(raw):
        return norm_path(raw)
    return norm_path(os.path.join(ROOT, raw))

def _code_workbench_is_secret_like_v2code_a(path):
    low = str(path or "").lower()
    name = os.path.basename(low)
    if name == ".env" or name.endswith(".env"):
        return True
    for needle in ["key", "token", "password", "credential", "id_rsa", ".pem"]:
        if needle in low:
            return True
    return False

def _code_workbench_source_allowed_v2code_a(path):
    path = norm_path(path)
    if is_inside(path, ROOT):
        return True
    for approved in load_approved_folders():
        if is_inside(path, approved):
            return True
    return False

def _code_workbench_staged_path_v2code_a(staged_name):
    raw = str(staged_name or "").strip().strip('"')
    if not raw:
        return ""
    staged_dir = _code_workbench_staged_dir_v2code_a()
    if os.path.isabs(raw):
        candidate = norm_path(raw)
    else:
        candidate = norm_path(os.path.join(staged_dir, raw))
    if not is_inside(candidate, staged_dir):
        return ""
    return candidate

def _code_workbench_parse_two_paths_v2code_a(rest):
    text = str(rest or "").strip()
    if not text:
        return "", ""
    try:
        import shlex
        parts = shlex.split(text, posix=False)
    except Exception:
        parts = text.split()
    if len(parts) < 2:
        return "", ""
    staged = parts[-1].strip().strip('"')
    target = " ".join(parts[:-1]).strip().strip('"')
    return target, staged

