def _write_active_provider_early_v2provider(value):
    import json
    path = os.path.join(MEMORY_DIR, "BRAIN_BACKENDS.json")
    data = {}
    try:
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8", errors="replace") as f:
                loaded = json.load(f)
            if isinstance(loaded, dict):
                data = loaded
    except Exception:
        data = {}
    if not data:
        data = {
            "version": "2.0",
            "active_provider": "",
            "policy": {"no_provider_required_for_startup": True},
            "providers": {},
        }
    data["active_provider"] = value
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2)


