def _human_action_result_text(result):
    lines = [
        "# Human Command Result",
        "",
        "Status: " + str(getattr(result, "status", "")),
        "OK: " + ("yes" if bool(getattr(result, "ok", False)) else "no"),
        "Message: " + str(getattr(result, "message", "")),
    ]
    for label, attr in [
        ("Path", "path"),
        ("Source", "source"),
        ("Destination", "destination"),
        ("Package", "package_name"),
        ("Python executable", "python_executable"),
        ("Report path", "report_path"),
    ]:
        value = str(getattr(result, attr, "") or "")
        if value:
            lines.append(label + ": " + value)
    files_inspected = int(getattr(result, "files_inspected", 0) or 0)
    if files_inspected:
        lines.append("Files inspected: " + str(files_inspected))
    lines += [
        "Bounded: " + ("yes" if bool(getattr(result, "bounded", True)) else "no"),
        "Wrote file: " + ("yes" if bool(getattr(result, "wrote_file", False)) else "no"),
        "Copied file: " + ("yes" if bool(getattr(result, "copied_file", False)) else "no"),
        "Installed dependency: " + ("yes" if bool(getattr(result, "installed_dependency", False)) else "no"),
        "",
        "Safety:",
        "- Deterministic Human Command Mode route.",
        "- No model output triggered this action.",
        "- No arbitrary shell route was used.",
        "- No provider/API fallback, autonomy, background worker, trusted-memory write, queue mutation, route mutation, source edit, or applied learning was enabled.",
    ]
    return "\n".join(lines)


