        "- " + _agent_skill_candidate_scaffold_project_rel_v1(result.get("json_path", "")),
        "- " + _agent_skill_candidate_scaffold_project_rel_v1(result.get("markdown_path", "")),
        "",
        "Receipt:",
        "- " + _agent_skill_candidate_scaffold_project_rel_v1(result.get("receipt_path", "")),
        "",
        "schema_validation_result: " + str(result.get("schema_validation_result", "")),
        "scaffold_verifier_result: " + str(result.get("verifier_result", "")),
        "",
