def agent_skill_candidate_scaffold_command_v1(
    text,
    *,
    storage_root=None,
    receipt_root=None,
    approved_storage_roots=None,
    run_verifier=True,
):
    msg = str(text or "").strip()
    lower = msg.lower()
    route_prefixes = [
        ("engel ai candidate scaffold", None),
    ]
    matched_prefix = ""
    implicit_type = None
    for prefix, candidate_type in route_prefixes:
        if lower == prefix or lower.startswith(prefix + " "):
            matched_prefix = prefix
            implicit_type = candidate_type
            break
    if not matched_prefix:
        return None

    rest = msg[len(matched_prefix):].strip()
    rest_lower = rest.lower()
    discovery_topics = {
        "": "all",
        "help": "all",
        "examples": "all",
        "agent example": "agent",
        "skill example": "skill",
    }
    if rest_lower in discovery_topics:
        return _agent_skill_candidate_scaffold_help_response_v1(discovery_topics[rest_lower])

    fields, parse_error = _agent_skill_candidate_scaffold_parse_named_args_v1(rest)
    if parse_error:
        return _agent_skill_candidate_scaffold_blocked_response_v1(parse_error)
    danger_reason = _agent_skill_candidate_scaffold_dangerous_input_reason_v1(fields)
    if danger_reason:
        return _agent_skill_candidate_scaffold_dangerous_response_v1(danger_reason, fields)

    if AGENT_SKILL_CANDIDATE_SCAFFOLD_APPROVAL_PHRASE_V1 not in rest.split():
        return _agent_skill_candidate_scaffold_missing_approval_response_v1(fields)

    candidate_type = (fields.get("type") or fields.get("candidate_type") or implicit_type or "").strip().lower()
    candidate_id = (fields.get("id") or fields.get("candidate_id") or "").strip()
    missing_fields = []
    if candidate_type not in {"agent", "skill"}:
        missing_fields.append("type=agent or type=skill")
    if not candidate_id:
        missing_fields.append("id=<candidate_id>")
    if candidate_type == "agent":
        if not str(fields.get("name") or "").strip():
            missing_fields.append("name=<name>")
        if not str(fields.get("purpose") or fields.get("description") or "").strip():
            missing_fields.append("purpose=<purpose>")
    elif candidate_type == "skill":
        if not str(fields.get("skill_name") or fields.get("name") or "").strip():
            missing_fields.append("skill_name=<skill_name>")
        if not str(fields.get("description") or fields.get("purpose") or "").strip():
            missing_fields.append("description=<description>")
    if missing_fields:
        return _agent_skill_candidate_scaffold_missing_fields_response_v1(missing_fields)

    try:
        import engel_agent_skill_candidate_scaffold as scaffold

        if candidate_type == "agent":
            name = str(fields.get("name") or "").strip()
            purpose = str(fields.get("purpose") or fields.get("description") or "").strip()
            description = str(fields.get("description") or purpose).strip()
            if not name or not purpose:
                return _agent_skill_candidate_scaffold_blocked_response_v1("agent candidates require name and purpose or description.")
            candidate = scaffold.build_agent_candidate(
                candidate_id=candidate_id,
                name=name,
                purpose=purpose,
                description=description,
                created_by="Engel Human Command Mode",
            )
        else:
            skill_name = str(fields.get("skill_name") or fields.get("name") or "").strip()
            description = str(fields.get("description") or fields.get("purpose") or "").strip()
            if not skill_name or not description:
                return _agent_skill_candidate_scaffold_blocked_response_v1("skill candidates require skill_name/name and description or purpose.")
            candidate = scaffold.build_skill_candidate(
                candidate_id=candidate_id,
                skill_name=skill_name,
                description=description,
                created_by="Engel Human Command Mode",
            )

        verifier_result = _agent_skill_candidate_scaffold_verifier_result_v1() if run_verifier else "SKIP_TEMP_SELF_TEST"
        if run_verifier and verifier_result != "PASS":
            return _agent_skill_candidate_scaffold_blocked_response_v1(
                "Scaffold verifier did not pass; candidate files were not created. verifier_result=" + str(verifier_result)
            )
        result = scaffold.write_candidate_scaffold(
            candidate,
            storage_root=storage_root,
            receipt_root=receipt_root,
            approved_storage_roots=approved_storage_roots,
            verifier_result=verifier_result,
        )
        return _agent_skill_candidate_scaffold_success_response_v1(result)
    except Exception as exc:
        return _agent_skill_candidate_scaffold_blocked_response_v1(type(exc).__name__ + ": " + str(exc))


