def _agent_skill_approved_inactive_parse_named_args_v1(rest):
    import shlex

    try:
        tokens = shlex.split(str(rest or ""), posix=True)
    except ValueError as exc:
        return {}, "Could not parse quoted command arguments: " + str(exc)
    fields = {}
    for token in tokens:
        if token == AGENT_SKILL_APPROVED_INACTIVE_APPROVAL_PHRASE_V1:
            continue
        if "=" not in token:
            return {}, "Unexpected argument `" + token + "`. Use key=value fields only after the approval phrase."
        key, value = token.split("=", 1)
        key = key.strip().lower().replace("-", "_")
        value = value.strip()
        if not key:
            return {}, "Empty argument key is not allowed."
        if key in fields:
            return {}, "Duplicate argument key is not allowed: " + key
        fields[key] = value
    return fields, ""


