def _agent_skill_approved_inactive_dangerous_input_reason_v1(fields):
    allowed_keys = {"id", "candidate_id", "note", "reviewer", "dry_run"}
    forbidden_keys = {
        "output_path",
        "runtime_enabled",
        "autorun_enabled",
        "activate",
        "run",
        "install",
        "startup_load_allowed",
        "auto_discovery_execution_allowed",
        "external_ai_access_allowed",
        "network_allowed",
        "provider_api_allowed",
        "trusted_memory_write_allowed",
        "source_mutation_allowed",
        "route_mutation_allowed",
        "queue_mutation_allowed",
        "package_install_allowed",
        "mobile_runtime_allowed",
        "remote_queen_runtime_allowed",
        "storage_root",
        "registry_path",
        "receipt_path",
        "path",
        "file",
        "provider",
        "api_key",
        "url",
        "model",
        "package",
    }
    dangerous_value_needles = [
        "runtime_enabled",
        "autorun_enabled",
        "trusted_memory_write_allowed",
        "source_mutation_allowed",
        "route_mutation_allowed",
        "queue_mutation_allowed",
        "network_allowed",
        "provider_api_allowed",
        "package_install_allowed",
        "mobile_runtime_allowed",
        "remote_queen_runtime_allowed",
        "http://",
        "https://",
        "\\\\",
        "../",
        "..\\",
        ".py",
        ".ps1",
        ".bat",
        ".cmd",
        ".exe",
        ".dll",
        ".sh",
        "api_key",
        "openai",
        "provider",
        "pip install",
        "package install",
        "model server",
        "local llm",
    ]
    for key, value in fields.items():
        if key in forbidden_keys:
            return "Forbidden field is not accepted by this approved-inactive route: " + key
        if key not in allowed_keys:
            return "Unsupported field `" + key + "`. This route accepts only id/candidate_id plus optional note/reviewer/dry_run."
        lower_value = str(value or "").lower()
        if any(needle in lower_value for needle in dangerous_value_needles):
            return "Dangerous value content is not accepted for field `" + key + "`."
    return ""


def _agent_skill_approved_inactive_validate_candidate_id_v1(candidate_id):
    candidate_id = str(candidate_id or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_-]{1,80}", candidate_id):
        raise ValueError("candidate_id must use only letters, numbers, underscore, or hyphen and be 1-80 characters")
    if ".." in candidate_id or "/" in candidate_id or "\\" in candidate_id or ":" in candidate_id:
        raise ValueError("candidate_id must not contain path traversal, absolute path markers, or path separators")
    return candidate_id


def _agent_skill_approved_inactive_is_relative_to_v1(path, root):
    try:
        Path(path).resolve(strict=False).relative_to(Path(root).resolve(strict=False))
        return True
    except ValueError:
        return False


def _agent_skill_approved_inactive_safe_path_v1(path, label):
    resolved = Path(path).resolve(strict=False)
    if not _agent_skill_approved_inactive_is_relative_to_v1(resolved, ROOT):
        raise ValueError(label + " must stay inside " + str(ROOT))
    return resolved


