def _verifier_health_check_project_rel_v1(path):
    try:
        return str(Path(path).resolve(strict=False).relative_to(Path(ROOT).resolve(strict=False)))
    except Exception:
        return str(path)


def _verifier_health_check_load_json_v1(relative_path):
    path = Path(ROOT) / relative_path
    with path.open("r", encoding="utf-8") as handle:
        return json.load(handle)


def _verifier_health_check_static_gate_result_v1():
    checks = []

    def require_path(relative_path, label):
        path = Path(ROOT) / relative_path
        if not path.exists():
            raise RuntimeError(label + " missing: " + relative_path)
        checks.append(label + ": present")
        return path

    candidate_path = require_path(r"reports\agent_skill_candidates\verifier_health_check.agent.json", "candidate JSON")
    require_path(r"reports\agent_skill_candidates\verifier_health_check.agent.md", "candidate Markdown")
    candidate = _verifier_health_check_load_json_v1(candidate_path.relative_to(Path(ROOT)))
    if candidate.get("candidate_id") != VERIFIER_HEALTH_CHECK_AGENT_ID_V1:
        raise RuntimeError("candidate id mismatch")
    if candidate.get("status") not in {"candidate_only", "reviewed_candidate"}:
        raise RuntimeError("candidate status is not candidate_only/reviewed_candidate")
    if candidate.get("trust_status") not in {"untrusted_candidate", "reviewed_candidate"}:
        raise RuntimeError("candidate trust_status is not untrusted/reviewed")
    checks.append("candidate state: " + str(candidate.get("status")) + "/" + str(candidate.get("trust_status")))

    registry_path = require_path(r"memory\ENGEL_AGENT_SKILL_APPROVED_INACTIVE_REGISTRY_V1.json", "approved-inactive registry")
    registry = _verifier_health_check_load_json_v1(registry_path.relative_to(Path(ROOT)))
    entries = registry.get("entries") if isinstance(registry, dict) else []
    entry = next((item for item in entries if isinstance(item, dict) and item.get("candidate_id") == VERIFIER_HEALTH_CHECK_AGENT_ID_V1), None)
    if not entry:
        raise RuntimeError("approved-inactive registry entry missing")
    if entry.get("status") != "approved_inactive":
        raise RuntimeError("registry entry is not approved_inactive")
    if entry.get("trust_status") != "reviewed_but_inactive":
        raise RuntimeError("registry entry is not reviewed_but_inactive")
    for field in [
        "runtime_enabled",
        "autorun_enabled",
        "startup_load_allowed",
        "auto_discovery_execution_allowed",
        "trusted_memory_write_allowed",
        "source_mutation_allowed",
        "route_mutation_allowed",
        "queue_mutation_allowed",
        "network_allowed",
        "provider_api_allowed",
        "external_ai_access_allowed",
        "local_llm_inference_allowed",
        "package_install_allowed",
        "mobile_runtime_allowed",
        "remote_queen_runtime_allowed",
    ]:
        if entry.get(field) is not False:
            raise RuntimeError("registry entry unsafe flag is not false: " + field)
    checks.append("registry entry: " + str(entry.get("registry_entry_id")))

    activation = _verifier_health_check_load_json_v1(r"memory\ENGEL_VERIFIER_HEALTH_CHECK_AGENT_ACTIVATION_CONTRACT_V1.json")
    if activation.get("status") != "contract_only":
        raise RuntimeError("activation contract is not contract_only")
    checks.append("activation contract: contract_only")

    manual = _verifier_health_check_load_json_v1(r"memory\ENGEL_VERIFIER_HEALTH_CHECK_AGENT_MANUAL_RUN_CONTRACT_V1.json")
    if manual.get("status") != "contract_only":
        raise RuntimeError("manual-run contract is not contract_only")
    checks.append("manual-run contract: contract_only")

    command_contract = _verifier_health_check_load_json_v1(r"memory\ENGEL_VERIFIER_HEALTH_CHECK_AGENT_MANUAL_RUN_COMMAND_CONTRACT_V1.json")
    if command_contract.get("status") != "contract_only":
        raise RuntimeError("manual-run command contract is not contract_only")
    if command_contract.get("command_name") != VERIFIER_HEALTH_CHECK_MANUAL_RUN_COMMAND_V1:
        raise RuntimeError("manual-run command contract command mismatch")
    checks.append("manual-run command contract: contract_only")

    if len(VERIFIER_HEALTH_CHECK_ALLOWLIST_V1) > VERIFIER_HEALTH_CHECK_MAX_COMMANDS_PER_RUN_V1:
        raise RuntimeError("allowlist exceeds max command count")
    for item in VERIFIER_HEALTH_CHECK_ALLOWLIST_V1:
        require_path(item["path"], "allowlisted verifier")
    checks.append("fixed allowlist commands: " + str(len(VERIFIER_HEALTH_CHECK_ALLOWLIST_V1)))

    try:
        import engel_global_password_gate as password_gate
        summary = password_gate.protected_action_gate_summary(VERIFIER_HEALTH_CHECK_PROTECTED_ACTION_ID_V1)
    except Exception as exc:
        raise RuntimeError("password gate summary unavailable: " + type(exc).__name__) from exc
    if not summary.get("ok"):
        raise RuntimeError("password gate action is unavailable")
    if summary.get("password_required") is not True:
        raise RuntimeError("password gate action must require password")
    if summary.get("configured") is not True:
        raise RuntimeError("global password gate is not configured")
    if str(summary.get("current_state", "")).lower() == "blocked":
        raise RuntimeError("protected action is blocked")
    checks.append("password gate action: configured/protected")

    return {
        "ok": True,
        "checks": checks,
        "registry_entry_id": str(entry.get("registry_entry_id")),
        "activation_contract_id": str(activation.get("contract_id")),
        "manual_run_contract_id": str(manual.get("contract_id")),
        "command_contract_id": str(command_contract.get("contract_id")),
        "protected_action_id": VERIFIER_HEALTH_CHECK_PROTECTED_ACTION_ID_V1,
    }


