def _debruijn_quantum_approved_promote_reject_v1(reason, hint=None):
    lines = [
        "# De Bruijn Quantum Approved Promote Command",
        "",
        "status: REJECTED",
        "final_status: " + DEBRUIJN_QUANTUM_APPROVED_PROMOTE_DISABLED_REASON_V1,
        "reason: " + reason,
    ]
    if hint:
        lines.extend(["", hint])
    lines.append("")
    lines.append(
        "Exact form: "
        + DEBRUIJN_QUANTUM_APPROVED_PROMOTE_COMMAND_PREFIX_V1
        + " "
        + DEBRUIJN_QUANTUM_APPROVED_PROMOTE_COMMAND_APPROVAL_PHRASE_V1
        + " build_receipt=<receipt_path>"
    )
    lines.append("")
    lines.extend(_debruijn_quantum_approved_promote_safety_lines_v1())
    return "\n".join(lines)


def _debruijn_quantum_approved_promote_parse_args_v1(args_text):
    if not args_text:
        return None, "missing approval phrase and build_receipt argument"
    parts = args_text.split()
    if len(parts) < 2:
        return None, "command requires exact approval phrase and build_receipt=<receipt_path>"
    phrase = parts[0]
    rest = parts[1:]
    if phrase != DEBRUIJN_QUANTUM_APPROVED_PROMOTE_COMMAND_APPROVAL_PHRASE_V1:
        return None, "exact approval phrase required: " + DEBRUIJN_QUANTUM_APPROVED_PROMOTE_COMMAND_APPROVAL_PHRASE_V1
    receipt_value = None
    receipt_seen = 0
    for token in rest:
        lowered = token.lower()
        for bad in DEBRUIJN_QUANTUM_APPROVED_PROMOTE_FORBIDDEN_FLAGS_V1:
            if lowered.startswith(bad):
                return None, "forbidden flag/argument rejected: " + token
        if "://" in lowered or lowered.startswith(("http:", "https:", "file:", "ftp:")):
            return None, "external URL rejected in command arguments"
        if "*" in token or "?" in token:
            return None, "wildcard arguments rejected"
        if token.startswith("build_receipt="):
            receipt_seen += 1
            if receipt_seen > 1:
                return None, "multiple build_receipt arguments rejected"
            value = token[len("build_receipt="):]
            if not value:
                return None, "build_receipt path is empty"
            if ".." in value.replace("\\", "/").split("/"):
                return None, "build_receipt path traversal rejected"
            receipt_value = value
        else:
            return None, "unknown extra argument rejected: " + token
    if not receipt_value:
        return None, "build_receipt=<receipt_path> argument required"
    return receipt_value, None


def debruijn_quantum_approved_promote_command_v1(msg):
    lower = msg.lower().strip()
    prefix = DEBRUIJN_QUANTUM_APPROVED_PROMOTE_COMMAND_PREFIX_V1
    if not lower.startswith(prefix):
        return _debruijn_quantum_approved_promote_reject_v1("command prefix did not match")
    args_text = msg.strip()[len(prefix):].strip()
    if not args_text:
        lines = [
            "# De Bruijn Quantum Approved Promote Command",
            "",
            "status: USAGE",
            "final_status: " + DEBRUIJN_QUANTUM_APPROVED_PROMOTE_DISABLED_REASON_V1,
            "",
            "Exact form:",
            "  " + prefix + " " + DEBRUIJN_QUANTUM_APPROVED_PROMOTE_COMMAND_APPROVAL_PHRASE_V1 + " build_receipt=<receipt_path>",
            "",
            "This route requires the exact approval phrase, Global Password Gate, a verified approved-build receipt, and the declared live-target allowlist.",
            "",
        ]
        lines.extend(_debruijn_quantum_approved_promote_safety_lines_v1())
        return "\n".join(lines)

    receipt_path, parse_error = _debruijn_quantum_approved_promote_parse_args_v1(args_text)
    if parse_error:
        return _debruijn_quantum_approved_promote_reject_v1(parse_error)

    try:
        from engel_debruijn_quantum_build_promote import (
            DEFAULT_ROOT as _BP_ROOT,
            BuildPromoteSafetyError,
            run_approved_graph_promote,
            resolve_workspace_path,
        )
    except Exception as exc:
        return _debruijn_quantum_approved_promote_reject_v1(
            "build/promote engine unavailable: " + type(exc).__name__ + ": " + str(exc)
        )

    try:
        from pathlib import Path as _Path
        resolved = resolve_workspace_path(receipt_path, _BP_ROOT, must_exist=False)
        if not resolved.exists():
            return _debruijn_quantum_approved_promote_reject_v1(
                "build_receipt path does not exist: " + receipt_path
            )
    except BuildPromoteSafetyError as exc:
        return _debruijn_quantum_approved_promote_reject_v1("build_receipt path rejected: " + str(exc))
    except Exception as exc:
        return _debruijn_quantum_approved_promote_reject_v1(
            "build_receipt path check failed: " + type(exc).__name__ + ": " + str(exc)
        )

    try:
        import engel_global_password_gate as password_gate
        gate_result = password_gate.prompt_and_require_action(DEBRUIJN_QUANTUM_APPROVED_PROMOTE_PROTECTED_ACTION_ID_V1)
    except Exception as exc:
        return _debruijn_quantum_approved_promote_reject_v1(
            "Password gate failed closed: " + type(exc).__name__ + ": " + str(exc)
        )
    if not gate_result.get("ok"):
        return _debruijn_quantum_approved_promote_reject_v1("Password gate did not approve the protected action.")

    try:
        result = run_approved_graph_promote(
            _Path(receipt_path),
            _BP_ROOT,
            approval_phrase=DEBRUIJN_QUANTUM_APPROVED_PROMOTE_COMMAND_APPROVAL_PHRASE_V1,
            password_gate_result=gate_result,
        )
    except BuildPromoteSafetyError as exc:
        return _debruijn_quantum_approved_promote_reject_v1("approved promote lane rejected: " + str(exc))
    except Exception as exc:
        return _debruijn_quantum_approved_promote_reject_v1(
            "approved promote lane failed closed: " + type(exc).__name__ + ": " + str(exc)
        )

    lines = [
        "# De Bruijn Quantum Approved Promote Command",
        "",
        "status: PROTECTED_ACTION_COMPLETE_REVIEW_REQUIRED",
        "final_status: " + str(getattr(result, "final_status", "unknown")),
        "approval_phrase: " + DEBRUIJN_QUANTUM_APPROVED_PROMOTE_COMMAND_APPROVAL_PHRASE_V1,
        "build_receipt_path: " + receipt_path,
        "password_gate_status: pass_redacted",
        "live_smoke_result: " + str(getattr(result, "live_smoke_result", "unknown")),
        "human_review_required: true",
        "",
        "Receipt paths:",
    ]
    receipt_paths = getattr(result, "files_changed", []) or []
    if receipt_paths:
        lines.extend("- " + str(p) for p in receipt_paths)
    else:
        lines.append("- (none)")
    lines.append("")
    lines.append(
        "Approved promote route completed through the protected promote lane. It may write"
        " only the declared live target and declared backup path. It does not build, does"
        " not run PyInstaller, does not write dist, does not stage or commit, and does not"
        " write trusted memory."
    )
    lines.append("")
    lines.extend(_debruijn_quantum_approved_promote_safety_lines_v1())
    return "\n".join(lines)


