def _debruijn_quantum_approved_build_reject_v1(reason, hint=None):
    lines = [
        "# De Bruijn Quantum Approved Build Command",
        "",
        "status: REJECTED",
        "final_status: " + DEBRUIJN_QUANTUM_APPROVED_BUILD_DISABLED_REASON_V1,
        "reason: " + reason,
    ]
    if hint:
        lines.extend(["", hint])
    lines.append("")
    lines.append(
        "Exact form: "
        + DEBRUIJN_QUANTUM_APPROVED_BUILD_COMMAND_PREFIX_V1
        + " "
        + DEBRUIJN_QUANTUM_APPROVED_BUILD_COMMAND_APPROVAL_PHRASE_V1
        + " candidate=<candidate_path>"
    )
    lines.append("")
    lines.extend(_debruijn_quantum_approved_build_safety_lines_v1())
    return "\n".join(lines)


def _debruijn_quantum_approved_build_parse_args_v1(args_text):
    if not args_text:
        return None, "missing approval phrase and candidate argument"
    parts = args_text.split()
    if len(parts) < 2:
        return None, "command requires exact approval phrase and candidate=<candidate_path>"
    phrase = parts[0]
    rest = parts[1:]
    if phrase != DEBRUIJN_QUANTUM_APPROVED_BUILD_COMMAND_APPROVAL_PHRASE_V1:
        return None, "exact approval phrase required: " + DEBRUIJN_QUANTUM_APPROVED_BUILD_COMMAND_APPROVAL_PHRASE_V1
    candidate_value = None
    candidate_seen = 0
    for token in rest:
        lowered = token.lower()
        for bad in DEBRUIJN_QUANTUM_APPROVED_BUILD_FORBIDDEN_FLAGS_V1:
            if lowered.startswith(bad):
                return None, "forbidden flag/argument rejected: " + token
        if "://" in lowered or lowered.startswith(("http:", "https:", "file:", "ftp:")):
            return None, "external URL rejected in command arguments"
        if "*" in token or "?" in token:
            return None, "wildcard arguments rejected"
        if token.startswith("candidate="):
            candidate_seen += 1
            if candidate_seen > 1:
                return None, "multiple candidate arguments rejected"
            value = token[len("candidate="):]
            if not value:
                return None, "candidate path is empty"
            if ".." in value.replace("\\", "/").split("/"):
                return None, "candidate path traversal rejected"
            candidate_value = value
        else:
            return None, "unknown extra argument rejected: " + token
    if not candidate_value:
        return None, "candidate=<candidate_path> argument required"
    return candidate_value, None


def debruijn_quantum_approved_build_command_v1(msg):
    lower = msg.lower().strip()
    prefix = DEBRUIJN_QUANTUM_APPROVED_BUILD_COMMAND_PREFIX_V1
    if not lower.startswith(prefix):
        return _debruijn_quantum_approved_build_reject_v1("command prefix did not match")
    args_text = msg.strip()[len(prefix):].strip()
    if not args_text:
        lines = [
            "# De Bruijn Quantum Approved Build Command",
            "",
            "status: USAGE",
            "final_status: " + DEBRUIJN_QUANTUM_APPROVED_BUILD_DISABLED_REASON_V1,
            "",
            "Exact form:",
            "  " + prefix + " " + DEBRUIJN_QUANTUM_APPROVED_BUILD_COMMAND_APPROVAL_PHRASE_V1 + " candidate=<candidate_path>",
            "",
            "This route requires the exact approval phrase, Global Password Gate, a verified graph build candidate, and the fixed build script allowlist.",
            "",
        ]
        lines.extend(_debruijn_quantum_approved_build_safety_lines_v1())
        return "\n".join(lines)

    candidate_path, parse_error = _debruijn_quantum_approved_build_parse_args_v1(args_text)
    if parse_error:
        return _debruijn_quantum_approved_build_reject_v1(parse_error)

    try:
        from engel_debruijn_quantum_build_promote import (
            DEFAULT_ROOT as _BP_ROOT,
            BuildPromoteSafetyError,
            run_build_preflight_only,
            run_approved_graph_build,
            resolve_workspace_path,
        )
    except Exception as exc:
        return _debruijn_quantum_approved_build_reject_v1(
            "build/promote engine unavailable: " + type(exc).__name__ + ": " + str(exc)
        )

    try:
        from pathlib import Path as _Path
        resolved = resolve_workspace_path(candidate_path, _BP_ROOT, must_exist=False)
        if not resolved.exists():
            return _debruijn_quantum_approved_build_reject_v1(
                "candidate path does not exist: " + candidate_path
            )
        preflight = run_build_preflight_only(_Path(candidate_path), _BP_ROOT)
    except BuildPromoteSafetyError as exc:
        return _debruijn_quantum_approved_build_reject_v1("preflight rejected: " + str(exc))
    except Exception as exc:
        return _debruijn_quantum_approved_build_reject_v1(
            "preflight failed: " + type(exc).__name__ + ": " + str(exc)
        )

    preflight_status = getattr(preflight, "final_status", "unknown")
    receipt_paths = getattr(preflight, "files_changed", []) or []

    if preflight_status != "BUILD_PREFLIGHT_READY_BUILD_DISABLED":
        lines = [
            "# De Bruijn Quantum Approved Build Command",
            "",
            "status: REJECTED",
            "final_status: BUILD_PREFLIGHT_NOT_READY",
            "approval_phrase: " + DEBRUIJN_QUANTUM_APPROVED_BUILD_COMMAND_APPROVAL_PHRASE_V1,
            "candidate_path: " + candidate_path,
            "preflight_status: " + str(preflight_status),
            "password_gate_status: not_invoked_preflight_not_ready",
            "human_review_required: true",
            "",
            "Preflight receipt paths:",
        ]
        if receipt_paths:
            lines.extend("- " + str(p) for p in receipt_paths)
        else:
            lines.append("- (none)")
        lines.append("")
        lines.append("Approved build stopped before password prompt because the graph build candidate is not ready for an approved build attempt.")
        lines.append("")
        lines.extend(_debruijn_quantum_approved_build_safety_lines_v1())
        return "\n".join(lines)

    try:
        import engel_global_password_gate as password_gate
        gate_result = password_gate.prompt_and_require_action(DEBRUIJN_QUANTUM_APPROVED_BUILD_PROTECTED_ACTION_ID_V1)
    except Exception as exc:
        return _debruijn_quantum_approved_build_reject_v1(
            "Password gate failed closed: " + type(exc).__name__ + ": " + str(exc)
        )
    if not gate_result.get("ok"):
        return _debruijn_quantum_approved_build_reject_v1("Password gate did not approve the protected action.")

    try:
        result = run_approved_graph_build(
            _Path(candidate_path),
            _BP_ROOT,
            approval_phrase=DEBRUIJN_QUANTUM_APPROVED_BUILD_COMMAND_APPROVAL_PHRASE_V1,
            password_gate_result=gate_result,
        )
    except BuildPromoteSafetyError as exc:
        return _debruijn_quantum_approved_build_reject_v1("approved build lane rejected: " + str(exc))
    except Exception as exc:
        return _debruijn_quantum_approved_build_reject_v1(
            "approved build lane failed closed: " + type(exc).__name__ + ": " + str(exc)
        )

    lines = [
        "# De Bruijn Quantum Approved Build Command",
        "",
        "status: PROTECTED_ACTION_COMPLETE_REVIEW_REQUIRED",
        "final_status: " + str(getattr(result, "final_status", "unknown")),
        "approval_phrase: " + DEBRUIJN_QUANTUM_APPROVED_BUILD_COMMAND_APPROVAL_PHRASE_V1,
        "candidate_path: " + candidate_path,
        "preflight_status: " + str(preflight_status),
        "password_gate_status: pass_redacted",
        "staged_smoke_result: " + str(getattr(result, "staged_smoke_result", "unknown")),
        "human_review_required: true",
        "",
        "Receipt paths:",
    ]
    if receipt_paths:
        lines.extend("- " + str(p) for p in receipt_paths)
    result_paths = getattr(result, "files_changed", []) or []
    if result_paths:
        lines.extend("- " + str(p) for p in result_paths)
    else:
        lines.append("- (none)")
    lines.append("")
    lines.append(
        "Approved build route completed through the protected build lane. It may write"
        " staged artifacts only under build\\staging. It does not promote, does not write"
        " live/dist/backups, does not stage or commit, and does not write trusted memory."
    )
    lines.append("")
    lines.extend(_debruijn_quantum_approved_build_safety_lines_v1())
    return "\n".join(lines)


