def _upgrade_connection_path_state(relative_path: str) -> str:
    parts = [part for part in relative_path.replace("/", "\\").split("\\") if part]
    path = os.path.join(ROOT, *parts)
    return "present" if os.path.exists(path) else "missing"


def _upgrade_connection_file_count(relative_path: str) -> int:
    parts = [part for part in relative_path.replace("/", "\\").split("\\") if part]
    folder = os.path.join(ROOT, *parts)
    try:
        return sum(
            1
            for name in os.listdir(folder)
            if os.path.isfile(os.path.join(folder, name))
        )
    except OSError:
        return 0


def _recent_upgrade_report_names(limit: int = 12) -> list[str]:
    folder = os.path.join(ROOT, "reports", "codex_bridge")
    try:
        rows = []
        for name in os.listdir(folder):
            path = os.path.join(folder, name)
            if not name.lower().endswith(".md") or not os.path.isfile(path):
                continue
            if "20260510" not in name and not name.startswith("NEW_LOCAL_RESOURCES_CONNECTED"):
                continue
            rows.append((os.path.getmtime(path), name))
        rows.sort(reverse=True)
        return [name for _, name in rows[:limit]]
    except OSError:
        return []


