def sanitize_file_to_report(path_text: str, report_name: str) -> str:
    validation = hcm.validate_read_file(path_text)
    if not validation.ok or validation.path is None:
        return "# Sanitize File Blocked\n\n" + validation.message
    path = Path(str(validation.path))
    try:
        size = path.stat().st_size
    except Exception:
        size = 0
    if size > PROMPT_SCAN_MAX_FILE_BYTES:
        return "# Sanitize File Blocked\n\nFile too large for bounded sanitize route."
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except Exception as exc:
        return "# Sanitize File Failed\n\n" + str(exc)
    if len(text) > PROMPT_SCAN_MAX_CHARS:
        text = text[:PROMPT_SCAN_MAX_CHARS]
    findings = scan_text_for_leaks(text)
    redacted = redact_sensitive_text(text)
    finding_lines = [f"- [{finding.kind}] {finding.value} -> suggest {finding.suggestion}" for finding in findings[:60]]
    report_body = "\n".join(
        [
            "# Sanitized File Report",
            "",
            "Source file: " + str(path),
            "Findings before redaction: " + str(len(findings)),
            "",
            "## Sanitized Content",
            redacted,
            "",
            "## Findings Summary",
            *(finding_lines or ["- none"]),
        ]
    )
    result = hcm.write_report_safely(report_name, report_body, r"reports\codex_bridge")
    return "\n".join(
        [
            "# Sanitize File To Report",
            "",
            "Source: " + str(path),
            "Findings: " + str(len(findings)),
            "",
            _human_action_result_text(result),
            "",
            "Safety:",
            "- Source read is bounded by approved read roots.",
            "- Output write is bounded to reports\\codex_bridge.",
        ]
    )


