def critical_signal_scan_file(path_text: str) -> str:
    validation = hcm.validate_read_file(path_text)
    if not validation.ok or validation.path is None:
        return "# Critical Signal Scan Blocked\n\n" + validation.message
    path = Path(str(validation.path))
    try:
        size = path.stat().st_size
    except Exception:
        size = 0
    if size > PROMPT_SCAN_MAX_FILE_BYTES:
        return "# Critical Signal Scan Blocked\n\nFile too large for bounded scan."
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except Exception as exc:
        return "# Critical Signal Scan Failed\n\n" + str(exc)
    if len(text) > PROMPT_SCAN_MAX_CHARS:
        text = text[:PROMPT_SCAN_MAX_CHARS]
    findings = _critical_signal_findings(text)
    hits: list[str] = []
    if findings:
        for index, line in enumerate(text.splitlines(), start=1):
            normalized = line.lower()
            if any(word in normalized for word in findings):
                hits.append(f"- L{index}: {line.strip()[:160]}")
                if len(hits) >= 30:
                    break
    lines = [
        "# Critical Signal Scan File",
        "",
        "File: " + str(path),
        "Keyword hits: " + str(len(findings)),
        "",
        "Matched keywords:",
    ]
    lines.extend([f"- {word}" for word in findings] or ["- none"])
    lines.extend(
        [
            "",
            "Hit lines:",
        ]
    )
    lines.extend(hits or ["- none"])
    lines.extend(
        [
            "",
            "Safety:",
            "- Read-only bounded scan under approved roots.",
            "- No execution and no writes.",
        ]
    )
    return "\n".join(lines)


def _localsend_readable_file_size(size_bytes: int) -> str:
    size = int(size_bytes or 0)
    if size < 1024:
        return f"{size} B"
    if size < 1024 * 1024:
        return f"{size / 1024:.1f} KB"
    if size < 1024 * 1024 * 1024:
        return f"{size / (1024 * 1024):.1f} MB"
    return f"{size / (1024 * 1024 * 1024):.1f} GB"


def _localsend_extension(path_text: str) -> str:
    name = str(path_text or "").replace("\\", "/").split("/")[-1]
    index = name.rfind(".")
    return name[index + 1 :].lower() if index != -1 else ""


def _localsend_with_count(file_name: str, count: int) -> str:
    source = str(file_name or "")
    index = source.rfind(".")
    if index != -1:
        base = source[:index]
        ext = source[index + 1 :].lower()
    else:
        base = source
        ext = ""
    match = _LOCALSEND_FILE_NUMBER_RE.match(base)
    if match:
        base = match.group(1) or base
    candidate = f"{base} ({int(count)})"
    return f"{candidate}.{ext}" if ext else candidate


def _localsend_guess_file_type(ext: str) -> str:
    e = str(ext or "").lower()
    if e in {"bmp", "jpg", "jpeg", "heic", "png", "gif", "svg", "dng"}:
        return "image"
    if e in {"mp4", "mov"}:
        return "video"
    if e == "pdf":
        return "pdf"
    if e == "txt":
        return "text"
    if e == "apk":
        return "apk"
    return "other"


