def _web_get_browser(user_agent: str) -> str | None:
    ua = str(user_agent or "")
    if "Firefox" in ua:
        return "Firefox"
    if "Chrome" in ua:
        return "Chrome"
    if "Safari" in ua:
        return "Safari"
    if "Opera" in ua or "OPR" in ua:
        return "Opera"
    if "Edg" in ua:
        return "Edge"
    if "MSIE" in ua or "Trident" in ua:
        return "Internet Explorer"
    if "insomnia" in ua:
        return "Insomnia"
    return None


def _web_get_os(user_agent: str) -> str | None:
    ua = str(user_agent or "")
    if "Win" in ua:
        return "Windows"
    if "Android" in ua:
        return "Android"
    if "Macintosh" in ua:
        return "macOS"
    if "iPhone" in ua or "iPad" in ua or "iPod" in ua:
        return "iOS"
    if "X11" in ua:
        return "Linux"
    return None


