def web_base64_encode_text(text: str) -> str:
    raw = str(text or "")
    encoded = base64.urlsafe_b64encode(raw.encode("utf-8")).decode("ascii").rstrip("=")
    return "\n".join(
        [
            "# Web Base64 Encode",
            "",
            "Input chars: " + str(len(raw)),
            "Output:",
            encoded or "[empty]",
            "",
            "Safety:",
            "- Local deterministic transform only.",
            "- No execution and no mutation.",
        ]
    )


def web_base64_decode_text(value: str) -> str:
    token = str(value or "").strip()
    if not token:
        return "Use exact form: web base64 decode <urlsafe_base64>"
    padded = token + ("=" * ((4 - len(token) % 4) % 4))
    try:
        decoded = base64.urlsafe_b64decode(padded.encode("ascii")).decode("utf-8", errors="replace")
    except Exception as exc:
        return "# Web Base64 Decode Failed\n\n" + str(exc)
    return "\n".join(
        [
            "# Web Base64 Decode",
            "",
            "Input chars: " + str(len(token)),
            "Decoded text:",
            decoded if decoded else "[empty]",
            "",
            "Safety:",
            "- Local deterministic transform only.",
            "- No execution and no mutation.",
        ]
    )


