def _ehuman_parse_semver_parts(version: str) -> tuple[int, int, int] | None:
    text = str(version or "").strip()
    match = EHUMAN_SEMVER_RE.match(text)
    if not match:
        return None
    return (
        int(match.group(1) or "0"),
        int(match.group(2) or "0"),
        int(match.group(3) or "0"),
    )


def _ehuman_compare_semver(a: str, b: str) -> int:
    left = _ehuman_parse_semver_parts(a)
    right = _ehuman_parse_semver_parts(b)
    if not left or not right:
        return 0
    for index in range(3):
        if left[index] != right[index]:
            return -1 if left[index] < right[index] else 1
    return 0


def ehuman_semver_compare(left: str, right: str) -> str:
    left_parts = _ehuman_parse_semver_parts(left)
    right_parts = _ehuman_parse_semver_parts(right)
    if not left_parts or not right_parts:
        return (
            "# EHuman Semver Compare\n\n"
            "Input parse failed. Use numeric dotted versions like 0.51.0 or v1.2.3."
        )
    cmp_value = _ehuman_compare_semver(left, right)
    relation = "equal to" if cmp_value == 0 else ("less than" if cmp_value < 0 else "greater than")
    return "\n".join(
        [
            "# EHuman Semver Compare",
            "",
            f"Left: {left.strip()} -> {left_parts}",
            f"Right: {right.strip()} -> {right_parts}",
            "Result: left is " + relation + " right",
            "Compare value: " + str(cmp_value),
            "",
            "Safety:",
            "- Local deterministic version parsing only.",
            "- No execution and no writes.",
        ]
    )


def ehuman_semver_at_least(current: str, minimum: str) -> str:
    current_parts = _ehuman_parse_semver_parts(current)
    minimum_parts = _ehuman_parse_semver_parts(minimum)
    if not current_parts or not minimum_parts:
        return (
            "# EHuman Semver At Least\n\n"
            "Input parse failed. Use numeric dotted versions like 0.51.0 or v1.2.3."
        )
    is_at_least = _ehuman_compare_semver(current, minimum) >= 0
    return "\n".join(
        [
            "# EHuman Semver At Least",
            "",
            f"Current: {current.strip()} -> {current_parts}",
            f"Minimum: {minimum.strip()} -> {minimum_parts}",
            "Verdict: " + ("PASS" if is_at_least else "FAIL"),
            "",
            "Safety:",
            "- Local deterministic version comparison only.",
            "- No execution and no writes.",
        ]
    )


def _ehuman_split_sentences(text: str) -> list[str]:
    parts: list[str] = []
    current = ""
    for index in range(len(text)):
        current += text[index]
        next_1 = text[index + 1] if index + 1 < len(text) else ""
        next_2 = text[index + 2] if index + 2 < len(text) else ""
        if text[index] in ".!?" and next_1 == " " and next_2 and "A" <= next_2 <= "Z":
            piece = current.strip()
            if piece:
                parts.append(piece)
            current = ""
    tail = current.strip()
    if tail:
        parts.append(tail)
    return parts


def _ehuman_merge_too_short(parts: list[str], joiner: str) -> list[str]:
    merged: list[str] = []
    for part in parts:
        if merged and len(part) < EHUMAN_MIN_SEGMENT_CHARS:
            merged[-1] += joiner + part
        else:
            merged.append(part)
    return merged


def _ehuman_group_sentences(sentences: list[str]) -> list[str]:
    if not sentences:
        return []
    target_count = min(3, max(1, (len(sentences) + 1) // 2))
    group_size = (len(sentences) + target_count - 1) // target_count
    groups: list[str] = []
    for i in range(0, len(sentences), group_size):
        groups.append(" ".join(sentences[i : i + group_size]))
    return [group for group in groups if len(group) >= EHUMAN_MIN_SEGMENT_CHARS]


def ehuman_segment_text(text: str) -> str:
    trimmed = str(text or "").strip()
    if not trimmed:
        return "Use exact form: ehuman segment text <text>"
    if len(trimmed) < 80:
        segments = [trimmed]
    else:
        paragraphs = [p.strip() for p in re.split(r"\n\n+", trimmed) if p.strip()]
        segments = []
        if len(paragraphs) >= 2:
            merged = _ehuman_merge_too_short(paragraphs, "\n\n")
            if len(merged) >= 2:
                segments = merged[:EHUMAN_MAX_SEGMENTS]
        if not segments:
            sentences = _ehuman_split_sentences(trimmed)
            if len(sentences) >= 2:
                grouped = _ehuman_group_sentences(sentences)
                if len(grouped) >= 2:
                    segments = grouped[:EHUMAN_MAX_SEGMENTS]
        if not segments:
            segments = [trimmed]
    lines = [
        "# EHuman Segment Text",
        "",
        "Input chars: " + str(len(trimmed)),
        "Segments: " + str(len(segments)),
        "",
        "Output:",
    ]
    for idx, seg in enumerate(segments, start=1):
        lines.append(f"- [{idx}] {seg}")
    lines.extend(
        [
            "",
            "Safety:",
            "- Local deterministic text segmentation only.",
            "- No execution and no writes.",
        ]
    )
    return "\n".join(lines)


def ehuman_update_decision(command_text: str) -> str:
    text = str(command_text or "").strip()
    match = re.match(
        r"^\s*structural\s+(\d+)\s+total\s+(\d+)\s+dirs_changed\s+(yes|no|true|false|1|0)\s*$",
        text,
        re.IGNORECASE,
    )
    if not match:
        return "Use exact form: ehuman update decision structural <count> total <count> dirs_changed <yes|no>"
    structural_count = int(match.group(1))
    total_files = int(match.group(2))
    dirs_changed = match.group(3).lower() in {"yes", "true", "1"}
    if total_files < 0:
        return "# EHuman Update Decision Blocked\n\nTotal must be zero or greater."
    if structural_count < 0:
        return "# EHuman Update Decision Blocked\n\nStructural count must be zero or greater."

    if structural_count == 0:
        action = "SKIP"
        rerun_architecture = "no"
        rerun_tour = "no"
        reason = "No structural changes detected."
    else:
        percent = (float(structural_count) / float(total_files)) if total_files > 0 else 0.0
        if structural_count > 30 or (total_files > 0 and percent > 0.5):
            action = "FULL_UPDATE"
            rerun_architecture = "yes"
            rerun_tour = "yes"
            reason = "Structural change volume crosses full-update threshold."
        elif dirs_changed or structural_count > 10:
            action = "ARCHITECTURE_UPDATE"
            rerun_architecture = "yes"
            rerun_tour = "yes"
            reason = "Directory structure change or medium structural change volume."
        else:
            action = "PARTIAL_UPDATE"
            rerun_architecture = "no"
            rerun_tour = "no"
            reason = "Localized structural changes suggest partial update."

    return "\n".join(
        [
            "# EHuman Update Decision",
            "",
            "Structural count: " + str(structural_count),
            "Total files: " + str(total_files),
            "Directories changed: " + ("yes" if dirs_changed else "no"),
            "Decision: " + action,
            "Rerun architecture: " + rerun_architecture,
            "Rerun tour: " + rerun_tour,
            "Reason: " + reason,
            "",
            "Safety:",
            "- Local deterministic decision helper only.",
            "- No execution and no writes.",
        ]
    )


def ehuman_structural_summary(command_text: str) -> str:
    text = str(command_text or "").strip()
    match = re.match(
        r"^\s*changed\s+(\d+)\s+new\s+(\d+)\s+deleted\s+(\d+)\s+cosmetic\s+(\d+)\s+unchanged\s+(\d+)\s*$",
        text,
        re.IGNORECASE,
    )
    if not match:
        return "Use exact form: ehuman structural summary changed <count> new <count> deleted <count> cosmetic <count> unchanged <count>"
    changed = int(match.group(1))
    new_files = int(match.group(2))
    deleted = int(match.group(3))
    cosmetic = int(match.group(4))
    unchanged = int(match.group(5))
    structural_total = changed + new_files + deleted
    total_seen = structural_total + cosmetic + unchanged
    if total_seen <= 0:
        return "# EHuman Structural Summary Blocked\n\nProvide counts greater than zero."
    structural_ratio = (float(structural_total) / float(total_seen)) * 100.0
    if structural_total > 30 or structural_ratio > 50.0:
        impact = "HIGH"
    elif structural_total > 10 or structural_ratio > 20.0:
        impact = "MEDIUM"
    else:
        impact = "LOW"
    return "\n".join(
        [
            "# EHuman Structural Summary",
            "",
            "Changed (modified): " + str(changed),
            "New files: " + str(new_files),
            "Deleted files: " + str(deleted),
            "Cosmetic-only files: " + str(cosmetic),
            "Unchanged files: " + str(unchanged),
            "Structural total: " + str(structural_total),
            "Total seen: " + str(total_seen),
            f"Structural ratio: {structural_ratio:.2f}%",
            "Impact: " + impact,
            "",
            "Safety:",
            "- Local deterministic summary helper only.",
            "- No execution and no writes.",
        ]
    )


def ehuman_timeout_guard(command_text: str) -> str:
    text = str(command_text or "").strip()
    match = re.match(r"^\s*(\d+)\s*$", text)
    if not match:
        return "Use exact form: ehuman timeout guard <seconds>"
    timeout_seconds = int(match.group(1))
    if timeout_seconds <= 0:
        return "# EHuman Timeout Guard Blocked\n\nTimeout must be greater than zero."
    grace_seconds = 30
    return "\n".join(
        [
            "# EHuman Timeout Guard",
            "",
            f"Requested timeout: {timeout_seconds}s",
            f"Grace period after soft stop: {grace_seconds}s",
            "Escalation model:",
            "- Step 1: run command in isolated process group/session",
            "- Step 2: wait until timeout",
            "- Step 3: send soft termination signal to process group",
            "- Step 4: wait grace period",
            "- Step 5: force-kill process group if still active",
            "",
            "Operator note:",
            "- Timeout helper is planning-only; it does not execute commands.",
            "",
            "Safety:",
            "- Deterministic local planning helper only.",
            "- No execution and no writes.",
        ]
    )


def ehuman_dependency_boundary_scan(command_text: str) -> str:
    raw = str(command_text or "").strip()
    if not raw:
        return "Use exact form: ehuman dependency boundary scan <comma_separated_dependency_names>"
    deps = [part.strip() for part in raw.split(",") if part.strip()]
    if not deps:
        return "Use exact form: ehuman dependency boundary scan <comma_separated_dependency_names>"
    risk_tokens = (
        "provider",
        "runtime",
        "desktop",
        "worker",
        "network",
        "socket",
        "gateway",
        "openai",
        "anthropic",
    )
    flagged: list[str] = []
    for dep in deps:
        lower = dep.lower()
        hits = [token for token in risk_tokens if token in lower]
        if hits:
            flagged.append(f"- {dep} -> risk tokens: {', '.join(hits)}")
    verdict = "PASS" if not flagged else "REVIEW"
    lines = [
        "# EHuman Dependency Boundary Scan",
        "",
        "Dependencies scanned: " + str(len(deps)),
        "Verdict: " + verdict,
        "",
        "Flagged entries:",
    ]
    lines.extend(flagged or ["- none"])
    lines.extend(
        [
            "",
            "Safety:",
            "- Deterministic local text policy scan only.",
            "- No execution and no writes.",
        ]
    )
    return "\n".join(lines)


def ehuman_token_overhead(command_text: str) -> str:
    text = str(command_text or "").strip()
    match = re.match(
        r"^\s*baseline\s+(\d+)\s+current\s+(\d+)\s+max_overhead_pct\s+([+-]?\d+(?:\.\d+)?)\s*$",
        text,
        re.IGNORECASE,
    )
    if not match:
        return "Use exact form: ehuman token overhead baseline <count> current <count> max_overhead_pct <percent>"
    baseline = int(match.group(1))
    current = int(match.group(2))
    max_overhead_pct = float(match.group(3))
    if baseline <= 0:
        return "# EHuman Token Overhead Blocked\n\nBaseline must be greater than zero."
    pct_diff = ((float(current) - float(baseline)) / float(baseline)) * 100.0
    if pct_diff <= 0.0:
        verdict = "PASS"
        summary = f"Current uses {abs(pct_diff):.2f}% fewer tokens than baseline."
    elif pct_diff <= max_overhead_pct:
        verdict = "PASS"
        summary = f"Current uses {pct_diff:.2f}% more tokens (within allowed threshold)."
    else:
        verdict = "FAIL"
        summary = f"Current uses {pct_diff:.2f}% more tokens (exceeds threshold)."
    return "\n".join(
        [
            "# EHuman Token Overhead",
            "",
            "Baseline tokens: " + str(baseline),
            "Current tokens: " + str(current),
            f"Difference: {current - baseline:+}",
            f"Percent difference: {pct_diff:+.2f}%",
            f"Max overhead threshold: {max_overhead_pct:.2f}%",
            "Verdict: " + verdict,
            "Summary: " + summary,
            "",
            "Safety:",
            "- Deterministic local budget math helper only.",
            "- No execution and no writes.",
        ]
    )


def ehuman_ratchet_budget(command_text: str) -> str:
    text = str(command_text or "").strip()
    match = re.match(
        r"^\s*baseline\s+(\d+)\s+current\s+(\d+)\s*$",
        text,
        re.IGNORECASE,
    )
    if not match:
        return "Use exact form: ehuman ratchet budget baseline <count> current <count>"
    baseline = int(match.group(1))
    current = int(match.group(2))
    delta = current - baseline
    if delta > 0:
        verdict = "REGRESSION"
        action = "Block growth; reduce current count or intentionally refresh baseline after cleanup review."
    elif delta < 0:
        verdict = "IMPROVED"
        action = "Budget improved; consider baseline refresh only after intentional acceptance."
    else:
        verdict = "UNCHANGED"
        action = "No change against ratchet baseline."
    return "\n".join(
        [
            "# EHuman Ratchet Budget",
            "",
            "Baseline count: " + str(baseline),
            "Current count: " + str(current),
            f"Delta: {delta:+}",
            "Verdict: " + verdict,
            "Guidance: " + action,
            "",
            "Safety:",
            "- Deterministic local ratchet-budget helper only.",
            "- No execution and no writes.",
        ]
    )


def ehuman_ignore_suggestions() -> str:
    default_patterns = {
        "node_modules/",
        ".git/",
        "dist/",
        "build/",
        "__pycache__/",
        "*.lock",
        "*.min.js",
    }
    detectable_dirs = [
        "__tests__",
        "test",
        "tests",
        "fixtures",
        "testdata",
        "docs",
        "examples",
        "scripts",
        "migrations",
        ".storybook",
    ]
    generic = ["*.test.*", "*.spec.*", "*.snap"]
    gitignore_patterns: list[str] = []
    gitignore_path = Path(ROOT) / ".gitignore"
    if gitignore_path.exists():
        try:
            for raw in gitignore_path.read_text(encoding="utf-8", errors="replace").splitlines():
                line = raw.strip()
                if not line or line.startswith("#"):
                    continue
                normalized = line.rstrip("/")
                if any(p.rstrip("/") == normalized for p in default_patterns):
                    continue
                gitignore_patterns.append(line)
        except Exception:
            gitignore_patterns = []

    detected = [name + "/" for name in detectable_dirs if (Path(ROOT) / name).exists()]
    lines = [
        "# EHuman Ignore Suggestions",
        "",
        "Root: " + str(ROOT),
        "Mode: read-only suggestion generator (no file writes)",
        "",
        "# .understandignore starter suggestions (commented)",
    ]
    if gitignore_patterns:
        lines.extend(["", "# From .gitignore (uncomment as needed)"])
        lines.extend(["# " + pattern for pattern in gitignore_patterns[:80]])
    if detected:
        lines.extend(["", "# Detected directories (uncomment as needed)"])
        lines.extend(["# " + pattern for pattern in detected])
    lines.extend(["", "# Generic test patterns (uncomment as needed)"])
    lines.extend(["# " + pattern for pattern in generic])
    lines.extend(
        [
            "",
            "Safety:",
            "- Read-only local file/folder inspection only.",
            "- No execution and no writes.",
        ]
    )
    return "\n".join(lines)


