def _handle_growth_utility_routes(msg: str, lower: str) -> str | None:
    try:
        from engel_ai_update_routes import resolve_update_route

        update_route = resolve_update_route(msg)
        if update_route:
            return engel_ai_update_route_status(update_route)
    except Exception:
        pass

    if lower == "ai help":
        return ai_planner.render_help()
    if lower == "ai planner status":
        return ai_planner.render_status()
    if lower.startswith("ai classify "):
        raw = msg[len("ai classify "):].strip()
        if not raw:
            return "Use exact form: ai classify <text>"
        return ai_planner.render_classification(ai_planner.classify_intent(raw))
    if lower.startswith("ai plan "):
        raw = msg[len("ai plan "):].strip()
        if not raw:
            return "Use exact form: ai plan <text>"
        return ai_planner.render_plan(ai_planner.build_plan(raw))
    if lower == "mind growth status":
        return mind_growth_status()
    if lower == "upgrade connections status":
        return upgrade_connections_status()
    if lower in {
        "future upgrades status",
        "future upgrade status",
        "upgrade readiness status",
        "next upgrades status",
    }:
        return future_upgrades_status()
    if lower == "complex routes status":
        return complex_routes_status()
    if lower in {
        "long term memory drive status",
        "long-term memory drive status",
        "engel long term memory status",
        "engel long-term memory status",
    }:
        return long_term_memory_drive_status()
    for handler in (
        _handle_ehuman_utility_routes,
        _handle_engel_utility_routes,
        _handle_web_utility_routes,
        _handle_elsand_utility_routes,
        _handle_file_utility_routes,
        _handle_humanizer_routes,
        _handle_threat_guard_routes,
    ):
        result = handler(msg, lower)
        if result is not None:
            return result
    return None


