def _handle_reps_system_routes(msg: str, lower: str) -> str | None:
    if lower in {"reps status", "r.e.p.s. status", "reps recorder", "reps recorder status", "r.e.p.s. recorder status"}:
        if "recorder status" in lower:
            return _run_reps_system_bridge(["recorder-status"], timeout=25)
        return _run_reps_system_bridge(["status"], timeout=30)
    if lower.startswith("reps record "):
        lesson = msg[len("reps record "):].strip()
        return _run_reps_system_bridge(["record", lesson], timeout=30)
    if lower.startswith("r.e.p.s. record "):
        lesson = msg[len("r.e.p.s. record "):].strip()
        return _run_reps_system_bridge(["record", lesson], timeout=30)
    if lower.startswith("reps cycle approve "):
        lesson = msg[len("reps cycle approve "):].strip()
        return _run_reps_system_bridge(["cycle", "--approve", lesson], timeout=30)
    if lower.startswith("reps run approve "):
        lesson = msg[len("reps run approve "):].strip()
        return _run_reps_system_bridge(["cycle", "--approve", lesson], timeout=30)
    if lower.startswith("reps approve cycle "):
        lesson = msg[len("reps approve cycle "):].strip()
        return _run_reps_system_bridge(["cycle", "--approve", lesson], timeout=30)
    if lower.startswith("r.e.p.s. cycle approve "):
        lesson = msg[len("r.e.p.s. cycle approve "):].strip()
        return _run_reps_system_bridge(["cycle", "--approve", lesson], timeout=30)
    if lower.startswith("reps cycle "):
        lesson = msg[len("reps cycle "):].strip()
        return _run_reps_system_bridge(["cycle", lesson], timeout=30)
    if lower.startswith("reps run "):
        lesson = msg[len("reps run "):].strip()
        return _run_reps_system_bridge(["cycle", lesson], timeout=30)
    if lower.startswith("r.e.p.s. cycle "):
        lesson = msg[len("r.e.p.s. cycle "):].strip()
        return _run_reps_system_bridge(["cycle", lesson], timeout=30)
    return None


def _run_reps_system_bridge(args, timeout=30):
    import os
    import subprocess
    import sys

    tool = os.path.join(ROOT, "tools", "engel_reps_system_bridge.py")
    python_exe = os.path.join(ROOT, "runtime", "python310", "python.exe")
    if not os.path.isfile(python_exe):
        python_exe = sys.executable
    command = [python_exe, tool] + [str(arg) for arg in args if str(arg).strip()]
    try:
        result = subprocess.run(
            command,
            cwd=ROOT,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=timeout,
        )
    except Exception as exc:
        return "\n".join(
            [
                "# Engel R.E.P.S. Bridge Failed",
                "",
                "Command: " + " ".join(command),
                "Error: " + str(exc),
            ]
        )
    output = (result.stdout or "").strip()
    error = (result.stderr or "").strip()
    if result.returncode == 0 and output:
        return output
    return "\n".join(
        [
            "# Engel R.E.P.S. Bridge Failed",
            "",
            "Command: " + " ".join(command),
            "Exit: " + str(result.returncode),
            "",
            "stdout:",
            output,
            "",
            "stderr:",
            error,
        ]
    )


