    mkdir = _ct246_lora_run_ssh_json_v1("mkdir -p /opt/engel/tools /opt/engel/memory/training", timeout=20)
    if not mkdir.get("ok"):
        return "# CT246 LoRA Math Repair Sync Failed\n\nCould not create CT target directories.\n" + str(mkdir.get("stderr", ""))

