def handle_human_command_mode_cli(text):
    msg = str(text or "").strip()
    lower = msg.lower()
    if not msg:
        return ""

    if lower == "human command mode status":
        return hcm.build_human_command_mode_status()
    growth_reply = _handle_growth_utility_routes(msg, lower)
    if growth_reply is not None:
        return growth_reply
    complex_route_reply = _handle_complex_human_command_routes(msg, lower)
    if complex_route_reply is not None:
        return complex_route_reply
    if lower == "guarded write status":
        return hcm.build_guarded_write_status()
    if lower == "human command help":
        return human_command_help_v1()
    rust_ui_shell_reply = rust_ui_shell_bridge.handle_human_command(msg)
    if rust_ui_shell_reply is not None:
        return rust_ui_shell_reply
    rust_local_chat_reply = rust_local_chat_bridge.handle_human_command(msg)
    if rust_local_chat_reply is not None:
        return rust_local_chat_reply
    candidate_scaffold_reply = agent_skill_candidate_scaffold_command_v1(msg)
    if candidate_scaffold_reply is not None:
        return candidate_scaffold_reply
    approved_inactive_reply = agent_skill_approved_inactive_flow_command_v1(msg)
    if approved_inactive_reply is not None:
        return approved_inactive_reply
    verifier_health_check_reply = verifier_health_check_agent_manual_run_command_v1(msg)
    if verifier_health_check_reply is not None:
        return verifier_health_check_reply
    if lower in {"manual v2", "operator manual v2"}:
        return operator_manual_v2_summary()
    if lower == "python teaching mode status":
        return ptm.build_python_teaching_status()
    if lower == "python lesson help":
        return ptm.build_python_lesson_help()
    if lower.startswith("create python lesson "):
        topic = msg[len("create python lesson "):].strip()
        return ptm.create_python_lesson(topic)
    if lower.startswith("create python practice "):
        topic = msg[len("create python practice "):].strip()
        return ptm.create_python_practice(topic)
    if lower.startswith("explain python file "):
        path = msg[len("explain python file "):].strip()
        return ptm.explain_python_file(path)
    if lower.startswith("compile python lesson "):
        path = msg[len("compile python lesson "):].strip()
        return ptm.compile_python_lesson(path)
    if lower.startswith("run python lesson "):
        rest = msg[len("run python lesson "):].strip()
        path = rest
        token = ""
        if " " in rest:
            path, token = rest.rsplit(" ", 1)
        return ptm.run_python_lesson(path.strip(), token.strip())
    if lower.startswith("python concept "):
        topic = msg[len("python concept "):].strip()
        return ptm.python_concept(topic)
    if lower == "python learning path":
        return ptm.python_learning_path()
    if lower == "create python learning path report":
        return ptm.create_python_learning_path_report()
    if lower.startswith("create python teaching report "):
        topic = msg[len("create python teaching report "):].strip()
        return ptm.create_python_teaching_report(topic)

    if lower.startswith("download "):
        return (
            "# Network Download Blocked\n\n"
            "Network/download behavior requires a separate approved task with exact source, destination, rollback note, and verifier plan."
        )

    if lower.startswith("research this file "):
        msg = "research file " + msg[len("research this file "):].strip()
        lower = msg.lower()
    if lower.startswith("research file "):
        path = msg[len("research file "):].strip()
        return hcm.summarize_file_bounded(path)

    if lower.startswith("research this folder "):
        msg = "research folder " + msg[len("research this folder "):].strip()
        lower = msg.lower()
    if lower.startswith("research folder "):
        rest = msg[len("research folder "):].strip()
        folder, report_name = _human_split_keyword(rest, "to report")
        if folder and report_name:
            summary = hcm.summarize_folder_bounded(folder)
            if summary.startswith("# Folder Research Blocked"):
                return summary
            report = hcm.write_report_safely(report_name, summary, r"reports\codex_bridge")
            return summary + "\n\n" + _human_action_result_text(report)
        return hcm.summarize_folder_bounded(rest)

    if lower == "training memory status":
        return training_memory.render_status()
    if lower == "training memory preview":
        return training_memory.render_preview()
    if lower.startswith("training memory preview "):
        source = msg[len("training memory preview "):].strip()
        return training_memory.render_preview(source)
    if lower == "training memory direct write":
        return training_memory.render_write_result(training_memory.write_direct_training_trusted_memory())
    if lower.startswith("training memory direct write "):
        source = msg[len("training memory direct write "):].strip()
        return training_memory.render_write_result(training_memory.write_direct_training_trusted_memory(source))

    if lower in {"ct246 lora proof status", "engel lora proof status", "local lora proof status"}:
        return ct246_lora_proof_status_v1()
    if lower.startswith("ct246 lora proof start"):
        approval = msg[len("ct246 lora proof start"):].strip()
        return ct246_lora_proof_start_v1(approval)
    if lower.startswith("engel lora proof start"):
        approval = msg[len("engel lora proof start"):].strip()
        return ct246_lora_proof_start_v1(approval)
    if lower.startswith("local lora proof start"):
        approval = msg[len("local lora proof start"):].strip()
        return ct246_lora_proof_start_v1(approval)

    if lower.startswith("ct246 lora math repair start"):
        approval = msg[len("ct246 lora math repair start"):].strip()
        return ct246_lora_math_repair_start_v1(approval)
    if lower.startswith("engel lora math repair start"):
        approval = msg[len("engel lora math repair start"):].strip()
        return ct246_lora_math_repair_start_v1(approval)
    if lower.startswith("local lora math repair start"):
        approval = msg[len("local lora math repair start"):].strip()
        return ct246_lora_math_repair_start_v1(approval)

    if lower in {"ct246 lora canary status", "engel lora canary status", "local lora canary status"}:
        return ct246_lora_canary_status_v1()
    if lower.startswith("ct246 lora canary start"):
        approval = msg[len("ct246 lora canary start"):].strip()
        return ct246_lora_canary_start_v1(approval)
    if lower.startswith("engel lora canary start"):
        approval = msg[len("engel lora canary start"):].strip()
        return ct246_lora_canary_start_v1(approval)
    if lower.startswith("local lora canary start"):
        approval = msg[len("local lora canary start"):].strip()
        return ct246_lora_canary_start_v1(approval)

    if lower.startswith("create report "):
        report_name = msg[len("create report "):].strip()
        skeleton = "\n".join([
            "# " + (report_name.rsplit(".", 1)[0].replace("_", " ").strip() or "Human Command Report"),
            "",
            "Status: DRAFT",
            "",
            "## Notes",
            "",
            "- Created by deterministic Human Command Mode.",
            "- Report contents remain untrusted until reviewed.",
        ])
        return _human_action_result_text(hcm.write_report_safely(report_name, skeleton, r"reports\codex_bridge"))

    if lower.startswith("put this in file "):
        return "Use exact form: put text in file <path> :: <text>"
    if lower.startswith("put text in file "):
        rest = msg[len("put text in file "):].strip()
        if " :: " not in rest:
            return "Use exact form: put text in file <path> :: <text>"
        path, content = rest.split(" :: ", 1)
        return _human_action_result_text(hcm.write_file_safely(path.strip(), content, overwrite=False))

    if lower.startswith("install this here"):
        return "Use exact form: install local file <source_path> to <destination_folder>"
    if lower.startswith("install local file "):
        rest = msg[len("install local file "):].strip()
        source, destination = _human_split_keyword(rest, "to")
        if not source or not destination:
            return "Use exact form: install local file <source_path> to <destination_folder>"
        return _human_action_result_text(hcm.copy_local_file_safely(source, destination, overwrite=False))

    if lower.startswith("install model file "):
        source = msg[len("install model file "):].strip()
        return _human_action_result_text(hcm.install_model_file_safely(source))

    if lower.startswith("research and install dependency"):
        context = msg[len("research and install dependency"):].strip()
        return research_dependency_need_v1(context) + "\n\nInstall was not performed. Use dependency install plan first, then the exact APPROVE_INSTALL route."
    if lower.startswith("research dependency needed for "):
        context = msg[len("research dependency needed for "):].strip()
        return research_dependency_need_v1(context)
    if lower.startswith("research dependency need "):
        context = msg[len("research dependency need "):].strip()
        return research_dependency_need_v1(context)

    if lower.startswith("dependency install plan "):
        rest = msg[len("dependency install plan "):].strip()
        package, reason = _human_split_keyword(rest, "for")
        if not package or not reason:
            return "Use exact form: dependency install plan <package> for <reason>"
        return hcm.build_dependency_install_plan(package, reason)

    if lower.startswith("install dependency "):
        rest = msg[len("install dependency "):].strip()
        token = " APPROVE_INSTALL"
        has_token = rest.endswith(token)
        body = rest[:-len(token)].strip() if has_token else rest
        package, reason = _human_split_keyword(body, "for")
        if not package or not reason:
            return "Use exact form: install dependency <package> for <reason> APPROVE_INSTALL"
        if not has_token:
            return hcm.build_package_install_requires_approval_message(package, reason)
        return _human_action_result_text(hcm.run_approved_dependency_install(package, reason, "APPROVE_INSTALL"))

    if lower.startswith("install package "):
        package = msg[len("install package "):].strip()
        return hcm.build_package_install_requires_approval_message(package)

    if lower.startswith("request package install "):
        rest = msg[len("request package install "):].strip()
        package, reason = _human_split_keyword(rest, "for")
        if not package or not reason:
            return "Use exact form: request package install <package> for <reason>"
        return request_package_install_v1(package, reason)

    if any(phrase in lower for phrase in ["system install", "install build tools", "install visual studio", "run installer", "add to path"]):
        return "System install requires a separate approved task with exact installer/source, rollback note, and verifier plan."

    return ""


def local_communication_response_for_unrouted_text_v2comm_sanity(text):
    try:
        from engel_offline_seed_llm import offline_seed_llm_gate_enabled, run_offline_seed_llm_for_companion_chat
        llm_enabled = offline_seed_llm_gate_enabled()
        llm_fn = run_offline_seed_llm_for_companion_chat
    except Exception:
        llm_enabled = False
        llm_fn = None

    routed = route_companion_text_or_command(
        text,
        context="CLI",
        local_llm_fn=llm_fn,
        llm_enabled=llm_enabled,
    )
    intent = routed.intent
    if intent.category == "known_command":
        return ""
    if routed.route_target == "colony_hive_status":
        return colony_hive_status()
    if routed.route_target == "offline_seed_llm_status":
        return offline_seed_llm_status()
    if str(routed.route_target or "").startswith("engel."):
        return routed.response or engel_ai_update_route_status(routed.route_target)
    if intent.category in {
        "companion_greeting",
        "companion_chat",
        "companion_question",
        "human_command_candidate",
        "unsafe_or_requires_approval",
    }:
        return routed.response or build_local_companion_response(text, intent)
    return ""


def local_communication_unknown_candidate_response_v2comm_sanity(text):
    intent = classify_user_input(text)
    if intent.category == "unknown_command_candidate":
        return build_local_companion_response(text, intent)
    return ""


def guardian_allows_prompt_guard_diagnostic(text):
    lower = str(text or "").strip().lower()
    if lower in {"prompt injection status", "ai help", "ai planner status"}:
        return True
    if lower in {
        "remote worker link manager enable auto worker approve",
        "remote worker link manager enable rust control bridge approve",
        "remote worker link manager disable rust control bridge",
        "remote worker link manager rust control bridge status",
        "remote worker link manager check-now",
        "remote worker link manager enable rust bridge soak approve",
        "remote worker link manager disable rust bridge soak",
        "remote worker link manager rust bridge soak status",
        "local chat bounded run execution status",
        "local chat bounded run execute status",
        "engel main rust local chat status",
        "local chat persistent session status",
        "local chat persistent session controls status",
        "engel main rust persistent session status",
        "local chat persistent session start",
        "local chat persistent session start approved",
        "local chat persistent session stop",
        "local chat persistent session stop approved",
        "engel main rust ui bridge status",
        "rust ui shell bridge status",
        "ui shell status",
        "engel ui shell status",
        "ui shell command bridge",
        "engel ui shell command bridge",
        "ui shell verify",
        "engel ui shell verify",
        "verify ui shell",
        "engel main status",
        "engel desktop status",
        "engel companion status",
        "show engel main",
        "engel main health",
        "engel main version",
        "engel companion version",
        "engel main binaries",
        "engel main bins",
        "list engel main binaries",
        "engel main bring up",
        "engel companion bring up",
        "bring up engel main",
        "engel main setup",
        "engel main guide",
        "engel main verify",
        "engel main install",
        "engel main install approved",
        "install engel main",
        "engel main deps install",
        "pnpm install engel main",
        "engel main build",
        "engel main build approved",
        "engel companion build",
        "build engel main",
        "compile engel main",
        "engel main web build",
        "engel main dev start",
        "engel main dev start approved",
        "engel main start",
        "start engel main",
        "launch engel main",
        "engel main dev",
        "open engel companion",
        "engel main dev stop",
        "engel main dev stop approved",
        "engel main stop",
        "stop engel main",
        "kill engel main",
        "close engel companion",
        "engel main tauri build",
        "engel main tauri build approved",
        "engel companion tauri build",
        "build engel main desktop",
        "engel main full build",
        "engel main desktop build",
    }:
        return True
    return (
        lower.startswith("prompt injection check ")
        or lower.startswith("prompt injection scan file ")
        or lower.startswith("prompt injection scan folder ")
        or lower.startswith("ai classify ")
        or lower.startswith("ai plan ")
        or lower.startswith("local chat bounded run execute ")
    )


