# Patch Guard V2 - preflight risk check before edits
# ----------------------------------------------------------------------
def _patch_guard_v2_paths():
    import os
    root = globals().get("ROOT", ROOT)
    memory = globals().get("MEMORY_DIR", os.path.join(root, "memory"))
    reports = globals().get("REPORTS_DIR", os.path.join(root, "reports"))
    return {
        "root": root,
        "memory": memory,
        "reports": reports,
        "mistakes": os.path.join(memory, "MISTAKE_LOG.md"),
        "learning": os.path.join(memory, "LEARNING_LOG.md"),
        "last_check": os.path.join(memory, "PATCH_GUARD_LAST_CHECK.md"),
        "commands": os.path.join(memory, "ENGEL_COMMANDS.md"),
    }

def _patch_guard_v2_now():
    try:
        return now()
    except Exception:
        import datetime
        return datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")

def _patch_guard_v2_read(path):
    try:
        import os
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8", errors="replace") as f:
                return f.read()
    except Exception:
        pass
    return ""

def _patch_guard_v2_write(path, text):
    try:
        import os
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            f.write(text)
        return True
    except Exception:
        return False

def _patch_guard_v2_recent_backups(limit=8):
    import os
    p = _patch_guard_v2_paths()
    parent = os.path.dirname(p["root"].rstrip("\\/"))
    backups = []
    try:
        for name in os.listdir(parent):
            if name.startswith("EngelStandalone_BACKUP"):
                full = os.path.join(parent, name)
                if os.path.isdir(full):
                    backups.append((name, os.path.getmtime(full)))
        backups.sort(key=lambda x: x[1], reverse=True)
    except Exception:
        pass
    return [x[0] for x in backups[:limit]]

def _patch_guard_v2_last_mistakes(limit=4):
    p = _patch_guard_v2_paths()
    text = _patch_guard_v2_read(p["mistakes"])
    if not text.strip():
        return ["No mistake log entries found yet."]
    chunks = text.split("\n## ")
    chunks = [c.strip() for c in chunks if c.strip()]
    last = chunks[-limit:]
    out = []
    for c in last:
        c = c.replace("\r", "")
        if not c.startswith("#"):
            c = "## " + c
        out.append(c[:900])
    return out

def _patch_guard_v2_risk(plan):
    low = str(plan or "").lower()
    risk_score = 1
    reasons = []
    risky = [
        ("startup", "Touches startup/open behavior"),
        ("auto-open", "Auto-open behavior caused a recent regression pattern"),
        ("send_message", "Touches main chat routing"),
        ("engel_companion", "Touches companion UI/controller file"),
        ("button", "Touches UI button layout"),
        ("toggle", "Touches toggle behavior"),
        ("pid", "Touches process tracking"),
        ("thread", "Touches threading/process lifecycle"),
        ("delete", "Mentions delete/remove"),
        ("kill", "Mentions process kill"),
        ("subprocess", "Touches subprocess/process launching"),
        ("replace(", "May be broad string replacement"),
        ("regex", "Uses regex patching"),
        ("indent", "Indentation-sensitive change"),
        ("mobile", "Touches mobile bridge"),
        ("firewall", "Touches network/firewall"),
        ("credential", "Mentions credentials/secrets"),
        ("password", "Mentions password handling"),
    ]
    for term, reason in risky:
        if term in low:
            risk_score += 1
            reasons.append(reason)
    if len(low) > 600:
        risk_score += 1
        reasons.append("Large/complex patch description")
    if risk_score <= 2:
        label = "LOW"
    elif risk_score <= 5:
        label = "MEDIUM"
    else:
        label = "HIGH"
    if not reasons:
        reasons = ["No high-risk terms detected."]
    return label, reasons[:10]

def patch_guard_check(plan_text=""):
    plan_text = str(plan_text or "").strip()
    if not plan_text:
        plan_text = "No plan text provided. Use: patch guard check describe the exact patch/change."

    p = _patch_guard_v2_paths()
    backups = _patch_guard_v2_recent_backups()
    mistakes = _patch_guard_v2_last_mistakes()
    risk, reasons = _patch_guard_v2_risk(plan_text)

    backup_lines = ["- " + b for b in backups] if backups else ["- none found"]
    reason_lines = ["- " + r for r in reasons]

    mistake_lines = []
    for m in mistakes:
        mistake_lines.append("```")
        mistake_lines.append(m)
        mistake_lines.append("```")

    checklist = [
        "# Engel Patch Guard V2 Preflight",
        "",
        "Time: " + _patch_guard_v2_now(),
        "",
        "## Proposed Patch / Change",
        plan_text,
        "",
        "## Risk Level",
        risk,
        "",
        "## Risk Reasons",
        *reason_lines,
        "",
        "## Required Before Editing",
        "- Confirm a fresh backup exists.",
        "- Keep patch small.",
        "- Avoid broad blind replacements.",
        "- Compile-check touched Python files.",
        "- If Engel fails to open, stop and roll back immediately.",
        "- Record any regression in MISTAKE_LOG.md.",
        "",
        "## Recent Backups",
        *backup_lines,
        "",
        "## Recent Mistake Lessons",
        *mistake_lines,
        "",
        "## Recommended Next Step",
    ]

    if risk == "HIGH":
        checklist += [
            "Do not patch all at once. Split into a tiny diagnostic patch first.",
            "Avoid startup, auto-open, and main send_message routing unless absolutely necessary.",
        ]
    elif risk == "MEDIUM":
        checklist += ["Patch one file/feature at a time and compile immediately."]
    else:
        checklist += ["Proceed with normal backup -> patch -> compile -> health test."]

    checklist += [
        "",
        "Safety:",
        "- Preflight only.",
        "- No browsing.",
        "- No clicking.",
        "- No sending.",
        "- No deleting.",
    ]

    text = "\n".join(checklist)
    _patch_guard_v2_write(p["last_check"], text)
    return text

def patch_guard_last_check():
    p = _patch_guard_v2_paths()
    text = _patch_guard_v2_read(p["last_check"]).strip()
    if not text:
        return "# Patch Guard Last Check\n\nNo preflight check has been saved yet.\n\nUse:\npatch guard check describe the planned patch"
    if len(text) > 9000:
        text = text[-9000:]
    return text

def patch_guard_v2_status():
    p = _patch_guard_v2_paths()
    backups = _patch_guard_v2_recent_backups()
    return "\n".join([
        "# Patch Guard V2 Status",
        "",
        "Mode: ACTIVE / PREFLIGHT-FIRST",
        "",
        "Commands:",
        "- patch guard check describe the planned patch",
        "- patch guard last check",
        "- patch guard status",
        "- mistake note your lesson here",
        "- mistake log",
        "",
        "Files:",
        "- Last check: " + p["last_check"],
        "- Mistake log: " + p["mistakes"],
        "- Learning log: " + p["learning"],
        "",
        "Recent backups:",
        *(["- " + b for b in backups] if backups else ["- none found"]),
        "",
        "Standing rule:",
        "If a patch causes a regression, stop, diagnose, roll back, document, and patch smaller next time.",
    ])





# ----------------------------------------------------------------------
# Thinking Screen Single-Instance Repair V2
# ----------------------------------------------------------------------
def _thinking_controls_root_v2():
    return globals().get("ROOT", ROOT)

def _thinking_controls_memory_dir_v2():
    import os
    return globals().get("MEMORY_DIR", os.path.join(_thinking_controls_root_v2(), "memory"))

def _thinking_pid_file_v2():
    import os
    return os.path.join(_thinking_controls_memory_dir_v2(), "engel_research_thinking_screen.pid")

def _thinking_lock_file_v2():
    import os
    return os.path.join(_thinking_controls_memory_dir_v2(), "engel_research_thinking_screen.lock")

def _thinking_pid_alive_v2(pid):
    try:
        import ctypes
        if not pid:
            return False
        PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
        STILL_ACTIVE = 259
        handle = ctypes.windll.kernel32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, False, int(pid))
        if not handle:
            return False
        exit_code = ctypes.c_ulong()
        ok = ctypes.windll.kernel32.GetExitCodeProcess(handle, ctypes.byref(exit_code))
        ctypes.windll.kernel32.CloseHandle(handle)
        return bool(ok) and exit_code.value == STILL_ACTIVE
    except Exception:
        return False

def _thinking_processes_v2():
    import subprocess
    pids = []
    try:
        cmd = [
            "powershell", "-NoProfile", "-Command",
            "Get-CimInstance Win32_Process | Where-Object {($_.Name -eq 'python.exe' -or $_.Name -eq 'pythonw.exe') -and $_.CommandLine -like '*engel_research_thinking_screen.py*'} | Select-Object -ExpandProperty ProcessId"
        ]
        out = subprocess.check_output(cmd, text=True, errors="replace", stderr=subprocess.DEVNULL)
        for line in out.splitlines():
            line = line.strip()
            if line.isdigit():
                pids.append(int(line))
    except Exception:
        pass
    return pids

def _thinking_read_pid_v2():
    try:
        import os
        path = _thinking_pid_file_v2()
        if os.path.exists(path):
            txt = read_file(path).strip()
            if txt.isdigit():
                return int(txt)
    except Exception:
        pass
    return None

def _thinking_write_pid_v2(pid):
    try:
        import os
        path = _thinking_pid_file_v2()
        os.makedirs(os.path.dirname(path), exist_ok=True)
        write_file(path, str(pid))
    except Exception:
        pass

def _thinking_clear_pid_lock_v2():
    try:
        import os
        for path in [_thinking_pid_file_v2(), _thinking_lock_file_v2()]:
            if os.path.exists(path):
                os.remove(path)
    except Exception:
        pass

def _thinking_try_lock_v2():
    try:
        import os
        import time
        path = _thinking_lock_file_v2()
        os.makedirs(os.path.dirname(path), exist_ok=True)
        if os.path.exists(path):
            if time.time() - os.path.getmtime(path) > 8:
                os.remove(path)
        fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        os.write(fd, str(os.getpid()).encode("utf-8"))
        os.close(fd)
        return True
    except Exception:
        return False

def _thinking_unlock_v2():
    try:
        import os
        path = _thinking_lock_file_v2()
        if os.path.exists(path):
            os.remove(path)
    except Exception:
        pass

def research_thinking_screen_safe():
    import os
    import sys
    import time
    import subprocess

    existing = _thinking_processes_v2()
    if existing:
        _thinking_write_pid_v2(existing[0])
        return "\n".join([
            "# Research Thinking Screen",
            "",
            "Already open.",
            "",
            "Tracked PID: " + str(existing[0]),
            "Open screen count: " + str(len(existing)),
            "",
            "Commands:",
            "- research thinking status",
            "- research thinking off",
        ])

    pid = _thinking_read_pid_v2()
    if _thinking_pid_alive_v2(pid):
        return "# Research Thinking Screen\n\nAlready open.\n\nTracked PID: " + str(pid)

    if not _thinking_try_lock_v2():
        time.sleep(0.8)
        existing = _thinking_processes_v2()
        if existing:
            _thinking_write_pid_v2(existing[0])
            return "# Research Thinking Screen\n\nAlready opening/open.\n\nTracked PID: " + str(existing[0])
        return "# Research Thinking Screen\n\nOpen request already in progress. Try again in a second."

    try:
        existing = _thinking_processes_v2()
        if existing:
            _thinking_write_pid_v2(existing[0])
            return "# Research Thinking Screen\n\nAlready open.\n\nTracked PID: " + str(existing[0])

        root = _thinking_controls_root_v2()
        script = os.path.join(root, "engel_research_thinking_screen.py")
        if not os.path.exists(script):
            return "# Research Thinking Screen\n\nMissing script:\n" + script

        pyw = os.path.join(root, ".venv", "Scripts", "pythonw.exe")
        py = os.path.join(root, ".venv", "Scripts", "python.exe")
        exe = pyw if os.path.exists(pyw) else py if os.path.exists(py) else sys.executable

        flags = 0
        try:
            flags = subprocess.CREATE_NO_WINDOW
        except Exception:
            flags = 0

        proc = subprocess.Popen([exe, script], cwd=root, creationflags=flags)
        _thinking_write_pid_v2(proc.pid)

        return "\n".join([
            "# Research Thinking Screen",
            "",
            "Opened Engel Research Thinking screen.",
            "",
            "Tracked PID: " + str(proc.pid),
            "",
            "Safety:",
            "- Optional local screen only.",
            "- No browsing.",
            "- No clicking.",
            "- No sending.",
            "- No API use.",
        ])
    finally:
        _thinking_unlock_v2()

def research_thinking_screen():
    return research_thinking_screen_safe()

def research_thinking_status():
    import os
    existing = _thinking_processes_v2()
    pid = existing[0] if existing else _thinking_read_pid_v2()
    alive = bool(existing) or _thinking_pid_alive_v2(pid)
    if alive and pid:
        _thinking_write_pid_v2(pid)

    root = _thinking_controls_root_v2()
    live_file = os.path.join(root, "reports", "research", "RESEARCH_LIVE_STATUS.md")
    live = ""
    try:
        if os.path.exists(live_file):
            with open(live_file, "r", encoding="utf-8", errors="replace") as f:
                live = f.read().strip()
    except Exception:
        live = ""

    return "\n".join([
        "# Research Thinking Screen Status",
        "",
        "PID file:",
        _thinking_pid_file_v2(),
        "",
        "Tracked PID:",
        str(pid or "none"),
        "",
        "Screen running:",
        str(alive),
        "",
        "Open screen count:",
        str(len(existing)),
        "",
        "## Live Status",
        live if live else "No live status file yet.",
        "",
        "Safety:",
        "- Status only.",
        "- No browsing.",
        "- No sending.",
        "- No API use.",
    ])

def research_thinking_off():
    import os
    import signal
    import time
    existing = _thinking_processes_v2()
    stopped = []
    for pid in existing:
        try:
            os.kill(pid, signal.SIGTERM)
            stopped.append(pid)
        except Exception:
            try:
                os.kill(pid, 9)
                stopped.append(pid)
            except Exception:
                pass
    time.sleep(0.3)
    _thinking_clear_pid_lock_v2()
    return "\n".join([
        "# Research Thinking Screen OFF",
        "",
        "Stopped thinking screen process count: " + str(len(stopped)),
        "PIDs: " + (", ".join(map(str, stopped)) if stopped else "none"),
    ])





