def _alive_visual_settings_path_v1():
    import os
    root = globals().get("ROOT", ROOT)
    memory = globals().get("MEMORY_DIR", os.path.join(root, "memory"))
    return os.path.join(memory, "ALIVE_VISUAL_SETTINGS.json")

def _alive_visual_default_settings_v1():
    return {
        "mode": "alive",
        "intensity": 1.0,
        "pulse_ms": 850,
        "show_subtext": True,
        "orb_note": "Orb presence remains visual-only.",
    }

def _alive_visual_now_v1():
    try:
        return now()
    except Exception:
        import datetime
        return datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")

def _alive_visual_read_settings_v1():
    import json
    import os
    path = _alive_visual_settings_path_v1()
    data = _alive_visual_default_settings_v1()
    try:
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8", errors="replace") as f:
                loaded = json.load(f)
            if isinstance(loaded, dict):
                data.update(loaded)
    except Exception:
        pass
    return data

def _alive_visual_write_settings_v1(mode):
    import json
    import os

    presets = {
        "calm": {
            "mode": "calm",
            "intensity": 0.55,
            "pulse_ms": 1250,
            "show_subtext": True,
            "description": "Soft glow, slower pulse, calmer visual presence.",
        },
        "alive": {
            "mode": "alive",
            "intensity": 1.0,
            "pulse_ms": 850,
            "show_subtext": True,
            "description": "Balanced living visual presence.",
        },
        "bright": {
            "mode": "bright",
            "intensity": 1.35,
            "pulse_ms": 620,
            "show_subtext": True,
            "description": "Brighter glow and more active visual pulse.",
        },
    }

    mode = str(mode or "").strip().lower()
    if mode not in presets:
        mode = "alive"

    data = _alive_visual_default_settings_v1()
    data.update(presets[mode])
    data["updated"] = _alive_visual_now_v1()

    path = _alive_visual_settings_path_v1()
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2)

    return data

