# ----------------------------------------------------------------------
# Health Provider Check V2
# Missing brain provider config is safe, not a startup failure.
# No process launching, no cloud fallback.
# ----------------------------------------------------------------------
def _health_degraded_brain_check_v1():
    selected = _select_brain_provider_v2provider()
    chatgpt = _chatgpt_config_v2provider()
    local = _local_llm_config_v2provider()
    result = {
        "status": "PROVIDER_CONFIGURED" if selected.get("configured") else "NO_PROVIDER_CONFIGURED",
        "detail": "",
        "provider": selected.get("provider") or "none",
        "chatgpt_enabled": chatgpt["enabled"],
        "chatgpt_configured": chatgpt["configured"],
        "local_enabled": local["enabled"],
        "local_configured": local["configured"],
    }
    if result["status"] == "PROVIDER_CONFIGURED":
        result["detail"] = "A provider is explicitly configured. Health does not ping providers."
    else:
        result["detail"] = "No brain provider is configured. This is safe for startup and status-only commands."
    return result

def guardian_check():
    required_dirs = [
        ROOT,
        os.path.join(ROOT, "prompts"),
        MEMORY_DIR,
        REPORTS_DIR,
        WORKSPACE_DIR,
        APPROVED_PROJECTS_DIR
    ]

    required_files = [
        PROMPT_FILE,
        LOG_FILE,
        LEARNING_LOG,
        APPROVED_FOLDERS_FILE,
        os.path.join(MEMORY_DIR, "GUARDIAN_STATUS.md"),
        os.path.join(MEMORY_DIR, "NEXT_STEPS.md"),
        os.path.join(MEMORY_DIR, "CHANGE_LOG.md")
    ]

    lines = []
    lines.append("# Guardian Status Report")
    lines.append("")
    lines.append("Time: " + now())
    lines.append("Workspace: " + ROOT)
    lines.append("Mode: " + MODE)
    lines.append("Brain provider: " + (_select_brain_provider_v2provider().get("provider") or "none"))
    lines.append("Local model: " + str(MODEL))
    lines.append("")
    lines.append("## Directory Checks")

    core_ok = True

    for d in required_dirs:
        exists = os.path.isdir(d)
        lines.append("- " + ("OK" if exists else "MISSING") + ": " + d)
        if not exists:
            core_ok = False

    lines.append("")
    lines.append("## File Checks")

    for f in required_files:
        exists = os.path.isfile(f)
        lines.append("- " + ("OK" if exists else "MISSING") + ": " + f)
        if not exists:
            core_ok = False

    lines.append("")
    lines.append("## Approved Read-Only Folders")
    lines.append(approved_folder_text())

    lines.append("")
    lines.append("## Brain Check")

    brain = _health_degraded_brain_check_v1()
    brain_status = brain.get("status", "UNKNOWN")

    if brain_status == "PROVIDER_CONFIGURED":
        lines.append("- OK: Brain provider is configured.")
        lines.append("- Selected provider: " + str(brain.get("provider", "none")))
        lines.append("- Detail: " + str(brain.get("detail", "")))
    elif brain_status == "NO_PROVIDER_CONFIGURED":
        lines.append("- OK: No brain provider is configured; safe fallback is active.")
        lines.append("- Detail: " + str(brain.get("detail", "")))
        lines.append("- Meaning: Engel shell/safety/local commands can still run; model-dependent chat/vision/summarizing return readable fallback messages.")
    else:
        lines.append("- Provider status: " + str(brain_status))
        lines.append("- Detail: " + str(brain.get("detail", "")))

    lines.append("")
    lines.append("## Result")

    if not core_ok:
        guardian_status = "Guardian status: NEEDS ATTENTION"
    else:
        guardian_status = "Guardian status: OK"

    lines.append(guardian_status)
    lines.append("")
    lines.append("No files were edited except this Guardian status report.")

    report = "\n".join(lines)

    guardian_file = os.path.join(MEMORY_DIR, "GUARDIAN_STATUS.md")
    write_file(guardian_file, report)
    append_log("Guardian health check completed.\nReport: " + guardian_file)

    return report

def health_repair():
    import py_compile
    import traceback

    lines = []
    lines.append("# Engel Health Repair Report")
    lines.append("")
    lines.append("Time: " + now())
    lines.append("Workspace: " + ROOT)
    lines.append("Mode: " + MODE)
    lines.append("")
    lines.append("## Compile Checks")

    ok = True
    degraded = False

    files_to_check = [
        os.path.join(ROOT, "engel_app.py"),
        os.path.join(ROOT, "engel_companion.py"),
    ]

    for file_path in files_to_check:
        try:
            py_compile.compile(file_path, doraise=True)
            lines.append("- OK: " + file_path)
        except Exception:
            ok = False
            lines.append("- FAILED: " + file_path)
            lines.append("```")
            lines.append(traceback.format_exc())
            lines.append("```")

    lines.append("")
    lines.append("## Guardian Check")
    try:
        guardian = guardian_check()
        lines.append(guardian)
        if "Guardian status: NEEDS ATTENTION" in guardian:
            ok = False
        elif "Guardian status: DEGRADED" in guardian:
            degraded = True
    except Exception:
        ok = False
        lines.append("Guardian check failed:")
        lines.append("```")
        lines.append(traceback.format_exc())
        lines.append("```")

    lines.append("")
    lines.append("## Desktop Control Check")
    try:
        if "desktop_control_status" in globals():
            lines.append(desktop_control_status())
        else:
            ok = False
            lines.append("desktop_control_status is missing.")
    except Exception:
        ok = False
        lines.append("Desktop control status failed:")
        lines.append("```")
        lines.append(traceback.format_exc())
        lines.append("```")

    lines.append("")
    lines.append("## Result")
    if ok and not degraded:
        lines.append("Health repair status: OK")
        lines.append("Engel is safe to restart from the current files.")
    elif ok and degraded:
        lines.append("Health repair status: OK - NO PROVIDER CONFIGURED")
        lines.append("Engel shell, safety gates, visual controls, notes, backups, and local status commands are healthy.")
        lines.append("Model-dependent chat, summaries, and vision need an explicitly configured brain provider.")
        lines.append("Patching may continue only for non-model-dependent, local-safe changes.")
    else:
        lines.append("Health repair status: NEEDS ATTENTION")
        lines.append("Do not patch further until the failed item is fixed.")

    lines.append("")
    lines.append("Safety: This command performed checks only. It did not edit source files.")

    report = "\n".join(lines)
    report_file = os.path.join(REPORTS_DIR, "HEALTH_REPAIR_REPORT.md")
    write_file(report_file, report)
    append_log("Health repair completed.\nReport: " + report_file)

    return report


def _proposal_harvest_paths_v2night_b():
    import os
    overnight = os.path.join(REPORTS_DIR, "overnight")
    harvest = os.path.join(overnight, "proposal_harvest")
    return {
        "overnight": overnight,
        "harvest": harvest,
        "manifest": os.path.join(overnight, "OVERNIGHT_PROPOSAL_HARVEST_MANIFEST.json"),
        "latest": os.path.join(overnight, "OVERNIGHT_PROPOSAL_HARVEST_LATEST.md"),
        "history": os.path.join(REPORTS_DIR, "OVERNIGHT_RESEARCH_LOOP_HISTORY.jsonl"),
        "proposals": os.path.join(REPORTS_DIR, "research", "LEARNING_PROPOSALS.md"),
    }

def _proposal_harvest_slug_v2night_b(text, limit=72):
    import re
    slug = re.sub(r"[^a-z0-9]+", "-", str(text or "").lower()).strip("-")
    return (slug[:limit].strip("-") or "proposal")

def _proposal_harvest_norm_v2night_b(text):
    import re
    return re.sub(r"[^a-z0-9]+", " ", str(text or "").lower()).strip()

def _proposal_harvest_read_jsonl_v2night_b(path):
    import json
    import os
    rows = []
    if not os.path.exists(path):
        return rows
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    rows.append(json.loads(line))
                except Exception:
                    pass
    except Exception:
        pass
    return rows

def _proposal_harvest_infer_cycle_v2night_b(pid=None):
    import os
    p = _proposal_harvest_paths_v2night_b()
    rows = _proposal_harvest_read_jsonl_v2night_b(p["history"])
    pid_text = str(pid or os.getpid())
    for row in reversed(rows):
        if row.get("event") == "RUNNER_START" and str(row.get("runner_pid", "")) == pid_text:
            return row.get("cycle"), row.get("time", "")
    for row in reversed(rows):
        if row.get("event") == "CYCLE_START":
            return row.get("cycle"), row.get("time", "")
    return None, ""

def _proposal_harvest_extract_topic_v2night_b(status_text="", fallback=""):
    import re
    text = str(status_text or "")
    for pattern in [
        r"(?im)^Topic:\s*(.+)$",
        r"(?im)^- Topic:\s*(.+)$",
    ]:
        m = re.search(pattern, text)
        if m and m.group(1).strip():
            return m.group(1).strip()
    m = re.search(r"(?is)## Next Best Topic.*?\nTopic:\s*\n(.+?)(?:\n|$)", text)
    if m and m.group(1).strip():
        return m.group(1).strip()
    return str(fallback or "").strip()

def _proposal_harvest_cycle_for_source_v2night_b(source_file):
    import os
    p = _proposal_harvest_paths_v2night_b()
    rows = _proposal_harvest_read_jsonl_v2night_b(p["history"])
    starts = {}
    exits = {}
    topics = {}
    for row in rows:
        try:
            cycle = int(row.get("cycle"))
        except Exception:
            continue
        if row.get("event") == "CYCLE_START":
            starts[cycle] = row.get("time")
        elif row.get("event") == "RUNNER_EXIT":
            exits[cycle] = row.get("time")
        elif row.get("event") in ["TOPIC_ROTATION", "TOPIC_ROTATION_V1D"]:
            topics[cycle] = str(row.get("topic") or "")
    if not source_file or not os.path.exists(str(source_file)):
        return None, ""
    try:
        import datetime
        mtime = datetime.datetime.fromtimestamp(os.path.getmtime(str(source_file)))
        for cycle in sorted(starts):
            if cycle not in exits:
                continue
            start = datetime.datetime.strptime(str(starts[cycle]), "%Y-%m-%d %H:%M:%S")
            end = datetime.datetime.strptime(str(exits[cycle]), "%Y-%m-%d %H:%M:%S")
            if start <= mtime <= end:
                return cycle, topics.get(cycle, "")
    except Exception:
        pass
    return None, ""

def _proposal_harvest_parse_blocks_v2night_b(text):
    import re
    blocks = []
    for part in re.split(r"\n### Proposal\s+", "\n" + str(text or ""))[1:]:
        lines = part.splitlines()
        proposal_id = lines[0].strip() if lines else "UNKNOWN"
        block = "\n".join(lines[1:])

        def field(label):
            m = re.search(r"(?im)^- " + re.escape(label) + r":\s*(.+)$", block)
            return m.group(1).strip() if m else ""

        raw_type = field("Type").upper()
        proposed = field("Proposed lesson") or field("Proposed action") or field("Research fact")
        evidence = field("Evidence") or proposed
        source = field("Source")
        target = field("Target")
        try:
            score = int(field("Score") or "0")
        except Exception:
            score = 0

        if not proposed:
            continue

        if raw_type == "FACT":
            proposal_type = "RESEARCH_TOPIC"
            status = "RESEARCH_NOTE_ONLY"
            target_clean = "PROJECT_MEMORY"
        elif raw_type == "NEXT_ACTION":
            proposal_type = "NEXT_ACTION"
            status = "REVIEW_NEEDED"
            target_clean = "NEXT_STEPS.md" if "NEXT_STEPS" in target.upper() else "RESEARCH_QUEUE"
        elif raw_type == "LESSON":
            low = (proposed + " " + evidence).lower()
            if any(x in low for x in ["source-quality", "source quality", "blocked", "login", "javascript", "weak source"]):
                proposal_type = "SAFETY_RULE"
            elif any(x in low for x in ["memory", "learning_log", "facts are not lessons", "raw external facts"]):
                proposal_type = "MEMORY_HYGIENE"
            else:
                proposal_type = "LESSON"
            status = "REVIEW_NEEDED"
            target_clean = "LEARNING_LOG.md"
        else:
            proposal_type = raw_type if raw_type in ["PATCH_IDEA", "RESEARCH_TOPIC", "BUG_OR_REGRESSION"] else "RESEARCH_TOPIC"
            status = "REVIEW_NEEDED"
            target_clean = "RESEARCH_QUEUE"

        weak_evidence = (source + " " + evidence).lower()
        if any(x in weak_evidence for x in ["blocked / error", "weak source", "login", "javascript", "research brief failed"]):
            if proposal_type == "LESSON":
                proposal_type = "RESEARCH_TOPIC"
            status = "RESEARCH_NOTE_ONLY"

        blocks.append({
            "proposal_id": proposal_id,
            "proposal_type": proposal_type,
            "raw_type": raw_type,
            "source_file": source,
            "source_quality_status": "GOOD SOURCE" if "brief_latest_" in source else "SYSTEM_RULE",
            "proposed_text": proposed,
            "evidence": evidence,
            "target": target_clean,
            "score": score,
            "status": status,
        })
    return blocks

def _proposal_harvest_good_brief_count_v2night_b():
    import os
    root = os.path.join(REPORTS_DIR, "research")
    good = 0
    weak = 0
    total = 0
    if not os.path.isdir(root):
        return total, good, weak
    for name in os.listdir(root):
        if not (name.startswith("brief_latest_") and name.endswith(".md")):
            continue
        total += 1
        txt = read_file(os.path.join(root, name))
        if "Source quality: GOOD SOURCE" in txt:
            good += 1
        else:
            weak += 1
    return total, good, weak

def _proposal_harvest_manifest_existing_keys_v2night_b(manifest_path, exclude_cycle=None):
    import json
    import os
    keys = set()
    if not os.path.exists(manifest_path):
        return keys
    try:
        data = json.loads(read_file(manifest_path))
        for item in data.get("items", []):
            if exclude_cycle is not None and str(item.get("cycle")) == str(exclude_cycle):
                continue
            key = item.get("duplicate_key")
            if key:
                keys.add(key)
    except Exception:
        pass
    return keys

def overnight_proposal_harvest_review_v2night_b(cycle_hint=None, topic_hint=""):
    import json
    import os
    import shutil
    p = _proposal_harvest_paths_v2night_b()
    os.makedirs(p["harvest"], exist_ok=True)

    cycle, cycle_time = _proposal_harvest_infer_cycle_v2night_b()
    if cycle_hint not in [None, ""]:
        cycle = cycle_hint

    status_file = os.path.join(p["overnight"], "OVERNIGHT_RUNNER_STATUS.md")
    status_text = read_file(status_file)
    topic = _proposal_harvest_extract_topic_v2night_b(status_text, topic_hint)
    proposal_text = read_file(p["proposals"])
    parsed = _proposal_harvest_parse_blocks_v2night_b(proposal_text)

    if cycle_hint in [None, ""]:
        source_cycles = []
        source_topics = {}
        for raw in parsed:
            c, t = _proposal_harvest_cycle_for_source_v2night_b(raw.get("source_file", ""))
            if c is not None:
                source_cycles.append(c)
                if t:
                    source_topics[c] = t
        status_label = ""
        try:
            import re
            m = re.search(r"(?im)^Status:\s*(.+)$", status_text)
            status_label = m.group(1).strip().upper() if m else ""
        except Exception:
            status_label = ""
        if source_cycles and (cycle is None or status_label in ["", "OFF"]):
            cycle = max(source_cycles)
            if not topic:
                topic = source_topics.get(cycle, "")

    run_seen = set()
    items = []
    timestamp = now()
    cycle_label = str(cycle or "unknown")
    existing_keys = _proposal_harvest_manifest_existing_keys_v2night_b(p["manifest"], exclude_cycle=cycle)

    per_type_caps = {
        "LESSON": 3,
        "MEMORY_HYGIENE": 3,
        "SAFETY_RULE": 3,
        "NEXT_ACTION": 3,
        "PATCH_IDEA": 2,
        "RESEARCH_TOPIC": 2,
        "BUG_OR_REGRESSION": 2,
    }
    per_type_counts = {}

    for raw in parsed:
        duplicate_key = raw["proposal_type"] + ":" + _proposal_harvest_norm_v2night_b(raw["proposed_text"])[:160]
        status = raw["status"]
        if duplicate_key in existing_keys or duplicate_key in run_seen:
            status = "DUPLICATE_CANDIDATE"
        run_seen.add(duplicate_key)

        count = per_type_counts.get(raw["proposal_type"], 0)
        if count >= per_type_caps.get(raw["proposal_type"], 2):
            continue
        per_type_counts[raw["proposal_type"]] = count + 1

        item_id = "cycle_" + cycle_label + "_" + raw["proposal_id"].lower().replace(" ", "_")
        md_name = item_id + "_" + _proposal_harvest_slug_v2night_b(raw["proposal_type"]) + ".md"
        md_path = os.path.join(p["harvest"], md_name)
        item = {
            "id": item_id,
            "cycle": cycle,
            "timestamp": timestamp,
            "guided_topic": topic,
            "source_file": raw["source_file"],
            "source_quality_status": raw["source_quality_status"],
            "proposal_type": raw["proposal_type"],
            "proposed_text": raw["proposed_text"],
            "evidence": raw["evidence"],
            "target": raw["target"],
            "score": raw["score"],
            "duplicate_key": duplicate_key,
            "status": status,
            "harvest_file": md_path,
        }
        lines = [
            "# Overnight Proposal Harvest Item",
            "",
            "Time: " + timestamp,
            "Cycle: " + cycle_label,
            "Guided topic: " + (topic or "unknown"),
            "",
            "## Proposal",
            "- Type: " + item["proposal_type"],
            "- Status: " + item["status"],
            "- Score: " + str(item["score"]),
            "- Target: " + item["target"],
            "- Duplicate key: " + item["duplicate_key"],
            "",
            "## Proposed Text",
            item["proposed_text"],
            "",
            "## Evidence",
            item["evidence"],
            "",
            "## Source",
            "- Source file: " + str(item["source_file"]),
            "- Source quality status: " + str(item["source_quality_status"]),
            "",
            "Safety:",
            "- Report/read/harvest only.",
            "- No learning applied.",
            "- LEARNING_LOG.md not edited.",
            "- Source code not edited.",
        ]
        write_file(md_path, "\n".join(lines))
        items.append(item)

    archived_proposals = ""
    if os.path.exists(p["proposals"]):
        archive_name = "cycle_" + cycle_label + "_LEARNING_PROPOSALS_" + timestamp.replace(":", "-").replace(" ", "_") + ".md"
        archived_proposals = os.path.join(p["harvest"], archive_name)
        try:
            shutil.copyfile(p["proposals"], archived_proposals)
        except Exception:
            archived_proposals = ""

    total_briefs, good_briefs, weak_briefs = _proposal_harvest_good_brief_count_v2night_b()
    type_counts = {}
    topic_counts = {}
    status_counts = {}
    for item in items:
        type_counts[item["proposal_type"]] = type_counts.get(item["proposal_type"], 0) + 1
        topic_counts[item["guided_topic"] or "unknown"] = topic_counts.get(item["guided_topic"] or "unknown", 0) + 1
        status_counts[item["status"]] = status_counts.get(item["status"], 0) + 1

    manifest = {
        "version": "V2NIGHT-B",
        "generated_at": timestamp,
        "mode": "REPORT_ONLY",
        "cycle": cycle,
        "cycle_time": cycle_time,
        "guided_topic": topic,
        "source_learning_proposals_file": p["proposals"],
        "archived_learning_proposals_file": archived_proposals,
        "total_briefs_found": total_briefs,
        "good_source_briefs": good_briefs,
        "blocked_or_weak_source_briefs": weak_briefs,
        "harvested_proposal_count": len(items),
        "duplicates": status_counts.get("DUPLICATE_CANDIDATE", 0),
        "review_needed_items": status_counts.get("REVIEW_NEEDED", 0),
        "proposal_count_by_type": type_counts,
        "proposal_count_by_topic": topic_counts,
        "items": items,
        "safety": [
            "Report/read/harvest only.",
            "No learning apply.",
            "No LEARNING_LOG edit.",
            "No source-code edit.",
            "No source auto-apply.",
        ],
    }
    write_file(p["manifest"], json.dumps(manifest, indent=2))

    lines = [
        "# Overnight Proposal Harvest Latest V2NIGHT-B",
        "",
        "Time: " + timestamp,
        "Mode: REPORT ONLY",
        "",
        "## Summary",
        "- Total cycles reviewed: " + ("1" if cycle else "unknown"),
        "- Total briefs found: " + str(total_briefs),
        "- GOOD source briefs: " + str(good_briefs),
        "- Blocked/weak source briefs: " + str(weak_briefs),
        "- Harvested proposal count: " + str(len(items)),
        "- Duplicates: " + str(status_counts.get("DUPLICATE_CANDIDATE", 0)),
        "- Review-needed items: " + str(status_counts.get("REVIEW_NEEDED", 0)),
        "",
        "## Files",
        "- Harvest folder: " + p["harvest"],
        "- Manifest: " + p["manifest"],
        "- Archived current proposals: " + (archived_proposals or "none"),
        "",
        "## Proposal Count By Type",
    ]
    if type_counts:
        for key in sorted(type_counts):
            lines.append("- " + key + ": " + str(type_counts[key]))
    else:
        lines.append("- none")
    lines += ["", "## Proposal Count By Topic"]
    if topic_counts:
        for key in sorted(topic_counts):
            lines.append("- " + key + ": " + str(topic_counts[key]))
    else:
        lines.append("- none")
    lines += ["", "## Items"]
    if items:
        for item in items:
            lines.append("- " + item["id"] + " | " + item["proposal_type"] + " | " + item["status"] + " | " + item["proposed_text"][:180])
    else:
        lines.append("- none")
    lines += [
        "",
        "## Safety",
        "- Report/read/harvest only.",
        "- No learning applied.",
        "- LEARNING_LOG.md not edited.",
        "- No source code edited.",
        "- Source apply still requires V2R + APPROVE.",
    ]
    write_file(p["latest"], "\n".join(lines))
    append_log("Overnight Proposal Harvest V2NIGHT-B report created: " + p["latest"])
    return "\n".join([
        "# Overnight Proposal Harvest Review V2NIGHT-B",
        "",
        "Latest summary:",
        p["latest"],
        "",
        "Manifest:",
        p["manifest"],
        "",
        "Harvested proposal count: " + str(len(items)),
        "Review-needed items: " + str(status_counts.get("REVIEW_NEEDED", 0)),
        "Duplicates: " + str(status_counts.get("DUPLICATE_CANDIDATE", 0)),
        "",
        "Safety:",
        "- Report/write-report only.",
        "- No learning applied.",
        "- No source code edited.",
    ])

def overnight_proposal_harvest_status_v2night_b():
    import json
