    if harvest_summary.get("items"):
        for item in harvest_summary.get("items", []):
            lines.append("- " + str(item.get("id", "")) + " | " + str(item.get("proposal_type", "")) + " | " + str(item.get("status", "")) + " | " + str(item.get("target", "")) + " | " + str(item.get("proposed_text", "")))
