    lines += [""] + _morning_review_render_excerpt_block_v2night_c("Overnight Harvest Latest Excerpt", {"excerpt": harvest_latest.get("excerpt", "")})
    lines += _morning_review_render_excerpt_block_v2night_c("Learning Proposals Review", learning_review)
    lines += _morning_review_render_excerpt_block_v2night_c("Learning Apply Without APPROVE Check", learning_block)
    lines += _morning_review_render_excerpt_block_v2night_c("Tool Check: Learning Proposals Apply", tool_apply)
    lines += _morning_review_render_excerpt_block_v2night_c("Router Check: Learning Proposals Apply", router_apply)
    lines += _morning_review_render_excerpt_block_v2night_c("Router Check: Learning Proposals Apply APPROVE", router_apply_approve)
