# ----------------------------------------------------------------------
# Thinking Screen Runtime Cleanup V4
# Final override: no PowerShell/Get-CimInstance in runtime thinking commands.
# ----------------------------------------------------------------------
def _thinking_v4_root():
    return globals().get("ROOT", ROOT)

def _thinking_v4_memory():
    import os
    return globals().get("MEMORY_DIR", os.path.join(_thinking_v4_root(), "memory"))

def _thinking_v4_pid_file():
    import os
    return os.path.join(_thinking_v4_memory(), "engel_research_thinking_screen.pid")

def _thinking_v4_lock_file():
    import os
    return os.path.join(_thinking_v4_memory(), "engel_research_thinking_screen.lock")

def _thinking_v4_read_pid():
    try:
        import os
        path = _thinking_v4_pid_file()
        if os.path.exists(path):
            txt = read_file(path).strip()
            if txt.isdigit():
                return int(txt)
    except Exception:
        pass
    return None

def _thinking_v4_write_pid(pid):
    try:
        import os
        path = _thinking_v4_pid_file()
        os.makedirs(os.path.dirname(path), exist_ok=True)
        write_file(path, str(pid))
    except Exception:
        pass

def _thinking_v4_clear_files():
    try:
        import os
        for path in [_thinking_v4_pid_file(), _thinking_v4_lock_file()]:
            if os.path.exists(path):
                os.remove(path)
    except Exception:
        pass

def _thinking_v4_pid_alive(pid):
    try:
        import ctypes
        if not pid:
            return False
        PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
        STILL_ACTIVE = 259
        handle = ctypes.windll.kernel32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, False, int(pid))
        if not handle:
            return False
        exit_code = ctypes.c_ulong()
        ok = ctypes.windll.kernel32.GetExitCodeProcess(handle, ctypes.byref(exit_code))
        ctypes.windll.kernel32.CloseHandle(handle)
        return bool(ok) and exit_code.value == STILL_ACTIVE
    except Exception:
        return False

_THINKING_V4_WINDOW_TITLE = "Engel Research Thinking Screen"
_THINKING_V4_PYTHON_PROCESS_NAMES = {"python.exe", "pythonw.exe", "py.exe", "pyw.exe"}

def _thinking_v4_process_path(pid):
    try:
        import ctypes
        from ctypes import wintypes
        if not pid:
            return ""
        PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
        handle = ctypes.windll.kernel32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, False, int(pid))
        if not handle:
            return ""
        try:
            size = wintypes.DWORD(32768)
            buf = ctypes.create_unicode_buffer(size.value)
            ok = ctypes.windll.kernel32.QueryFullProcessImageNameW(handle, 0, buf, ctypes.byref(size))
            return buf.value if ok else ""
        finally:
            ctypes.windll.kernel32.CloseHandle(handle)
    except Exception:
        return ""

def _thinking_v4_process_name(pid):
    try:
        import os
        return os.path.basename(_thinking_v4_process_path(pid)).lower()
    except Exception:
        return ""

def _thinking_v4_screen_windows(pid=None):
    windows = []
    try:
        import ctypes
        from ctypes import wintypes

        user32 = ctypes.windll.user32
        enum_proc = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)

        def _callback(hwnd, _lparam):
            found_pid = wintypes.DWORD()
            user32.GetWindowThreadProcessId(hwnd, ctypes.byref(found_pid))
            if pid is not None and found_pid.value != int(pid):
                return True

            length = user32.GetWindowTextLengthW(hwnd)
            if length <= 0:
                return True

            buf = ctypes.create_unicode_buffer(length + 1)
            user32.GetWindowTextW(hwnd, buf, length + 1)
            title = buf.value
            if _THINKING_V4_WINDOW_TITLE not in title:
                return True

            windows.append({
                "hwnd": int(hwnd),
                "pid": int(found_pid.value),
                "title": title,
                "visible": bool(user32.IsWindowVisible(hwnd)),
                "minimized": bool(user32.IsIconic(hwnd)),
            })
            return True

        user32.EnumWindows(enum_proc(_callback), 0)
    except Exception:
        pass
    return windows

def _thinking_v4_focus_window(hwnd):
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32
        hwnd = int(hwnd)
        SW_SHOW = 5
        SW_RESTORE = 9
        SWP_NOSIZE = 0x0001
        SWP_NOMOVE = 0x0002
        SWP_SHOWWINDOW = 0x0040
        HWND_TOPMOST = -1
        HWND_NOTOPMOST = -2

        user32.ShowWindow(hwnd, SW_RESTORE if user32.IsIconic(hwnd) else SW_SHOW)
        user32.BringWindowToTop(hwnd)
        user32.SetWindowPos(hwnd, HWND_TOPMOST, 0, 0, 0, 0, SWP_NOMOVE | SWP_NOSIZE | SWP_SHOWWINDOW)
        user32.SetWindowPos(hwnd, HWND_NOTOPMOST, 0, 0, 0, 0, SWP_NOMOVE | SWP_NOSIZE | SWP_SHOWWINDOW)
        current_thread = kernel32.GetCurrentThreadId()
        target_pid = wintypes.DWORD()
        target_thread = user32.GetWindowThreadProcessId(hwnd, ctypes.byref(target_pid))
        foreground = user32.GetForegroundWindow()
        foreground_pid = wintypes.DWORD()
        foreground_thread = user32.GetWindowThreadProcessId(foreground, ctypes.byref(foreground_pid)) if foreground else 0
        attached_target = False
        attached_foreground = False
        try:
            if target_thread and target_thread != current_thread:
                attached_target = bool(user32.AttachThreadInput(current_thread, target_thread, True))
            if foreground_thread and foreground_thread != current_thread:
                attached_foreground = bool(user32.AttachThreadInput(current_thread, foreground_thread, True))
            ok = bool(user32.SetForegroundWindow(hwnd))
            user32.SetActiveWindow(hwnd)
            user32.SetFocus(hwnd)
            return bool(ok or user32.GetForegroundWindow() == hwnd)
        finally:
            if attached_foreground:
                user32.AttachThreadInput(current_thread, foreground_thread, False)
            if attached_target:
                user32.AttachThreadInput(current_thread, target_thread, False)
    except Exception:
        return False

def _thinking_v4_focus_tracked_window(pid):
    windows = _thinking_v4_screen_windows(pid)
    if not windows:
        return {"found": False, "visible": False, "minimized": False, "focused": False}

    target = windows[0]
    focused = _thinking_v4_focus_window(target.get("hwnd"))
    refreshed = _thinking_v4_screen_windows(pid)
    if refreshed:
        target = refreshed[0]
    return {
        "found": True,
        "visible": bool(target.get("visible")),
        "minimized": bool(target.get("minimized")),
        "focused": bool(focused),
    }

def _thinking_v4_is_screen_process_candidate(pid):
    if not _thinking_v4_pid_alive(pid):
        return False
    if _thinking_v4_screen_windows(pid):
        return True
    return _thinking_v4_process_name(pid) in _THINKING_V4_PYTHON_PROCESS_NAMES

def _thinking_v4_can_stop_screen_candidate(pid):
    if not _thinking_v4_pid_alive(pid):
        return False
    if _thinking_v4_screen_windows(pid):
        return True
    return _thinking_v4_process_name(pid) in {"python.exe", "pythonw.exe"}

def _thinking_v4_close_screen_candidate(pid):
    import os
    import signal
    import time

    closed_window = False
    stopped_process = False
    skipped_reason = ""

    windows = _thinking_v4_screen_windows(pid)
    if windows:
        try:
            import ctypes
            WM_CLOSE = 0x0010
            ctypes.windll.user32.PostMessageW(int(windows[0].get("hwnd")), WM_CLOSE, 0, 0)
            closed_window = True
            time.sleep(0.6)
        except Exception:
            closed_window = False

    if _thinking_v4_pid_alive(pid):
        if _thinking_v4_can_stop_screen_candidate(pid):
            try:
                os.kill(int(pid), signal.SIGTERM)
                stopped_process = True
            except Exception:
                try:
                    os.kill(int(pid), 9)
                    stopped_process = True
                except Exception:
                    stopped_process = False
        else:
            skipped_reason = "Tracked PID is not a verified Research Thinking Screen process."

    return {
        "closed_window": bool(closed_window),
        "stopped_process": bool(stopped_process),
        "skipped_reason": skipped_reason,
    }

def _thinking_v4_add_python_candidate(candidates, seen, args, label):
    try:
        import os
        exe = args[0]
        if not exe or not os.path.exists(exe):
            return
        key = tuple(os.path.normcase(os.path.abspath(part)) if i == 0 else part for i, part in enumerate(args))
        if key in seen:
            return
        if os.path.basename(exe).lower() == "engel.exe":
            return
        candidates.append((args, label))
        seen.add(key)
    except Exception:
        pass

def _thinking_v4_python_commands(script):
    import glob
    import os
    import shutil
    import sys

    root = _thinking_v4_root()
    candidates = []
    seen = set()

    _thinking_v4_add_python_candidate(
        candidates,
        seen,
        [os.path.join(root, ".venv", "Scripts", "pythonw.exe"), script],
        "project .venv pythonw.exe",
    )
    _thinking_v4_add_python_candidate(
        candidates,
        seen,
        [os.path.join(root, ".venv", "Scripts", "python.exe"), script],
        "project .venv python.exe",
    )

    if not getattr(sys, "frozen", False):
        _thinking_v4_add_python_candidate(candidates, seen, [sys.executable, script], "current source Python")

    base_exe = getattr(sys, "_base_executable", "")
    _thinking_v4_add_python_candidate(candidates, seen, [base_exe, script], "base Python executable")

    for name in ["pythonw.exe", "python.exe"]:
        _thinking_v4_add_python_candidate(candidates, seen, [shutil.which(name) or "", script], "PATH " + name)

    search_roots = [
        os.path.join(os.environ.get("LOCALAPPDATA", ""), "Programs", "Python"),
        os.environ.get("ProgramFiles", ""),
        os.environ.get("ProgramFiles(x86)", ""),
    ]
    for search_root in search_roots:
        if not search_root:
            continue
        for exe in sorted(glob.glob(os.path.join(search_root, "Python*", "pythonw.exe")), reverse=True):
            _thinking_v4_add_python_candidate(candidates, seen, [exe, script], "installed pythonw.exe")
        for exe in sorted(glob.glob(os.path.join(search_root, "Python*", "python.exe")), reverse=True):
            _thinking_v4_add_python_candidate(candidates, seen, [exe, script], "installed python.exe")

    return candidates

def _thinking_v4_try_lock():
    try:
        import os
        import time
        path = _thinking_v4_lock_file()
        os.makedirs(os.path.dirname(path), exist_ok=True)

        if os.path.exists(path):
            if time.time() - os.path.getmtime(path) > 8:
                os.remove(path)

        fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        os.write(fd, str(os.getpid()).encode("utf-8"))
        os.close(fd)
        return True
    except Exception:
        return False

def _thinking_v4_unlock():
    try:
        import os
        path = _thinking_v4_lock_file()
        if os.path.exists(path):
            os.remove(path)
    except Exception:
        pass

def research_thinking_screen_safe():
    import os
    import time
    import subprocess

    pid = _thinking_v4_read_pid()
    if _thinking_v4_pid_alive(pid):
        if not _thinking_v4_is_screen_process_candidate(pid):
            stale_name = _thinking_v4_process_name(pid) or "unknown"
            _thinking_v4_clear_files()
        else:
            focus = _thinking_v4_focus_tracked_window(pid)
            if focus.get("found"):
                return "\n".join([
                    "# Research Thinking Screen",
                    "",
                    "Brought existing Research Thinking Screen to front.",
                    "",
                    "Tracked PID: " + str(pid),
                    "Screen running: True",
                    "Window found: True",
                    "Window visible: " + str(focus.get("visible")),
                    "Focus requested: " + str(focus.get("focused")),
                    "Open screen count: 1",
                    "",
                    "Commands:",
                    "- research thinking status",
                    "- research thinking off",
                ])

            recovery = _thinking_v4_close_screen_candidate(pid)
            _thinking_v4_clear_files()
            stale_name = _thinking_v4_process_name(pid) or "screen process"
            return "\n".join([
                "# Research Thinking Screen",
                "",
                "Screen process was running but no visible Research Thinking Screen window was found.",
                "Cleared stale screen tracker and stopped only the tracked screen candidate: " + str(recovery.get("stopped_process")),
                "Open Research Thinking Screen again to launch a fresh visible window.",
                "",
                "Tracked PID: " + str(pid),
                "Process name: " + stale_name,
                "Window found: False",
                "Skipped reason: " + (recovery.get("skipped_reason") or "none"),
            ])

    stale_note = ""
    if pid:
        stale_note = "Cleared stale screen tracker for PID " + str(pid) + "."

    existing_windows = _thinking_v4_screen_windows()
    if existing_windows:
        existing_pid = existing_windows[0].get("pid")
        _thinking_v4_write_pid(existing_pid)
        focus = _thinking_v4_focus_tracked_window(existing_pid)
        return "\n".join([
            "# Research Thinking Screen",
            "",
            "Brought existing Research Thinking Screen to front.",
            "",
            "Tracked PID: " + str(existing_pid),
            "Screen running: " + str(_thinking_v4_pid_alive(existing_pid)),
            "Window found: True",
            "Window visible: " + str(focus.get("visible")),
            "Focus requested: " + str(focus.get("focused")),
            "Open screen count: 1",
            "",
            "Commands:",
            "- research thinking status",
            "- research thinking off",
        ])

    if not _thinking_v4_try_lock():
        time.sleep(0.5)
        pid = _thinking_v4_read_pid()
        if _thinking_v4_pid_alive(pid):
            focus = _thinking_v4_focus_tracked_window(pid)
            if focus.get("found"):
                return "# Research Thinking Screen\n\nBrought existing Research Thinking Screen to front.\n\nTracked PID: " + str(pid) + "\nOpen screen count: 1"
        return "# Research Thinking Screen\n\nOpen request already in progress. Try again in a second."

    try:
        pid = _thinking_v4_read_pid()
        if _thinking_v4_pid_alive(pid):
            if _thinking_v4_is_screen_process_candidate(pid):
                focus = _thinking_v4_focus_tracked_window(pid)
                if focus.get("found"):
                    return "# Research Thinking Screen\n\nBrought existing Research Thinking Screen to front.\n\nTracked PID: " + str(pid) + "\nOpen screen count: 1"
                recovery = _thinking_v4_close_screen_candidate(pid)
                _thinking_v4_clear_files()
                stale_note = "Cleared stale screen tracker for PID " + str(pid) + "; stopped tracked screen candidate: " + str(recovery.get("stopped_process")) + "."
            else:
                stale_note = "Cleared stale screen tracker for non-screen PID " + str(pid) + " (" + (_thinking_v4_process_name(pid) or "unknown") + ")."
                _thinking_v4_clear_files()

        root = _thinking_v4_root()
        script = os.path.join(root, "engel_research_thinking_screen.py")
        if not os.path.exists(script):
            return "# Research Thinking Screen\n\nMissing script:\n" + script

        flags = 0
        try:
            flags = subprocess.CREATE_NO_WINDOW
        except Exception:
            flags = 0

        launch_errors = []
        proc = None
        launch_label = ""
        alive = False
        focus = {"found": False, "visible": False, "focused": False}
        for command, label in _thinking_v4_python_commands(script):
            try:
                proc = subprocess.Popen(command, cwd=root, creationflags=flags)
                _thinking_v4_write_pid(proc.pid)
                launch_label = label
                time.sleep(0.8)
                alive = _thinking_v4_pid_alive(proc.pid)
                if alive:
                    for _ in range(10):
                        focus = _thinking_v4_focus_tracked_window(proc.pid)
                        if focus.get("found"):
                            break
                        time.sleep(0.2)
                    if focus.get("found"):
                        break
                    recovery = _thinking_v4_close_screen_candidate(proc.pid)
                    launch_errors.append(label + " started but no Research Thinking Screen window was found; stopped tracked candidate: " + str(recovery.get("stopped_process")))
                    _thinking_v4_clear_files()
                    alive = False
                    continue
                launch_errors.append(label + " exited before the screen stayed open.")
            except Exception as e:
                launch_errors.append(label + " failed: " + str(e))

        if proc is None or not alive:
            _thinking_v4_clear_files()
            return "\n".join([
                "# Research Thinking Screen",
                "",
                "Could not open a visible Research Thinking Screen.",
                "",
                "Recovery:",
                "- Install/restore the project .venv Python, or launch from source Python.",
                "- The screen script was not started.",
                "",
                "Launch notes: " + ("; ".join(launch_errors) if launch_errors else "none"),
            ])

        return "\n".join([
            "# Research Thinking Screen",
            "",
            "Opened Research Thinking Screen." if alive else "Tried to open Research Thinking Screen, but process is not alive.",
            stale_note,
            "",
            "Tracked PID: " + str(proc.pid),
            "Screen running: " + str(alive),
            "Window found: " + str(focus.get("found")),
            "Window visible: " + str(focus.get("visible")),
            "Focus requested: " + str(focus.get("focused")),
            "Open screen count: " + ("1" if alive else "0"),
            "Launch executable: " + launch_label,
            "Launch notes: " + ("; ".join(launch_errors) if launch_errors else "none"),
            "",
            "Safety:",
            "- Optional local screen only.",
            "- No browsing.",
            "- No clicking.",
            "- No sending.",
            "- No API use.",
        ])
    finally:
        _thinking_v4_unlock()

def research_thinking_screen():
    return research_thinking_screen_safe()

def research_thinking_status():
    import os

    pid = _thinking_v4_read_pid()
    alive = _thinking_v4_pid_alive(pid)
    process_name = _thinking_v4_process_name(pid) if alive else ""
    process_path = _thinking_v4_process_path(pid) if alive else ""
    windows = _thinking_v4_screen_windows(pid) if alive else []
    window_found = bool(windows)
    window_visible = bool(windows and windows[0].get("visible"))
    window_minimized = bool(windows and windows[0].get("minimized"))
    screen_candidate = bool(alive and _thinking_v4_is_screen_process_candidate(pid))
    recovery = "No recovery needed."

    if not alive:
        _thinking_v4_clear_files()
        pid = None
        recovery = "Tracker was stale or empty. Open Research Thinking Screen to launch it."
    elif not screen_candidate:
        recovery = "Tracked PID is alive but is not the Research Thinking Screen. Open Research Thinking Screen again to clear the stale tracker and relaunch."
    elif not window_found:
        recovery = "Screen process is running but no visible window was found. Open Research Thinking Screen again to recover, or run research thinking off."
    elif window_minimized or not window_visible:
        recovery = "Screen window exists but is minimized or hidden. Open Research Thinking Screen again to bring it forward."

    root = _thinking_v4_root()
    live_file = os.path.join(root, "reports", "research", "RESEARCH_LIVE_STATUS.md")
    live = ""
    try:
        if os.path.exists(live_file):
            with open(live_file, "r", encoding="utf-8", errors="replace") as f:
                live = f.read().strip()
    except Exception:
        live = ""

    return "\n".join([
        "# Research Thinking Screen Status",
        "",
        "PID file:",
        _thinking_v4_pid_file(),
        "",
        "Tracked PID:",
        str(pid or "none"),
        "",
        "Screen running:",
        str(alive),
        "",
        "Process name:",
        process_name if process_name else "none",
        "",
        "Process path:",
        process_path if process_path else "none",
        "",
        "Screen process candidate:",
        str(screen_candidate),
        "",
        "Window found:",
        str(window_found),
        "",
        "Window visible:",
        str(window_visible),
        "",
        "Window minimized:",
        str(window_minimized),
        "",
        "Open screen count:",
        "1" if window_found else "0",
        "",
        "Recovery:",
        recovery,
        "",
        "Runtime:",
        "V4 local PID/window recovery; no provider, network, browser, or background worker.",
        "",
        "## Live Status",
        live if live else "No live status file yet.",
        "",
        "Safety:",
        "- Status only.",
        "- No browsing.",
        "- No sending.",
        "- No API use.",
    ])


# ----------------------------------------------------------------------
# Research Thinking Status Truth Fix V2U-C
# If the research loop is OFF, old RUNNING_RESEARCH live-status text is
# marked historical/stale instead of being shown as active.
# Status/report only. No process start/stop.
# ----------------------------------------------------------------------
_research_thinking_status_base_v2uc = research_thinking_status

def _research_loop_off_truth_v2uc():
    import os
    import re

    status_path = os.path.join(REPORTS_DIR, "OVERNIGHT_RESEARCH_LOOP_STATUS.md")
    if not os.path.exists(status_path):
        return False, status_path, ""

    text = read_file(status_path)
    stage_off = bool(re.search(r"(?im)^Stage:\s*OFF\s*$", text))
    runner_none = bool(re.search(r"(?im)^Runner PID:\s*none\s*$", text))

    return bool(stage_off and runner_none), status_path, text

def research_thinking_status():
    base = _research_thinking_status_base_v2uc()

    try:
        loop_off, loop_status_path, loop_status_text = _research_loop_off_truth_v2uc()
    except Exception:
        return base

    if not loop_off:
        return base

    stale_markers = [
        "Stage: RUNNING_RESEARCH",
        "Stage: QUEUE_CLEANUP",
        "Stage: DIGESTING",
        "Stage: STARTING",
        "Approved research cycle is running",
    ]

    if "## Live Status" not in base:
        return base + "\n\n## Research Loop Truth V2U-C\n\nCurrent research loop status: OFF.\n\nSafety:\n- Status only.\n- No process launched.\n- No browsing/sending/deleting."

    head, live = base.split("## Live Status", 1)
    live_is_stale = any(marker in live for marker in stale_markers)

    if not live_is_stale:
        return base + "\n\n## Research Loop Truth V2U-C\n\nCurrent research loop status: OFF.\n\nSafety:\n- Status only.\n- No process launched."

    return "\n".join([
        head.rstrip(),
        "",
        "## Live Status Reconciled V2U-C",
        "",
        "Current research loop status: OFF.",
        "",
        "The previous live-status file is stale/historical. It is not an active research run.",
        "",
        "Loop status file:",
        loop_status_path,
        "",
        "Historical live status:",
        "",
        "## Live Status",
        live.strip(),
        "",
        "Safety:",
        "- Status only.",
        "- No research process launched.",
        "- No process stopped.",
        "- No browsing.",
        "- No sending.",
        "- No deleting.",
        "- No cloud fallback.",
    ])


def research_thinking_off():
    import time

    pid = _thinking_v4_read_pid()
    alive_before = _thinking_v4_pid_alive(pid)
    process_name = _thinking_v4_process_name(pid) if alive_before else ""
    process_path = _thinking_v4_process_path(pid) if alive_before else ""
    window_found = bool(_thinking_v4_screen_windows(pid)) if alive_before else False
    result = {"closed_window": False, "stopped_process": False, "skipped_reason": ""}

    if pid and alive_before:
        result = _thinking_v4_close_screen_candidate(pid)

    time.sleep(0.3)
    _thinking_v4_clear_files()
    alive_after = _thinking_v4_pid_alive(pid)

    return "\n".join([
        "# Research Thinking Screen OFF",
        "",
        "Closed visible screen window: " + str(result.get("closed_window")),
        "Stopped tracked screen process: " + str(result.get("stopped_process")),
        "Skipped reason: " + (result.get("skipped_reason") or "none"),
        "PID: " + str(pid or "none"),
        "Was alive before OFF: " + str(alive_before),
        "Alive after OFF: " + str(alive_after),
        "Window found before OFF: " + str(window_found),
        "Process name: " + (process_name or "none"),
        "Process path: " + (process_path or "none"),
        "",
        "Tracker cleared: True",
    ])


