def _research_goals_hook_paths_v1():
    import os
    root = globals().get("ROOT", ROOT)
    memory = globals().get("MEMORY_DIR", os.path.join(root, "memory"))
    reports = globals().get("REPORTS_DIR", os.path.join(root, "reports"))
    return {
        "queue": os.path.join(memory, "RESEARCH_GOALS_QUEUE_V1.md"),
        "active": os.path.join(memory, "RESEARCH_GOALS_ACTIVE_V1.json"),
        "state": os.path.join(memory, "RESEARCH_GOALS_HOOK_V1.json"),
        "report_dir": os.path.join(reports, "research_goals"),
        "report": os.path.join(reports, "research_goals", "RESEARCH_GOALS_HOOK_V1_STATUS.md"),
        "rotation": os.path.join(memory, "OVERNIGHT_TOPIC_ROTATION.json"),
        "rotation_report": os.path.join(reports, "OVERNIGHT_TOPIC_ROTATION_STATUS.md"),
        "runner_status": os.path.join(reports, "overnight", "OVERNIGHT_RUNNER_STATUS.md"),
    }


def _research_goals_hook_now_v1():
    try:
        return now()
    except Exception:
        import datetime
        return datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def _research_goals_hook_read_text_v1(path):
    try:
        if "read_file" in globals():
            return read_file(path)
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            return f.read()
    except Exception:
        return ""


def _research_goals_hook_norm_v1(text):
    import re
    t = str(text or "").strip().lower()
    t = re.sub(r"^\s*\[(\d+)\]\s*", "", t)
    t = re.sub(r"\s+#.*$", "", t)
    t = re.sub(r"\s*\(cooldown[^)]*\)\s*$", "", t, flags=re.I)
    t = re.sub(r"[^a-z0-9 ]", " ", t)
    return re.sub(r"\s+", " ", t).strip()


def _research_goals_hook_extract_topics_v1(text):
    import re
    topics = []
    for raw in str(text or "").splitlines():
        m = re.match(r"^\s*\d+\.\s+(.+?)\s*$", raw)
        if not m:
            continue
        topic = re.sub(r"\s+", " ", m.group(1).strip())
        if topic:
            topics.append(topic)

    seen = set()
    out = []
    for topic in topics:
        key = _research_goals_hook_norm_v1(topic)
        if not key or key in seen:
            continue
        seen.add(key)
        out.append(topic)
    return out


def _research_goals_hook_active_v1():
    import json, os
    p = _research_goals_hook_paths_v1()
    default = {
        "mode": "missing",
        "research_may_use_as_guidance": False,
        "auto_apply_learning": False,
        "auto_apply_source": False,
        "cloud_fallback": False,
        "approval_gates_preserved": True,
    }
    if not os.path.exists(p["active"]):
        return default
    try:
        data = json.loads(_research_goals_hook_read_text_v1(p["active"]))
        if isinstance(data, dict):
            default.update(data)
    except Exception:
        default["mode"] = "read_error"
        default["research_may_use_as_guidance"] = False
    return default


def _research_goals_hook_recent_topics_v1():
    import json, os, re
    p = _research_goals_hook_paths_v1()
    recent = set()

    try:
        if os.path.exists(p["rotation"]):
            data = json.loads(_research_goals_hook_read_text_v1(p["rotation"]))
            if isinstance(data, dict):
                completed = data.get("completed_topics", [])
                if isinstance(completed, dict):
                    for key in completed.keys():
                        norm = _research_goals_hook_norm_v1(key)
                        if norm:
                            recent.add(norm)
                if isinstance(completed, list):
                    for item in completed[-50:]:
                        topic = item.get("topic") if isinstance(item, dict) else item
                        norm = _research_goals_hook_norm_v1(topic)
                        if norm:
                            recent.add(norm)
                cooldown = data.get("cooldown", {})
                if isinstance(cooldown, dict):
                    for key in cooldown.keys():
                        norm = _research_goals_hook_norm_v1(key)
                        if norm:
                            recent.add(norm)
    except Exception:
        pass

    for path in [p["rotation_report"], p["runner_status"]]:
        try:
            if not os.path.exists(path):
                continue
            txt = _research_goals_hook_read_text_v1(path)
            for m in re.findall(r"(?im)^Detected completed topic:\s*\n\s*(.+?)\s*$", txt):
                norm = _research_goals_hook_norm_v1(m)
                if norm and norm != "none":
                    recent.add(norm)
            for m in re.findall(r"(?im)^Topic:\s*\n\s*(.+?)\s*$", txt):
                norm = _research_goals_hook_norm_v1(m)
                if norm and norm != "none":
                    recent.add(norm)
        except Exception:
            pass

    return recent


def research_goals_hook_select_v1(reason="status", write_status=False):
    import json, os
    p = _research_goals_hook_paths_v1()
    active = _research_goals_hook_active_v1()
    queue_exists = os.path.exists(p["queue"])
    queue_text = _research_goals_hook_read_text_v1(p["queue"]) if queue_exists else ""
    topics = _research_goals_hook_extract_topics_v1(queue_text)
    recent = _research_goals_hook_recent_topics_v1()

    enabled = bool(active.get("research_may_use_as_guidance")) and bool(active.get("approval_gates_preserved", True))
    enabled = enabled and not bool(active.get("auto_apply_learning"))
    enabled = enabled and not bool(active.get("auto_apply_source"))
    enabled = enabled and not bool(active.get("cloud_fallback"))

    selected = ""
    fallback = "existing overnight queue behavior unchanged"
    hook_mode = "report-only"
    if not queue_exists:
        fallback = "goal queue missing; existing overnight queue behavior unchanged"
    elif not enabled:
        fallback = "goal hook inactive or safety metadata invalid; existing overnight queue behavior unchanged"
    elif not topics:
        fallback = "no numbered goal topics found; existing overnight queue behavior unchanged"
    else:
        for topic in topics:
            if _research_goals_hook_norm_v1(topic) not in recent:
                selected = topic
                break
        if selected:
            hook_mode = "active"
            fallback = "not used for this cycle because guided topic is available"
        else:
            fallback = "all goal topics appear recently completed/cooldown; existing overnight queue behavior unchanged"

    state = {
        "time": _research_goals_hook_now_v1(),
        "reason": str(reason or ""),
        "queue_exists": queue_exists,
        "active_mode": str(active.get("mode", "unknown")),
        "topics_found": len(topics),
        "hook_mode": hook_mode,
        "selected_topic": selected,
        "fallback_behavior": fallback,
        "safety": {
            "no_source_auto_apply": True,
            "no_learning_auto_apply": True,
            "no_cloud_fallback": True,
            "no_login_click_send_delete_payment_system": True,
            "source_quality_gate_active": True,
            "research_on_off_owner": True,
        },
    }

    if write_status:
        os.makedirs(p["report_dir"], exist_ok=True)
        os.makedirs(os.path.dirname(p["state"]), exist_ok=True)
        with open(p["state"], "w", encoding="utf-8") as f:
            json.dump(state, f, indent=2)
        lines = [
            "# Research Goals Hook V1 Status",
            "",
            "Time: " + state["time"],
            "",
            "Goal queue exists: " + str(queue_exists),
            "Active mode: " + state["active_mode"],
            "Goal topics found: " + str(len(topics)),
            "Hook mode: " + hook_mode,
            "Latest selected topic: " + (selected if selected else "none"),
            "Fallback behavior: " + fallback,
            "",
            "Files:",
            "- Goal queue: " + p["queue"],
            "- Active state: " + p["active"],
            "- Hook state: " + p["state"],
            "- Hook report: " + p["report"],
            "",
            "Safety rules:",
            "- Guided topic selection only.",
            "- No source auto-apply.",
            "- No learning auto-apply.",
            "- No cloud fallback.",
            "- No login/click/send/delete/payment/system changes.",
            "- Source-quality gate remains active.",
            "- Research ON/OFF remains owner of long-running research.",
            "- Goal queue items are not deleted.",
        ]
        with open(p["report"], "w", encoding="utf-8") as f:
            f.write("\n".join(lines) + "\n")

    return state


def research_goals_hook_status_v1():
    import json, os
    p = _research_goals_hook_paths_v1()
    active = _research_goals_hook_active_v1()
    queue_exists = os.path.exists(p["queue"])
    queue_text = _research_goals_hook_read_text_v1(p["queue"]) if queue_exists else ""
    topics = _research_goals_hook_extract_topics_v1(queue_text)
    latest = {}
    if os.path.exists(p["state"]):
        try:
            loaded = json.loads(_research_goals_hook_read_text_v1(p["state"]))
            if isinstance(loaded, dict):
                latest = loaded
        except Exception:
            latest = {}

    enabled = bool(active.get("research_may_use_as_guidance")) and bool(active.get("approval_gates_preserved", True))
    enabled = enabled and not bool(active.get("auto_apply_learning"))
    enabled = enabled and not bool(active.get("auto_apply_source"))
    enabled = enabled and not bool(active.get("cloud_fallback"))

    hook_mode = "active" if enabled and queue_exists and topics else "report-only"
    fallback = "existing overnight queue behavior unchanged when no valid goal topic is available"

    lines = [
        "# Research Goals Hook V1 Status",
        "",
        "Time: " + _research_goals_hook_now_v1(),
        "",
        "Goal queue exists: " + str(queue_exists),
        "Active mode: " + str(active.get("mode", "unknown")),
        "Goal topics found: " + str(len(topics)),
        "Hook enabled/report-only/active: " + hook_mode,
        "Latest selected topic: " + str(latest.get("selected_topic") or "none"),
        "Fallback behavior: " + str(latest.get("fallback_behavior") or fallback),
        "",
        "Files:",
        "- Goal queue: " + p["queue"],
        "- Active state: " + p["active"],
        "- Hook state: " + p["state"],
        "- Hook report: " + p["report"],
        "",
        "Safety rules:",
        "- Status/report only for this command.",
        "- No source auto-apply.",
        "- No learning auto-apply.",
        "- No cloud fallback.",
        "- No login/click/send/delete/payment/system changes.",
        "- Source-quality gate stays active.",
        "- Research ON/OFF remains owner of long-running research.",
        "- Goal queue items are not deleted.",
    ]

    return "\n".join(lines)



# Brain Provider Layer V2
# Provider-gated brain layer + MAS communication protocol status.
# No provider is required for startup. No process launching.
# ----------------------------------------------------------------------
def _brain_backend_paths_v1():
    import os
    root = globals().get("ROOT", ROOT)
    memory = globals().get("MEMORY_DIR", os.path.join(root, "memory"))
    reports = globals().get("REPORTS_DIR", os.path.join(root, "reports"))
    return {
        "memory": memory,
        "reports": reports,
        "backends": os.path.join(memory, "BRAIN_BACKENDS.json"),
        "protocol": os.path.join(memory, "MAS_AGENT_PROTOCOL.md"),
        "bus": os.path.join(memory, "MAS_MESSAGE_BUS.jsonl"),
        "status": os.path.join(reports, "BRAIN_BACKEND_STATUS.md"),
    }

def _brain_backend_now_v1():
    try:
        return now()
    except Exception:
        import datetime
        return datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")

def _brain_backend_default_v1():
    return {
        "version": "2.0",
        "active_provider": "",
        "policy": {
            "no_provider_required_for_startup": True,
            "no_cloud_provider_without_explicit_enable": True,
            "do_not_auto_start_runners": True,
            "approval_required_for_memory_or_source_apply": True,
            "no_secrets_written_to_repo": True
        },
        "providers": {
            "local_offline": {
                "type": "generic_local_offline",
                "status": "available_when_configured",
                "enabled_env": "ENGEL_LOCAL_LLM_ENABLED",
                "provider_env": "ENGEL_LOCAL_LLM_PROVIDER",
                "endpoint_env": "ENGEL_LOCAL_LLM_ENDPOINT",
                "model_env": "ENGEL_LOCAL_LLM_MODEL",
                "notes": "Generic local/offline provider slot. No built-in runner dependency."
            },
            "chatgpt": {
                "type": "online_llm",
                "status": "available_when_explicitly_enabled_and_configured",
                "enabled_env": "ENGEL_ONLINE_LLM_ENABLED",
                "provider_env": "ENGEL_ONLINE_LLM_PROVIDER",
                "key_env": "OPENAI_API_KEY",
                "model_env": "ENGEL_ONLINE_LLM_MODEL",
                "notes": "Preferred online LLM provider when explicitly enabled and configured."
            }
        },
        "research_search": {
            "provider": "gemini",
            "status": "available_when_explicitly_enabled_and_configured",
            "enabled_env": "ENGEL_GEMINI_SEARCH_ENABLED",
            "provider_env": "ENGEL_RESEARCH_SEARCH_PROVIDER",
            "key_env": "GEMINI_API_KEY",
            "notes": "Provider-gated overnight research search/enrichment only."
        },
        "spell_check": {
            "enabled_env": "ENGEL_SPELL_CHECK_ENABLED",
            "default_enabled": False,
            "mode": "safe_noop"
        }
    }

def _brain_backend_read_v1():
    import json
    import os
    p = _brain_backend_paths_v1()
    data = _brain_backend_default_v1()
    try:
        if os.path.exists(p["backends"]):
            with open(p["backends"], "r", encoding="utf-8", errors="replace") as f:
                loaded = json.load(f)
            if isinstance(loaded, dict):
                if str(loaded.get("active_provider", "")).strip() in data["providers"]:
                    data["active_provider"] = str(loaded.get("active_provider", "")).strip()
                if isinstance(loaded.get("policy"), dict):
                    data["policy"].update(loaded.get("policy"))
                if isinstance(loaded.get("providers"), dict):
                    for name in list(data["providers"].keys()):
                        if isinstance(loaded["providers"].get(name), dict):
                            data["providers"][name].update(loaded["providers"][name])
                if isinstance(loaded.get("research_search"), dict):
                    data["research_search"].update(loaded["research_search"])
                if isinstance(loaded.get("spell_check"), dict):
                    data["spell_check"].update(loaded["spell_check"])
    except Exception:
        pass
    return data

def _brain_backend_write_v1(data):
    import json
    import os
    p = _brain_backend_paths_v1()
    os.makedirs(os.path.dirname(p["backends"]), exist_ok=True)
    with open(p["backends"], "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2)

def brain_backend_status():
    data = _brain_backend_read_v1()
    selected = _select_brain_provider_v2provider()
    chatgpt = _chatgpt_config_v2provider()
