# ----------------------------------------------------------------------
# Overnight Research Loop V1
# Repeats approved research cycles until overnight loop OFF.
# No cloud fallback. No login/sending/deleting. Starts only by explicit command.
# ----------------------------------------------------------------------
def _overnight_loop_paths_v1():
    import os
    root = globals().get("ROOT", ROOT)
    memory = globals().get("MEMORY_DIR", os.path.join(root, "memory"))
    reports = globals().get("REPORTS_DIR", os.path.join(root, "reports"))
    return {
        "root": root,
        "memory": memory,
        "reports": reports,
        "script": os.path.join(root, "engel_overnight_loop.py"),
        "runner": os.path.join(root, "engel_overnight_runner.py"),
        "pid": os.path.join(memory, "overnight_research_loop.pid"),
        "stop": os.path.join(memory, "overnight_research_loop.stop"),
        "status": os.path.join(reports, "OVERNIGHT_RESEARCH_LOOP_STATUS.md"),
        "config": os.path.join(memory, "OVERNIGHT_RESEARCH_LOOP_CONFIG.json"),
    }

def _overnight_loop_pid_v1():
    import os
    p = _overnight_loop_paths_v1()
    try:
        if os.path.exists(p["pid"]):
            txt = read_file(p["pid"]).strip()
            if txt.isdigit():
                return int(txt)
    except Exception:
        pass
    return None

def _overnight_loop_pid_alive_v1(pid):
    try:
        import ctypes
        if not pid:
            return False
        PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
        STILL_ACTIVE = 259
        handle = ctypes.windll.kernel32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, False, int(pid))
        if not handle:
            return False
        code = ctypes.c_ulong()
        ok = ctypes.windll.kernel32.GetExitCodeProcess(handle, ctypes.byref(code))
        ctypes.windll.kernel32.CloseHandle(handle)
        return bool(ok) and code.value == STILL_ACTIVE
    except Exception:
        return False


# ----------------------------------------------------------------------
# Research Start Lock Guard V2M-B
# Prevents duplicate durable overnight loop starts when duplicate UI routes fire.
# Core safety layer: even if two callers invoke overnight_loop_on(), only one wins.
# ----------------------------------------------------------------------
def _research_start_lock_paths_v2mb():
    import os
    return {
        "lock": os.path.join(MEMORY_DIR, "research_start_v2mb.lock"),
    }

def _research_start_lock_acquire_v2mb():
    import os, time
    p = _research_start_lock_paths_v2mb()["lock"]

    # Clear very old stale lock.
    try:
        if os.path.exists(p):
            age = time.time() - os.path.getmtime(p)
            if age > 60:
                os.remove(p)
    except Exception:
        pass

    try:
        fd = os.open(p, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        os.write(fd, str(os.getpid()).encode("utf-8", errors="replace"))
        os.close(fd)
        return True
    except FileExistsError:
        return False
    except Exception:
        # Fail closed-ish: do not crash Engel; allow existing PID guard to decide.
        return True

def _research_start_lock_release_v2mb():
    import os
    p = _research_start_lock_paths_v2mb()["lock"]
    try:
        if os.path.exists(p):
            os.remove(p)
    except Exception:
        pass



def _pid_cmdline_contains_v2runnera(pid, needle):
    import subprocess
    try:
        pid = int(pid)
    except Exception:
        return False
    try:
        cmd = [
            "powershell", "-NoProfile", "-Command",
            "$p = Get-CimInstance Win32_Process -Filter \"ProcessId = " + str(pid) + "\"; "
            "if ($p -and $p.CommandLine -match '" + str(needle).replace("'", "''") + "') { 'LIVE' }"
        ]
        out = subprocess.check_output(cmd, text=True, errors="replace", timeout=5)
        return "LIVE" in out
    except Exception:
        return False



def _pid_parent_v2runnerc(pid):
    import subprocess
    try:
        pid = int(pid)
    except Exception:
        return None
    try:
        cmd = [
            "powershell", "-NoProfile", "-Command",
            "$p = Get-CimInstance Win32_Process -Filter \"ProcessId = " + str(pid) + "\"; "
            "if ($p) { [string]$p.ParentProcessId }"
        ]
        out = subprocess.check_output(cmd, text=True, errors="replace", timeout=5).strip()
        if out.isdigit():
            return int(out)
    except Exception:
        pass
    return None


def _runner_pids_are_parent_child_v2runnerc(pid_texts):
    try:
        pids = sorted(set([int(str(x).strip()) for x in pid_texts if str(x).strip().isdigit()]))
    except Exception:
        return False
    if len(pids) < 2:
        return False
    parent_map = {pid: _pid_parent_v2runnerc(pid) for pid in pids}
    for child, parent in parent_map.items():
        if parent in pids:
            return True
    return False


def overnight_loop_status():
    import os
    import re

    p = _overnight_loop_paths_v1()
    loop_pid = _overnight_loop_pid_v1()
    loop_alive = _overnight_loop_pid_alive_v1(loop_pid)

    status_text = ""
    try:
        if os.path.exists(p["status"]):
            status_text = read_file(p["status"]).strip()
    except Exception:
        status_text = ""

    gateway_pid = os.getpid()

    loop_pid_label = str(loop_pid or "none")
    if loop_pid and not loop_alive:
        loop_pid_label += " [stale / not running]"

    # Runner PID reconciliation:
    # - Loop status may report one Runner PID.
    # - OVR runner status may report another PID.
    # Show both and mark live/stale instead of pretending there is only one truth.
    runner_entries = []

    try:
        m = re.search(r"(?im)^Runner PID:\s*(.+)$", status_text)
        if m:
            raw = m.group(1).strip()
            if raw and raw.lower() != "none":
                live = raw.isdigit() and _pid_cmdline_contains_v2runnera(int(raw), "engel_overnight_runner.py")
                runner_entries.append(("from loop status", raw, live))
    except Exception:
        pass

    try:
        runner_status = os.path.join(p["reports"], "overnight", "OVERNIGHT_RUNNER_STATUS.md")
        if os.path.exists(runner_status):
            runner_text = read_file(runner_status)
            m = re.search(r"(?im)^PID:\s*(.+)$", runner_text)
            if m:
                raw = m.group(1).strip()
                if raw and raw.lower() != "none":
                    live = raw.isdigit() and _pid_cmdline_contains_v2runnera(int(raw), "engel_overnight_runner.py")
                    runner_entries.append(("from runner status", raw, live))
    except Exception:
        pass

    # Dedupe runner entries by PID while preserving labels.
    seen_runner = set()
    runner_lines = []
    for source, raw, live in runner_entries:
        key = raw
        if key in seen_runner:
            continue
        seen_runner.add(key)
        state = "running" if live else "stale / not running"
        runner_lines.append("- Runner PID (engel_overnight_runner.py, " + source + "): " + raw + " [" + state + "]")

    if not runner_lines:
        runner_lines.append("- Runner PID (engel_overnight_runner.py): none")

    runner_lock_line_v2runnerb = "- Runner lock (V2RUNNER-A): none"
    runner_lock_warning_v2runnerb = ""
    try:
        runner_lock_v2runnerb = os.path.join(p["memory"], "overnight_runner_single_instance_v2runnera.lock")
        if os.path.exists(runner_lock_v2runnerb):
            owner = read_file(runner_lock_v2runnerb).strip() or "unknown"
            if str(owner).isdigit():
                live = _pid_cmdline_contains_v2runnera(int(owner), "engel_overnight_runner.py")
                state = "live owner" if live else "stale owner / not running"
                if not live:
                    runner_lock_warning_v2runnerb = "- V2RUNNER-B: Runner lock exists but owner PID is not a live engel_overnight_runner.py process: " + str(owner)
            else:
                state = "unreadable owner"
                runner_lock_warning_v2runnerb = "- V2RUNNER-B: Runner lock exists but owner is unreadable: " + str(owner)
            runner_lock_line_v2runnerb = "- Runner lock (V2RUNNER-A): " + str(owner) + " [" + state + "]"
    except Exception as e:
        runner_lock_line_v2runnerb = "- Runner lock (V2RUNNER-A): status error [" + str(e) + "]"

    thinking_pid = "none"
    thinking_state = "no pid file"
    try:
        thinking_pid_file = os.path.join(p["memory"], "engel_research_thinking_screen.pid")
        if os.path.exists(thinking_pid_file):
            raw = read_file(thinking_pid_file).strip()
            if raw.isdigit():
                thinking_pid = raw
                thinking_state = "running" if _overnight_loop_pid_alive_v1(int(raw)) else "stale / not running"
            elif raw:
                thinking_state = "pid file unreadable"
    except Exception:
        thinking_state = "status read error"

    warnings = []
    if runner_lock_warning_v2runnerb:
        warnings.append(runner_lock_warning_v2runnerb)
    live_runner_pids_v2runnera = sorted(set([raw for source, raw, live in runner_entries if live]))
    if len(live_runner_pids_v2runnera) > 1:
        if _runner_pids_are_parent_child_v2runnerc(live_runner_pids_v2runnera):
            warnings.append("- V2RUNNER-C: Runner PIDs are parent/child launcher chain, not independent duplicate runners: " + ", ".join(live_runner_pids_v2runnera))
        else:
            warnings.append("- V2RUNNER-A: More than one independent live engel_overnight_runner.py PID was detected: " + ", ".join(live_runner_pids_v2runnera))
    if not loop_alive and "Stage: RUNNING_RESEARCH" in status_text:
        warnings.append("- Loop PID is not alive, but status file still says RUNNING_RESEARCH. Status file may be stale.")
    for source, raw, live in runner_entries:
        if live and not loop_alive:
            warnings.append("- Runner PID " + raw + " is alive while loop PID is not alive. This may be an orphan runner.")

    lines = [
        "# Overnight Research Loop",
        "",
        "Loop running: " + str(loop_alive),
        "",
        "## PID Labels",
        "- Gateway PID (Engel UI / command process): " + str(gateway_pid),
        "- Loop PID (engel_overnight_loop.py): " + loop_pid_label,
    ]

    lines += runner_lines
    lines.append(runner_lock_line_v2runnerb)

    lines += [
        "- Thinking Screen PID (engel_research_thinking_screen.py): " + str(thinking_pid) + " [" + thinking_state + "]",
        "",
    ]

    if warnings:
        lines += ["## PID Warnings"] + warnings + [""]

    lines += [
        "Files:",
        "- Script: " + p["script"],
        "- Loop PID file: " + p["pid"],
        "- Stop flag: " + p["stop"],
        "- Status: " + p["status"],
        "",
        "Commands:",
        "- research on",
        "- research off",
        "- research status",
        "- research thinking status",
        "- overnight loop on",
        "- overnight loop off",
        "- overnight loop status",
        "- overnight loop once",
        "",
        "## Current Status",
        status_text if status_text else "No overnight loop status file yet.",
        "",
        "Safety:",
        "- Status only.",
        "- No research process launched from status.",
        "- No sending/deleting/cloud fallback.",
    ]
    return "\n".join(lines)


def overnight_loop_on():
    import os
    import subprocess
    import sys

    p = _overnight_loop_paths_v1()
    pid = _overnight_loop_pid_v1()
    if _overnight_loop_pid_alive_v1(pid):
        return "\n".join([
            "# Overnight Research Loop ON",
            "",
            "Already running.",
            "Tracked PID: " + str(pid),
            "",
            "Use:",
            "- overnight loop status",
            "- overnight loop off",
        ])

    missing = []
    if not os.path.exists(p["script"]):
        missing.append(p["script"])
    if not os.path.exists(p["runner"]):
        missing.append(p["runner"])

    if missing:
        return "\n".join([
            "# Overnight Research Startup Unavailable",
            "",
            "One or more overnight research runtime scripts are not installed:",
            "",
            "\n".join("- " + path for path in missing),
            "",
            "No research loop was started.",
            "No runner was started.",
            "No provider, network, browser, cloud fallback, or autonomy behavior was enabled.",
            "",
            "Suggested safe commands:",
            "- command suggest research",
            "- router check research status",
            "- research brief latest",
            "- morning research review status",
            "- overnight loop status",
            "",
            "Safety:",
            "- Graceful failure only.",
            "- No process launched.",
            "- No trusted-memory write.",
            "- No queue mutation.",
            "- No ALIVE_STATE write.",
        ])

    try:
        if os.path.exists(p["stop"]):
            os.remove(p["stop"])
    except Exception:
        pass

    pyw = os.path.join(p["root"], ".venv", "Scripts", "pythonw.exe")
    py = os.path.join(p["root"], ".venv", "Scripts", "python.exe")
    exe = pyw if os.path.exists(pyw) else py if os.path.exists(py) else sys.executable

    creationflags = 0
    try:
        creationflags = subprocess.CREATE_NO_WINDOW
    except Exception:
        creationflags = 0

    proc = subprocess.Popen([exe, p["script"]], cwd=p["root"], creationflags=creationflags)

    try:
        write_file(p["pid"], str(proc.pid))
    except Exception:
        pass

    try:
        os.makedirs(os.path.dirname(p["status"]), exist_ok=True)
        write_file(
            p["status"],
            "\n".join([
                "# Overnight Research Loop Status",
                "",
                "Time: " + now(),
                "Stage: STARTING",
                "Cycle: none",
                "Loop PID: " + str(proc.pid),
                "Runner PID: none",
                "Last runner exit: none",
                "",
                "Detail:",
                "Research ON / overnight loop on started the explicit local loop process.",
                "",
                "Files:",
                "- PID: " + p["pid"],
                "- Stop flag: " + p["stop"],
                "- Status: " + p["status"],
                "- History: " + os.path.join(p["reports"], "OVERNIGHT_RESEARCH_LOOP_HISTORY.jsonl"),
                "- Runner: " + p["runner"],
                "",
                "Safety:",
                "- Explicit local loop startup only.",
                "- The loop delegates only to the installed overnight runner script.",
                "- No provider/network/browser/cloud fallback/autonomy behavior was enabled by startup.",
            ])
        )
    except Exception:
        pass

    return "\n".join([
        "# Overnight Research Loop ON",
        "",
        "Started overnight research loop.",
        "PID: " + str(proc.pid),
        "",
        "Behavior:",
        "- Runs one staged local research-brain runner cycle per iteration.",
        "- Preserves exact APPROVE and APPROVE_REPORT gates.",
        "- Pauses between cycles.",
        "- Starts the next cycle until you turn the loop OFF.",
        "",
        "Commands:",
        "- overnight loop status",
        "- overnight loop off",
        "",
        "Safety:",
        "- Explicitly started by Josh.",
        "- No cloud fallback.",
        "- No provider/network/browser startup path.",
        "- No clicking/login/sending/deleting.",
    ])

def overnight_loop_off():
    import os
    import subprocess

    p = _overnight_loop_paths_v1()
    pid = _overnight_loop_pid_v1()

    runner_lock_v2runnerb = os.path.join(p["memory"], "overnight_runner_single_instance_v2runnera.lock")
    runner_lock_owner_v2runnerb = "none"
    runner_lock_removed_v2runnerb = False

    stopped = False

    try:
        write_file(p["stop"], "stop requested " + now())
    except Exception:
        pass

    if _overnight_loop_pid_alive_v1(pid):
        try:
            r = subprocess.run(
                ["taskkill", "/PID", str(pid), "/T", "/F"],
                capture_output=True,
                text=True,
            )
            stopped = (r.returncode == 0)
        except Exception:
            stopped = False

    # V2RUNNER-B stale runner lock cleanup
    # Research OFF may taskkill the runner before atexit can remove the lock.
    try:
        if os.path.exists(runner_lock_v2runnerb):
            runner_lock_owner_v2runnerb = read_file(runner_lock_v2runnerb).strip() or "unknown"
            owner_live = False
            if str(runner_lock_owner_v2runnerb).isdigit():
                owner_live = _pid_cmdline_contains_v2runnera(int(runner_lock_owner_v2runnerb), "engel_overnight_runner.py")
            if not owner_live:
                os.remove(runner_lock_v2runnerb)
                runner_lock_removed_v2runnerb = True
    except Exception as e:
        runner_lock_owner_v2runnerb = "cleanup error: " + str(e)

    # Stale Status Cleanup V2K-D
    # Research OFF / overnight loop OFF should leave clean OFF status files.
    try:
        write_file(
            p["status"],
            "\n".join([
                "# Overnight Research Loop Status",
                "",
                "Time: " + now(),
                "Stage: OFF",
                "Cycle: none",
                "Runner PID: none",
                "Last runner exit: clean-stop",
                "Loop runtime: none",
                "",
                "Detail:",
                "Research loop stopped by Research OFF / overnight loop off.",
                "",
                "Files:",
                "- PID: " + p["pid"],
                "- Stop flag: " + p["stop"],
                "- Status: " + p["status"],
                "- History: " + os.path.join(p["reports"], "OVERNIGHT_RESEARCH_LOOP_HISTORY.jsonl"),
                "- Runner: " + os.path.join(p["root"], "engel_overnight_runner.py"),
                "",
                "Safety:",
                "- Stop request only.",
                "- No files deleted.",
                "- No sending/deleting/cloud fallback.",
            ])
        )
    except Exception:
        pass

    try:
        runner_status = os.path.join(p["reports"], "overnight", "OVERNIGHT_RUNNER_STATUS.md")
        write_file(
            runner_status,
            "\n".join([
                "# Research Runner Status",
                "",
                "Time: " + now(),
                "Status: OFF",
                "PID: none",
                "Research runner stopped/cleared by Research OFF / overnight loop off.",
                "",
                "Safety:",
                "- Status cleanup only.",
                "- No browsing.",
                "- No clicking.",
                "- No sending.",
                "- No deleting.",
            ])
        )
    except Exception:
        pass

    return "\n".join([
        "# Overnight Research Loop OFF",
        "",
        "Stop flag written:",
        p["stop"],
        "",
        "Stopped tracked loop process: " + str(stopped),
        "PID: " + str(pid or "none"),
        "",
        "Status cleanup:",
        "- Loop status written: OFF",
        "- Runner status written: OFF",
        "- Runner lock cleanup V2RUNNER-B: " + ("removed stale lock owned by " + str(runner_lock_owner_v2runnerb) if runner_lock_removed_v2runnerb else "no stale lock removed"),
        "",
        "Safety:",
        "- Stop request only.",
        "- No files deleted except normal process cleanup.",
        "- No sending/deleting/cloud fallback.",
    ])




# ----------------------------------------------------------------------
# Research OS Process Guard V2M-C
# Blocks duplicate overnight loop starts by checking live OS processes.
# ----------------------------------------------------------------------
def _research_loop_processes_v2mc():
    import subprocess
    rows = []
    try:
        cmd = [
            "powershell", "-NoProfile", "-Command",
            "Get-CimInstance Win32_Process | "
            "Where-Object { ($_.Name -match 'python') -and ($_.CommandLine -match 'engel_overnight_loop.py') } | "
            "ForEach-Object { [string]$_.ProcessId + '|' + [string]$_.Name + '|' + [string]$_.CommandLine }"
        ]
        out = subprocess.check_output(cmd, text=True, errors="replace", timeout=8)
        for line in out.splitlines():
            line = line.strip()
            if "|" not in line:
                continue
            parts = line.split("|", 2)
            if len(parts) != 3:
                continue
            pid, name, command = parts
            low_name = str(name).lower()
            low_command = str(command).lower()

            # V2M-D: avoid self-detecting the PowerShell/CIM query as the loop.
            if "powershell" in low_name or "powershell" in low_command:
                continue
            if "python" not in low_name:
                continue
            if "engel_overnight_loop.py" not in low_command:
                continue

            rows.append({"pid": pid, "name": name, "command": command})
    except Exception:
        pass
    return rows


def _research_loop_already_running_v2mc():
    rows = _research_loop_processes_v2mc()
    return len(rows) > 0, rows


# ----------------------------------------------------------------------
# V2M-B wrapper: locked overnight_loop_on
# ----------------------------------------------------------------------
_overnight_loop_on_base_v2mb = overnight_loop_on

def overnight_loop_on():
    if not _research_start_lock_acquire_v2mb():
        return "\n".join([
            "# Overnight Research Loop ON",
            "",
            "Start request ignored because another Research ON start is already in progress.",
            "",
            "Safety:",
            "- Duplicate loop start blocked by V2M-B.",
            "- No second loop started.",
            "- No second runner started.",
            "- No cloud fallback.",
        ])

    try:
        return _overnight_loop_on_base_v2mb()
    finally:
        _research_start_lock_release_v2mb()



# ----------------------------------------------------------------------
# V2M-C wrapper: OS-process guarded overnight_loop_on
# ----------------------------------------------------------------------
_overnight_loop_on_base_v2mc = overnight_loop_on

def overnight_loop_on():
    running, rows = _research_loop_already_running_v2mc()
    if running:
        details = []
        for r in rows:
            details.append("- PID " + str(r.get("pid")) + ": " + str(r.get("command")))

        return "\n".join([
            "# Overnight Research Loop ON",
            "",
            "Already running.",
            "",
            "## OS Process Guard V2M-C",
            "Existing overnight loop process(es) detected:",
            "",
            "\n".join(details) if details else "- detected, details unavailable",
            "",
            "Safety:",
            "- Duplicate loop start blocked.",
            "- No second loop started.",
            "- No second runner started by this command.",
            "- No cloud fallback.",
        ])

    return _overnight_loop_on_base_v2mc()


def overnight_loop_once():
    import os
    import subprocess
    import sys

    root = globals().get("ROOT", ROOT)
    runner = os.path.join(root, "engel_overnight_runner.py")
    if not os.path.exists(runner):
        return "\n".join([
            "# Overnight Loop Once Unavailable",
            "",
            "The overnight research runner script is not installed at the expected path:",
            runner,
            "",
            "No runner was started.",
            "No provider, network, browser, cloud fallback, or autonomy behavior was enabled.",
            "",
            "Safety:",
            "- Graceful failure only.",
            "- No process launched.",
            "- No trusted-memory write.",
            "- No queue mutation.",
            "- No ALIVE_STATE write.",
        ])

    pyw = os.path.join(root, ".venv", "Scripts", "pythonw.exe")
    py = os.path.join(root, ".venv", "Scripts", "python.exe")
    exe = pyw if os.path.exists(pyw) else py if os.path.exists(py) else sys.executable

    creationflags = 0
    try:
        creationflags = subprocess.CREATE_NO_WINDOW
    except Exception:
        creationflags = 0

    proc = subprocess.Popen([exe, runner], cwd=root, creationflags=creationflags)

    return "\n".join([
        "# Overnight Loop Once",
        "",
        "Started one staged local research-brain cycle.",
        "Runner PID: " + str(proc.pid),
        "",
        "This is single-cycle, not the full loop.",
        "",
        "For full overnight loop:",
        "- overnight loop on",
        "",
        "Safety:",
        "- Explicitly started by Josh.",
        "- No cloud fallback.",
        "- Exact APPROVE and APPROVE_REPORT gates remain separate.",
        "- No clicking/login/sending/deleting.",
    ])


