# Overnight Loop V1C Topic Rotation Status + Manual Runner Guard
# ----------------------------------------------------------------------
def overnight_topic_rotation_status():
    import os
    paths = {
        "rotation": os.path.join(MEMORY_DIR, "OVERNIGHT_TOPIC_ROTATION.json"),
        "report": os.path.join(REPORTS_DIR, "OVERNIGHT_TOPIC_ROTATION_STATUS.md"),
        "queue": os.path.join(REPORTS_DIR, "overnight", "OVERNIGHT_QUEUE.md"),
    }
    lines = ["# Overnight Topic Rotation Status", "", "Files:", "- Rotation JSON: " + paths["rotation"], "- Rotation report: " + paths["report"], "- Queue: " + paths["queue"], ""]
    try:
        if os.path.exists(paths["report"]):
            lines.append(read_file(paths["report"]))
        else:
            lines.append("No rotation report yet. It will appear after a loop cycle completes.")
    except Exception as e:
        lines.append("Could not read rotation report: " + str(e))
    lines += ["", "Safety:", "- Status only.", "- No process launching.", "- No browsing/clicking/sending/deleting."]
    return "\n".join(lines)

def _overnight_loop_is_running_guard_v1c():
    try:
        pid_file = os.path.join(MEMORY_DIR, "overnight_research_loop.pid")
        if not os.path.exists(pid_file):
            return False, None
        txt = read_file(pid_file).strip()
        if not txt.isdigit():
            return False, None
        pid = int(txt)
        import ctypes
        PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
        STILL_ACTIVE = 259
        handle = ctypes.windll.kernel32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
        if not handle:
            return False, pid
        code = ctypes.c_ulong()
        ok = ctypes.windll.kernel32.GetExitCodeProcess(handle, ctypes.byref(code))
        ctypes.windll.kernel32.CloseHandle(handle)
        return bool(ok) and code.value == STILL_ACTIVE, pid
    except Exception:
        return False, None




